prompt
prompt Creating view ACT_BNK_JV_VIEW
prompt =============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.ACT_BNK_JV_VIEW AS
SELECT DISTINCT "MVH_CP_CODE","DVH_COA3_CODE","MVH_DATE","MVH_CHQ_NO","MVH_REM","DVH_DBT_AMT","DVH_CRD_AMT","DVH_MVH_NUM","MVH_BNK_CODE","BNK_COA3_CODE","DBS_CP_CODE","DBS_BNK_CODE","DBS_FM_DATE","DBS_TO_DATE","DBS_SEQ_NUM","DBS_TRS_DATE","DBS_MVH_NUM","DBS_CRD_AMT","DBS_DBT_AMT","DBS_STATUS","DBS_BR_CODE","DBS_REM" FROM (
  SELECT MVH_CP_CODE, DVH_COA3_CODE, MVH_DATE,MVH_CHQ_NO,
  DECODE(NVL(MVH_PAY_NAME,'-'),'-',DECODE(NVL(DVH_REM,'-'),'-',MVH_REM,DVH_REM),MVH_PAY_NAME) AS MVH_REM,
  DVH_DBT_OTH AS DVH_DBT_AMT,
         DVH_CRD_OTH AS DVH_CRD_AMT, DVH_MVH_NUM, MVH_BNK_CODE, BNK_COA3_CODE
  FROM   ACT_TM_VOUCHER,ACT_TD_VOUCHER, ACT_SM_BANK
  WHERE  MVH_STATUS    = 'P'
  AND    MVH_CP_CODE   = DVH_CP_CODE
  AND    MVH_NUM       = DVH_MVH_NUM
  AND    MVH_VTP_TYPE NOT IN ('P','R')
  AND    DVH_CP_CODE   = BNK_CP_CODE
  AND    DVH_COA3_CODE = BNK_COA3_CODE)
  LEFT  JOIN ACT_TD_BNK_STAT ON (DBS_CP_CODE = MVH_CP_CODE
     AND DBS_BNK_CODE = DVH_COA3_CODE
      AND DBS_MVH_NUM  = DVH_MVH_NUM
     AND DBS_STATUS = 'Y')
  WHERE DBS_MVH_NUM IS NULL
  ORDER BY MVH_CHQ_NO;

prompt
prompt Creating view ACT_BNK_VCH_VIEW
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.ACT_BNK_VCH_VIEW AS
SELECT DISTINCT "MVH_CP_CODE","MVH_BNK_CODE","MVH_DATE","MVH_CHQ_NO","MVH_REM","DVH_DBT_AMT","DVH_CRD_AMT","DVH_MVH_NUM","DVH_COA3_CODE","BNK_COA3_CODE","DBS_CP_CODE","DBS_BNK_CODE","DBS_FM_DATE","DBS_TO_DATE","DBS_SEQ_NUM","DBS_TRS_DATE","DBS_MVH_NUM","DBS_CRD_AMT","DBS_DBT_AMT","DBS_STATUS","DBS_BR_CODE","DBS_REM" FROM (
 SELECT   MVH_CP_CODE, MVH_BNK_CODE, MVH_DATE,MVH_CHQ_NO,
   DECODE(NVL(MVH_PAY_NAME,'-'),'-',DECODE(NVL(DVH_REM,'-'),'-',MVH_REM,DVH_REM),MVH_PAY_NAME) AS MVH_REM,
   DVH_DBT_OTH AS DVH_DBT_AMT,
          DVH_CRD_OTH AS DVH_CRD_AMT,DVH_MVH_NUM, DVH_COA3_CODE, BNK_COA3_CODE
 FROM     ACT_TM_VOUCHER,ACT_TD_VOUCHER, ACT_SM_BANK
 WHERE    MVH_STATUS    = 'P'
 AND      MVH_CP_CODE   = DVH_CP_CODE
 AND      MVH_NUM       = DVH_MVH_NUM
 AND      DVH_CP_CODE   = BNK_CP_CODE
 AND      DVH_COA3_CODE = BNK_COA3_CODE
 AND      MVH_VTP_TYPE IN ('P','R'))
 LEFT JOIN ACT_TD_BNK_STAT ON (DBS_CP_CODE = MVH_CP_CODE
          AND DBS_BNK_CODE = DVH_COA3_CODE
           AND DBS_MVH_NUM  = DVH_MVH_NUM
          AND DBS_STATUS = 'Y')
 WHERE DBS_MVH_NUM IS NULL
 ORDER BY MVH_CHQ_NO;

