prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.ACT_TD_CWIP_VW AS
SELECT MVH_CP_CODE,
       DVH_DOC_NUM,
       MVH_NUM,
       MVH_DATE,
       SUM(NVL(DVH_DBT_AMT,0)) AS DVH_DBT_AMT,
       SUM(NVL(DVH_CRD_AMT,0)) AS DVH_CRD_AMT,
       MVH_REM
FROM   ACT_TM_VOUCHER,ACT_TD_VOUCHER,ACT_TM_CWIP
WHERE  MVH_CP_CODE   = DVH_CP_CODE
AND    MVH_NUM       = DVH_MVH_NUM
AND    MVH_CP_CODE   = MCW_CP_CODE
AND    DVH_COA3_CODE = MCW_COA3_CODE
AND    DVH_DOC_NUM   = MCW_NUM
GROUP BY MVH_CP_CODE,DVH_DOC_NUM,MVH_NUM,MVH_DATE,MVH_REM
ORDER BY 2,1;

prompt
prompt Creating view ADJUSTED_ADV_REG
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.ADJUSTED_ADV_REG AS
(
SELECT  'ADV' AS ADJ_NATURE, DAD_CP_CODE AS ADJ_CP_CODE, DAD_MPF_FILE_NUM ADJ_DOC_NUM, DAD_MPF_MPT_ID ADJ_MPT_ID,
 CASE WHEN MBP_DATE < DAD_ADV_DATE THEN DAD_ADV_DATE ELSE MBP_DATE END AS ADJ_DATE,
 MBP_DATE AS ADJ_REF_DATE, MBP_MPF_DIS_CODE AS ADJ_REF_NUM,
 DAD_ADV_TYPE ADJ_TYPE,  DAD_ADV_SLIP_NUM ADJ_SLIP_NUM,
 DAD_AMT AS ADJ_AMT, MPF_TYPE AS ADJ_SAL_TYPE, DAD_ADV_DATE AS ADJ_TR_DATE, DAD_MPF_FILE_NUM AS ADJ_FILE_NUM
FROM    HOS_TD_PAT_ADV_INFO, HOS_TO_BILL_PROCESS, HOS_TM_PATIENT_FILE
WHERE   MBP_CP_CODE = DAD_CP_CODE
AND     MBP_MPF_FILE_NUM = DAD_MPF_FILE_NUM
AND     MBP_MPT_ID = DAD_MPF_MPT_ID
AND     NVL(DAD_STATUS,'Y') = 'Y'
AND     DAD_ADV_TYPE = 'A'
AND     MPF_CP_CODE  = DAD_CP_CODE
AND     MPF_FILE_NUM = DAD_MPF_FILE_NUM
UNION ALL
SELECT  'ADV' AS ADJ_NATURE, DAD_CP_CODE AS ADJ_CP_CODE, DAD_MPF_FILE_NUM ADJ_DOC_NUM, DAD_MPF_MPT_ID ADJ_MPT_ID,
 CASE WHEN MAR_DATE < DAD_ADV_DATE THEN DAD_ADV_DATE ELSE MAR_DATE END AS ADJ_DATE,
 MAR_DATE AS ADJ_REF_DATE, MAR_NUM AS ADJ_REF_NUM,
 DAD_ADV_TYPE ADJ_TYPE,  DAD_ADV_SLIP_NUM ADJ_SLIP_NUM,
 DAD_AMT AS ADJ_AMT, MPF_TYPE AS ADJ_SAL_TYPE, DAD_ADV_DATE AS ADJ_TR_DATE, DAD_MPF_FILE_NUM AS ADJ_FILE_NUM
FROM    HOS_TD_PAT_ADV_INFO, HOS_TO_ADV_REFUND, HOS_TM_PATIENT_FILE
WHERE   MAR_CP_CODE = DAD_CP_CODE
AND     MAR_MPF_FILE_NUM = DAD_MPF_FILE_NUM
AND     MAR_DAD_ADV_SLIP_NUM = DAD_ADV_SLIP_NUM
AND     NVL(DAD_STATUS,'Y') = 'N'
AND     DAD_ADV_TYPE = 'A'
AND     MPF_CP_CODE  = DAD_CP_CODE
AND     MPF_FILE_NUM = DAD_MPF_FILE_NUM
UNION ALL
SELECT  'REG' AS ADJ_NATURE, DAD_CP_CODE AS ADJ_CP_CODE, DAD_MPF_FILE_NUM ADJ_DOC_NUM, DAD_MPF_MPT_ID ADJ_MPT_ID,
 CASE WHEN MBP_DATE < MPR_REG_DATE THEN MPR_REG_DATE ELSE MBP_DATE END AS ADJ_DATE,
 MBP_DATE AS ADJ_REF_DATE, MBP_MPF_DIS_CODE AS ADJ_REF_NUM,
 DAD_ADV_TYPE ADJ_TYPE,  MPR_REG_NUM ADJ_SLIP_NUM,
 DAD_AMT AS ADJ_AMT, MPF_TYPE AS ADJ_SAL_TYPE, MPR_REG_DATE AS ADJ_TR_DATE, DAD_MPF_FILE_NUM  AS ADJ_FILE_NUM
FROM    HOS_TM_PAT_REGISTRATION, HOS_TD_PAT_ADV_INFO, HOS_TO_BILL_PROCESS, HOS_TM_PATIENT_FILE
WHERE   MBP_CP_CODE = DAD_CP_CODE
AND     MBP_MPF_FILE_NUM = DAD_MPF_FILE_NUM
AND     MBP_MPT_ID = DAD_MPF_MPT_ID
AND     NVL(DAD_STATUS,'Y') = 'Y'
AND     DAD_ADV_TYPE = 'R'
AND     MPR_CP_CODE  = DAD_CP_CODE
AND     MPR_REG_NUM  = DAD_ADV_REG_NUM
AND     MPF_CP_CODE  = DAD_CP_CODE
AND     MPF_FILE_NUM = DAD_MPF_FILE_NUM
UNION ALL
SELECT  'REG' AS ADJ_NATURE, MPR_CP_CODE AS ADJ_CP_CODE, '---' ADJ_DOC_NUM, MPR_MPT_ID ADJ_MPT_ID,
 CASE WHEN MRR_DATE < MPR_REG_DATE THEN MPR_REG_DATE ELSE MRR_DATE END AS ADJ_DATE,
 MRR_DATE AS ADJ_REF_DATE, MRR_NUM AS ADJ_REF_NUM,
 'R' ADJ_TYPE,  MPR_REG_NUM ADJ_SLIP_NUM,
 MPR_AMT_IN_ADV AS ADJ_AMT, MPR_REG_TYPE AS ADJ_SAL_TYPE, MPR_REG_DATE AS ADJ_TR_DATE, '---' AS ADJ_FILE_NUM
FROM    HOS_TM_PAT_REGISTRATION, HOS_TM_REG_REFUND
WHERE   MRR_CP_CODE = MPR_CP_CODE
AND     MRR_MPR_REG_NUM  =  MPR_REG_NUM
AND     MRR_MPR_REG_DATE =  MPR_REG_DATE
AND     MRR_MPT_ID       =  MPR_MPT_ID
)
;

