prompt
prompt Creating view ALL_STOCK
prompt =======================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.ALL_STOCK AS
SELECT TR_TYPE, TR_CP_CODE, TR_LOC_CODE,TR_DIT_CODE, TR_BCH_NUM, TR_LOT_NUM, TR_EXP_DATE, TR_DATE, TR_DOC_NUM, TR_SEQ_NUM, TR_TRN_TYPE, TR_INS_TIME, TR_INS_DATE, TR_MIN_QTY, TR_MAX_QTY, TR_MIN_RATE, TR_MAX_RATE, TR_AMT, TR_BR_CODE, TR_DAT_FLAG, TR_MIN_ADD_COST, TR_MAX_ADD_COST, TR_REF_NUM, TR_FVL_FLAG, TR_LOC_OUT, TR_TBL_TYPE, TR_NATURE, TR_VAL_QTY, TR_VAL_RATE, TR_VAL_AMT, TR_VAL_AMT2, TR_REF_SQN, TR_BAR_CODE
FROM (
    SELECT   '10' AS TR_TYPE,
        DOI_CP_CODE AS TR_CP_CODE, DOI_LOC_CODE AS TR_LOC_CODE,
        DOI_DIT_CODE AS TR_DIT_CODE, DOI_BCH_NUM AS TR_BCH_NUM, DOI_LOT_NUM AS TR_LOT_NUM,
        DOI_EXP_DATE AS TR_EXP_DATE, DOI_FYR_FM AS TR_DATE,
        'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD') AS TR_DOC_NUM,
       -- DOI_SEQ_NUM AS TR_SEQ_NUM,
        TO_CHAR(TO_NUMBER(REPLACE(DOI_SEQ_NUM,SUBSTR(DOI_LOC_CODE,1,3)||TO_CHAR(DOI_FYR_FM,'RRRR')))) AS TR_SEQ_NUM,
        'OB' AS TR_TRN_TYPE,
        DOI_INS_TIME AS TR_INS_TIME, DOI_INS_DATE AS TR_INS_DATE,
        DOI_QTY AS TR_MIN_QTY, DOI_MAX_QTY AS TR_MAX_QTY,
        DOI_MIN_ADD_COST AS TR_MIN_RATE, DOI_MAX_ADD_COST AS TR_MAX_RATE,
        DOI_MIN_ADD_COST * DOI_QTY AS TR_AMT,
        SUBSTR(DOI_LOC_CODE,1,3) AS TR_BR_CODE,
        'I' AS TR_DAT_FLAG, 0 AS TR_MIN_ADD_COST, 0 AS TR_MAX_ADD_COST, NULL AS TR_REF_NUM,
        NULL AS TR_FVL_FLAG, NULL AS TR_LOC_OUT , NULL AS TR_TBL_TYPE, 'IN' AS TR_NATURE,
        DOI_VAL_QTY AS TR_VAL_QTY, DOI_VAL_RATE AS TR_VAL_RATE, DOI_VAL_AMT AS TR_VAL_AMT,
        NVL(DOI_VAL_QTY,0) * NVL(DOI_VAL_RATE,0) AS TR_VAL_AMT2, '0' AS TR_REF_SQN, DOI_BAR_CODE         TR_BAR_CODE
    FROM    PPI_SD_ITEM_OPNBAL
    UNION ALL
    SELECT   '11',
        MST_CP_CODE, MST_LOC_IN,
        DST_DIT_CODE, DST_BCH_NUM, DST_LOT_NUM,
        DST_EXP_DATE, MST_DATE,
        MST_NUM,
        TO_CHAR(DST_SEQ_NUM), 'SP',
        DST_INS_TIME, DST_INS_DATE,
        NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0), NVL(DST_MAX_QTY,0) + NVL(DST_BNS_MAX_QTY,0),
        (NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0)) / (NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0)),
        DECODE(NVL(DST_MAX_QTY,0),0,0,(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0)) / (NVL(DST_MAX_QTY,0) + NVL(DST_BNS_MAX_QTY,0))),
        (NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0)),
        MST_BR_CODE,
        'I', 0, 0, MST_REF_NUM, NULL, MST_LOC_OUT, MST_TYPE, 'IN',
        DST_VAL_QTY AS TR_VAL_QTY, DST_VAL_RATE AS TR_VAL_RATE, DST_VAL_AMT AS TR_VAL_AMT,
        NVL(DST_VAL_QTY,0) * NVL(DST_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DST_REF_SQN) AS TR_REF_SQN,
        DST_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_STOCK, PPI_TD_STOCK
    WHERE    MST_TYPE = 'SP'
    AND     DST_CP_CODE = MST_CP_CODE
    AND     DST_MST_NUM = MST_NUM
    UNION ALL
    SELECT   '12', MSL_CP_CODE, MSL_LOC_CODE,
        DSL_DIT_CODE, DSL_BCH_NUM, NULL,
        DSL_EXP_DATE, MSL_DATE,
        MSL_NUM,
        TO_CHAR(DSL_SEQ_NUM), 'SR',
        DSL_INS_TIME, DSL_INS_DATE,
        DSL_MIN_QTY, DSL_MAX_QTY,
        DSL_MIN_COST, DSL_MAX_COST,
        NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_COST,0),
        MSL_BR_CODE,
        'I', 0, 0, MSL_REF_NUM, NULL, NULL, MSL_TRN_TYPE, 'IN',
        DSL_VAL_QTY AS TR_VAL_QTY, DSL_VAL_RATE AS TR_VAL_RATE, DSL_VAL_AMT AS TR_VAL_AMT,
        NVL(DSL_VAL_QTY,0) * NVL(DSL_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DSL_IN_SEQ_NUM) AS TR_REF_SQN, DSL_BAR_CODE TR_BAR_CODE
    FROM     HOS_TM_SALES, HOS_TD_SALES
    WHERE    MSL_TRN_TYPE = 'SR'
    AND     DSL_CP_CODE = MSL_CP_CODE
    AND     DSL_MSL_NUM = MSL_NUM
    UNION ALL
    SELECT   '14',
        MST_CP_CODE, MST_LOC_IN,
        DST_DIT_CODE, DST_BCH_NUM, DST_LOT_NUM,
        DST_EXP_DATE, MST_DATE,
        MST_NUM,
        TO_CHAR(DST_SEQ_NUM), 'ST',
        DST_INS_TIME, DST_INS_DATE,
        NVL(DST_QTY,0), NVL(DST_MAX_QTY,0),
        DST_RATE, DST_MAX_RATE,
        (DST_QTY * DST_RATE),
        MST_BR_CODE,
        'I', 0, 0, MST_NUM, NULL, MST_LOC_OUT, MST_TYPE, 'IN/OUT',
        DST_VAL_QTY AS TR_VAL_QTY, DST_VAL_RATE AS TR_VAL_RATE, DST_VAL_AMT AS TR_VAL_AMT,
        NVL(DST_VAL_QTY,0) * NVL(DST_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DST_REF_SQN), DST_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_STOCK, PPI_TD_STOCK
    WHERE  MST_TYPE = 'ST'
    AND   DST_CP_CODE = MST_CP_CODE
    AND   DST_MST_NUM = MST_NUM
    UNION ALL
    SELECT   '13',
        MSE_CP_CODE, MSE_LOC_CODE,
        DSE_DIT_CODE, DSE_BCH_NUM, NULL,
        DSE_EXP_DATE, MSE_DATE,
        MSE_NUM,
        DSE_SEQ_NUM, 'EX',
        DSE_INS_TIME, DSE_INS_DATE,
        NVL(DSE_DIF_MIN_QTY,0), NVL(DSE_DIF_MAX_QTY,0),
        DSE_MIN_COST, DSE_MAX_COST,
        (DSE_DIF_MIN_QTY * DSE_MIN_COST),
        MSE_BR_CODE,
        'I', 0, 0, NULL, NULL, NULL, DSE_TYPE, 'IN',
        DSE_VAL_QTY AS TR_VAL_QTY, DSE_VAL_RATE AS TR_VAL_RATE, DSE_VAL_AMT AS TR_VAL_AMT,
        NVL(DSE_VAL_QTY,0) * NVL(DSE_VAL_RATE,0) AS TR_VAL_AMT2, '0', DSE_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_SHT_EXC, PPI_TD_SHT_EXC
    WHERE   MSE_STATUS = 'P'
    AND      DSE_CP_CODE = MSE_CP_CODE
    AND      DSE_MSE_NUM = MSE_NUM
    AND  DSE_DIF_MIN_QTY > 0
    UNION ALL
    SELECT   '21',
        MST_CP_CODE, MST_LOC_IN,
        DST_DIT_CODE, DST_BCH_NUM, DST_LOT_NUM,
        DST_EXP_DATE, MST_DATE,
        MST_NUM,
        TO_CHAR(DST_SEQ_NUM), 'PR',
        DST_INS_TIME, DST_INS_DATE,
        NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0), NVL(DST_MAX_QTY,0) + NVL(DST_BNS_MAX_QTY,0),
        0,
        0,
        0,
        MST_BR_CODE,
        'I', 0, 0, MST_REF_NUM, NULL, MST_LOC_OUT, MST_TYPE, 'OUT',
        DST_VAL_QTY AS TR_VAL_QTY, DST_VAL_RATE AS TR_VAL_RATE, DST_VAL_AMT AS TR_VAL_AMT,
        NVL(DST_VAL_QTY,0) * NVL(DST_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DST_REF_SQN), DST_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_STOCK, PPI_TD_STOCK
    WHERE    MST_TYPE = 'PR'
    AND     DST_CP_CODE = MST_CP_CODE
    AND     DST_MST_NUM = MST_NUM
    UNION ALL
    SELECT   '20',
        MSL_CP_CODE, MSL_LOC_CODE,
        DSL_DIT_CODE, DSL_BCH_NUM,NULL,
        DSL_EXP_DATE, MSL_DATE,
        MSL_NUM,
        TO_CHAR(DSL_SEQ_NUM), 'SL',
        DSL_INS_TIME, DSL_INS_DATE,
        DSL_MIN_QTY, DSL_MAX_QTY,
        DSL_MIN_COST, DSL_MAX_COST,
        NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_COST,0),
        MSL_BR_CODE,
        'I', 0, 0, MSL_REF_NUM, NULL, MSL_LOC_CODE, MSL_TRN_TYPE, 'OUT',
        DSL_VAL_QTY AS TR_VAL_QTY, DSL_VAL_RATE AS TR_VAL_RATE, DSL_VAL_AMT AS TR_VAL_AMT,
        NVL(DSL_VAL_QTY,0) * NVL(DSL_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DSL_IN_SEQ_NUM),   DSL_BAR_CODE TR_BAR_CODE
    FROM     HOS_TM_SALES, HOS_TD_SALES
    WHERE    MSL_TRN_TYPE = 'SL'
    AND     DSL_CP_CODE  = MSL_CP_CODE
    AND     DSL_MSL_NUM  = MSL_NUM
    UNION ALL
    SELECT   '23',
        MSE_CP_CODE, MSE_LOC_CODE,
        DSE_DIT_CODE, DSE_BCH_NUM, NULL,
        DSE_EXP_DATE, MSE_DATE,
        MSE_NUM,
        DSE_SEQ_NUM, 'SH',
        DSE_INS_TIME, DSE_INS_DATE,
        ABS(NVL(DSE_DIF_MIN_QTY,0)), ABS(NVL(DSE_DIF_MAX_QTY,0)),
        DSE_MIN_COST, DSE_MAX_COST,
        (DSE_DIF_MIN_QTY * DSE_MIN_COST),
        MSE_BR_CODE,
        'I', 0, 0, NULL, NULL, MSE_LOC_CODE, DSE_TYPE, 'OUT',
        DSE_VAL_QTY AS TR_VAL_QTY, DSE_VAL_RATE AS TR_VAL_RATE, DSE_VAL_AMT AS TR_VAL_AMT,
        NVL(DSE_VAL_QTY,0) * NVL(DSE_VAL_RATE,0) AS TR_VAL_AMT2, '0', DSE_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_SHT_EXC, PPI_TD_SHT_EXC
    WHERE  MSE_STATUS = 'P'
    AND      DSE_CP_CODE = MSE_CP_CODE
    AND      DSE_MSE_NUM = MSE_NUM
    AND     DSE_DIF_MIN_QTY < 0
    UNION ALL
    SELECT   '24',
        MST_CP_CODE, MST_LOC_IN,
        DST_DIT_CODE, DST_BCH_NUM, DST_LOT_NUM,
        DST_EXP_DATE, MST_DATE,
        MST_NUM,
        TO_CHAR(DST_SEQ_NUM), 'SI',
        DST_INS_TIME, DST_INS_DATE,
        NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0), NVL(DST_MAX_QTY,0) + NVL(DST_BNS_MAX_QTY,0),
        0,
        0,
        0,
        MST_BR_CODE,
        'I', 0, 0, MST_REF_NUM, NULL, MST_LOC_OUT, MST_TYPE, 'OUT',
        DST_VAL_QTY AS TR_VAL_QTY, DST_VAL_RATE AS TR_VAL_RATE, DST_VAL_AMT AS TR_VAL_AMT,
        NVL(DST_VAL_QTY,0) * NVL(DST_VAL_RATE,0) AS TR_VAL_AMT2, TO_CHAR(DST_REF_SQN), DST_BAR_CODE TR_BAR_CODE
    FROM     PPI_TM_STOCK, PPI_TD_STOCK
    WHERE    MST_TYPE = 'SI'
    AND     DST_CP_CODE = MST_CP_CODE
    AND     DST_MST_NUM = MST_NUM
)
ORDER BY TR_DATE, TR_TYPE
;

