prompt Creating view BBM_VIEW_BLOOD_STOCK_INQUIRY
prompt ==========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.BBM_VIEW_BLOOD_STOCK_INQUIRY AS
SELECT MPS_CP_CODE,
       MPS_BR_CODE,
       MPS_BPL_BPD_DP_CODE,
       DP_NAME,
       MPS_MDH_DATE,
       MPS_MDH_NUM,
       MPS_MDH_TIME_START,
       MPS_MDH_TIME_END,
       MPS_BGP_CODE,
       BGP_DESC,
       MPS_BPD_CODE,
       BPD_DESC,
       MPS_DATE,
       MPS_NUM,
       MPS_EXP_DATE,
       MPS_REMARKS,
       MPS_PST_FLAG,
       MPS_MRT_NUM,
       MPS_MRT_DATE,
       MPS_DLV_DATE,
       MPS_DLV_TIME,
       MPS_MCM_NUM,
       MPS_MCM_DATE,
       MPS_DLV_REMARKS,
       MPS_STATUS,
       MPS_INS_USER,
       MPS_INS_DATE,
       MPS_INS_TIME,
       MPS_UPD_USER,
       MPS_UPD_DATE,
       MPS_UPD_TIME,
       MPS_MDE_NUM,
       MPS_MDE_DATE,
       MDH_CNIC,
       MDH_NAME,
       MDH_CONTACT_NBR ,
      COUNT(*) AS CNT
  FROM BBM_TM_PRODUCT_STOCK
 INNER JOIN ISR_XD_DEPT
    ON (BBM_TM_PRODUCT_STOCK.MPS_CP_CODE = ISR_XD_DEPT.DP_CP_CODE AND
       BBM_TM_PRODUCT_STOCK.MPS_BPL_BPD_DP_CODE = ISR_XD_DEPT.DP_CODE)
 INNER JOIN BBM_SO_BLOOD_GROUPS
    ON (BBM_TM_PRODUCT_STOCK.MPS_CP_CODE = BBM_SO_BLOOD_GROUPS.BGP_CP_CODE AND
       BBM_TM_PRODUCT_STOCK.MPS_BGP_CODE = BBM_SO_BLOOD_GROUPS.BGP_CODE)
 INNER JOIN BBM_SO_BLOOD_PRODUCTS
    ON (BBM_TM_PRODUCT_STOCK.MPS_CP_CODE =
       BBM_SO_BLOOD_PRODUCTS.BPD_CP_CODE AND
       BBM_TM_PRODUCT_STOCK.MPS_BPD_CODE = BBM_SO_BLOOD_PRODUCTS.BPD_CODE)
 INNER JOIN BBM_TM_DONORS_HISTORY
    ON (BBM_TM_PRODUCT_STOCK.MPS_CP_CODE =
       BBM_TM_DONORS_HISTORY.MDH_CP_CODE AND
       BBM_TM_PRODUCT_STOCK.MPS_BR_CODE =
       BBM_TM_DONORS_HISTORY.MDH_BR_CODE AND
       BBM_TM_PRODUCT_STOCK.MPS_MDH_DATE = BBM_TM_DONORS_HISTORY.MDH_DATE AND
       BBM_TM_PRODUCT_STOCK.MPS_MDH_NUM = BBM_TM_DONORS_HISTORY.MDH_NUM)
      -- WHERE NVL(TO_DATE(MPS_MCM_EXP_DATE),TO_DATE(SYSDATE)-1)   < TO_DATE(SYSDATE)


       WHERE ( TO_DATE(TO_CHAR(MPS_MCM_EXP_DATE,'YYYY-MON-DD HH24:MI:SS'),'YYYY-MON-DD HH24:MI:SS')
    <  TO_DATE(TO_CHAR(SYSDATE,'YYYY-MON-DD HH24:MI:SS'),'YYYY-MON-DD HH24:MI:SS')
OR  MPS_MCM_EXP_DATE IS NULL)


       AND   MPS_STATUS  = 'I'
       AND   mps_out_num IS NULL AND  MPS_OUT_DATE IS NULL
       GROUP BY  MPS_CP_CODE,
       MPS_BR_CODE,
       MPS_BPL_BPD_DP_CODE,
       DP_NAME,
       MPS_MDH_DATE,
       MPS_MDH_NUM,
       MPS_MDH_TIME_START,
       MPS_MDH_TIME_END,
       MPS_BGP_CODE,
       BGP_DESC,
       MPS_BPD_CODE,
       BPD_DESC,
       MPS_DATE,
       MPS_NUM,
       MPS_EXP_DATE,
       MPS_REMARKS,
       MPS_PST_FLAG,
       MPS_MRT_NUM,
       MPS_MRT_DATE,
       MPS_DLV_DATE,
       MPS_DLV_TIME,
       MPS_MCM_NUM,
       MPS_MCM_DATE,
       MPS_DLV_REMARKS,
       MPS_STATUS,
       MPS_INS_USER,
       MPS_INS_DATE,
       MPS_INS_TIME,
       MPS_UPD_USER,
       MPS_UPD_DATE,
       MPS_UPD_TIME,
       MPS_MDE_NUM,
       MPS_MDE_DATE,
       MDH_CNIC,
       MDH_NAME,
       MDH_CONTACT_NBR
;

