prompt Creating view BILL_PROCESSED_FILES
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.BILL_PROCESSED_FILES AS
(
SELECT MPF_CP_CODE, MPF_FILE_NUM, MPF_MPT_ID, MPT_NAME||' '||
 DECODE(MPT_RELT_FLAG, 'S', 'S/O', 'F', 'F/O', 'W', 'W/O', 'D', 'D/O', 'M', 'M/O', 'H', 'H/O')||' '||MPT_FATHER_NAME MPT_NAME,
 MPF_ADM_DATE, MPF_DIS_DATE, MPF_DIS_CODE, MBP_DATE, MBP_USR_NAME, MPF_ADVANCE_AMT,
 MPF_NET_TOT AS BILL_AMT, DECODE(MPF_TYPE, 'C', MPF_NET_TOT, MPF_MPT_AMT) AS REC_REF_AMT,
 MPF_GRS_AMT, MPF_DISC_AMT, MBF_MPF_FILE_NUM , MBP_BR_CODE , MPF_BR_CODE , MBF_BR_CODE
FROM HOS_TO_BILL_PROCESS
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = MBP_CP_CODE AND MPF_FILE_NUM = MBP_MPF_FILE_NUM AND MPF_MPT_ID = MBP_MPT_ID AND MPF_TYPE = 'C')
INNER JOIN HOS_SM_PATIENT ON (MPT_ID = MBP_MPT_ID)
LEFT JOIN  HOS_TO_BILL_PROCESS_FINAL ON (MBF_CP_CODE = MBP_CP_CODE AND MBF_MPF_FILE_NUM = MBP_MPF_FILE_NUM AND MBF_MPF_MPT_ID = MBP_MPT_ID)
WHERE MBP_CP_CODE      = '01'
AND   NVL(DECODE(MPF_TYPE, 'C', MPF_NET_TOT, MPF_MPT_AMT), 0) <> 0
AND   MBF_MPF_FILE_NUM IS NULL
);

prompt
prompt Creating view CHECK_DEFICIENT_OPD_SLIPS
prompt =======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.CHECK_DEFICIENT_OPD_SLIPS AS
SELECT "MSR_CP_CODE","MSR_BR_CODE","MSR_PRG_CODE","MSR_INS_USER","MSR_INS_DATE" , "MSR_REF_TYPE","MSR_DATE","MSR_NUM","MSR_TYPE","MSR_AMOUNT","DTL_QTY_AMT","DTL_DSR_AMT","MSR_DISCOUNT","DTL_DISCOUNT","MSR_NET_AMT","DTL_NET_AMT","MSR_RCVD_AMT","MSR_DUE_AMT" FROM
(
SELECT   MSR_CP_CODE, MSR_BR_CODE , MSR_PRG_CODE , MSR_INS_USER, MSR_INS_DATE,MSR_REF_TYPE, MSR_DATE, MSR_NUM, MSR_TYPE, MSR_AMOUNT,
  SUM(NVL(DSR_QTY,0) * NVL(DSR_RATE,0)) AS DTL_QTY_AMT,
  SUM(DSR_AMT) AS DTL_DSR_AMT,
  MSR_DISCOUNT, SUM(DSR_DISC) AS DTL_DISCOUNT,
  MSR_NET_AMT, SUM(DSR_NET_AMT) AS DTL_NET_AMT,
  MSR_RCVD_AMT, MSR_DUE_AMT
FROM HOS_TM_OPD_SRV_RCPT
LEFT JOIN HOS_TD_OPD_SRV_RCPT ON (MSR_CP_CODE = DSR_CP_CODE
AND   MSR_NUM     = DSR_MSR_NUM)
GROUP BY MSR_CP_CODE, MSR_BR_CODE , MSR_PRG_CODE , MSR_INS_USER,MSR_INS_DATE , MSR_REF_TYPE, MSR_DATE, MSR_NUM, MSR_TYPE, MSR_AMOUNT, MSR_DISCOUNT, MSR_NET_AMT, MSR_RCVD_AMT, MSR_DUE_AMT
)
WHERE   (NVL(MSR_AMOUNT,0) - NVL(MSR_DISCOUNT,0)) <>  MSR_NET_AMT
OR   NVL(MSR_NET_AMT,0) <> (NVL(MSR_RCVD_AMT,0) + NVL(MSR_DUE_AMT,0))
OR      NVL(DTL_QTY_AMT,0) <> NVL(DTL_DSR_AMT,0)
OR      NVL(DTL_NET_AMT,0) <> (NVL(DTL_DSR_AMT,0) - NVL(DTL_DISCOUNT,0))
OR      NVL(DTL_NET_AMT,0) <> NVL(MSR_NET_AMT,0)
OR      NVL(MSR_DISCOUNT,0) <> NVL(DTL_DISCOUNT,0)
OR      (NVL(DTL_DSR_AMT,0) = 0 AND  NVL(MSR_NET_AMT,0) >0)
ORDER BY MSR_DATE;

prompt
prompt Creating view HOS_TD_PAT_BLOOD_RECORD
prompt =====================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_TD_PAT_BLOOD_RECORD AS
(SELECT M.MRT_CP_CODE, M.MRT_MPT_ID, M.MRT_DATE, M.MRT_NUM, M.MRT_MRQ_NUM, M.MRT_MPF_FILE_NUM, M.MRT_SLIP_TYPE, COUNT(D.DRT_BPD_CODE)AS TOT_PRD,
  SUM(NVL(MRT_RCVD_AMT,0))    AS MRT_RCVD_AMT,
  SUM(NVL(MRT_DUE_AMT,0))  / COUNT(D.DRT_BPD_CODE)   AS MRT_DUE_AMT,
  SUM(NVL(D.DRT_GROSS_AMT,0)) AS DRT_GROSS_AMT,
  SUM(NVL(D.DRT_NET_AMT,0))   AS DRT_NET_AMT,
  SUM(NVL(D.DRT_DISC_AMT,0))  AS DRT_DISC_AMT
  FROM BBM_TM_RECEIPT M
  LEFT JOIN BBM_TD_RECEIPT D ON (      D.DRT_CP_CODE  = M.MRT_CP_CODE
                                 AND   D.DRT_BR_CODE  = M.MRT_BR_CODE
                                 AND   D.DRT_MRT_NUM  = M.MRT_NUM
                                 AND   D.DRT_MRT_DATE = M.MRT_DATE)
  WHERE M.MRT_CP_CODE        IS NOT NULL
  AND   M.MRT_MPT_ID         IS NOT NULL
  AND   M.MRT_MPF_FILE_NUM   IS NOT NULL
  AND   M.MRT_IPD_OPD_TYPE   <> 'OD'
  GROUP BY M.MRT_CP_CODE, M.MRT_MPT_ID, M.MRT_DATE, M.MRT_NUM, M.MRT_MRQ_NUM, M.MRT_MPF_FILE_NUM, M.MRT_SLIP_TYPE
  HAVING SUM(D.DRT_GROSS_AMT) > 0);

prompt
prompt Creating view HOS_TD_PAT_PHRM_RECORD
prompt ====================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_TD_PAT_PHRM_RECORD AS
(SELECT M.MSL_CP_CODE, M.MSL_PAT_ID, M.MSL_FILE_NO,
M.MSL_DATE, M.MSL_NUM, M.MSL_REF_NUM, M.MSL_MPF_FILE_NUM, M.MSL_SAL_TYPE,
DECODE(M.MSL_TYPE,'I',SUM(NVL(D.DSL_AMOUNT,0)),'R',SUM(NVL(D.DSL_AMOUNT,0)) * -1) AS DSL_AMOUNT,
DECODE(M.MSL_TYPE,'I',SUM(NVL(D.DSL_AMOUNT,0)),'R',SUM(NVL(D.DSL_AMOUNT,0)) * -1) AS DSL_NET_AMOUNT,
SUM(NVL(D.DSL_DISCOUNT,0)) AS DSL_DISCOUNT
FROM HOS_TM_SALES M
LEFT JOIN HOS_TD_SALES D ON (D.DSL_CP_CODE = M.MSL_CP_CODE
AND   D.DSL_MSL_NUM  = M.MSL_NUM
AND   D.DSL_MSL_TYPE = M.MSL_TYPE
AND   D.DSL_MSL_DATE = M.MSL_DATE)
WHERE M.MSL_CP_CODE IS NOT NULL
AND   M.MSL_PAT_ID IS NOT NULL
AND   M.MSL_MPF_FILE_NUM IS NOT NULL
AND   M.MSL_SAL_TYPE <> 'C'
GROUP BY M.MSL_CP_CODE, M.MSL_PAT_ID, M.MSL_FILE_NO,
M.MSL_DATE, M.MSL_NUM, M.MSL_REF_NUM, M.MSL_MPF_FILE_NUM,
M.MSL_SAL_TYPE, M.MSL_TYPE
HAVING SUM(D.DSL_AMOUNT) > 0);

prompt
prompt Creating function GET_PATIENT_FILE_GROSS_AMOUNT
prompt ===============================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_PATIENT_FILE_GROSS_AMOUNT" (ARG_CP_CODE VARCHAR2, ARG_MPF_FILE_NUM VARCHAR2)
RETURN NUMBER IS

LC_GRS_TOT NUMBER(13,2);

LC_ROOM_AMT NUMBER(13,2);
LC_SRV_AMT  NUMBER(13,2);
LC_SUR_AMT  NUMBER(13,2);
LC_VST_AMT  NUMBER(13,2);
LC_PHR_AMT  NUMBER(13,2);
LC_BLR_AMT  NUMBER(13,2);
LC_ADV_AMT  NUMBER(13,2);
LC_DISCOUNT NUMBER(13,2);

BEGIN
 SELECT NVL(SUM(NVL(DRM_NET_AMT,0)),0)
 INTO   LC_ROOM_AMT
 FROM   HOS_TD_PAT_ROOM_MOVM_INFO
 WHERE  DRM_CP_CODE = ARG_CP_CODE
 AND    DRM_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DHS_NET_AMT,0)),0)
 INTO   LC_SRV_AMT
 FROM   HOS_TD_PAT_HOSP_SRV
 WHERE  DHS_CP_CODE = ARG_CP_CODE

 AND    DHS_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DPS_AMT,0) + NVL(DPS_ANT_RATE,0) + NVL(DPS_OT_AMT,0)),0)
 INTO   LC_SUR_AMT
 FROM   HOS_TD_PAT_SUR
 WHERE  DPS_CP_CODE = ARG_CP_CODE
 AND    DPS_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DCV_NET_AMT,0)),0)
 INTO   LC_VST_AMT
 FROM   HOS_TD_CON_VISITS
 WHERE  DCV_CP_CODE = ARG_CP_CODE
 AND    DCV_MPF_FILE_NUM = ARG_MPF_FILE_NUM;


 SELECT NVL(SUM(NVL(DSL_NET_AMOUNT,0)),0)
 INTO   LC_PHR_AMT
 FROM   HOS_TD_PAT_PHRM_RECORD
 WHERE  MSL_CP_CODE = ARG_CP_CODE
 AND    MSL_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DRT_NET_AMT,0)),0)
 INTO   LC_BLR_AMT
 FROM   HOS_TD_PAT_BLOOD_RECORD
 WHERE  MRT_CP_CODE = ARG_CP_CODE
 AND    MRT_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 LC_GRS_TOT := NVL((LC_ROOM_AMT + LC_SRV_AMT + LC_SUR_AMT + LC_VST_AMT + LC_PHR_AMT + LC_BLR_AMT),0);

 RETURN NVL(LC_GRS_TOT,0);
END;
/

prompt
prompt Creating function GET_PATIENT_FILE_NET_AMT
prompt ==========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_PATIENT_FILE_NET_AMT (ARG_CP_CODE VARCHAR2, ARG_MPF_FILE_NUM VARCHAR2)
RETURN NUMBER IS

LC_NET_TOT NUMBER(13,2);
LC_ROOM_AMT NUMBER(13,2);
LC_SRV_AMT  NUMBER(13,2);
LC_SUR_AMT  NUMBER(13,2);
LC_VST_AMT  NUMBER(13,2);
LC_PHR_AMT  NUMBER(13,2);
LC_BLR_AMT  NUMBER(13,2);
LC_ADV_AMT  NUMBER(13,2);
LC_DISCOUNT NUMBER(13,2);

BEGIN
 SELECT NVL(SUM(NVL(DRM_NET_AMT,0)),0)
 INTO   LC_ROOM_AMT
 FROM   HOS_TD_PAT_ROOM_MOVM_INFO
 WHERE  DRM_CP_CODE = ARG_CP_CODE
 AND    DRM_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DHS_NET_AMT,0)),0)
 INTO   LC_SRV_AMT
 FROM   HOS_TD_PAT_HOSP_SRV
 WHERE  DHS_CP_CODE = ARG_CP_CODE

 AND    DHS_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DPS_AMT,0) + NVL(DPS_ANT_RATE,0) + NVL(DPS_OT_AMT,0)),0)
 INTO   LC_SUR_AMT
 FROM   HOS_TD_PAT_SUR
 WHERE  DPS_CP_CODE = ARG_CP_CODE
 AND    DPS_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DCV_NET_AMT,0)),0)
 INTO   LC_VST_AMT
 FROM   HOS_TD_CON_VISITS
 WHERE  DCV_CP_CODE = ARG_CP_CODE
 AND    DCV_MPF_FILE_NUM = ARG_MPF_FILE_NUM;


 SELECT NVL(SUM(NVL(DSL_NET_AMOUNT,0)),0)
 INTO   LC_PHR_AMT
 FROM   HOS_TD_PAT_PHRM_RECORD
 WHERE  MSL_CP_CODE = ARG_CP_CODE
 AND    MSL_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DRT_NET_AMT,0)),0) AS DRT_NET_AMT
 INTO   LC_BLR_AMT
 FROM   HOS_TD_PAT_BLOOD_RECORD
 WHERE  MRT_CP_CODE = ARG_CP_CODE
 AND    MRT_MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 SELECT NVL(SUM(NVL(DAD_AMT,0)),0)
 INTO   LC_ADV_AMT
 FROM   HOS_TD_PAT_ADV_INFO
 WHERE  DAD_CP_CODE = ARG_CP_CODE
 AND    NVL(DAD_STATUS,'Y') = 'Y'
 AND    DAD_MPF_FILE_NUM = ARG_MPF_FILE_NUM;


 SELECT NVL(SUM(NVL(MPF_DISC_AMT,0)),0)
 INTO   LC_DISCOUNT
 FROM   HOS_TM_PATIENT_FILE
 WHERE  MPF_CP_CODE = ARG_CP_CODE
 AND    MPF_FILE_NUM = ARG_MPF_FILE_NUM;

 LC_NET_TOT := NVL((LC_ROOM_AMT + LC_SRV_AMT + LC_SUR_AMT + LC_VST_AMT + LC_PHR_AMT + LC_BLR_AMT),0);
 LC_NET_TOT := LC_NET_TOT - NVL(LC_ADV_AMT,0);
 LC_NET_TOT := ROUND((LC_NET_TOT - NVL(LC_DISCOUNT,0)),0);

 RETURN NVL(LC_NET_TOT,0);
END;
/

prompt
prompt Creating view CHECK_DEFICIENT_PATIENT_FILE
prompt ==========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.CHECK_DEFICIENT_PATIENT_FILE AS
SELECT "MPF_FILE_NUM","MPF_BR_CODE","MPF_ADM_DATE","MPF_DIS_DATE","MPF_GRS_AMT","MPF_ADVANCE_AMT","MPF_DISC_AMT","MPF_NET_TOT","MPF_MPT_LIMIT","MPF_CMP_AMT","MPF_MPT_AMT","MBP_DATE","MBP_AMT","MBF_DATE","MBF_NUM","MBF_NET_AMT","DTL_GRS_AMT","DTL_NET_AMT" FROM
(
SELECT MPF_FILE_NUM, MPF_BR_CODE, MPF_ADM_DATE, MPF_DIS_DATE, MPF_GRS_AMT, MPF_ADVANCE_AMT, MPF_DISC_AMT, MPF_NET_TOT,
MPF_MPT_LIMIT, MPF_CMP_AMT, MPF_MPT_AMT, MBP_DATE, MBP_AMT, MBF_DATE, MBF_NUM, MBF_NET_AMT,
GET_PATIENT_FILE_GROSS_AMOUNT(MPF_CP_CODE, MPF_FILE_NUM) AS DTL_GRS_AMT,
GET_PATIENT_FILE_NET_AMT(MPF_CP_CODE, MPF_FILE_NUM) AS DTL_NET_AMT
FROM HOS_TM_PATIENT_FILE
LEFT JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_TO_BILL_PROCESS_FINAL ON (MBF_CP_CODE = MPF_CP_CODE AND  MBF_MPF_FILE_NUM = MPF_FILE_NUM)
)
WHERE MBP_DATE IS NOT NULL
  AND (NVL(MPF_GRS_AMT,0) <> NVL(DTL_GRS_AMT,0)
  OR NVL(MPF_NET_TOT,0) <> NVL(DTL_NET_AMT,0)
  OR NVL(MPF_NET_TOT,0) <> (NVL(MPF_GRS_AMT,0) - NVL(MPF_ADVANCE_AMT,0) - NVL(MPF_DISC_AMT,0))
  OR (MBP_DATE IS NOT NULL AND NVL(MBP_AMT,0) <> NVL(MPF_NET_TOT,0))
  OR (MBF_NUM IS NOT NULL AND NVL(MPF_NET_TOT,0) <> NVL(MBF_NET_AMT,0))
  OR (NVL(MPF_MPT_LIMIT,0) > 0 AND NVL(MPF_MPT_LIMIT,0) <> (NVL(MPF_MPT_AMT,0) + NVL(MPF_CMP_AMT,0))))
ORDER BY MPF_BR_CODE, MPF_DIS_DATE, MPF_FILE_NUM;

prompt
prompt Creating view IPD_REG_NETAMT
prompt ============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.IPD_REG_NETAMT AS
(
SELECT CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE, SUM(CBL_NET_AMT) AS CBL_NET_AMT
FROM (
SELECT MPR_CP_CODE AS CBL_CP_CODE, MPR_REG_NUM AS CBL_SLIP_NUM, MPR_MPA_CODE AS CBL_MPA_CODE, MPR_AMT_IN_ADV AS CBL_NET_AMT
FROM HOS_TM_PAT_REGISTRATION
WHERE MPR_REG_TYPE = 'R'
AND   MPR_MPA_CODE IS NOT NULL
UNION ALL
SELECT MRR_CP_CODE AS ABL_CP_CODE, MRR_MPR_REG_NUM AS CBL_SLIP_NUM, MPR_MPA_CODE AS CBL_MPA_CODE, -1*(MRR_HOS_AMT + MRR_NET_AMT) AS
CBL_NET_AMT
FROM HOS_TM_REG_REFUND, HOS_TM_PAT_REGISTRATION
WHERE MRR_CP_CODE = MPR_CP_CODE
AND   MRR_MPR_REG_NUM = MPR_REG_NUM
AND   MRR_MPT_ID = MPR_MPT_ID
AND   MPR_MPA_CODE IS NOT NULL
AND   MPR_REG_TYPE = 'R')
GROUP BY CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE);

prompt
prompt Creating view COMPANY_BILLING
prompt =============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.COMPANY_BILLING AS
(
SELECT 'A' LC_SEQ, MCR_CP_CODE AS CBL_CP_CODE, MCR_NUM AS CBL_SLIP_NUM, MCR_REF_NUM AS CBL_REF_NUM, MCR_DATE AS CBL_SLIP_DATE,
MCR_MPA_CODE AS CBL_MPA_CODE, MCR_MCT_CODE AS CBL_MCT_CODE, MCR_DEP_CODE AS CBL_DEP_CODE, MCR_MPT_ID  AS CBL_MPT_ID,
MCR_EMP_ID AS CBL_EMP_ID, MCR_EMP_NAME AS CBL_EMP_NAME, MCR_EMP_RELATION AS CBL_EMP_RELATION,
MCR_EMP_VALID AS CBL_EMP_VALID, 'OPD RCPT-' || TO_CHAR(MCR_DATE,'MONYY') CBL_SLIP_TYPE,
MCR_EMP_LIMIT AS CBL_EMP_LIMIT, MCR_EMP_APPROVAL AS CBL_EMP_APPROVAL, MCR_EMP_APP_REF AS CBL_EMP_APP_REF,
MCR_EMP_APP_DATE AS CBL_EMP_APP_DATE, MCR_EMP_APP_REMARKS AS CBL_EMP_APP_REMARKS,
--DECODE(MCR_RCP_TYPE, 'RC', MCR_NET_AMT, MCR_NET_AMT*-1) AS CBL_NET_AMT
DECODE(MCR_RCP_TYPE, 'RC', MCR_DUE_AMT , MCR_DUE_AMT*-1) AS CBL_NET_AMT
FROM HOS_TM_OPD_CON_RCPT
WHERE MCR_TYPE     ='R'
AND   MCR_MPA_CODE IS NOT NULL
AND   MCR_RCP_TYPE IN('RC','RR')
AND   MCR_NF_TYPE  = 'N'
UNION ALL
SELECT 'B' LC_SEQ, MSR_CP_CODE AS CBL_CP_CODE, MSR_NUM AS CBL_SLIP_NUM, MSR_REF_NUM CBL_REF_NUM, MSR_DATE AS CBL_SLIP_DATE, MSR_MPA_CODE AS CBL_MPA_CODE,
 MSR_MCT_CODE AS CBL_MCT_CODE, MSR_DEP_CODE AS CBL_DEP_CODE, MSR_PAT_ID AS CBL_MPT_ID, MSR_EMP_ID AS CBL_EMP_ID,
MSR_EMP_NAME AS CBL_EMP_NAME, MSR_EMP_RELATION AS CBL_EMP_RELATION, MSR_EMP_VALID AS CBL_EMP_VALID, 'OPD SRV-' || TO_CHAR(MSR_DATE,'MONYY') AS CBL_SLIP_TYPE,
MSR_EMP_LIMIT AS CBL_EMP_LIMIT, MSR_EMP_APPROVAL AS CBL_EMP_APPROVAL, MSR_EMP_APP_REF AS CBL_EMP_APP_REF,
MSR_EMP_APP_DATE AS CBL_EMP_APP_DATE, MSR_EMP_APP_REMARKS AS CBL_EMP_APP_REMARKS,
DECODE(MSR_REF_TYPE,'I',MSR_DUE_AMT, - MSR_DUE_AMT)  AS CBL_NET_AMT
----SUM(NVL(DSR_RATE,0)*NVL(DSR_QTY,0)) - NVL(MSR_DISCOUNT,0),-SUM(NVL(DSR_RATE,0)*NVL(DSR_QTY,0)) - NVL(MSR_DISCOUNT,0)) AS CBL_NET_AMT
FROM HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT
WHERE  MSR_CP_CODE  = DSR_CP_CODE
AND    MSR_NF_TYPE  = DSR_MSR_NF_TYPE
AND    MSR_DATE     = DSR_MSR_DATE
AND    MSR_NUM      = DSR_MSR_NUM
AND    MSR_PAT_TYPE = DSR_MSR_PAT_TYPE
AND    MSR_TYPE     = 'R'
AND    MSR_REF_TYPE IN('I','R')
AND    MSR_MPA_CODE IS NOT NULL
AND    MSR_NF_TYPE = 'N'
GROUP BY MSR_CP_CODE, MSR_NUM, MSR_REF_NUM, MSR_DATE, MSR_MPA_CODE,
 MSR_MCT_CODE, MSR_DEP_CODE, MSR_PAT_ID, MSR_EMP_ID,
MSR_EMP_NAME, MSR_EMP_RELATION, MSR_EMP_VALID, 'OPD SRV-' || TO_CHAR(MSR_DATE,'MONYY'),
MSR_EMP_LIMIT, MSR_EMP_APPROVAL, MSR_EMP_APP_REF,
MSR_EMP_APP_DATE, MSR_EMP_APP_REMARKS, MSR_REF_TYPE , MSR_DUE_AMT
---NVL(MSR_DISCOUNT,0)
UNION ALL
SELECT 'C' LC_SEQ, MBP_CP_CODE CBL_CP_CODE, MBP_MPF_FILE_NUM AS CBL_SLIP_NUM, NULL CBL_REF_NUM, MBP_DATE CBL_SLIP_DATE,
MPF_MPA_CODE CBL_MPA_CODE, MPF_MCT_CODE CBL_MCT_CODE, MPF_DEP_CODE AS CBL_DEP_CODE, MBP_MPT_ID CBL_MPT_ID,
MPF_EMP_ID CBL_EMP_ID, MPF_EMP_NAME CBL_EMP_NAME, MPF_EMP_RELATION CBL_EMP_RELATION, MPF_EMP_VALID CBL_EMP_VALID,
MBP_MPF_FILE_NUM CBL_SLIP_TYPE, MPF_MPT_LIMIT CBL_EMP_LIMIT, MPF_EMP_APPROVAL CBL_EMP_APPROVAL,
MPF_EMP_APP_REF CBL_EMP_APP_REF, MPF_EMP_APP_DATE CBL_EMP_APP_DATE, MPF_EMP_APP_REMARKS CBL_EMP_APP_REMARKS,
MBP_AMT CBL_NET_AMT
FROM HOS_TO_BILL_PROCESS, HOS_TM_PATIENT_FILE
WHERE MBP_CP_CODE = MPF_CP_CODE
AND   MBP_MPF_FILE_NUM = MPF_FILE_NUM
AND   MBP_MPT_ID   = MPF_MPT_ID
AND   MPF_TYPE = 'R'
AND   MBP_AMT > 0
AND   MPF_MPA_CODE IS NOT NULL
UNION ALL
SELECT 'D' LC_SEQ, MSL_CP_CODE AS CBL_CP_CODE, MSL_NUM AS CBL_SLIP_NUM, MSL_REF_NUM AS CBL_REF_NUM,
MSL_DATE CBL_SLIP_DATE, MSL_MPA_CODE AS CBL_MPA_CODE, NULL CBL_MCT_CODE, NULL AS CBL_DEP_CODE,
MSL_PAT_ID AS CBL_MPT_ID, MSL_EMP_ID CBL_EMP_ID, MSL_EMP_NAME CBL_EMP_NAME,
MSL_EMP_RELATION AS CBL_EMP_RELATION, MSL_EMP_VALID CBL_EMP_VALID,
'PHARMACY-' || TO_CHAR(MSL_DATE,'MONYY') CBL_SLIP_TYPE, NULL CBL_EMP_LIMIT,
MSL_EMP_APPROVAL CBL_EMP_APPROVAL, MSL_EMP_APP_REF CBL_EMP_APP_REF, MSL_EMP_APP_DATE  CBL_EMP_APP_DATE,
NULL CBL_EMP_APP_REMARKS, SUM(NVL(DSL_MIN_RATE,0) * NVL(DSL_MIN_QTY,0)) AS CBL_NET_AMT
FROM HOS_TD_SALES, HOS_TM_SALES
WHERE DSL_CP_CODE  = MSL_CP_CODE
AND   DSL_MSL_NUM  = MSL_NUM
AND   DSL_MSL_TYPE = MSL_TYPE
AND   DSL_MSL_DATE = MSL_DATE
AND   MSL_SAL_TYPE = 'R'
AND   MSL_TYPE     = 'I'
AND   MSL_MPA_CODE IS NOT NULL
GROUP BY MSL_CP_CODE, MSL_DATE, MSL_NUM, MSL_REF_NUM, MSL_MPA_CODE, MSL_PAT_ID, MSL_EMP_ID,
MSL_EMP_NAME, MSL_EMP_RELATION, MSL_EMP_VALID, MSL_EMP_APPROVAL, MSL_EMP_APP_REF,
MSL_EMP_APP_DATE
UNION ALL
SELECT 'D' LC_SEQ, MSL_CP_CODE AS CBL_CP_CODE, MSL_NUM AS CBL_SLIP_NUM, MSL_REF_NUM AS CBL_REF_NUM,
MSL_DATE CBL_SLIP_DATE, MSL_MPA_CODE AS CBL_MPA_CODE, NULL CBL_MCT_CODE, NULL AS CBL_DEP_CODE,
MSL_PAT_ID AS CBL_MPT_ID, MSL_EMP_ID CBL_EMP_ID, MSL_EMP_NAME CBL_EMP_NAME,
MSL_EMP_RELATION AS CBL_EMP_RELATION, MSL_EMP_VALID CBL_EMP_VALID,
'PHARMACY-' || TO_CHAR(MSL_DATE,'MONYY') CBL_SLIP_TYPE, NULL CBL_EMP_LIMIT,
MSL_EMP_APPROVAL CBL_EMP_APPROVAL, MSL_EMP_APP_REF CBL_EMP_APP_REF, MSL_EMP_APP_DATE  CBL_EMP_APP_DATE,
NULL CBL_EMP_APP_REMARKS, -SUM(NVL(DSL_MIN_RATE,0) * NVL(DSL_MIN_QTY,0)) AS CBL_NET_AMT
FROM HOS_TD_SALES, HOS_TM_SALES
WHERE DSL_CP_CODE  = MSL_CP_CODE
AND   DSL_MSL_NUM  = MSL_NUM
AND   DSL_MSL_TYPE = MSL_TYPE
AND   DSL_MSL_DATE = MSL_DATE
AND   MSL_SAL_TYPE = 'R'
AND   MSL_TYPE     = 'R'
AND   MSL_MPA_CODE IS NOT NULL
GROUP BY MSL_CP_CODE, MSL_DATE, MSL_NUM, MSL_REF_NUM, MSL_MPA_CODE, MSL_PAT_ID, MSL_EMP_ID,
MSL_EMP_NAME, MSL_EMP_RELATION, MSL_EMP_VALID, MSL_EMP_APPROVAL, MSL_EMP_APP_REF,
MSL_EMP_APP_DATE
UNION ALL
SELECT 'E' LC_SEQ, CBL_CP_CODE, CBL_SLIP_NUM, NULL AS CBL_REF_NUM, MPR_REG_DATE AS CBL_SLIP_DATE, CBL_MPA_CODE,
MPR_MCT_CODE AS CBL_MCT_CODE, MPR_DEP_CODE AS CBL_DEP_CODE, MPR_MPT_ID AS CBL_MPT_ID, MPR_EMP_ID AS CBL_EMP_ID,
MPR_EMP_NAME AS CBL_EMP_NAME, MPR_EMP_RELATION AS CBL_EMP_RELATION, MPR_EMP_VALID AS CBL_EMP_VALID,
'IPD REG' AS CBL_SLIP_TYPE, NULL AS CBL_EMP_LIMIT, MPR_EMP_APPROVAL AS CBL_EMP_APPROVAL, MPR_EMP_APP_REF AS CBL_EMP_APP_REF,
MPR_EMP_APP_DATE AS CBL_EMP_APP_DATE, MPR_APP_REMARKS CBL_EMP_APP_REMARKS, SUM(CBL_NET_AMT) AS CBL_NET_AMT
FROM HOS_TM_PAT_REGISTRATION, IPD_REG_NETAMT
WHERE MPR_REG_TYPE = 'R'
AND   MPR_MPA_CODE IS NOT NULL
AND   MPR_CP_CODE  = CBL_CP_CODE
AND   MPR_REG_NUM  = CBL_SLIP_NUM
AND   MPR_MPA_CODE = CBL_MPA_CODE
GROUP BY CBL_CP_CODE, CBL_SLIP_NUM, MPR_REG_DATE, CBL_MPA_CODE, MPR_MCT_CODE, MPR_DEP_CODE, MPR_MPT_ID,
MPR_EMP_ID, MPR_EMP_NAME,MPR_EMP_RELATION, MPR_EMP_VALID, MPR_EMP_APPROVAL, MPR_EMP_APP_REF, MPR_EMP_APP_DATE, MPR_APP_REMARKS
UNION ALL
SELECT 'F' LC_SEQ, MRT_CP_CODE AS CBL_CP_CODE, MRT_NUM AS CBL_SLIP_NUM, MRT_REF_NUM CBL_REF_NUM, MRT_DATE AS CBL_SLIP_DATE, MRT_MPA_CODE AS CBL_MPA_CODE,
 MRT_MCT_CODE AS CBL_MCT_CODE, NULL AS CBL_DEP_CODE, MRT_MPT_ID AS CBL_MPT_ID, MRT_EMP_ID AS CBL_EMP_ID,
MRT_EMP_NAME AS CBL_EMP_NAME, MRT_EMP_RELATION AS CBL_EMP_RELATION, MRT_EMP_VALID AS CBL_EMP_VALID,'BLD BNK-' || TO_CHAR(MRT_DATE,'MONYY') AS CBL_SLIP_TYPE,
MRT_EMP_LIMIT AS CBL_EMP_LIMIT, MRT_EMP_APPROVAL AS CBL_EMP_APPROVAL, MRT_EMP_APP_REF AS CBL_EMP_APP_REF,
MRT_EMP_APP_DATE AS CBL_EMP_APP_DATE, MRT_DUE_REMARKS AS CBL_EMP_APP_REMARKS,
DECODE(MRT_REF_FLAG,'I',MRT_DUE_AMT, - MRT_DUE_AMT) AS CBL_NET_AMT
FROM BBM_TM_RECEIPT,BBM_TD_RECEIPT
WHERE MRT_CP_CODE  = DRT_CP_CODE
AND   MRT_BR_CODE  = DRT_BR_CODE
AND   MRT_NUM      = DRT_MRT_NUM
AND    MRT_SLIP_TYPE     = 'R'
AND    MRT_REF_FLAG          = 'I'
AND    MRT_MPA_CODE IS NOT NULL
AND    0 <> (SELECT COUNT(*) FROM BBM_TD_RECEIPT WHERE DRT_CP_CODE = MRT_CP_CODE AND DRT_MRT_NUM = MRT_NUM AND DRT_MRT_DATE = MRT_DATE)
GROUP BY MRT_CP_CODE, MRT_NUM, MRT_REF_NUM, MRT_DATE, MRT_MPA_CODE,
 MRT_MCT_CODE, MRT_MPT_ID, MRT_EMP_ID,MRT_REF_FLAG,
MRT_EMP_NAME, MRT_EMP_RELATION, MRT_EMP_VALID, 'BLD BNK-' || TO_CHAR(MRT_DATE,'MONYY'),
MRT_EMP_LIMIT, MRT_EMP_APPROVAL, MRT_EMP_APP_REF,
MRT_EMP_APP_DATE, MRT_DUE_REMARKS , MRT_DUE_AMT)
;

prompt
prompt Creating view COMPANY_OUTSTANDING_SLIPS
prompt =======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.COMPANY_OUTSTANDING_SLIPS AS
(
SELECT DCB_CP_CODE, DCB_MCB_MPA_CODE, DCB_MCB_DATE_FM, DCB_MCB_DATE_TO, DCB_MCB_NUM,
 DCB_SLIP_NUM, DCB_SLIP_DATE, DCB_SLIP_TYPE, DCB_MPT_ID, DCB_EMP_NAME, DCB_EMP_ID,  DCB_EMP_VALID, DCB_MCT_CODE, DCB_DEP_CODE, DCB_MCB_MPA_TYPE,
 SUM(NVL(DCB_SLIP_AMOUNT,0)) DCB_SLIP_AMOUNT,
 SUM(NVL(DCB_RCVD_AMT,0)) DCB_RCVD_AMT,
 SUM(NVL(DCB_SLIP_AMOUNT,0)) - SUM(NVL(DCB_RCVD_AMT,0)) AS BAL_AMT
FROM (
SELECT  DCB_CP_CODE, DCB_MCB_DATE, DCB_MCB_MPA_CODE, DCB_MCB_DATE_FM, DCB_MCB_DATE_TO, DCB_MCB_NUM,
 DCB_SLIP_NUM, DCB_SLIP_DATE, DCB_SLIP_TYPE, DCB_MPT_ID, DCB_EMP_NAME, DCB_EMP_ID,  DCB_EMP_VALID, DCB_MCT_CODE, DCB_DEP_CODE, DCB_MCB_MPA_TYPE,
 NVL(DCB_SLIP_AMOUNT,0) DCB_SLIP_AMOUNT, 0 DCB_RCVD_AMT
FROM    HOS_TD_COMPANY_BILL
WHERE   DCB_MCB_TYPE = 'V'
UNION ALL
SELECT  DCB_CP_CODE, DCB_MCB_DATE, DCB_MCB_MPA_CODE, DCB_MCB_DATE_FM, DCB_MCB_DATE_TO, DCB_REF_NUM,
 DCB_SLIP_NUM, DCB_SLIP_DATE, DCB_SLIP_TYPE, DCB_MPT_ID, DCB_EMP_NAME, DCB_EMP_ID,  DCB_EMP_VALID, DCB_MCT_CODE, DCB_DEP_CODE, DCB_MCB_MPA_TYPE,
 0, NVL(DCB_RCVD_AMT, 0)
FROM    HOS_TD_COMPANY_BILL
WHERE DCB_MCB_TYPE = 'T'
)
GROUP BY DCB_CP_CODE, DCB_MCB_MPA_CODE, DCB_MCB_DATE_FM, DCB_MCB_DATE_TO, DCB_MCB_NUM,
 DCB_SLIP_NUM, DCB_SLIP_DATE, DCB_SLIP_TYPE, DCB_MPT_ID, DCB_EMP_NAME, DCB_EMP_ID,  DCB_EMP_VALID, DCB_MCT_CODE, DCB_MCB_MPA_TYPE, DCB_DEP_CODE
HAVING  SUM(NVL(DCB_SLIP_AMOUNT,0)) - SUM(NVL(DCB_RCVD_AMT,0)) > 0);

