prompt Creating view DEFICIENT_CON_RECEPTS
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DEFICIENT_CON_RECEPTS AS
(
SELECT MCR_CP_CODE, MCR_BR_CODE , NVL(MCR_REF_NUM,MCR_NUM) AS MCR_SLIP_NUM, MCR_NUM, MCR_REF_NUM, MCR_DATE, SUM(MCR_NET_AMT) MCR_NET_AMT,
SUM(MCR_HOS_AMT) MCR_HOS_AMT, SUM(MCR_MCT_AMT) MCR_MCT_AMT,
SUM(MCR_PAT_REG_FEE) AS MCR_PAT_REG_FEE, MCR_UPD_USER
FROM HOS_TM_OPD_CON_RCPT
GROUP BY  MCR_CP_CODE, MCR_BR_CODE , MCR_NUM, MCR_REF_NUM, MCR_DATE, MCR_UPD_USER
HAVING SUM(MCR_NET_AMT) <> (SUM(MCR_HOS_AMT) + SUM(MCR_MCT_AMT))
);

