SUM(DSR_NET_AMT) MCR_NET_AMT,
SUM(DSR_HOS_AMT) MCR_HOS_AMT, SUM(DSR_MCT_AMT) MCR_MCT_AMT,
DSR_UPD_USER, DSR_MCT_CODE
