prompt Creating view DEFICIENT_STOCK
prompt =============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DEFICIENT_STOCK AS
SELECT "TR_NATURE","TR_TRN_TYPE","TR_DATE","TR_DOC_NUM","TR_DIT_CODE","DIT_DESC","TR_QTY","TR_SEQ_NUM","TR_LOC_CODE","MPB_IN_NUM" FROM (
SELECT '(+)TR(-)PM' AS TR_NATURE, TR_TRN_TYPE, TR_DATE, TR_DOC_NUM, TR_DIT_CODE,  DIT_DESC, TR_QTY,
TR_SEQ_NUM, TR_LOC_CODE, MPB_IN_NUM
FROM (
SELECT   0 AS TR_TYPE,  'OB' AS TR_TRN_TYPE, DOI_FYR_FM AS TR_DATE,
  'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD') AS TR_DOC_NUM,
  DOI_DIT_CODE AS TR_DIT_CODE,
  DOI_QTY AS TR_QTY,
  ROUND(DOI_QTY * DOI_MIN_ADD_COST,4) AS TR_AMT,
  DOI_SEQ_NUM AS TR_SEQ_NUM, DOI_LOC_CODE AS TR_LOC_CODE
FROM    PPI_SD_ITEM_OPNBAL
WHERE   DOI_CP_CODE = '01'
AND      DOI_LOC_CODE  LIKE '%'
AND      DOI_FYR_FM <= SYSDATE
