prompt Creating view DIS_VW_DONATION_HEADS
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DIS_VW_DONATION_HEADS AS
SELECT DH5_CP_CODE, DH5_DESC, DH5_CODE, DH4_DESC, DH4_CODE, DH3_DESC, DH3_CODE, DH2_DESC, DH2_CODE, DH1_DESC, DH1_CODE, DH5_FLAG, DH5_DNT_CODE, DNT_DESC
FROM DIS_SD_DONATION_HEAD05
LEFT JOIN DIS_SD_DONATION_HEAD04 ON (DH4_CP_CODE = DH5_CP_CODE AND DH4_CODE = DH5_DH4_CODE)
LEFT JOIN DIS_SD_DONATION_HEAD03 ON (DH3_CP_CODE = DH4_CP_CODE AND DH3_CODE = DH4_DH3_CODE)
LEFT JOIN DIS_SD_DONATION_HEAD02 ON (DH2_CP_CODE = DH3_CP_CODE AND DH2_CODE = DH3_DH2_CODE)
LEFT JOIN DIS_SM_DONATION_HEAD01 ON (DH1_CP_CODE = DH2_CP_CODE AND DH1_CODE = DH2_DH1_CODE)
LEFT JOIN DIS_SO_DONATION_TYPES  ON (DNT_CP_CODE = DH5_CP_CODE AND DNT_CODE = DH5_DNT_CODE);

