prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DIS_VW_DONATION_RECEIPT AS
SELECT   MDR_CP_CODE, MDR_BR_CODE, MDR_DATE,  MDR_NUM, MDR_DNR_NAME, MDR_REF_NUM, MDR_TYPE, MDR_FC_FLAG, MDR_MAN_NUM,
  MDR_CHQ_NUM, MDR_CHQ_DATE, MDR_CHQ_BNK, MDR_REMARKS, MDR_FC_RATE, MDR_FC_AMOUNT, MDR_AMOUNT, MDR_PST_FLAG, MDR_MVH_NUM,
  DOT_DESC, MDR_DOT_CODE, DNR_NAME, MDR_DNR_NUM, LL3_DESC, MDR_LL3_CODE, CUR_DESC, MDR_CUR_CODE, PYM_DESC, PYM_CHQ_FLAG, MDR_PYM_CODE,
  DIS_SO_DONATION_TYPES.DNT_DESC AS DNT_DESC, DDR_DNT_CODE, DDR_DH5_CODE, DH5_DESC, DH4_DESC, DH3_DESC, DH2_DESC, DH1_DESC, DDR_FC_FLAG, DDR_FC_RATE, DDR_FC_AMOUNT,
  DDR_AMOUNT, DDR_REMARKS, DDR_RCP_TYPE, BR_FUL_NAME
FROM DIS_TM_DONATION_RECEIPT
LEFT JOIN DIS_TD_DONATION_RECEIPT ON (DDR_CP_CODE = MDR_CP_CODE
AND DDR_BR_CODE = MDR_BR_CODE
 AND DDR_MDR_DATE = MDR_DATE
 AND DDR_MDR_NUM = MDR_NUM)
LEFT JOIN DIS_SO_DONOR_TYPES ON (DOT_CP_CODE = MDR_CP_CODE AND DOT_CODE = MDR_DOT_CODE)
LEFT JOIN DIS_SO_DONORS ON (DNR_CP_CODE = MDR_CP_CODE AND DNR_NUM = MDR_DNR_NUM)
LEFT JOIN DIS_SD_LOC_LEVEL03 ON (LL3_CP_CODE = MDR_CP_CODE AND LL3_CODE = MDR_LL3_CODE)
LEFT JOIN ISR_SO_CURRENCY ON (CUR_CP_CODE = MDR_CP_CODE AND CUR_CODE = MDR_CUR_CODE)
LEFT JOIN DIS_SO_PAY_MODES ON (PYM_CP_CODE = MDR_CP_CODE AND PYM_CODE = MDR_PYM_CODE)
LEFT JOIN DIS_SO_DONATION_TYPES ON (DNT_CP_CODE = DDR_CP_CODE AND DNT_CODE = DDR_DNT_CODE)
LEFT JOIN DIS_VW_DONATION_HEADS ON (DH5_CP_CODE = DDR_CP_CODE AND DH5_CODE = DDR_DH5_CODE)
LEFT JOIN ISR_XM_BRANCH ON (BR_CP_CODE = MDR_CP_CODE AND BR_CODE = MDR_BR_CODE);

