prompt Creating view DIS_VW_DONORS
prompt ===========================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DIS_VW_DONORS AS
SELECT DNR_CP_CODE, DNR_BR_CODE, BR_FUL_NAME, DNR_NUM, DNR_DOT_CODE, DOT_DESC, DNR_NAME, DNR_CNIC_NBR, DNR_ADDRESS,
 DNR_CITY, DNR_COUNTRY, DNR_PHONE1, DNR_PHONE2, DNR_PHONE3, DNR_EMAIL, DNR_LL3_CODE, LL3_DESC, LL2_CODE, LL2_DESC,
 LL1_CODE, LL1_DESC, DNR_CARE_OF, DNR_BANK_DETAL, DNR_REMARKS, DNR_FLAG
FROM     DIS_SO_DONORS
LEFT JOIN DIS_SO_DONOR_TYPES ON (DOT_CP_CODE = DNR_CP_CODE AND DOT_CODE = DNR_DOT_CODE)
LEFT JOIN DIS_SD_LOC_LEVEL03 ON (LL3_CP_CODE = DNR_CP_CODE AND LL3_CODE = DNR_LL3_CODE)
LEFT JOIN DIS_SD_LOC_LEVEL02 ON (LL2_CP_CODE = LL3_CP_CODE AND LL2_CODE = LL3_LL2_CODE)
LEFT JOIN DIS_SM_LOC_LEVEL01 ON (LL1_CP_CODE = LL2_CP_CODE AND LL1_CODE = LL2_LL1_CODE)
LEFT JOIN ISR_XM_BRANCH      ON (BR_CP_cODE  = DNR_CP_CODE AND BR_CODE  = DNR_BR_CODE);

prompt
prompt Creating view DIS_VW_DONATION_PAYMENT
prompt =====================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.DIS_VW_DONATION_PAYMENT AS
SELECT   MDP_CP_CODE, MDP_BR_CODE, MDP_DATE,  MDP_NUM, MDP_PAR_NAME, MDP_REF_NUM, MDP_TYPE, MDP_FC_FLAG, MDP_MAN_NUM,
  MDP_CHQ_NUM, MDP_CHQ_DATE, MDP_CHQ_BNK, MDP_REMARKS, MDP_FC_RATE, MDP_FC_AMOUNT, MDP_AMOUNT, MDP_PST_FLAG, MDP_MVH_NUM,
  PYT_DESC, MDP_PYT_CODE, PAR_NAME, MDP_PAR_NUM, DIS_SD_LOC_LEVEL03.LL3_DESC, MDP_LL3_CODE, ISR_SO_CURRENCY.CUR_DESC, DIS_TM_DONATION_PAYMENT.MDP_CUR_CODE, DIS_SO_PAY_MODES.PYM_DESC,
  DIS_SO_PAY_MODES.PYM_CHQ_FLAG, DIS_TM_DONATION_PAYMENT.MDP_PYM_CODE,
  DIS_SO_DONATION_TYPES.DNT_DESC AS DNT_DESC, DDP_DNT_CODE, DDP_DH5_CODE, DIS_VW_DONATION_HEADS.DH5_DESC AS DH5_DESC,
  DIS_VW_DONATION_HEADS.DH4_DESC, DIS_VW_DONATION_HEADS.DH3_DESC, DIS_VW_DONATION_HEADS.DH2_DESC, DIS_VW_DONATION_HEADS.DH1_DESC, DDP_FC_FLAG, DDP_FC_RATE, DDP_FC_AMOUNT,
  DDP_AMOUNT, DDP_REMARKS, MDR_DATE, MDR_NUM, MDR_DNR_NAME, MDR_DNR_NUM, ISR_XM_BRANCH.BR_FUL_NAME AS BR_FUL_NAME
FROM DIS_TM_DONATION_PAYMENT
LEFT JOIN DIS_TD_DONATION_PAYMENT ON (DDP_CP_CODE = MDP_CP_CODE AND DDP_BR_CODE = MDP_BR_CODE AND DDP_MDP_DATE = MDP_DATE AND DDP_MDP_NUM = MDP_NUM)
LEFT JOIN DIS_VW_DONATION_RECEIPT ON (MDR_CP_CODE = DDP_CP_CODE AND MDR_BR_CODE = DDP_BR_CODE AND MDR_DATE = DDP_MDR_DATE AND MDR_NUM = DDP_MDR_NUM)
LEFT JOIN DIS_SO_PARTY_TYPES ON (PYT_CP_CODE = MDP_CP_CODE AND PYT_CODE = MDP_PYT_CODE)
LEFT JOIN DIS_SO_PARTIES ON (PAR_CP_CODE = MDP_CP_CODE AND PAR_NUM = MDP_PAR_NUM)
LEFT JOIN DIS_SD_LOC_LEVEL03 ON (LL3_CP_CODE = MDP_CP_CODE AND LL3_CODE = MDP_LL3_CODE)
LEFT JOIN ISR_SO_CURRENCY ON (CUR_CP_CODE = MDP_CP_CODE AND CUR_CODE = MDP_CUR_CODE)
LEFT JOIN DIS_SO_PAY_MODES ON (PYM_CP_CODE = MDP_CP_CODE AND PYM_CODE = MDP_PYM_CODE)
LEFT JOIN DIS_SO_DONATION_TYPES ON (DNT_CP_CODE = DDP_CP_CODE AND DNT_CODE = DDP_DNT_CODE)
LEFT JOIN DIS_VW_DONATION_HEADS ON (DH5_CP_CODE = DDP_CP_CODE AND DH5_CODE = DDP_DH5_CODE)
LEFT JOIN DIS_VW_DONORS ON (DNR_CP_CODE = MDR_CP_CODE AND DNR_NUM = MDR_DNR_NUM)
LEFT JOIN ISR_XM_BRANCH ON (BR_CP_CODE = MDP_CP_CODE AND BR_CODE = MDP_BR_CODE);

