prompt Creating view EMPLOYEE_LIST
prompt ===========================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.EMPLOYEE_LIST AS
SELECT A.DED_EMP_CODE, A.DED_DP_CODE, E.EMP_NAME, D.DP_NAME, DMI_EMP_MAC_ID
FROM   PAY_SD_EMP_DEPT A, PAY_SM_EMPLOYEE E, ISR_XD_DEPT D, PAY_SD_EMP_MACHINE_IDS S
WHERE  A.DED_EMP_CODE = E.EMP_CODE
AND    A.DED_DP_CODE  = D.DP_CODE
AND    E.EMP_CODE    =  S.DMI_EMP_CODE
AND    A.DED_DATE    = (SELECT MAX(B.DED_DATE)
                        FROM   PAY_SD_EMP_DEPT B
                        WHERE  B.DED_CP_CODE  = A.DED_CP_CODE
                        AND    B.DED_EMP_CODE = A.DED_EMP_CODE
                        AND    B.DED_DATE    <= SYSDATE);

