prompt Creating view GET_AUTH_BRANCH
prompt =============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.GET_AUTH_BRANCH AS
SELECT USD_CP_CODE AUT_CP_CODE
        , USD_NAME  AUT_NAME , USD_DEFAULT_BR_CODE AUT_BR_CODE,
       (SELECT BR_FUL_NAME
          FROM ISR_XM_BRANCH
         WHERE BR_CP_CODE = USD_CP_CODE
           AND BR_CODE = USD_DEFAULT_BR_CODE) AUT_DESC
  FROM ISR_XD_USERS
 WHERE USD_ACTIVE = 'Y'
UNION
SELECT USR_CP_CODE,USR_NAME,'-','All Branches'
FROM   ISR_XO_USERS
ORDER BY 3;

prompt
prompt Creating view GET_LAB_OPD_SERVICES
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.GET_LAB_OPD_SERVICES AS
SELECT MSC_CP_CODE, MSC_DOC_NUM, MSC_LTS_TYPE, DSC_SPC_NUM, DSC_DSC_CODE, DSC_MCT_CODE, DSC_SMN_DESC,
      DSC_SEQ_NUM, DSC_DLV_DATE, DSC_DLV_TIME, LTI_NATURE, LTI_REPORT, LTI_REP_HEADER, LTI_REMARKS,
      DSD_RPT_ID , LTI_TYPE , LTI_TMP_CODE  , LTI_SEQ_PRINT
  FROM(
  SELECT MSC_CP_CODE, MSC_DOC_NUM, MSC_LTS_TYPE, DSC_SPC_NUM, DSC_DSC_CODE, DSC_MCT_CODE, NVL(DSC_SMN_DESC, LTI_SMN_DESC) DSC_SMN_DESC,
      DSC_SEQ_NUM, DSC_DLV_DATE, DSC_DLV_TIME, LTI_NATURE, LTI_REPORT, LTI_REP_HEADER, LTI_REMARKS,
      DSD_RPT_ID , LTI_TYPE , LTI_TMP_CODE , LTI_SEQ_PRINT
  FROM  LAB_TD_SMN_COLL
  LEFT JOIN LAB_TD_SRV_DIAG ON (DSD_CP_CODE  = DSC_CP_CODE
      AND   DSD_RPT_ID   = DSD_RPT_ID
      AND   DSD_RPT_DATE = DSD_RPT_DATE
      AND   DSD_RCT_NUM  = DSC_DOC_NUM
      AND   DSD_DSC_CODE = DSC_DSC_CODE
      AND   DSD_SEQ_NUM  = DSC_SEQ_NUM)
  INNER JOIN LAB_TM_SMN_COLL ON (MSC_CP_CODE = DSC_CP_CODE
      AND   MSC_SPC_NUM   = DSC_SPC_NUM
      AND   MSC_SPC_DATE  = DSC_SPC_DATE
      AND   MSC_DOC_NUM   = DSC_DOC_NUM)
  INNER JOIN LAB_SM_LT_INFO ON (LTI_CP_CODE   = DSC_CP_CODE
      AND   LTI_SRV_CODE  = DSC_DSC_CODE)
  UNION ALL
  SELECT DSR_CP_CODE, DSR_MSR_NUM, 'OPD', NULL, DSR_DSC_CODE, DSR_MCT_CODE, NULL
, DSR_SEQ_NUM, DSR_DLV_DATE, DSR_DLV_TIME, LTI_NATURE, LTI_REPORT, LTI_REP_HEADER, NULL, NULL , LTI_TYPE , LTI_TMP_CODE , LTI_SEQ_PRINT
  FROM   HOS_TD_OPD_SRV_RCPT
  INNER JOIN LAB_SM_LT_INFO ON (LTI_CP_CODE    = DSR_CP_CODE
      AND   LTI_SRV_CODE   = DSR_DSC_CODE
      AND   LTI_SMN_FLAG = 'N')
  WHERE DSR_CP_CODE  = DSR_CP_CODE
  AND   DSR_MSR_NF_TYPE = DSR_MSR_NF_TYPE
  AND   DSR_MSR_DATE = DSR_MSR_DATE
  AND   DSR_MSR_NUM  = DSR_MSR_NUM
  AND   DSR_MSR_PAT_TYPE = DSR_MSR_PAT_TYPE
  AND   DSR_DSC_CODE = DSR_DSC_CODE
  AND   DSR_DLV_DATE IS NOT NULL
  AND   DSR_DLV_FLAG = 'N'
  AND   DSR_RFD_FLAG = 'N'
  AND   DSR_REP_FLAG = 'N'
  AND   NVL(DSR_SMN_FLAG,'N') = NVL(DSR_SMN_FLAG,'N'))
  WHERE DSD_RPT_ID IS NULL
 ORDER BY MSC_CP_CODE, MSC_DOC_NUM, DSC_DSC_CODE;

prompt
prompt Creating view HOSPITAL_CONSULTANT_SHARES
prompt ========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOSPITAL_CONSULTANT_SHARES AS
(
SELECT RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE,
   SUM(RPT_NET_OPDS) AS RPT_NET_OPDS,
   SUM(RPT_OPD_AMT) AS RPT_OPD_AMT,
   SUM(RPT_OPD_SRV_AMT) AS RPT_OPD_SRV_AMT,
   SUM(RPT_OPD_HOS_AMT) AS RPT_OPD_HOS_AMT,
   SUM(RPT_OPD_CON_AMT) AS RPT_OPD_CON_AMT,
   SUM(RPT_IPD_VST_AMT) AS RPT_IPD_VST_AMT,
   SUM(RPT_IPD_SRV_AMT) AS RPT_IPD_SRV_AMT,
   SUM(RPT_IPD_SUR_AMT) AS RPT_IPD_SUR_AMT,
   SUM(RPT_IPD_HOS_AMT) AS RPT_IPD_HOS_AMT,
   SUM(RPT_IPD_CON_AMT) AS RPT_IPD_CON_AMT
FROM (
  SELECT   RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE,
    SUM(LC_COUNT) AS RPT_NET_OPDS,
    SUM(LC_NET_AMT) - NVL(SUM(LC_PAT_REG_FEE),0) AS RPT_OPD_AMT,
    0 AS RPT_OPD_SRV_AMT,
    SUM(LC_HOS_AMT) - NVL(SUM(LC_PAT_REG_FEE),0) AS RPT_OPD_HOS_AMT,
    SUM(LC_MCT_AMT) AS RPT_OPD_CON_AMT, 0 AS RPT_IPD_VST_AMT,
     0 AS RPT_IPD_SRV_AMT, 0 AS RPT_IPD_SUR_AMT, 0 AS RPT_IPD_HOS_AMT,
     0 AS RPT_IPD_CON_AMT
  FROM (
      SELECT  MCR_CP_CODE AS RPT_CP_CODE,
      MCR_MCT_CODE AS RPT_MCT_CODE,
      MCR_DATE AS RPT_DATE,
      MCR_TYPE AS RPT_SAL_TYPE,
      MCR_NF_TYPE AS RPT_NF_TYPE,
      COUNT(*) AS LC_COUNT,
            SUM(NVL(MCR_MCT_AMT,0)) AS LC_MCT_AMT,
            SUM(NVL(MCR_HOS_AMT,0))  AS LC_HOS_AMT,
      SUM(NVL(MCR_NET_AMT,0)) AS LC_NET_AMT,
            SUM(NVL(MCR_PAT_REG_FEE,0)) LC_PAT_REG_FEE
      FROM  HOS_TM_OPD_CON_RCPT
      WHERE  MCR_RCP_TYPE = 'RC'
      AND   MCR_PST_FLAG <> 'C'
    GROUP BY MCR_CP_CODE, MCR_MCT_CODE, MCR_DATE, MCR_TYPE, MCR_NF_TYPE
      UNION ALL
      SELECT  MCR_CP_CODE AS RPT_CP_CODE,
      MCR_MCT_CODE AS RPT_MCT_CODE,
      MCR_DATE AS RPT_DATE,
      MCR_TYPE AS RPT_SAL_TYPE,
      MCR_NF_TYPE AS RPT_NF_TYPE,
      COUNT(*) *-1 AS LC_COUNT,
            SUM(NVL(MCR_MCT_AMT,0)) *-1 AS LC_MCT_AMT,
            SUM(NVL(MCR_HOS_AMT,0)) *-1 AS LC_HOS_AMT,
            SUM(NVL(MCR_NET_AMT,0)) *-1 AS LC_NET_AMT,
            SUM(NVL(MCR_PAT_REG_FEE,0)) * -1 LC_PAT_REG_FEE
      FROM  HOS_TM_OPD_CON_RCPT
      WHERE MCR_RCP_TYPE = 'RR'
      AND   MCR_PST_FLAG <> 'C'
    GROUP BY MCR_CP_CODE, MCR_MCT_CODE, MCR_DATE, MCR_TYPE, MCR_NF_TYPE
  )
  GROUP BY RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE
  UNION ALL
  SELECT   RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE,
    SUM(RPT_NET_OPDS) AS RPT_NET_OPDS,
    SUM(RPT_OPD_AMT) AS RPT_OPD_AMT,
    SUM(RPT_OPD_SRV_AMT) AS RPT_OPD_SRV_AMT,
    SUM(RPT_OPD_HOS_AMT) AS RPT_OPD_HOS_AMT,
    SUM(RPT_OPD_CON_AMT) AS RPT_OPD_CON_AMT, 0 AS RPT_IPD_VST_AMT,
     0 AS RPT_IPD_SRV_AMT, 0 AS RPT_IPD_SUR_AMT, 0 AS RPT_IPD_HOS_AMT,
     0 AS RPT_IPD_CON_AMT
  FROM (
        SELECT  MSR_CP_CODE  AS RPT_CP_CODE,
      DSR_MCT_CODE AS RPT_MCT_CODE,
      MSR_DATE AS RPT_DATE,
      MSR_TYPE AS RPT_SAL_TYPE,
      MSR_NF_TYPE AS RPT_NF_TYPE,
      0 AS RPT_NET_OPDS,
      0 AS RPT_OPD_AMT,
      SUM(LC_NET_AMT) AS RPT_OPD_SRV_AMT,
      SUM(LC_HOS_AMT) AS RPT_OPD_HOS_AMT,
      SUM(LC_MCT_AMT) AS RPT_OPD_CON_AMT
       FROM (
         SELECT  MSR_CP_CODE, DSR_MCT_CODE, MSR_DATE, MSR_TYPE, MSR_NF_TYPE,
        SUM(NVL(DSR_MCT_AMT,0)) AS LC_MCT_AMT,
               SUM(NVL(DSR_HOS_AMT,0)) AS LC_HOS_AMT,
               SUM(NVL(DSR_NET_AMT,0)) AS LC_NET_AMT
         FROM     HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT
         WHERE  MSR_CP_CODE = DSR_CP_CODE
         AND      MSR_NUM = DSR_MSR_NUM
         AND     MSR_DATE = DSR_MSR_DATE
         AND     MSR_NF_TYPE = DSR_MSR_NF_TYPE
         AND     MSR_REF_TYPE = 'I'
         AND     DSR_MCT_CODE IS NOT NULL
         AND     MSR_PST_FLAG <> 'C'
      GROUP BY MSR_CP_CODE, DSR_MCT_CODE, MSR_DATE, MSR_TYPE, MSR_NF_TYPE
         UNION ALL
      SELECT  MSR_CP_CODE, DSR_MCT_CODE, MSR_DATE, MSR_TYPE, MSR_NF_TYPE,
           SUM(NVL(DSR_MCT_AMT,0)) *-1 AS LC_MCT_AMT,
               SUM(NVL(DSR_HOS_AMT,0)) *-1 AS LC_HOS_AMT,
               SUM(NVL(DSR_NET_AMT,0)) *-1 AS LC_NET_AMT
         FROM   HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT
         WHERE  MSR_CP_CODE = DSR_CP_CODE
         AND      MSR_NUM = DSR_MSR_NUM
         AND     MSR_DATE = DSR_MSR_DATE
         AND     MSR_NF_TYPE = DSR_MSR_NF_TYPE
         AND     MSR_REF_TYPE = 'R'
         AND     DSR_MCT_CODE IS NOT NULL
         AND     MSR_PST_FLAG <> 'C'
      GROUP BY MSR_CP_CODE, DSR_MCT_CODE, MSR_DATE, MSR_TYPE, MSR_NF_TYPE
    )
    GROUP BY MSR_CP_CODE, DSR_MCT_CODE, MSR_DATE, MSR_TYPE, MSR_NF_TYPE
     )
  GROUP BY RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE
  UNION ALL
  SELECT   RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE,
    0 AS RPT_NET_OPDS, 0 AS RPT_OPD_AMT, 0 AS RPT_OPD_SRV_AMT,
    0 AS RPT_OPD_HOS_AMT, 0 AS RPT_OPD_CON_AMT,
    SUM(RPT_IPD_VST_AMT) AS RPT_IPD_VST_AMT,
     SUM(RPT_IPD_SRV_AMT) AS RPT_IPD_SRV_AMT,
    SUM(RPT_IPD_SUR_AMT) AS RPT_IPD_SUR_AMT,
    SUM(RPT_IPD_HOS_AMT) AS RPT_IPD_HOS_AMT,
     SUM(RPT_IPD_CON_AMT) AS RPT_IPD_CON_AMT
  FROM (
    SELECT   MPF_CP_CODE AS RPT_CP_CODE, MBP_DATE AS RPT_DATE, DHS_MCT_CODE AS RPT_MCT_CODE,
      MPF_TYPE AS RPT_SAL_TYPE, DHS_NF_TYPE AS RPT_NF_TYPE,
      0 AS RPT_NET_OPDS, 0 AS RPT_OPD_AMT, 0 AS RPT_OPD_SRV_AMT,
      0 AS RPT_OPD_HOS_AMT, 0 AS RPT_OPD_CON_AMT,
      0 AS RPT_IPD_VST_AMT,
       (NVL(DHS_QTY,0)* NVL(DHS_RATE,0)- NVL(DHS_DISC_AMT,0)) AS RPT_IPD_SRV_AMT,
      0 AS RPT_IPD_SUR_AMT,
      DHS_HOS_AMT  AS RPT_IPD_HOS_AMT,
       DHS_MCT_AMT  AS RPT_IPD_CON_AMT,
      DHS_SEQ_NUM AS SEQ_NUM,
      ROWNUM AS LC_ROWNUM,
      DHS_INC_FLAG AS INC_FLAG
    FROM   HOS_TM_PATIENT_FILE, HOS_TD_PAT_HOSP_SRV, HOS_TO_BILL_PROCESS
    WHERE  DHS_CP_CODE = MPF_CP_CODE
    AND  DHS_MPF_FILE_NUM = MPF_FILE_NUM
    AND  DHS_MPF_MPT_ID = MPF_MPT_ID
    AND  MBP_CP_CODE = MPF_CP_CODE
    AND  MBP_MPF_FILE_NUM = MPF_FILE_NUM
    AND  MBP_MPT_ID = MPF_MPT_ID
    AND     DHS_MCT_CODE   IS NOT NULL
    AND     DHS_AVL_FLAG = 'Y'
    UNION ALL
    SELECT   MPF_CP_CODE AS RPT_CP_CODE, MBP_DATE AS RPT_DATE, DCV_MCT_CODE AS RPT_MCT_CODE,
      MPF_TYPE AS RPT_SAL_TYPE, DCV_NF_TYPE AS RPT_NF_TYPE,
      0 AS RPT_NET_OPDS, 0 AS RPT_OPD_AMT, 0 AS RPT_OPD_SRV_AMT,
      0 AS RPT_OPD_HOS_AMT, 0 AS RPT_OPD_CON_AMT,
      DCV_NET_AMT AS RPT_IPD_VST_AMT,
       0 AS RPT_IPD_SRV_AMT,
      0 AS RPT_IPD_SUR_AMT,
      DCV_HOS_AMT AS RPT_IPD_HOS_AMT,
       DCV_MCT_AMT AS RPT_IPD_CON_AMT,
      DCV_SQN AS SEQ_NUM,
      ROWNUM AS LC_ROWNUM,
      DCV_INC_FLAG AS INC_FLAG
    FROM   HOS_TM_PATIENT_FILE, HOS_TD_CON_VISITS, HOS_TO_BILL_PROCESS
    WHERE  DCV_CP_CODE = MPF_CP_CODE
    AND  DCV_MPF_FILE_NUM = MPF_FILE_NUM
    AND  DCV_MPF_MPT_ID = MPF_MPT_ID
    AND  MBP_CP_CODE = MPF_CP_CODE
    AND  MBP_MPF_FILE_NUM = MPF_FILE_NUM
    AND  MBP_MPT_ID = MPF_MPT_ID
    AND     DCV_MCT_CODE  IS NOT NULL
    AND     DCV_AVL_FLAG = 'Y'
    UNION ALL
    SELECT   MPF_CP_CODE AS RPT_CP_CODE, MBP_DATE AS RPT_DATE, DPS_MCT_CODE AS RPT_MCT_CODE,
      MPF_TYPE AS RPT_SAL_TYPE, DPS_NF_TYPE AS RPT_NF_TYPE,
      0 AS RPT_NET_OPDS, 0 AS RPT_OPD_AMT, 0 AS RPT_OPD_SRV_AMT,
      0 AS RPT_OPD_HOS_AMT, 0 AS RPT_OPD_CON_AMT,
      0 AS RPT_IPD_VST_AMT,
       0 AS RPT_IPD_SRV_AMT,
      NVL(DPS_AMT,0) AS RPT_IPD_SUR_AMT,
      NVL(DPS_AMT,0) - NVL(DPS_MCT_AMT,0) AS RPT_IPD_HOS_AMT,
       NVL(DPS_MCT_AMT,0) AS RPT_IPD_CON_AMT,
      9999 AS SEQ_NUM,
      ROWNUM AS LC_ROWNUM,
      DPS_INC_FLAG AS INC_FLAG
    FROM  HOS_TM_PATIENT_FILE, HOS_TD_PAT_SUR, HOS_TO_BILL_PROCESS
    WHERE  DPS_CP_CODE = MPF_CP_CODE
    AND  DPS_MPF_FILE_NUM = MPF_FILE_NUM
    AND  DPS_MPF_MPT_ID = MPF_MPT_ID
    AND  MBP_CP_CODE = MPF_CP_CODE
    AND  MBP_MPF_FILE_NUM = MPF_FILE_NUM
    AND  MBP_MPT_ID = MPF_MPT_ID
    AND     DPS_MCT_CODE   IS NOT NULL
    AND     DPS_AVL_FLAG = 'Y'
    UNION ALL
    SELECT   MPF_CP_CODE AS RPT_CP_CODE, MBP_DATE AS RPT_DATE, DPS_ANT_CODE AS RPT_MCT_CODE,
      MPF_TYPE AS RPT_SAL_TYPE, DPS_ANT_NF_TYPE AS RPT_NF_TYPE,
      0 AS RPT_NET_OPDS, 0 AS RPT_OPD_AMT, 0 AS RPT_OPD_SRV_AMT,
      0 AS RPT_OPD_HOS_AMT, 0 AS RPT_OPD_CON_AMT,
      0 AS RPT_IPD_VST_AMT,
       0 AS RPT_IPD_SRV_AMT,
      NVL(DPS_ANT_RATE,0)  AS RPT_IPD_SUR_AMT,
      NVL(DPS_ANT_RATE,0) - NVL(DPS_ANT_AMT,0) AS RPT_IPD_HOS_AMT,
       NVL(DPS_ANT_AMT,0)  AS RPT_IPD_CON_AMT,
      8888 AS SEQ_NUM,
      ROWNUM AS LC_ROWNUM,
      DPS_INC_FLAG AS INC_FLAG
    FROM   HOS_TM_PATIENT_FILE, HOS_TD_PAT_SUR, HOS_TO_BILL_PROCESS
    WHERE  DPS_CP_CODE = MPF_CP_CODE
    AND  DPS_MPF_FILE_NUM = MPF_FILE_NUM
    AND  DPS_MPF_MPT_ID = MPF_MPT_ID
    AND  MBP_CP_CODE = MPF_CP_CODE
    AND  MBP_MPF_FILE_NUM = MPF_FILE_NUM
    AND  MBP_MPT_ID = MPF_MPT_ID
    AND     DPS_ANT_CODE   IS NOT NULL
    AND     DPS_AVL_FLAG = 'Y'
  )
  GROUP BY RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE
)
GROUP BY RPT_CP_CODE, RPT_DATE, RPT_MCT_CODE, RPT_SAL_TYPE, RPT_NF_TYPE
);

