prompt Creating view HOS_ALL_OPD_SRV_SLIPS
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_ALL_OPD_SRV_SLIPS AS
SELECT "DSR_CP_CODE","DSR_MSR_NF_TYPE","DSR_MSR_DATE","DSR_MSR_NUM","DSR_MSR_PAT_TYPE","DSR_DSC_CODE","DSR_DSC_TYPE","DSR_MCT_CODE","DSR_DEP_CODE","DSR_RATE","DSR_MCT_AMT","DSR_HOS_AMT","DSR_STATUS","DSR_DAT_FLAG","DSR_INS_DATE","DSR_INS_USER","DSR_UPD_DATE","DSR_UPD_USER","DSR_QTY","DSR_AMT","DSR_MSC_TYPE","DSR_REF_NUM","DSR_DISC","DSR_NET_AMT","DCV_JV_DATE","DCV_JV_NUM","MSR_CP_CODE","MSR_NF_TYPE","MSR_DATE","MSR_NUM","MSR_PAT_TYPE","MSR_PAT_ID","MSR_NAME","MSR_ADDRESS","MSR_PHONE","MSR_MCT_CODE","MSR_DEP_CODE","MSR_TYPE","MSR_MPA_CODE","MSR_EMP_ID","MSR_EMP_NAME","MSR_EMP_RELATION","MSR_EMP_VALID","MSR_EMP_LIMIT","MSR_EMP_APPROVAL","MSR_EMP_APP_REF","MSR_EMP_APP_DATE","MSR_COMPLEMENTRY","MSR_AMOUNT","MSR_DISCOUNT","MSR_NET_AMT","MSR_RCVD_AMT","MSR_RETU_AMT","MSR_DUE_AMT","MSR_DUE_RCVD_AMT","MSR_BILL_NUMBER","MSR_RCVD_STATUS","MSR_STATUS","MSR_DAT_FLAG","MSR_INS_DATE","MSR_INS_USER","MSR_UPD_DATE","MSR_UPD_USER","MSR_BILL_INCLUDE","MSR_EMP_APP_REMARKS","MSR_REF_NUM","MSR_REF_TYPE","MSR_PST_FLAG","MSR_INS_TIME","MSR_JV_DATE","MSR_JV_NUM","MSR_COM_FLAG","MSR_MCT_DESC","MSR_OTH_COMP_CODE","MSR_DIS_USR","MSR_DIS_DATE","MSR_DIS_TIME","MSR_SDD_SDI_CODE","MSR_REF_MCT_CODE","MSR_MPT_AGE","MSR_MPT_SEX","MSR_SDD_EFF_DATE","MSR_PRT_FLAG","MSR_WARD_CODE","MSR_PRG_CODE","MSR_PRG_DESC","MSR_DISC_REASON","MSR_TOKEN_NBR"
FROM HOS_TD_OPD_SRV_RCPT, HOS_TM_OPD_SRV_RCPT
WHERE DSR_CP_CODE      = MSR_CP_CODE
AND     DSR_MSR_NF_TYPE  = MSR_NF_TYPE
AND     DSR_MSR_DATE     = MSR_DATE
AND     DSR_MSR_NUM      = MSR_NUM
AND     DSR_MSR_PAT_TYPE = MSR_PAT_TYPE;

prompt
prompt Creating view HOS_DET_DW_ADVANCE
prompt ================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_DET_DW_ADVANCE AS
(SELECT MPF_TYPE AS MPT_TYPE,DAD_ADV_SLIP_NUM AS MPT_REG, DAD_ADV_DATE AS MPT_DATE,MPT_ID AS MPT_PATIENT,MPF_MPA_CODE AS MPT_CO_CODE,NVL(DAD_AMT,0) AS MPT_AMOUNT,1 AS MPT_COUNT,
MPF_ADM_DATE, MPF_DIS_DATE, MPF_WARD_CODE , MPF_BR_CODE
FROM HOS_TD_PAT_ADV_INFO, HOS_TM_PATIENT_FILE, HOS_SM_PATIENT
WHERE  MPF_CP_CODE  = DAD_CP_CODE
AND    MPF_BR_CODE  = DAD_BR_CODE
AND    MPF_FILE_NUM = DAD_MPF_FILE_NUM
AND    MPT_CP_CODE  = DAD_CP_CODE
AND    MPT_ID       = DAD_MPF_MPT_ID
UNION ALL
SELECT MPF_TYPE AS MDW_TYPE,MAR_DAD_ADV_SLIP_NUM  AS MDW_SLIP, MAR_DATE AS MDW_DATE,MPT_ID AS MPT_PATIENT,MPF_MPA_CODE AS MPT_CO_CODE,NVL(MAR_AMT,0) * -1 AS MDW_AMOUNT,-1 AS MPT_COUNT,
MPF_ADM_DATE, MPF_DIS_DATE, MPF_WARD_CODE , MPF_BR_CODE
FROM HOS_TO_ADV_REFUND , HOS_TM_PATIENT_FILE , HOS_SM_PATIENT
WHERE  MPF_CP_CODE  = MAR_CP_CODE
AND    MPF_BR_CODE  = MAR_BR_CODE
AND    MPF_FILE_NUM = MAR_MPF_FILE_NUM
AND    MPT_CP_CODE  = MAR_CP_CODE
AND    MPT_ID       = MAR_MPF_MPT_ID);

prompt
prompt Creating view HOS_DET_DW_REG
prompt ============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_DET_DW_REG AS
(SELECT MPR_REG_TYPE MPR_TYPE,MPR_REG_NUM MPR_REG, MPR_REG_DATE MPR_DATE,MPR_MPT_ID MPR_PATIENT,MPR_MPA_CODE MPR_CO_CODE, NVL(MPR_AMT_IN_ADV,0) MPR_AMOUNT,1 MPR_COUNT , MPR_BR_CODE
FROM HOS_TM_PAT_REGISTRATION
UNION ALL
SELECT MPR_REG_TYPE,MRR_MPR_REG_NUM, MRR_DATE,  MRR_MPT_ID,MPR_MPA_CODE AS MRR_MPA_CODE,NVL(MRR_NET_AMT,0) * -1,-1 AS LC_COUNT , MRR_BR_CODE
FROM HOS_TM_REG_REFUND,HOS_TM_PAT_REGISTRATION
WHERE  MRR_CP_CODE = MPR_CP_CODE
AND    MRR_BR_CODE = MPR_BR_CODE
AND    MRR_MPR_REG_NUM = MPR_REG_NUM
);

prompt
prompt Creating view HOS_LAB_TEST_PATIENTS_SLIPS
prompt =========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_LAB_TEST_PATIENTS_SLIPS AS
SELECT MSR_BR_CODE AS RPT_SLIP_BR_CODE, BR_FUL_NAME AS RPT_SLIP_BR_NAME,
       RPT_MONTH AS RPT_SLIP_MONTH,
       SUM(RPT_AMT) AS RPT_SLIP_AMT,
       COUNT(*) AS RPT_SLIP_COUNT
FROM (
SELECT MSR_BR_CODE, BR_FUL_NAME, TO_CHAR(MSR_DATE,'MON-YYYY') AS RPT_MONTH,
       SUM(DECODE(MSR_REF_TYPE,'I',DSR_NET_AMT, -DSR_NET_AMT)) AS RPT_AMT,
       DECODE(MSR_REF_TYPE,'I',MSR_NUM,MSR_REF_NUM) AS RPT_MSR_NUM
FROM   HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT, HOS_SM_SRV_CHARGES, ISR_XM_BRANCH
WHERE  MSR_NUM = DSR_MSR_NUM
AND    SUBSTR(DSR_DSC_CODE,1,4) = MSC_CODE
AND    MSC_TYPE = 'LT'
AND    BR_CODE = MSR_BR_CODE
GROUP BY MSR_BR_CODE, BR_FUL_NAME, TO_CHAR(MSR_DATE,'MON-YYYY'), MSR_REF_TYPE, MSR_NUM, MSR_REF_NUM
)
GROUP BY MSR_BR_CODE, BR_FUL_NAME, RPT_MONTH
HAVING  SUM(RPT_AMT) > 0
ORDER BY 1, 3;

prompt
prompt Creating view HOS_LAB_TEST_QTY
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_LAB_TEST_QTY AS
SELECT MSR_BR_CODE AS RPT_BR_CODE, BR_FUL_NAME, RPT_MONTH,
       SUM(RPT_AMT) AS RPT_AMT,
       SUM(RPT_QTY) AS RPT_QTY
FROM (
SELECT MSR_BR_CODE, BR_FUL_NAME, TO_CHAR(MSR_DATE,'MON-YYYY') AS RPT_MONTH,
       SUM(DECODE(MSR_REF_TYPE,'I',DSR_NET_AMT, -DSR_NET_AMT)) AS RPT_AMT,
       SUM(DECODE(MSR_REF_TYPE,'I',DSR_QTY,-DSR_QTY)) AS RPT_QTY
FROM   HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT, HOS_SM_SRV_CHARGES, ISR_XM_BRANCH
WHERE  MSR_NUM = DSR_MSR_NUM
AND    SUBSTR(DSR_DSC_CODE,1,4) = MSC_CODE
AND    MSC_TYPE = 'LT'
AND    BR_CODE = MSR_BR_CODE
GROUP BY MSR_BR_CODE, BR_FUL_NAME, TO_CHAR(MSR_DATE,'MON-YYYY'), MSR_REF_TYPE
)
GROUP BY MSR_BR_CODE, BR_FUL_NAME, RPT_MONTH
ORDER BY 1, 3;

prompt
prompt Creating view HOS_MIS_DET_NET_OPDS
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DET_NET_OPDS AS
(SELECT 'OPD-' || MCT_NAME AS MCT_NAME, MCR_TYPE MCR_TYPE,MCR_NUM MCR_NUM,MCR_DATE MCR_ACTIVITY_DATE,MCR_DATE
MCR_ADMIT_DATE
,MCR_MPT_ID MCR_MPT_ID,MCR_MPA_CODE MCR_MPA_CODE,
DECODE(MCR_RCP_TYPE,'RC',NVL(MCR_NET_AMT,0),-NVL(MCR_NET_AMT,0)) AS MCR_NET_AMT,
MCR_DATE MCR_DISC_DATE,
DECODE(MCR_RCP_TYPE,'RC',1,-1) AS MCR_LC_CNT,
MCR_NF_TYPE, MCR_WARD_CODE  , MCR_BR_CODE, 'OPD-' ||NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC
FROM HOS_TM_OPD_CON_RCPT
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MCR_CP_CODE AND MCT_CODE = MCR_MCT_CODE)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = MCT_CP_CODE AND COA3_CODE = MCT_OSL_COA3)
);

prompt
prompt Creating view HOS_MIS_DET_PHARMACY
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DET_PHARMACY AS
(
SELECT DECODE(MSL_SAL_TYPE,'P','R',MSL_SAL_TYPE) AS MSL_SAL_TYPE,MSL_NUM,MSL_DATE MSL_ACTIVITY_DATE,MSL_DATE MSL_ADM_DATE,MSL_PAT_ID,MSL_MPA_CODE,
DECODE(MSL_TYPE,'I',NVL(SUM(DSL_AMOUNT),0),-NVL(SUM(DSL_AMOUNT),0)) MSL_AMT,MSL_DATE MSL_DIS_DATE,
DECODE(MSL_TYPE,'I',1,-1) MSL_CNT,MSL_TYPE , MSL_BR_CODE
FROM  HOS_TM_SALES, HOS_TD_SALES
WHERE MSL_CP_CODE  = DSL_CP_CODE
AND   MSL_NUM   = DSL_MSL_NUM
AND   MSL_TYPE   = DSL_MSL_TYPE
AND   MSL_DATE   = DSL_MSL_DATE
GROUP BY MSL_SAL_TYPE,MSL_NUM,MSL_DATE ,MSL_DATE ,MSL_PAT_ID,MSL_MPA_CODE,MSL_DATE,MSL_TYPE, MSL_BR_CODE );

prompt
prompt Creating view HOS_MIS_DET_SERVICES
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DET_SERVICES AS
(
SELECT DHS_SRV_DATE AS MDW_SRV_DATE, DHS_NF_TYPE AS MDW_NF_TYPE,
       MPF_TYPE AS MDW_TYPE, DSC_DESC AS MDW_REF_GRP2,--DSC_REF_GRP2 AS MDW_REF_GRP2,
       NVL(SUM(DHS_QTY),0) MDW_CNT, NVL(SUM(DHS_NET_AMT),0) MDW_AMT,
       MPF_ADM_DATE, MPF_DIS_DATE, MPF_FILE_NUM, MPF_MPT_ID, MPF_MPA_CODE,
       1 AS MPF_COUNT, NULL AS MSR_NAME, MPF_WARD_CODE AS MDW_WARD_CODE , MPF_BR_CODE  AS MDW_BR_CODE
FROM HOS_TM_PATIENT_FILE, HOS_TD_PAT_HOSP_SRV, HOS_SD_SRV_CHARGES
WHERE MPF_CP_CODE  = DHS_CP_CODE
AND   MPF_FILE_NUM = DHS_MPF_FILE_NUM
AND   MPF_MPT_ID   = DHS_MPF_MPT_ID
AND   DHS_CP_CODE  = DSC_CP_CODE
AND   DHS_DSC_CODE = DSC_CODE
GROUP BY DHS_SRV_DATE, DHS_NF_TYPE, MPF_TYPE, DSC_DESC,
MPF_ADM_DATE, MPF_DIS_DATE, MPF_FILE_NUM, MPF_MPT_ID, MPF_MPA_CODE, MPF_WARD_CODE , MPF_BR_CODE
UNION ALL
SELECT MSR_DATE, MSR_NF_TYPE, MSR_TYPE, DSC_DESC AS MDW_REF_GRP2,--DSC_REF_GRP2 AS MDW_REF_GRP2,
       DECODE(MSR_REF_TYPE,'I',NVL(SUM(DSR_QTY),0),-NVL(SUM(DSR_QTY),0)),
       DECODE(MSR_REF_TYPE,'I',NVL(SUM(DSR_NET_AMT),0),-NVL(SUM(DSR_NET_AMT),0)),
       NULL ADM_DATE,NULL DIS_DATE,MSR_NUM,MSR_PAT_ID,MSR_MPA_CODE,
       DECODE(MSR_REF_TYPE,'I',1,-1) MSR_COUNT, MSR_NAME, MSR_WARD_CODE AS MDW_WARD_CODE
       , MSR_BR_CODE  AS MDW_BR_CODE
FROM HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT, HOS_SD_SRV_CHARGES
WHERE MSR_CP_CODE  = DSR_CP_CODE
AND   MSR_NF_TYPE  = DSR_MSR_NF_TYPE
AND   MSR_DATE     = DSR_MSR_DATE
AND   MSR_NUM      = DSR_MSR_NUM
AND   MSR_PAT_TYPE = DSR_MSR_PAT_TYPE
AND   DSR_CP_CODE  = DSC_CP_CODE
AND   DSR_DSC_CODE = DSC_CODE
GROUP BY MSR_DATE, MSR_NF_TYPE, MSR_TYPE, MSR_NAME, DSC_DESC, MSR_REF_TYPE,
MSR_DATE ,MSR_DATE ,MSR_NUM,MSR_PAT_ID,MSR_MPA_CODE, MSR_WARD_CODE , MSR_BR_CODE)
;

prompt
prompt Creating view HOS_MIS_DW_ADVANCE
prompt ================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_ADVANCE AS
(
SELECT MDW_SLIP, MDW_DATE, MDW_TYPE, SUM(MDW_AMOUNT) AS MDW_AMOUNT, MDW_WARD_CODE , MDW_BR_CODE
FROM (
SELECT DAD_ADV_SLIP_NUM AS MDW_SLIP, DAD_ADV_DATE AS MDW_DATE, MPF_TYPE AS MDW_TYPE, NVL(SUM(NVL(DAD_AMT,0)),0) AS MDW_AMOUNT,
 MPF_WARD_CODE AS MDW_WARD_CODE ,  DAD_BR_CODE AS MDW_BR_CODE
FROM HOS_TD_PAT_ADV_INFO, HOS_TM_PATIENT_FILE
WHERE  MPF_CP_CODE = DAD_CP_CODE
AND    MPF_BR_CODE = DAD_BR_CODE
AND    MPF_FILE_NUM = DAD_MPF_FILE_NUM
GROUP BY DAD_ADV_SLIP_NUM, DAD_ADV_DATE, MPF_TYPE, MPF_WARD_CODE , DAD_BR_CODE
UNION ALL
SELECT MAR_DAD_ADV_SLIP_NUM  AS MDW_SLIP, MAR_DATE AS MDW_DATE, MPF_TYPE AS MDW_TYPE, NVL(SUM(NVL(MAR_AMT,0)),0) * -1 AS MDW_AMOUNT,
 MPF_WARD_CODE AS MDW_WARD_CODE , MAR_BR_CODE AS MDW_BR_CODE
FROM HOS_TO_ADV_REFUND, HOS_TM_PATIENT_FILE
WHERE  MPF_CP_CODE = MAR_CP_CODE
AND    MPF_BR_CODE = MAR_BR_CODE
AND    MPF_FILE_NUM = MAR_MPF_FILE_NUM
GROUP BY MAR_DAD_ADV_SLIP_NUM, MAR_DATE, MPF_TYPE, MPF_WARD_CODE , MAR_BR_CODE
)
GROUP BY MDW_SLIP, MDW_DATE, MDW_TYPE, MDW_WARD_CODE  , MDW_BR_CODE
);

