prompt Creating view HOS_MIS_DW_ANESTHESIA
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_ANESTHESIA AS
(
SELECT MCT_NAME, MPF_TYPE, DPS_DATE, DPS_NF_TYPE AS DPS_ANT_NF_TYPE, DPS_ANT_RATE, MPF_WARD_CODE , MPF_BR_CODE,
 MPF_DIS_DATE, NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC
 FROM HOS_SM_CONSULTANT
 LEFT JOIN HOS_TD_PAT_SUR ON (MCT_CP_CODE = DPS_CP_CODE AND MCT_CODE = DPS_ANT_CODE)
 LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DPS_CP_CODE AND MPF_FILE_NUM = DPS_MPF_FILE_NUM AND MPF_MPT_ID = DPS_MPF_MPT_ID)
 LEFT JOIN HOS_SD_SURGERIES ON (DPS_CP_CODE = DSG_CP_CODE AND DPS_DSG_CODE = DSG_CODE)
 LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = MCT_CP_CODE AND COA3_CODE = MCT_CRE_COA3)
);

