prompt Creating view HOS_MIS_DW_ANESTHESIA_DETAIL
prompt ==========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_ANESTHESIA_DETAIL AS
(
SELECT MCT_NAME, MPF_TYPE, MPF_FILE_NUM, DPS_DATE AS ACTIVITY_DATE, MPF_ADM_DATE AS ADM_DATE, MPF_MPT_ID,
 MPF_MPA_CODE, DPS_ANT_RATE, MPF_DIS_DATE AS MPF_DC_DATE, 1 AS LC_COUNT, MPF_WARD_CODE, MPF_BR_CODE,
 DPS_NF_TYPE AS DPS_ANT_NF_TYPE, NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC
 FROM HOS_SM_CONSULTANT
 LEFT JOIN HOS_TD_PAT_SUR ON (MCT_CP_CODE = DPS_CP_CODE AND MCT_CODE = DPS_ANT_CODE)
 LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DPS_CP_CODE AND MPF_FILE_NUM = DPS_MPF_FILE_NUM AND MPF_MPT_ID = DPS_MPF_MPT_ID)
 LEFT JOIN HOS_SD_SURGERIES ON (DPS_CP_CODE = DSG_CP_CODE AND DPS_DSG_CODE = DSG_CODE)
 LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = MCT_CP_CODE AND COA3_CODE = MCT_CRE_COA3)
