prompt
prompt Creating view HOS_MIS_DW_BOOKING
prompt ================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_BOOKING AS
(
SELECT SUM(MDW_COUNT) AS MDW_COUNT, MDW_SLIP, MDW_DATE, MDW_REG_TYPE, SUM(MDW_AMOUNT) AS MDW_AMOUNT , MDW_BR_CODE
FROM (
SELECT 1 AS MDW_COUNT, MPR_REG_NUM AS MDW_SLIP, MPR_REG_TYPE AS MDW_REG_TYPE, MPR_REG_DATE AS MDW_DATE, NVL(SUM(NVL(MPR_AMT_IN_ADV,0)),0) AS MDW_AMOUNT ,  MPR_BR_CODE AS MDW_BR_CODE
FROM HOS_TM_PAT_REGISTRATION
GROUP BY MPR_REG_NUM, MPR_REG_DATE, MPR_REG_TYPE , MPR_BR_CODE
UNION ALL
SELECT -1 AS MDW_COUNT, MRR_MPR_REG_NUM, MPR_REG_TYPE AS MDW_REG_TYPE, MRR_DATE AS MDW_DATE, NVL(SUM(NVL(MRR_NET_AMT,0)),0) * -1 AS MDW_AMOUNT , MRR_BR_CODE AS MDW_BR_CODE
FROM HOS_TM_REG_REFUND, HOS_TM_PAT_REGISTRATION
WHERE  MRR_CP_CODE = MPR_CP_CODE
AND    MRR_BR_CODE = MPR_BR_CODE
AND    MRR_MPR_REG_NUM = MPR_REG_NUM
GROUP BY MRR_MPR_REG_NUM, MRR_DATE, MPR_REG_TYPE , MRR_BR_CODE
)
GROUP BY MDW_SLIP, MDW_DATE, MDW_REG_TYPE , MDW_BR_CODE
);

