MDW_IPD_AMT, MPF_WARD_CODE , MPF_BR_CODE, 'IPD VISIT-' ||NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC, MBP_DATE AS MPF_DIS_DATE
FROM  HOS_TD_CON_VISITS
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE  = DCV_CP_CODE AND MPF_FILE_NUM = DCV_MPF_FILE_NUM AND MPF_MPT_ID = DCV_MPF_MPT_ID)
LEFT JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE  = DCV_CP_CODE AND MBP_MPF_FILE_NUM = DCV_MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DCV_CP_CODE AND MCT_CODE = DCV_MCT_CODE)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = MCT_CP_CODE AND COA3_CODE = MCT_ISL_COA3)
);

