MPF_ADM_DATE,MPF_MPT_ID,MPF_MPA_CODE, NVL(DCV_NET_AMT,0) AS DCV_AMT, MPF_WARD_CODE , MPF_BR_CODE,
'IPD VISIT-' ||NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC, MPF_DIS_DATE, 1 AS LC_COUNT
FROM  HOS_TD_CON_VISITS
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE  = DCV_CP_CODE AND MPF_FILE_NUM = DCV_MPF_FILE_NUM AND MPF_MPT_ID = DCV_MPF_MPT_ID)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DCV_CP_CODE AND MCT_CODE = DCV_MCT_CODE)
