DECODE(MCR_RCP_TYPE,'RC',NVL(MCR_AMOUNT,0)-NVL(MCR_PAT_REG_FEE,0),-NVL(MCR_AMOUNT,0)) AS MDW_OPD_AMT,
DECODE(MCR_RCP_TYPE,'RC',1,-1) AS MDW_OPD_CNT, MCR_WARD_CODE AS MDW_WARD_CODE,
MCR_BR_CODE AS MDW_BR_CODE, 'OPD-' ||NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC
FROM HOS_TM_OPD_CON_RCPT
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MCR_CP_CODE AND MCT_CODE = MCR_MCT_CODE)
