NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC, MPF_DIS_DATE AS MPF_DC_DATE,
MPF_FILE_NUM, DPS_DATE ACTIVITY_DATE, MPF_ADM_DATE ADM_DATE, MPF_MPT_ID, MPF_MPA_CODE
FROM HOS_TD_PAT_SUR
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DPS_CP_CODE AND MPF_FILE_NUM = DPS_MPF_FILE_NUM AND MPF_MPT_ID = DPS_MPF_MPT_ID)
LEFT JOIN HOS_SD_SURGERIES ON (DSG_CP_CODE = DPS_CP_CODE AND DSG_CODE = DPS_DSG_CODE)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = DSG_CP_CODE AND COA3_CODE = DSG_OTC_COA3)
