prompt Creating view HOS_MIS_DW_PHARMACY
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_PHARMACY AS
(
SELECT  MSL_DATE, MSL_NUM, MSL_TYPE, MSL_PAT_ID, DECODE(MSL_SAL_TYPE,'P','R',MSL_SAL_TYPE) AS MSL_SAL_TYPE,
DECODE(MSL_TYPE,'I',NVL(SUM(DSL_AMOUNT),0),-NVL(SUM(DSL_AMOUNT),0)) MDW_AMT,
DECODE(MSL_TYPE,'I',1,-1) MDW_CNT , MSL_BR_CODE
FROM  HOS_TM_SALES, HOS_TD_SALES
WHERE MSL_CP_CODE  = DSL_CP_CODE
AND   MSL_NUM      = DSL_MSL_NUM
AND   MSL_TYPE     = DSL_MSL_TYPE
AND   MSL_DATE     = DSL_MSL_DATE
GROUP BY MSL_DATE, MSL_NUM, MSL_PAT_ID, MSL_SAL_TYPE, MSL_TYPE , MSL_BR_CODE
);

