prompt Creating view HOS_MIS_DW_ROOMS
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_ROOMS AS
(
SELECT MRM_DESC||' - '||MRM_REMARKS ROOM_DESC,  MPF_TYPE,  DRM_MPF_FILE_NUM, DRM_ACT_DATE, DRM_ACT_DATE_OUT, DRM_DAYS_STAYED, DRM_NET_AMT,
(DRM_NET_AMT / DRM_DAYS_STAYED) AS MDW_ROOM_RATE, MPF_WARD_CODE , MPF_BR_CODE, MPF_DIS_DATE, NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC
FROM HOS_SM_ROOMS
LEFT JOIN HOS_TD_PAT_ROOM_MOVM_INFO ON (MRM_CP_CODE = DRM_CP_CODE
AND MRM_CODE = DRM_MRM_CODE)
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE    = DRM_CP_CODE
AND   MPF_FILE_NUM   = DRM_MPF_FILE_NUM
AND   MPF_MPT_ID     = DRM_MPF_MPT_ID)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = MRM_CP_CODE AND COA3_CODE = MRM_ISL_COA3)
WHERE DRM_ACT_DATE_OUT IS NOT NULL
);

