prompt Creating view HOS_MIS_DW_RVOUCHER
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_RVOUCHER AS
(
SELECT MDW_SLIP, MDW_DATE, MDW_TYPE, SUM(MDW_AMOUNT) AS MDW_AMOUNT, MDW_WARD_CODE , MDW_BR_CODE
FROM (
SELECT MBF_NUM AS MDW_SLIP, MBF_DATE AS MDW_DATE, MPF_TYPE AS MDW_TYPE, DECODE(MPF_TYPE, 'C', NVL(MPF_NET_TOT,0), NVL(MPF_MPT_AMT,0))  AS MDW_AMOUNT,
MPF_WARD_CODE AS MDW_WARD_CODE , MPF_BR_CODE AS MDW_BR_CODE
FROM HOS_TO_BILL_PROCESS_FINAL, HOS_TM_PATIENT_FILE
WHERE  MPF_CP_CODE = MBF_CP_CODE
AND    MPF_BR_CODE = MBF_BR_CODE
AND    MPF_FILE_NUM = MBF_MPF_FILE_NUM
)
GROUP BY MDW_SLIP, MDW_DATE, MDW_TYPE, MDW_WARD_CODE , MDW_BR_CODE
);

prompt
prompt Creating view HOS_MIS_DW_SERVICES
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MIS_DW_SERVICES AS
(
SELECT MDW_SRV_DATE, MDW_NF_TYPE, MDW_TYPE, MDW_REF_GRP2,
       MDW_CNT AS MDW_CNT, NVL(MDW_AMT,0) AS MDW_AMT, MDW_WARD_CODE, MDW_BR_CODE,
       COA3_DESC, MPF_DIS_DATE, MPF_ADM_DATE, MPF_FILE_NUM, MPF_MPT_ID, MPF_MPA_CODE,
       1 AS MPF_COUNT, MSR_NAME
FROM (
SELECT DHS_SRV_DATE AS MDW_SRV_DATE, DHS_NF_TYPE AS MDW_NF_TYPE,
       MPF_TYPE AS MDW_TYPE, DSC_DESC AS MDW_REF_GRP2,
       NVL(DHS_QTY,0) MDW_CNT, NVL(DHS_NET_AMT,0) MDW_AMT,
       MPF_WARD_CODE AS MDW_WARD_CODE ,  MPF_BR_CODE AS MDW_BR_CODE,
       MPF_ADM_DATE, MPF_FILE_NUM, MPF_MPT_ID, MPF_MPA_CODE,
       1 AS MPF_COUNT, NULL AS MSR_NAME,
       NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC, MPF_DIS_DATE
FROM HOS_TD_PAT_HOSP_SRV
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DHS_CP_CODE AND MPF_FILE_NUM = DHS_MPF_FILE_NUM AND MPF_MPT_ID = DHS_MPF_MPT_ID)
LEFT JOIN HOS_SD_SRV_CHARGES ON (DHS_CP_CODE = DSC_CP_CODE AND DHS_DSC_CODE = DSC_CODE)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = DSC_CP_CODE AND COA3_CODE = DSC_ISL_COA3)
UNION ALL
SELECT MSR_DATE, MSR_NF_TYPE, MSR_TYPE, DSC_DESC AS MDW_REF_GRP2,
       DECODE(MSR_REF_TYPE,'I',NVL(DSR_QTY,0),-NVL(DSR_QTY,0)),
       DECODE(MSR_REF_TYPE,'I',NVL(DSR_NET_AMT,0),-NVL(DSR_NET_AMT,0)),
       MSR_WARD_CODE AS MDW_WARD_CODE ,  MSR_BR_CODE AS MDW_BR_CODE,
       NULL, NULL, MSR_PAT_ID, MSR_MPA_CODE,
       1 AS MPF_COUNT, MSR_NAME,
       NVL(COA3_DESC,'(NOT MAPPED)') AS COA3_DESC, MSR_DATE AS MPF_DIS_DATE
FROM HOS_TD_OPD_SRV_RCPT
LEFT JOIN HOS_TM_OPD_SRV_RCPT ON (MSR_CP_CODE = DSR_CP_CODE AND MSR_NF_TYPE = DSR_MSR_NF_TYPE AND MSR_DATE = DSR_MSR_DATE AND MSR_NUM = DSR_MSR_NUM AND
MSR_PAT_TYPE = DSR_MSR_PAT_TYPE)
LEFT JOIN HOS_SD_SRV_CHARGES ON (DSR_CP_CODE = DSC_CP_CODE AND DSR_DSC_CODE = DSC_CODE)
LEFT JOIN ACT_SD_COA_LEVEL3 ON (COA3_CP_CODE = DSC_CP_CODE AND COA3_CODE = DSC_OSL_COA3)
)
);

