prompt Creating view HOS_MOR_ANESTHETIST
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_ANESTHETIST AS
(
SELECT  DPS_CP_CODE AS RPT_CP_CODE,
  MPF_BR_CODE AS RPT_BR_CODE,
  DGM_ANT_DP_CODE AS RPT_COST_CENTER,
  DSG_ANC_COA3 AS RPT_COA3_CODE,
  DPS_ANT_CODE AS RPT_MCT_CODE,
  DECODE(NVL(DPS_ANT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| DPS_ANT_CODE ||']') AS RPT_CON_HOS,
  'ANESTHETIST' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
  MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
  MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPF_TYPE,'C',DPS_ANT_GRS_AMT,0)
  DECODE(MPF_TYPE,'C',DPS_ANT_RATE,0) AS RPT_CSH_GRS_AMT,
  --DECODE(MPF_TYPE,'C',DPS_ANT_DISCOUNT,0)
  0 AS RPT_CSH_DIS_AMT,
    DECODE(MPF_TYPE,'C',DPS_ANT_RATE,0) AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPF_TYPE,'R',DPS_ANT_GRS_AMT,0)
    DECODE(MPF_TYPE,'R',DPS_ANT_RATE,0) AS RPT_CRD_GRS_AMT,
    --DECODE(MPF_TYPE,'R',DPS_ANT_DISCOUNT,0)
    0 AS RPT_CRD_DIS_AMT,
    DECODE(MPF_TYPE,'R',DPS_ANT_RATE,0) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_PAT_SUR
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DPS_CP_CODE AND MPF_FILE_NUM = DPS_MPF_FILE_NUM AND MPF_MPT_ID = DPS_MPF_MPT_ID)
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DPS_CP_CODE AND MCT_CODE = DPS_ANT_CODE)
LEFT JOIN HOS_SD_SURGERIES ON (DSG_CP_CODE = DPS_CP_CODE AND DSG_CODE = DPS_DSG_CODE)
LEFT JOIN HOS_SD_SURGERIES_MAPPING ON (DGM_CP_CODE  = DPS_CP_CODE AND DGM_DSG_CODE = DPS_DSG_CODE AND DGM_BR_CODE = MPF_BR_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
WHERE NVL(DPS_INC_FLAG,'N') = 'N'
AND   NVL(DPS_ANT_CODE,'-') <> '-'
)
;

prompt
prompt Creating view HOS_MOR_CONSULTANCY
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_CONSULTANCY AS
(SELECT MCT_CP_CODE AS RPT_CP_CODE,
  MCT_BR_CODE AS RPT_BR_CODE,
  MCT_DP_CODE AS RPT_COST_CENTER,
  DECODE(MCR_RCP_TYPE,'RC',MCT_OSL_COA3,MCT_OSR_COA3) AS RPT_COA3_CODE,
  MCR_MCT_CODE AS RPT_MCT_CODE,
  DECODE(NVL(MCR_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| MCR_MCT_CODE ||']') AS RPT_CON_HOS,
  'CONSULTANCY' AS RPT_TR_TYPE,
  'OPD' AS RPT_OPD_IPD,
  MCR_TYPE AS RPT_CSH_CRD,
  MCR_DATE AS RPT_ACT_DATE,
  MCR_NUM  AS RPT_SLIP_NUM,
        MCR_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MCR_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MCR_MPA_CODE ||']') AS RPT_COMPANY,
        NULL AS RPT_DOA,
  NULL AS RPT_DOD,
  MCR_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MCR_MPT_ID) AS RPT_PATIENT,
  DECODE(MCR_TYPE,'C',1,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CSH_CNT,
  DECODE(MCR_TYPE,'C',MCR_AMOUNT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CSH_GRS_AMT,
  DECODE(MCR_TYPE,'C',MCR_DISCOUNT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CSH_DIS_AMT,
    DECODE(MCR_TYPE,'C',MCR_NET_AMT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CSH_NET_AMT,
    DECODE(MCR_TYPE,'R',1,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CRD_CNT,
    DECODE(MCR_TYPE,'R',MCR_AMOUNT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CRD_GRS_AMT,
    DECODE(MCR_TYPE,'R',MCR_DISCOUNT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CRD_DIS_AMT,
    DECODE(MCR_TYPE,'R',MCR_NET_AMT,0) * DECODE(MCR_RCP_TYPE,'RC',1,-1) AS RPT_CRD_NET_AMT,
  DECODE(NVL(MCR_SDD_SDI_CODE,'-'),'-',NULL, SDI_DESC || ' - [' || MCR_SDD_SDI_CODE || ']') AS RPT_DIS_HEAD,
  SDI_DP_CODE AS RPT_DIS_COST_CENTER,
  SDI_COA3_CODE AS RPT_DIS_COA3
FROM HOS_TM_OPD_CON_RCPT
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MCR_CP_CODE AND MCT_CODE = MCR_MCT_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MCR_CP_CODE AND MPA_CODE = MCR_MPA_CODE AND MPA_TYPE <> 'W')
LEFT JOIN PPI_SO_DISC_INFO ON (SDI_CP_CODE = MCR_CP_CODE AND SDI_BR_CODE = MCR_BR_CODE AND SDI_CODE = MCR_SDD_SDI_CODE)
UNION ALL
SELECT  DCV_CP_CODE AS RPT_CP_CODE,
  MPF_BR_CODE AS RPT_BR_CODE,
  MCT_IPD_DP_CODE AS RPT_COST_CENTER,
  MCT_ISL_COA3 AS RPT_COA3_CODE,
  DCV_MCT_CODE AS RPT_MCT_CODE,
  DECODE(NVL(DCV_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| DCV_MCT_CODE ||']') AS RPT_CON_HOS,
  'CONSULTANCY' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
  MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
  MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPF_TYPE,'C',DCV_AMT,0)
  DECODE(MPF_TYPE,'C',DCV_NET_AMT,0) AS RPT_CSH_GRS_AMT,
  --DECODE(MPF_TYPE,'C',DCV_DISC_AMT,0)
  0 AS RPT_CSH_DIS_AMT,
    DECODE(MPF_TYPE,'C',DCV_NET_AMT,0) AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPF_TYPE,'R',DCV_AMT,0)
    DECODE(MPF_TYPE,'R',DCV_NET_AMT,0) AS RPT_CRD_GRS_AMT,
    --DECODE(MPF_TYPE,'R',DCV_DISC_AMT,0)
    0 AS RPT_CRD_DIS_AMT,
    DECODE(MPF_TYPE,'R',DCV_NET_AMT,0) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_CON_VISITS
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DCV_CP_CODE AND MPF_FILE_NUM = DCV_MPF_FILE_NUM AND MPF_MPT_ID = DCV_MPF_MPT_ID)
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DCV_CP_CODE AND MCT_CODE = DCV_MCT_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
WHERE NVL(DCV_INC_FLAG,'N') = 'N')
;

prompt
prompt Creating view HOS_MOR_SERVICES
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_SERVICES AS
(
SELECT  DHS_CP_CODE AS RPT_CP_CODE,
  MPF_BR_CODE AS RPT_BR_CODE,
  DSM_IPD_DP_CODE AS RPT_COST_CENTER,
  DSC_ISL_COA3 AS RPT_COA3_CODE,
  DHS_MCT_CODE AS RPT_MCT_CODE,
  DECODE(NVL(DHS_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| DHS_MCT_CODE ||']') AS RPT_CON_HOS,
  'SERVICES' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
        MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
        MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPF_TYPE,'C',DHS_AMT,0)
  DECODE(MPF_TYPE,'C',DHS_NET_AMT,0) AS RPT_CSH_GRS_AMT,
  --DECODE(MPF_TYPE,'C',DHS_DISC_AMT,0)
  0 AS RPT_CSH_DIS_AMT,
    DECODE(MPF_TYPE,'C',DHS_NET_AMT,0) AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPF_TYPE,'R',DHS_AMT,0)
    DECODE(MPF_TYPE,'R',DHS_NET_AMT,0) AS RPT_CRD_GRS_AMT,
    --DECODE(MPF_TYPE,'R',DHS_DISC_AMT,0)
    0 AS RPT_CRD_DIS_AMT,
    DECODE(MPF_TYPE,'R',DHS_NET_AMT,0) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_PAT_HOSP_SRV
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DHS_CP_CODE AND MCT_CODE = DHS_MCT_CODE)
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DHS_CP_CODE AND MPF_FILE_NUM = DHS_MPF_FILE_NUM AND MPF_MPT_ID = DHS_MPF_MPT_ID)
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
INNER JOIN HOS_SD_SRV_CHARGES ON (DHS_CP_CODE = DSC_CP_CODE AND DHS_DSC_CODE = DSC_CODE)
LEFT  JOIN HOS_SD_SRV_CHARGES_MAPPING ON (DSM_CP_CODE = DHS_CP_CODE AND DSM_DSC_CODE = DHS_DSC_CODE AND DSM_BR_CODE = MPF_BR_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
WHERE NVL(DHS_INC_FLAG,'N') = 'N'
UNION ALL
SELECT MSR_CP_CODE AS RPT_CP_CODE,
  MSR_BR_CODE AS RPT_BR_CODE,
  DSM_OPD_DP_CODE AS RPT_COST_CENTER,
  DECODE(MSR_REF_TYPE,'I',DSC_OSL_COA3,DSC_OSR_COA3) AS RPT_COA3_CODE,
  MSR_MCT_CODE AS RPT_MCT_CODE,
  DECODE(NVL(MSR_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| MSR_MCT_CODE ||']') AS RPT_CON_HOS,
  'SERVICES' AS RPT_TR_TYPE,
  'OPD' AS RPT_OPD_IPD,
  MSR_TYPE AS RPT_CSH_CRD,
  MSR_DATE AS RPT_ACT_DATE,
  MSR_NUM  AS RPT_SLIP_NUM,
        MSR_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MSR_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MSR_MPA_CODE ||']') AS RPT_COMPANY,
        NULL AS RPT_DOA,
  NULL AS RPT_DOD,
  MSR_PAT_ID AS RPT_MPT_ID,
  MSR_NAME AS RPT_PATIENT,
  DECODE(MSR_TYPE,'C',NVL(DSR_QTY,1),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CSH_CNT,
  DECODE(MSR_TYPE,'C',NVL(DSR_AMT,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CSH_GRS_AMT,
  DECODE(MSR_TYPE,'C',NVL(DSR_DISC,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CSH_DIS_AMT,
    DECODE(MSR_TYPE,'C',NVL(DSR_NET_AMT,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CSH_NET_AMT,
    DECODE(MSR_TYPE,'R',NVL(DSR_QTY,1),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CRD_CNT,
    DECODE(MSR_TYPE,'R',NVL(DSR_AMT,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CRD_GRS_AMT,
    DECODE(MSR_TYPE,'R',NVL(DSR_DISC,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CRD_DIS_AMT,
    DECODE(MSR_TYPE,'R',NVL(DSR_NET_AMT,0),0) * DECODE(MSR_REF_TYPE,'I',1,-1) AS RPT_CRD_NET_AMT,
  DECODE(NVL(MSR_SDD_SDI_CODE,'-'),'-',NULL, SDI_DESC || ' - [' || MSR_SDD_SDI_CODE || ']') AS RPT_DIS_HEAD,
  SDI_DP_CODE AS RPT_DIS_COST_CENTER,
  SDI_COA3_CODE AS RPT_DIS_COA3
FROM HOS_TD_OPD_SRV_RCPT
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DSR_CP_CODE AND MCT_CODE = DSR_MCT_CODE)
INNER JOIN HOS_TM_OPD_SRV_RCPT ON (MSR_CP_CODE = DSR_CP_CODE AND MSR_NF_TYPE = DSR_MSR_NF_TYPE AND MSR_DATE = DSR_MSR_DATE AND MSR_NUM = DSR_MSR_NUM AND
MSR_PAT_TYPE = DSR_MSR_PAT_TYPE)
INNER JOIN HOS_SD_SRV_CHARGES ON (DSR_CP_CODE = DSC_CP_CODE AND DSR_DSC_CODE = DSC_CODE)
INNER  JOIN HOS_SD_SRV_CHARGES_MAPPING ON (DSM_CP_CODE = DSR_CP_CODE AND DSM_DSC_CODE = DSR_DSC_CODE AND DSM_BR_CODE = MSR_BR_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MSR_CP_CODE AND MPA_CODE = MSR_MPA_CODE AND MPA_TYPE <> 'W')
LEFT JOIN PPI_SO_DISC_INFO ON (SDI_CP_CODE = MSR_CP_CODE AND SDI_BR_CODE = MSR_BR_CODE AND SDI_CODE = MSR_SDD_SDI_CODE)
)
;

prompt
prompt Creating view HOS_MOR_DISCOUNT
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_DISCOUNT AS
(SELECT RPT_CP_CODE,
  RPT_BR_CODE,
  RPT_DIS_COST_CENTER AS RPT_COST_CENTER,
  RPT_DIS_COA3 AS RPT_COA3_CODE,
  RPT_MCT_CODE,
  RPT_CON_HOS,
  'DISCOUNT' AS RPT_TR_TYPE,
  RPT_OPD_IPD,
  RPT_CSH_CRD,
  RPT_ACT_DATE,
  RPT_SLIP_NUM,
        RPT_MPA_CODE,
  RPT_COMPANY,
        RPT_DOA,
  RPT_DOD,
  RPT_MPT_ID,
  RPT_PATIENT,
  RPT_CSH_CNT,
  0 AS RPT_CSH_GRS_AMT,
  RPT_CSH_DIS_AMT,
    0 AS RPT_CSH_NET_AMT,
    RPT_CRD_CNT,
    0 AS RPT_CRD_GRS_AMT,
    RPT_CRD_DIS_AMT,
    0 AS RPT_CRD_NET_AMT
FROM HOS_MOR_CONSULTANCY
WHERE RPT_DIS_COST_CENTER IS NOT NULL
AND   RPT_DIS_COA3 IS NOT NULL
UNION ALL
SELECT RPT_CP_CODE,
  RPT_BR_CODE,
  RPT_DIS_COST_CENTER AS RPT_COST_CENTER,
  RPT_DIS_COA3 AS RPT_COA3_CODE,
  RPT_MCT_CODE,
  RPT_CON_HOS,
  'DISCOUNT' AS RPT_TR_TYPE,
  RPT_OPD_IPD,
  RPT_CSH_CRD,
  RPT_ACT_DATE,
  RPT_SLIP_NUM,
        RPT_MPA_CODE,
  RPT_COMPANY,
        RPT_DOA,
  RPT_DOD,
  RPT_MPT_ID,
  RPT_PATIENT,
  RPT_CSH_CNT,
  0 AS RPT_CSH_GRS_AMT,
  RPT_CSH_DIS_AMT,
    0 AS RPT_CSH_NET_AMT,
    RPT_CRD_CNT,
    0 AS RPT_CRD_GRS_AMT,
    RPT_CRD_DIS_AMT,
    0 AS RPT_CRD_NET_AMT
FROM HOS_MOR_SERVICES
WHERE RPT_DIS_COST_CENTER IS NOT NULL
AND   RPT_DIS_COA3 IS NOT NULL
UNION ALL
SELECT MPF_CP_CODE AS RPT_CP_CODE,
 MPF_BR_CODE AS RPT_BR_CODE,
 SDI_DP_CODE AS RPT_COST_CENTER,
 SDI_COA3_CODE AS RPT_COA3_CODE,
 MPF_MCT_CODE AS RPT_MCT_CODE,
 DECODE(NVL(MPF_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| MPF_MCT_CODE ||']') AS RPT_CON_HOS,
  'DISCOUNT' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
  MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
  MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPF_TYPE,'C',NVL(MPF_GRS_AMT,0),0)
  0 AS RPT_CSH_GRS_AMT,
  DECODE(MPF_TYPE,'C',NVL(MPF_DISC_AMT,0),0) AS RPT_CSH_DIS_AMT,
    --DECODE(MPF_TYPE,'C',NVL(MPF_GRS_AMT,0)-NVL(MPF_DISC_AMT,0),0)
    0 AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPF_TYPE,'R',NVL(MPF_GRS_AMT,0),0)
    0 AS RPT_CRD_GRS_AMT,
    DECODE(MPF_TYPE,'R',NVL(MPF_DISC_AMT,0),0) AS RPT_CRD_DIS_AMT,
    --DECODE(MPF_TYPE,'R',NVL(MPF_GRS_AMT,0)-NVL(MPF_DISC_AMT,0),0)
    0 AS RPT_CRD_NET_AMT
FROM HOS_TM_PATIENT_FILE
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MPF_CP_CODE AND MCT_CODE = MPF_MCT_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
INNER JOIN PPI_SO_DISC_INFO ON (SDI_CP_CODE = MPF_CP_CODE AND SDI_BR_CODE = MPF_BR_CODE AND SDI_CODE = MPF_SDD_SDI_CODE)
WHERE NVL(MPF_DISC_AMT,0) > 0
UNION ALL
SELECT MPR_CP_CODE AS RPT_CP_CODE,
 MPR_BR_CODE AS RPT_BR_CODE,
 SDI_DP_CODE AS RPT_COST_CENTER,
 SDI_COA3_CODE AS RPT_COA3_CODE,
 MPR_MCT_CODE AS RPT_MCT_CODE,
 DECODE(NVL(MPR_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| MPR_MCT_CODE ||']') AS RPT_CON_HOS,
  'DISCOUNT' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPR_REG_TYPE AS RPT_CSH_CRD,
  MPR_REG_DATE AS RPT_ACT_DATE,
  MPR_REG_NUM  AS RPT_SLIP_NUM,
  MPR_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPR_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPR_MPA_CODE ||']') AS RPT_COMPANY,
  NULL AS RPT_DOA,
  NULL AS RPT_DOD,
  MPR_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPR_MPT_ID) AS RPT_PATIENT,
  DECODE(MPR_REG_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPR_REG_TYPE,'C',NVL(MPR_GRS_AMT,0),0)
  0 AS RPT_CSH_GRS_AMT,
  DECODE(MPR_REG_TYPE,'C',NVL(MPR_DISCOUNT,0),0) AS RPT_CSH_DIS_AMT,
  --DECODE(MPR_REG_TYPE,'C',NVL(MPR_AMT_IN_ADV,0),0)
  0 AS RPT_CSH_NET_AMT,
    DECODE(MPR_REG_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPR_REG_TYPE,'R',NVL(MPR_GRS_AMT,0),0)
    0 AS RPT_CRD_GRS_AMT,
    DECODE(MPR_REG_TYPE,'R',NVL(MPR_DISCOUNT,0),0) AS RPT_CRD_DIS_AMT,
    DECODE(MPR_REG_TYPE,'R',NVL(MPR_AMT_IN_ADV,0),0) AS RPT_CRD_NET_AMT
FROM HOS_TM_PAT_REGISTRATION
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MPR_CP_CODE AND MCT_CODE = MPR_MCT_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPR_CP_CODE AND MPA_CODE = MPR_MPA_CODE AND MPA_TYPE <> 'W')
INNER JOIN PPI_SO_DISC_INFO ON (SDI_CP_CODE = MPR_CP_CODE AND SDI_BR_CODE = MPR_BR_CODE AND SDI_CODE = MPR_SDD_SDI_CODE)
WHERE NVL(MPR_DISCOUNT,0) > 0
)
;

prompt
prompt Creating view HOS_MOR_OPERATION_THEATER
prompt =======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_OPERATION_THEATER AS
(
SELECT  DPS_CP_CODE AS RPT_CP_CODE,
  MPF_BR_CODE AS RPT_BR_CODE,
  DGM_OT_DP_CODE AS RPT_COST_CENTER,
  DSG_OTC_COA3 AS RPT_COA3_CODE,
  NULL AS RPT_MCT_CODE,
  'HOSPITAL -> ' || DECODE(NVL(DPS_MCT_CODE,'-'),'-','HOSPITAL',MCT_NAME || ' - ['|| DPS_MCT_CODE ||']') AS RPT_CON_HOS,
  'OPERATION THEATER' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
  MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
  MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  DECODE(MPF_TYPE,'C',DPS_OT_AMT,0) AS RPT_CSH_GRS_AMT,
  DECODE(MPF_TYPE,'C',0,0) AS RPT_CSH_DIS_AMT,
    DECODE(MPF_TYPE,'C',DPS_OT_AMT,0) AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    DECODE(MPF_TYPE,'R',DPS_OT_AMT,0) AS RPT_CRD_GRS_AMT,
    DECODE(MPF_TYPE,'R',0,0) AS RPT_CRD_DIS_AMT,
    DECODE(MPF_TYPE,'R',DPS_OT_AMT,0) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_PAT_SUR
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DPS_CP_CODE AND MPF_FILE_NUM = DPS_MPF_FILE_NUM AND MPF_MPT_ID = DPS_MPF_MPT_ID)
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = DPS_CP_CODE AND MCT_CODE = DPS_MCT_CODE)
LEFT JOIN HOS_SD_SURGERIES ON (DSG_CP_CODE = DPS_CP_CODE AND DSG_CODE = DPS_DSG_CODE)
LEFT JOIN HOS_SD_SURGERIES_MAPPING ON (DGM_CP_CODE  = DPS_CP_CODE AND DGM_DSG_CODE = DPS_DSG_CODE AND DGM_BR_CODE = MPF_BR_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
WHERE NVL(DPS_INC_FLAG,'N') = 'N'
AND   NVL(DPS_OT_AMT,0) > 0
);

