prompt Creating view HOS_MOR_PHARMACY
prompt ==============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_PHARMACY AS
(
SELECT MSL_CP_CODE AS RPT_CP_CODE,
 MSL_BR_CODE AS RPT_BR_CODE,
 MSL_LOC_CODE AS RPT_COST_CENTER,
 GET_INV_COA_DP(MSL_CP_CODE, DSL_DIT_CODE, MSL_LOC_CODE, 'ITM', 'SI', 'C') AS RPT_COA3_CODE,
 NULL AS RPT_MCT_CODE,
 'HOSPITAL' AS RPT_CON_HOS,
  'PHARMACY' AS RPT_TR_TYPE,
  DECODE(NVL(MSL_MPF_FILE_NUM,'-'),'-','OPD','IPD') AS RPT_OPD_IPD,
  DECODE(MSL_SAL_TYPE,'C','C','R') AS RPT_CSH_CRD,
  DECODE(NVL(MSL_MPF_FILE_NUM,'-'),'-',MSL_DATE,MBP_DATE) AS RPT_ACT_DATE,
  DECODE(NVL(MSL_MPF_FILE_NUM,'-'),'-',MSL_NUM,MSL_MPF_FILE_NUM) AS RPT_SLIP_NUM,
  MSL_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MSL_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MSL_MPA_CODE ||']') AS RPT_COMPANY,
  DECODE(NVL(MSL_MPF_FILE_NUM,'-'),'-',NULL,MPF_ADM_DATE) AS RPT_DOA,
  DECODE(NVL(MSL_MPF_FILE_NUM,'-'),'-',NULL,MPF_DIS_DATE) AS RPT_DOD,
  MSL_PAT_ID AS RPT_MPT_ID,
  MSL_PAT_DESC AS RPT_PATIENT,
  DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'C',1,0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CSH_CNT,
  DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'C',NVL(DSL_AMOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CSH_GRS_AMT,
  DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'C',NVL(DSL_DISCOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CSH_DIS_AMT,
    DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'C',NVL(DSL_NET_AMOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CSH_NET_AMT,
    DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'R',1,0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CRD_CNT,
    DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'R',NVL(DSL_AMOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CRD_GRS_AMT,
    DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'R',NVL(DSL_DISCOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CRD_DIS_AMT,
    DECODE(DECODE(MSL_SAL_TYPE,'C','C','R'),'R',NVL(DSL_NET_AMOUNT,0),0) * DECODE(MSL_TRN_TYPE,'SR',-1,1) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_SALES
INNER JOIN HOS_TM_SALES ON (MSL_CP_CODE = DSL_CP_CODE AND MSL_NUM = DSL_MSL_NUM)
LEFT JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = MSL_CP_CODE AND MPF_FILE_NUM = MSL_MPF_FILE_NUM)
LEFT JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MPF_CP_CODE AND MCT_CODE = MPF_MCT_CODE)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
);

