prompt Creating view HOS_MOR_ROOMS
prompt ===========================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MOR_ROOMS AS
(
SELECT  MRM_CP_CODE AS RPT_CP_CODE,
  MPF_BR_CODE AS RPT_BR_CODE,
  MRM_DP_CODE AS RPT_COST_CENTER,
  MRM_ISL_COA3 AS RPT_COA3_CODE,
  NULL AS RPT_MCT_CODE,
  NULL AS RPT_CON_HOS,
  'ROOM CHARGES' AS RPT_TR_TYPE,
  'IPD' AS RPT_OPD_IPD,
  MPF_TYPE AS RPT_CSH_CRD,
  MBP_DATE AS RPT_ACT_DATE,
  MPF_FILE_NUM  AS RPT_SLIP_NUM,
  MPF_MPA_CODE AS RPT_MPA_CODE,
  DECODE(NVL(MPF_MPA_CODE,'-'),'-',NULL,MPA_SHT_DESC || ' - ['|| MPF_MPA_CODE ||']') AS RPT_COMPANY,
  MPF_ADM_DATE AS RPT_DOA,
  MPF_DIS_DATE AS RPT_DOD,
  MPF_MPT_ID AS RPT_MPT_ID,
  GET_PATIENT_NAME(MPF_MPT_ID) AS RPT_PATIENT,
  DECODE(MPF_TYPE,'C',1,0) AS RPT_CSH_CNT,
  --DECODE(MPF_TYPE,'C',DRM_AMT,0)
  DECODE(MPF_TYPE,'C',DRM_NET_AMT,0) AS RPT_CSH_GRS_AMT,
  --DECODE(MPF_TYPE,'C',DRM_DISC_AMT,0)
  0 AS RPT_CSH_DIS_AMT,
    DECODE(MPF_TYPE,'C',DRM_NET_AMT,0) AS RPT_CSH_NET_AMT,
    DECODE(MPF_TYPE,'R',1,0) AS RPT_CRD_CNT,
    --DECODE(MPF_TYPE,'R',DRM_AMT,0)
    DECODE(MPF_TYPE,'R',DRM_NET_AMT,0) AS RPT_CRD_GRS_AMT,
    --DECODE(MPF_TYPE,'R',DRM_DISC_AMT,0)
    0 AS RPT_CRD_DIS_AMT,
    DECODE(MPF_TYPE,'R',DRM_NET_AMT,0) AS RPT_CRD_NET_AMT,
  NULL AS RPT_DIS_HEAD,
  NULL AS RPT_DIS_COST_CENTER,
  NULL AS RPT_DIS_COA3
FROM HOS_TD_PAT_ROOM_MOVM_INFO
LEFT JOIN HOS_SM_ROOMS ON (MRM_CP_CODE = DRM_CP_CODE AND MRM_CODE = DRM_MRM_CODE)
INNER JOIN HOS_TM_PATIENT_FILE ON (MPF_CP_CODE = DRM_CP_CODE AND MPF_FILE_NUM = DRM_MPF_FILE_NUM AND MPF_MPT_ID = DRM_MPF_MPT_ID)
INNER JOIN HOS_TO_BILL_PROCESS ON (MBP_CP_CODE = MPF_CP_CODE AND MBP_MPF_FILE_NUM = MPF_FILE_NUM)
LEFT JOIN HOS_SM_PANEL ON (MPA_CP_CODE = MPF_CP_CODE AND MPA_CODE = MPF_MPA_CODE AND MPA_TYPE <> 'W')
WHERE NVL(DRM_INC_FLAG,'N') = 'N'
)
;

