prompt Creating view HOS_MULTIPLE_DISCOUNT_SLIP_VW
prompt ===========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.HOS_MULTIPLE_DISCOUNT_SLIP_VW AS
SELECT MPF_ADM_DATE AS TRN_ADM_DATE, MPF_DIS_DATE AS TRN_DATE, MPF_MPT_ID AS TRN_MPT_ID, MPT_NAME AS TRN_MPT_NAME, 'HOSAS11' AS TRN_PRG_CODE, MPF_BR_CODE AS TRN_BR_CODE, MPF_FILE_NUM AS TRN_NO, MPF_DIS_CODE AS TRN_REF_NO,  'IP' AS TRN_OPD_IPD_TYPE, NVL(MPF_GRS_AMT ,0) AS TRN_AMOUNT, MPF_INS_USER AS TRN_INS_USER, MPF_INS_DATE AS TRN_INS_DATE, MPF_INS_TIME AS TRN_INS_TIME, MPF_DIS_CODE AS TRN_REF_NUM, MPF_REMARKS AS REMARKS, 'CD' AS TRN_CHG_DNR, MPF_FILE_NUM AS TRN_SEQ,
       MPF_MCT_CODE AS TRN_MCT_CODE
FROM   HOS_SM_PATIENT, HOS_TM_PATIENT_FILE, HOS_TO_BILL_PROCESS
WHERE  MPF_CP_CODE         = MPT_CP_CODE
AND    MPF_MPT_ID          = MPT_ID
AND    MPF_FILE_NUM        = MBP_MPF_FILE_NUM
AND    MPF_MPT_ID          = MBP_MPT_ID
AND    MBP_DATE        NOT IN (SELECT DISTINCT MVH_DATE
                               FROM   ACT_TM_VOUCHER
                               WHERE  MVH_NUM LIKE '%98%'
                               AND    MVH_REM = 'DAY END POSTING - AUTO GENERATED')
ORDER BY TRN_DATE, TRN_SEQ;

