prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_HINT_REMARK_VIEW AS
SELECT  RTH_CP_CODE "RH_CP_CODE" , RTH_LTP_SRV_CODE "RH_LTP_SRV_CODE" , RTH_LTP_PMT_CODE "RH_LTP_PMT_CODE", RTH_HINTS  "RH_HINTS" , LTP_HINT_REMARK
 "RH_HINT_REMARK" ,  nvl(RTH_SEQ_NUM,0) "RTH_SEQ_NUM"
  FROM LAB_SD_LTP_RTH  ,  LAB_SM_LTP_INFO
  WHERE RTH_CP_CODE        = LTP_CP_CODE
  AND   RTH_LTP_SRV_CODE   = LTP_SRV_CODE
  AND   RTH_LTP_PMT_CODE   = LTP_PMT_CODE
  AND   RTH_ACTIVE         = 'Y'
  AND   NVL(LTP_HINT_REMARK,'N')    = 'Y'
  order by nvl(RTH_SEQ_NUM,0);

