prompt Creating view LAB_IPD_SPC_COLLECTED
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_IPD_SPC_COLLECTED
(tr_cp_code, tr_doc_num, tr_spc_date, tr_spc_num, tr_srv_date, tr_dsc_code, tr_dsc_desc, tr_smn_coll, tr_rep_avl)
AS
SELECT  MIS_CP_CODE AS TR_CP_CODE, MIS_DOC_NUM AS TR_DOC_NUM, MIS_SPC_DATE ASTR_SPC_DATE, MIS_SPC_NUM AS TR_SPC_NUM,
 DIS_SRV_DATE AS TR_SRV_DATE, DIS_DSC_CODE AS TR_DSC_CODE, DSC_DESC AS TR_DSC_DESC, NVL(DHS_SMN_COLL,'N') AS TR_SMN_COLL,
 NVL(DHS_REP_AVL,'N') AS TR_REP_AVL
FROM    LAB_TD_IPD_SRVS
INNER   JOIN LAB_TM_IPD_SRVS ON (MIS_CP_CODE      = DIS_CP_CODE
     AND MIS_SPC_NUM  = DIS_SPC_NUM
     AND MIS_SPC_DATE = DIS_SPC_DATE
     AND MIS_DOC_NUM  = DIS_DOC_NUM)
INNER   JOIN  HOS_SD_SRV_CHARGES ON (DSC_CP_CODE = DIS_CP_CODE
     AND   DSC_CODE    = DIS_DSC_CODE)
LEFT    JOIN  HOS_TD_PAT_HOSP_SRV ON (DHS_CP_CODE = DIS_CP_CODE
     AND  DHS_MPF_FILE_NUM = DIS_DOC_NUM
     AND  DHS_DSC_CODE     = DIS_DSC_CODE
     AND  DHS_SRV_DATE     = DIS_SRV_DATE
     AND  DHS_SEQ_NUM      = DIS_SEQ_NUM
     AND  DHS_SPC_NUM      = DIS_SPC_NUM
     AND  NVL(DHS_SMN_COLL,'N')  = 'Y');

