prompt Creating view LAB_RO_COVID19_REPORT
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_RO_COVID19_REPORT AS
SELECT ROWNUM AS "S_NO",
       MSR_DATE AS "DATE_",
       MSR_PAT_ID AS "MR_NO" ,
       MSR_NUM "LAB_NO",
       MSR_NAME "NAME",
       DECODE(MPT_FATHER_NAME,NULL,NULL,MPT_RELT_FLAG||'/O '||MPT_FATHER_NAME) AS "SO_DO_WO",
       DECODE(MSR_MPT_SEX,'F','Female','M','Male',MSR_MPT_SEX) AS "GENDER",
       MSR_MPT_AGE AS "AGE",
      (SELECT ARE_DESC FROM HOS_SO_AREA WHERE ARE_CP_CODE = MSR_CP_CODE AND ARE_CODE = MPT_ARE_CODE) AS "DISTRICT_",
       MPT_ID_CARD AS "CNIC",
       NVL(MSR_ADDRESS,MPT_ADDRESS1) AS "ADDRESS",
       MSR_PHONE AS "CONTACT_NO",
       DECODE(DSD_RESULT,'N','NEGATIVE','P','POSITIVE',DSD_RESULT) AS "RESULT",
       MSR_BR_CODE,
       DSD_DSC_CODE,
       MSR_DATE
FROM   LAB_TM_DIAGNOSIS,LAB_TD_SRV_DIAG,HOS_SM_PATIENT,HOS_TM_OPD_SRV_RCPT
WHERE  MDG_CP_CODE  = DSD_CP_CODE
AND    MDG_RPT_ID   = DSD_RPT_ID
AND    MDG_CP_CODE  = MPT_CP_CODE
AND    MDG_PAT_ID   = MPT_ID
AND    MDG_RCT_NUM  = DSD_RCT_NUM
AND    MSR_CP_CODE  = MDG_CP_CODE
AND    MSR_PAT_ID   = MDG_PAT_ID
AND    MSR_NUM      = MDG_RCT_NUM
AND    DSD_STATUS = 'C'
--AND    MSR_BR_CODE  = NVL(:LC_BR_CODE,MSR_BR_CODE)
--AND    DSD_DSC_CODE BETWEEN :LC_CODE_FM AND :LC_CODE_TO
--AND    MSR_DATE BETWEEN :LC_FM_DATE AND:LC_TO_DATE
ORDER BY MSR_DATE
;

