prompt Creating view LAB_SRV_SPECIMEN_FOR_RESULTS
prompt ==========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_SRV_SPECIMEN_FOR_RESULTS AS
(SELECT  MSC_CP_CODE, MSC_SPC_NUM, MSC_SPC_DATE, MSC_DOC_NUM, MSC_DOC_DATE,
              MSC_LTS_TYPE, MSC_PAT_ID, MSC_PAT_NAME, MSC_PAT_AGE, MSC_PAT_GND, MSC_PST_FLAG,
              MSC_CONSULTANT, MSC_INS_USER, MSC_INS_DATE, MSC_INS_TIME, MSC_UPD_USER,
              MSC_UPD_DATE, MSC_UPD_TIME, DSC_CP_CODE, DSC_DOC_NUM, DSC_DSC_CODE, DSC_SRV_DATE, DSC_SMN_DESC,
              DSC_DLV_DATE, DSC_DLV_TIME, DSC_MCT_CODE, DSC_SEQ_NUM, DSC_INS_USER, DSC_INS_DATE,
              DSC_INS_TIME, DSC_UPD_USER, DSC_UPD_DATE, DSC_UPD_TIME, DSC_COLL_FLAG
              FROM LAB_TM_SMN_COLL, LAB_TD_SMN_COLL, HOS_TD_OPD_SRV_RCPT
              WHERE MSC_CP_CODE = DSC_CP_CODE
              AND MSC_SPC_NUM = DSC_SPC_NUM
              AND MSC_SPC_DATE = DSC_SPC_DATE
              AND MSC_DOC_NUM = DSC_DOC_NUM
              AND DSR_CP_CODE  = DSC_CP_CODE
              AND DSR_MSR_NUM = DSC_DOC_NUM
              AND DSR_DSC_CODE = DSC_DSC_CODE
              AND DSR_DLV_DATE IS NOT NULL
              AND DSR_DLV_FLAG = 'N'
              AND DSR_RFD_FLAG = 'N'
              AND DSR_REP_FLAG = 'N'
              AND DSR_SMN_FLAG  = 'Y');

prompt
prompt Creating view LAB_SRV_SERVICES_FOR_RESULTS
prompt ==========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_SRV_SERVICES_FOR_RESULTS AS
(SELECT DSR_CP_CODE,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_DOC_NUM, MSR_NUM)     AS MSR_NUM,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_DOC_DATE, MSR_DATE)    AS MSR_DATE,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_PAT_ID, MSR_PAT_ID)     AS MSR_PAT_ID,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_PAT_NAME, MSR_NAME)      AS MPT_NAME,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', NULL, MSR_MCT_CODE)    AS MSR_MCT_CODE,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_CONSULTANT, MCT_NAME)    AS MCT_NAME,
              MSR_REF_MCT_NAME MSR_REF_MCT_NAME,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_PAT_AGE,  MSR_PAT_AGE)    AS MSR_PAT_AGE,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_PAT_GND,  MSR_PAT_GENDER)  AS MSR_PAT_GENDER,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', NULL, MSR_INS_DATE)      AS MSR_INS_DATE,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', NULL, MSR_INS_TIME)      AS MSR_INS_TIME,
              DECODE(NVL(DSR_SMN_FLAG,'N'), 'Y', MSC_SPC_NUM, NULL)       AS MSR_SPC_NUM,
              DSR_SMN_FLAG, LTI_SMN_FLAG, DSR_DSC_CODE , MSR_BR_CODE
              FROM HOS_TD_OPD_SRV_RCPT
              INNER JOIN LAB_SM_LT_INFO ON (LTI_CP_CODE    = DSR_CP_CODE
                      AND   LTI_SRV_CODE   = DSR_DSC_CODE)
              INNER JOIN HOS_TM_OPD_SRV_RCPT ON (MSR_CP_CODE  = DSR_CP_CODE
                          AND MSR_NF_TYPE   = DSR_MSR_NF_TYPE
                          AND MSR_DATE         = DSR_MSR_DATE
                          AND MSR_NUM          = DSR_MSR_NUM
                          AND MSR_PAT_TYPE = DSR_MSR_PAT_TYPE)
              LEFT JOIN HOS_SM_CONSULTANT ON (MCT_CP_CODE = MSR_CP_CODE
                      AND   MCT_CODE = MSR_MCT_CODE)
              LEFT JOIN LAB_SRV_SPECIMEN_FOR_RESULTS ON (DSR_CP_CODE  = DSC_CP_CODE
                      AND DSR_MSR_NUM = DSC_DOC_NUM
                      AND DSR_DSC_CODE = DSC_DSC_CODE)
              WHERE DSR_DLV_DATE IS NOT NULL
              AND DSR_DLV_FLAG = 'N'
              AND DSR_RFD_FLAG = 'N'
              AND DSR_REP_FLAG = 'N');

prompt
prompt Creating view LAB_TEST_SMN_INFO
prompt ===============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_TEST_SMN_INFO AS
SELECT 'OPD' AS LTS_TYPE, A.MSR_CP_CODE LTS_CP_CODE, A.MSR_NUM LTS_DOC_NUM, A.MSR_PAT_ID LTS_PAT_ID,
            A.MSR_NAME LTS_PAT_NAME, A.MSR_DATE LTS_DOC_DATE,A.MSR_MPT_AGE LTS_PAT_AGE, MSR_MPT_SEX LTS_PAT_GENDER,
            A.MSR_INS_DATE LTS_INS_DATE, A.MSR_INS_TIME LTS_INS_TIME , A.MSR_BR_CODE LTS_BR_CODE
              FROM HOS_TM_OPD_SRV_RCPT A
              WHERE    EXISTS
                                 (SELECT   1
                                 FROM HOS_TD_OPD_SRV_RCPT B INNER JOIN LAB_SM_LT_INFO
                                 ON(   LTI_CP_CODE  =  B.DSR_CP_CODE
                                 AND   LTI_SRV_CODE =  B.DSR_DSC_CODE
                                 AND   LTI_SMN_FLAG =  'Y')
                                 WHERE    B.DSR_CP_CODE   = A.MSR_CP_CODE
                                 AND      B.DSR_MSR_NUM   = A.MSR_NUM
                                 AND      B.DSR_SMN_FLAG  = 'N'
                                 AND      B.DSR_RFD_FLAG  = 'N'
                                 AND      B.DSR_DLV_DATE IS NOT NULL)
            ---AND      NVL(MSR_PRT_FLAG,'N') =  'Y'
            AND     DECODE(MSR_PRG_CODE,'HOSAS26',NVL(MSR_PRT_FLAG,'N'),'Y')  = 'Y'
            AND      NVL(MSR_REF_NUM,'-')  = '-'
;

