prompt Creating view LAB_TEST_SMN_INFO_BREAKUP
prompt =======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_TEST_SMN_INFO_BREAKUP AS
SELECT 'OPD' AS LTS_TYPE,         MSR_CP_CODE LTS_CP_CODE,            MSR_NUM LTS_DOC_NUM,              MSR_PAT_ID LTS_PAT_ID,
       MSR_NAME LTS_PAT_NAME,     MSR_DATE LTS_DOC_DATE,              MSR_MPT_AGE LTS_PAT_AGE,          MSR_MPT_SEX LTS_PAT_GENDER,
       MSR_INS_DATE LTS_INS_DATE, MSR_INS_TIME LTS_INS_TIME,          MSR_BR_CODE LTS_BR_CODE,          DSR_SSB_TYPE LTS_SSB_TYPE,
       DSR_SRV_GRP LTS_SRV_GRP,   DSR_SPC_BCODE LTS_SPC_BCODE
FROM   HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT,LAB_SM_LT_INFO
WHERE  MSR_CP_CODE   = DSR_CP_CODE
AND    MSR_NUM       = DSR_MSR_NUM
AND    LTI_CP_CODE   = DSR_CP_CODE
AND    LTI_SRV_CODE  = DSR_DSC_CODE
AND    LTI_SMN_FLAG  =  'Y'
AND    DSR_SMN_FLAG  = 'N'
AND    DSR_RFD_FLAG  = 'N'
AND    DSR_DLV_DATE IS NOT NULL
AND    DECODE(MSR_PRG_CODE,'HOSAS26',NVL(MSR_PRT_FLAG,'N'),'Y')  = 'Y'
AND    NVL(MSR_REF_NUM,'-')  = '-'
GROUP BY MSR_CP_CODE,MSR_NUM,MSR_PAT_ID,MSR_NAME,MSR_DATE,MSR_MPT_AGE,MSR_MPT_SEX,MSR_INS_DATE,MSR_INS_TIME,MSR_BR_CODE,DSR_SSB_TYPE,DSR_SRV_GRP,DSR_SPC_BCODE;

