prompt Creating view LAB_TEST_SMN_INFO_OLD
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_TEST_SMN_INFO_OLD AS
SELECT 'OPD' AS LTS_TYPE, A.MSR_CP_CODE LTS_CP_CODE, A.MSR_NUM LTS_DOC_NUM, A.MSR_PAT_ID LTS_PAT_ID,
            A.MSR_NAME LTS_PAT_NAME, A.MSR_DATE LTS_DOC_DATE,A.MSR_MPT_AGE LTS_PAT_AGE, MSR_MPT_SEX LTS_PAT_GENDER,
            A.MSR_INS_DATE LTS_INS_DATE, A.MSR_INS_TIME LTS_INS_TIME , A.MSR_BR_CODE LTS_BR_CODE
            FROM HOS_TM_OPD_SRV_RCPT A
            WHERE A.MSR_NUM  IN
                               (SELECT B.DSR_MSR_NUM
                                 FROM HOS_TD_OPD_SRV_RCPT B, LAB_SM_LT_INFO
                                 WHERE B.DSR_SMN_FLAG = 'N'
                                 AND   B.DSR_RFD_FLAG = 'N'
                                 AND   B.DSR_DLV_DATE IS NOT NULL
                                 ---AND   GET_REFUND(B.DSR_CP_CODE, B.DSR_MSR_NUM , B.DSR_DSC_CODE) = 'F'
                                 AND   LTI_CP_CODE  = B.DSR_CP_CODE
                                 AND   LTI_SRV_CODE = B.DSR_DSC_CODE
                                AND   LTI_SMN_FLAG = 'Y')
            AND  MSR_REF_NUM  IS NULL
;

