prompt Creating view LAB_TO_B2B_INTERFACE
prompt ==================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_TO_B2B_INTERFACE AS
SELECT MSR_DATE, MSR_NUM, MSR_PAT_ID, MSR_NAME, MPT_FATHER_NAME, MPT_SEX, MPT_DOB, MPT_AGE, MPT_MOBILE,
       DSR_DSC_CODE, DSC_DESC, DMT_TEST_NAME, DMT_MACHINE_NAME
FROM   HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT, HOS_SM_PATIENT, LAB_INT_SD_TEST_DETAILS, HOS_SD_SRV_CHARGES
WHERE  DSR_MSR_NUM = MSR_NUM
AND    DSR_CP_CODE = MSR_CP_CODE
AND    MSR_PAT_ID  = MPT_ID
AND    MSR_CP_CODE = MPT_CP_CODE
AND    DSR_CP_CODE = DSC_CP_CODE
AND    DSR_DSC_CODE = DSC_CODE
AND    MSR_PRG_CODE = 'HOSAS26'
AND    MSR_REF_TYPE  = 'I'
AND    DSR_CP_CODE = DMT_CP_CODE
AND    DSR_DSC_CODE = DMT_MLI_SRV_CODE
UNION ALL
SELECT MIS_SPC_DATE, MIS_SPC_NUM, MIS_PAT_ID, MPT_NAME, MPT_FATHER_NAME, MPT_SEX, MPT_DOB, MPT_AGE, MPT_MOBILE,
       DIS_DSC_CODE, DSC_DESC, DMT_TEST_NAME, DMT_MACHINE_NAME
FROM   LAB_TM_IPD_SRVS, LAB_TD_IPD_SRVS, HOS_SM_PATIENT, LAB_INT_SD_TEST_DETAILS, HOS_SD_SRV_CHARGES
WHERE  DIS_SPC_NUM = MIS_SPC_NUM
AND    DIS_CP_CODE = MIS_CP_CODE
AND    MIS_PAT_ID  = MPT_ID
AND    MIS_CP_CODE = MPT_CP_CODE
AND    DIS_CP_CODE = DSC_CP_CODE
AND    DIS_DSC_CODE = DSC_CODE
AND    MIS_PRG_CODE = 'HOSAS26'
AND    DIS_CP_CODE = DMT_CP_CODE
AND    DIS_DSC_CODE = DMT_MLI_SRV_CODE
ORDER BY 1, 10;

