prompt Creating function GET_SERVICE_DESC
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_SERVICE_DESC (ARG_CP_CODE VARCHAR2, ARG_SER_CODE VARCHAR2 , ARG_FLAG VARCHAR2)
RETURN VARCHAR2 IS

LC_LTI_REP_HEADER  VARCHAR2(1000);
BEGIN
    IF  ARG_FLAG = 'H' THEN
          BEGIN
              SELECT LTI_REP_HEADER
              INTO   LC_LTI_REP_HEADER
              FROM LAB_SM_LT_INFO
              WHERE LTI_REP_HEADER IS NOT NULL
              AND   LTI_CP_CODE   =  ARG_CP_CODE

              AND   LTI_SRV_CODE  =  ARG_SER_CODE;
          EXCEPTION
                WHEN OTHERS THEN
                LC_LTI_REP_HEADER  := NULL;
          END;
    ELSIF  ARG_FLAG = 'S' THEN
          BEGIN
            SELECT  DSC_DESC
            INTO   LC_LTI_REP_HEADER
            FROM   HOS_SD_SRV_CHARGES, HOS_SM_SRV_CHARGES
            WHERE  DSC_CP_CODE   = ARG_CP_CODE
            AND    DSC_CP_CODE   = MSC_CP_CODE
            AND    DSC_MSC_CODE  = MSC_CODE

            AND    DSC_CODE      = ARG_SER_CODE;
          EXCEPTION
            WHEN OTHERS THEN
              LC_LTI_REP_HEADER  := NULL;
          END;
  ELSIF  ARG_FLAG = 'HH' THEN
   BEGIN

             SELECT HSC_DESC
             INTO   LC_LTI_REP_HEADER
             FROM   HOS_SM_SRV_CTG
             WHERE  HSC_CP_CODE = ARG_CP_CODE
             AND    HSC_CODE    =
                                     (SELECT DSC_HSC_CODE
                                     FROM    HOS_SD_SRV_CHARGES, HOS_SM_SRV_CHARGES
                                     WHERE   DSC_CP_CODE   = ARG_CP_CODE
                                     AND     DSC_CP_CODE   = MSC_CP_CODE
                                     AND     DSC_MSC_CODE  = MSC_CODE
                                     AND     DSC_CODE      = ARG_SER_CODE);
          EXCEPTION
            WHEN OTHERS THEN
              LC_LTI_REP_HEADER  := 'Others';
          END;
     ELSIF  ARG_FLAG = 'HC' THEN
           BEGIN

                SELECT DSC_HSC_CODE
                   INTO   LC_LTI_REP_HEADER
                FROM    HOS_SD_SRV_CHARGES, HOS_SM_SRV_CHARGES
                WHERE   DSC_CP_CODE   = ARG_CP_CODE
                AND     DSC_CP_CODE   = MSC_CP_CODE
                AND     DSC_MSC_CODE  = MSC_CODE
                AND     DSC_CODE      = ARG_SER_CODE;
          EXCEPTION
            WHEN OTHERS THEN
              LC_LTI_REP_HEADER  := '004';
          END;

    END IF;
RETURN LC_LTI_REP_HEADER;
END;
/

