prompt Creating view LAB_VIEW_TEST_REPORT_STATUS
prompt =========================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_VIEW_TEST_REPORT_STATUS AS
SELECT  'OPD' AS TRS_TYPE
, LAB_VIEW_OPD_RECEIPTS.MSR_CP_CODE AS TRS_CP_CODE
,       LAB_VIEW_OPD_RECEIPTS.MSR_BR_CODE  AS  TRS_BR_CODE
---,  LAB_VIEW_REPORT.MDG_BR_CODE_FM  AS  TRS_BR_CODE
,       LAB_VIEW_OPD_RECEIPTS.MSR_DATE     AS  TRS_DATE
,       LAB_VIEW_OPD_RECEIPTS.MSR_NUM      AS  TRS_NUM
,       LAB_VIEW_OPD_RECEIPTS.MSR_PAT_ID AS TRS_PATIENT_ID
,       LAB_VIEW_OPD_RECEIPTS.MSR_NAME  AS  TRS_PATIENT_NAME
,       MSR_AGE_YMDW||''||MSR_AGE_TYPE||'/'||MSR_MPT_SEX AS TRS_AGE
,       LAB_VIEW_SMN_COLL.MSC_SPC_DATE  AS TRS_SPC_DATE
,       LAB_VIEW_SMN_COLL.MSC_SPC_NUM   AS TRS_SPC_NUM
,       LAB_VIEW_SMN_COLL.MSC_SPC_BCODE AS TRS_SPC_BCODE
,       LAB_VIEW_OPD_RECEIPTS.LTI_REP_HEADER   AS  TRS_REP_HEADER
,       LAB_VIEW_OPD_RECEIPTS.DSR_DSC_CODE     AS  TRS_DSC_CODE
,       GET_SERVICE_DESC('01',  LAB_VIEW_OPD_RECEIPTS.DSR_DSC_CODE   , 'S')  AS  TRS_DSC_DESC
,       GET_LAB_REPORT_STATUS
        ( LAB_VIEW_OPD_RECEIPTS.LTI_SMN_FLAG ,  LAB_VIEW_SMN_COLL.MSC_SPC_NUM  ,
          LAB_VIEW_REPORT.MDG_RCT_NUM        ,  DECODE(LAB_VIEW_REPORT.DSD_STATUS,'X','C',LAB_VIEW_REPORT.DSD_STATUS),'D') AS  TRS_REPORT_STATUS,
          GET_LAB_REPORT_STATUS
        (LAB_VIEW_OPD_RECEIPTS.LTI_SMN_FLAG  ,  LAB_VIEW_SMN_COLL.MSC_SPC_NUM  ,
          LAB_VIEW_REPORT.MDG_RCT_NUM        ,  LAB_VIEW_REPORT.DSD_STATUS,'') AS  TRS_STATUS_SEQ
,         LAB_VIEW_OPD_RECEIPTS.MSR_MPA_CODE AS TRS_MPA_CODE
          ,  LAB_VIEW_SMN_COLL.MSC_INS_TIME AS TRS_MSC_INS_TIME,
          NVL(LAB_VIEW_OPD_RECEIPTS.LTI_SMN_FLAG,'N') AS TRS_SMN_FLAG
          ,LAB_VIEW_OPD_RECEIPTS.LTI_NATURE  AS TRS_LTI_NATURE, MDG_RPT_ID AS TRS_RPT_ID
FROM      LAB_VIEW_OPD_RECEIPTS
LEFT JOIN  LAB_VIEW_SMN_COLL
                  ON( LAB_VIEW_SMN_COLL.DSC_CP_CODE  = LAB_VIEW_OPD_RECEIPTS .DSR_CP_CODE
                  AND LAB_VIEW_SMN_COLL.DSC_DOC_NUM  = LAB_VIEW_OPD_RECEIPTS .DSR_MSR_NUM
                  AND LAB_VIEW_SMN_COLL.DSC_DSC_CODE = LAB_VIEW_OPD_RECEIPTS .DSR_DSC_CODE
                  AND LAB_VIEW_SMN_COLL.MSC_LTS_TYPE = 'OPD')
LEFT JOIN LAB_VIEW_REPORT
                  ON( LAB_VIEW_REPORT.MDG_CP_CODE  = LAB_VIEW_OPD_RECEIPTS .DSR_CP_CODE
                  AND LAB_VIEW_REPORT.MDG_RCT_NUM  = LAB_VIEW_OPD_RECEIPTS .DSR_MSR_NUM
                  AND LAB_VIEW_REPORT.DSD_DSC_CODE = LAB_VIEW_OPD_RECEIPTS .DSR_DSC_CODE
                  AND LAB_VIEW_REPORT.MDG_TYPE = 'OPD')
UNION ALL
SELECT 'IPD' AS TYPE
,  LAB_VIEW_IPD_RECEIPTS.MIS_CP_CODE
                     , LAB_VIEW_IPD_RECEIPTS.MIS_BR_CODE
                     , LAB_VIEW_IPD_RECEIPTS.MIS_SPC_DATE
                     , LAB_VIEW_IPD_RECEIPTS.MIS_SPC_NUM
                     , LAB_VIEW_IPD_RECEIPTS.MIS_PAT_ID    AS PATIENT_ID
                     , LAB_VIEW_IPD_RECEIPTS.MIS_PAT_NAME  AS PATIENT_NAME
                     , LAB_VIEW_IPD_RECEIPTS.MIS_PAT_AGE||'/'||LAB_VIEW_IPD_RECEIPTS.MIS_PAT_GND
                     , LAB_VIEW_IPD_RECEIPTS.MIS_DOC_DATE
                     , LAB_VIEW_IPD_RECEIPTS.MIS_DOC_NUM
                     , LAB_VIEW_IPD_RECEIPTS.MIS_SPC_BCODE
                     , LAB_VIEW_IPD_RECEIPTS.LTI_REP_HEADER
                     , LAB_VIEW_IPD_RECEIPTS.DIS_DSC_CODE
                     , GET_SERVICE_DESC('01', LAB_VIEW_IPD_RECEIPTS.DIS_DSC_CODE  , 'S') "Test_Code_Desc"
                     , DECODE(NVL(LAB_VIEW_IPD_RECEIPTS.MIS_PST_FLAG,'U') , 'U' , 'SERVICES NOT POSTED', GET_LAB_REPORT_STATUS
                                                              (   LAB_VIEW_IPD_RECEIPTS.LTI_SMN_FLAG   ,  LAB_VIEW_IPD_RECEIPTS .MIS_SPC_NUM  ,
                                                                  LAB_VIEW_REPORT.MDG_RCT_NUM          ,  LAB_VIEW_REPORT.DSD_STATUS , 'D')) "REPORT_STATUS" ,

                       GET_LAB_REPORT_STATUS
                                                              (   LAB_VIEW_IPD_RECEIPTS.LTI_SMN_FLAG   ,  LAB_VIEW_IPD_RECEIPTS .MIS_SPC_NUM  ,
                                                                  LAB_VIEW_REPORT.MDG_RCT_NUM          ,  LAB_VIEW_REPORT.DSD_STATUS , 'D') "STATUS_SEQ",
LAB_VIEW_IPD_RECEIPTS.MPF_MPA_CODE
 ,  LAB_VIEW_IPD_RECEIPTS.MIS_INS_TIME AS TRS_MSC_INS_TIME ,
LAB_VIEW_IPD_RECEIPTS.LTI_SMN_FLAG , LAB_VIEW_IPD_RECEIPTS.LTI_NATURE,MDG_RPT_ID AS TRS_RPT_ID
FROM LAB_VIEW_IPD_RECEIPTS
LEFT JOIN LAB_VIEW_REPORT
                  ON( LAB_VIEW_REPORT.MDG_CP_CODE  = LAB_VIEW_IPD_RECEIPTS .MIS_CP_CODE
                  AND LAB_VIEW_REPORT.MDG_RCT_NUM  = LAB_VIEW_IPD_RECEIPTS .MIS_SPC_NUM
                  AND LAB_VIEW_REPORT.MDG_COL_NUM  = LAB_VIEW_IPD_RECEIPTS .MIS_DOC_NUM
                  --AND LAB_VIEW_REPORT.MDG_RCT_NUM  = LAB_VIEW_IPD_RECEIPTS .MIS_DOC_NUM
                  --AND LAB_VIEW_REPORT.DSD_SPC_NUM  = LAB_VIEW_IPD_RECEIPTS .MIS_SPC_NUM
                  AND LAB_VIEW_REPORT.DSD_DSC_CODE = LAB_VIEW_IPD_RECEIPTS .DIS_DSC_CODE
                  AND LAB_VIEW_REPORT.MDG_TYPE = 'IPD')
;

