prompt Creating view LAB_VIEW_TEST_REPORT_DIS
prompt ======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.LAB_VIEW_TEST_REPORT_DIS AS
(SELECT   DISTINCT TRS_DATE AS VRS_DATE  , TRS_CP_CODE AS VRS_CP_CODE, TRS_BR_CODE AS VRS_BR_CODE,
  TRS_TYPE AS VRS_TYPE, TRS_NUM AS VRS_NUM,
  GET_LAB_REPORT_GEN_STATUS(TRS_CP_CODE, TRS_NUM) AS VRS_STATUS
FROM LAB_VIEW_TEST_REPORT_STATUS)
ORDER BY TRS_BR_CODE , TRS_NUM;

prompt
prompt Creating view MUL_BILL_PROCESSED_FILES
prompt ======================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.MUL_BILL_PROCESSED_FILES AS
(SELECT MPF_CP_CODE, MPF_BR_CODE, MPF_FILE_NUM, MPF_MPT_ID, MPT_NAME||' '||
 DECODE(MPT_RELT_FLAG, 'S', 'S/O', 'F', 'F/O', 'W', 'W/O', 'D', 'D/O', 'M', 'M/O', 'H', 'H/O')||' '||MPT_FATHER_NAME MPT_NAME,
 MPF_ADM_DATE, MPF_DIS_DATE, MPF_DIS_CODE, MBP_DATE, MBP_USR_NAME,
 MPF_ADVANCE_AMT,
 MPF_NET_TOT AS BILL_AMT, DECODE(MPF_TYPE, 'C', MPF_NET_TOT, MPF_MPT_AMT) AS REC_REF_AMT,
 MPF_GRS_AMT,
 MPF_DISC_AMT,
 NVL(MPF_GRS_AMT,0) - NVL(MPF_DISC_AMT,0) AS MPF_NET_AMT
FROM HOS_TO_BILL_PROCESS, HOS_TM_PATIENT_FILE, HOS_SM_PATIENT
WHERE MPF_CP_CODE  = MBP_CP_CODE
AND   MPF_FILE_NUM = MBP_MPF_FILE_NUM
AND   MPF_MPT_ID   = MBP_MPT_ID
AND   MPT_ID       = MBP_MPT_ID);

prompt
prompt Creating view OPD_CON_NETAMT
prompt ============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.OPD_CON_NETAMT AS
(
SELECT CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE, SUM(CBL_NET_AMT) AS CBL_NET_AMT
FROM (
SELECT /*+ index (HOS_TM_OPD_CON_RCPT, HOS_TM_OPD_CON_RCPT_IND10) */
 MCR_CP_CODE AS CBL_CP_CODE, MCR_NUM AS CBL_SLIP_NUM, MCR_MPA_CODE AS CBL_MPA_CODE, MCR_NET_AMT AS CBL_NET_AMT
FROM  HOS_TM_OPD_CON_RCPT
WHERE MCR_TYPE     = 'R'
AND   MCR_MPA_CODE IS NOT NULL
AND   MCR_RCP_TYPE = 'RC'
AND   MCR_NF_TYPE  = 'N'
UNION ALL
SELECT /*+ index (HOS_TM_OPD_CON_RCPT, HOS_TM_OPD_CON_RCPT_IND10) */
 MCR_CP_CODE AS CBL_CP_CODE, MCR_REF_NUM AS CBL_SLIP_NUM, MCR_MPA_CODE AS CBL_MPA_CODE, -1*MCR_NET_AMT AS CBL_NET_AMT
FROM   HOS_TM_OPD_CON_RCPT
WHERE MCR_TYPE     = 'R'
AND   MCR_MPA_CODE IS NOT NULL
AND   MCR_RCP_TYPE = 'RR'
AND   MCR_NF_TYPE  = 'N')
GROUP BY CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE);

prompt
prompt Creating view OPD_CON_VISIT_HISTORY
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.OPD_CON_VISIT_HISTORY AS
SELECT  TO_CHAR(MCR_DATE,'MM-YYYY')AS DMONWISE,
        TO_CHAR(MCR_DATE,'YYYY')AS YEARWISE,
        TO_CHAR(MCR_DATE,'MON-YYYY')AS MONWISE,
        MCR_CP_CODE,MCR_MPT_ID,MCR_MCT_CODE,MCR_DEP_CODE ,
        COUNT(*) VISITS
FROM HOS_TM_OPD_CON_RCPT
WHERE   MCR_REF_NUM IS NULL
AND MCR_NUM NOT IN (SELECT MCR_REF_NUM
                      FROM HOS_TM_OPD_CON_RCPT
                      WHERE MCR_REF_NUM IS NOT NULL)
GROUP BY  TO_CHAR(MCR_DATE,'MM-YYYY'),TO_CHAR(MCR_DATE,'YYYY'),TO_CHAR(MCR_DATE,'MON-YYYY'),MCR_CP_CODE,MCR_MPT_ID,MCR_MCT_CODE,MCR_DEP_CODE
ORDER BY TO_CHAR(MCR_DATE,'YYYY'),TO_CHAR(MCR_DATE,'MM-YYYY');

prompt
prompt Creating view OPD_SERVICES__HISTORY
prompt ===================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.OPD_SERVICES__HISTORY AS
SELECT  DMONWISE,
        YEARWISE,
        MONWISE,
        MSR_CP_CODE,MSR_PAT_ID,DSR_DSC_CODE,
        DSR_MCT_CODE,DSR_DEP_CODE,
        SUM(QTY) AS QTY
FROM (
SELECT  TO_CHAR(MSR_DATE,'MM-YYYY')AS DMONWISE,
        TO_CHAR(MSR_DATE,'YYYY')AS YEARWISE,
        TO_CHAR(MSR_DATE,'MON-YYYY')AS MONWISE,
        MSR_CP_CODE,MSR_PAT_ID,DSR_DSC_CODE,
        DSR_MCT_CODE,DSR_DEP_CODE,
        DECODE(MSR_REF_TYPE,'I',NVL(SUM(DSR_QTY),0),-NVL(SUM(DSR_QTY),0)) AS QTY
FROM HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT
WHERE  MSR_CP_CODE= DSR_CP_CODE
AND    MSR_NUM = DSR_MSR_NUM
GROUP BY TO_CHAR(MSR_DATE,'MM-YYYY'),TO_CHAR(MSR_DATE,'YYYY'),
      TO_CHAR(MSR_DATE,'MON-YYYY'),MSR_CP_CODE,
      MSR_PAT_ID,DSR_DSC_CODE,
       DSR_MCT_CODE,DSR_DEP_CODE, MSR_REF_TYPE
)
GROUP BY DMONWISE,
        YEARWISE,
        MONWISE,
        MSR_CP_CODE,MSR_PAT_ID,DSR_DSC_CODE,
        DSR_MCT_CODE,DSR_DEP_CODE
ORDER BY YEARWISE,DMONWISE;

prompt
prompt Creating view OPD_SRV_SUR_NETAMT
prompt ================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.OPD_SRV_SUR_NETAMT AS
(
SELECT CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE, CBL_SLIP_TYPE, SUM(CBL_NET_AMT) AS CBL_NET_AMT
FROM (
SELECT MSR_CP_CODE AS CBL_CP_CODE, MSR_NUM AS CBL_SLIP_NUM, MSR_MPA_CODE AS CBL_MPA_CODE, 'OPD SRV-' || TO_CHAR(MSR_DATE,'MONYY') AS CBL_SLIP_TYPE, SUM(NVL(DSR_RATE,0)*NVL(DSR_QTY,0)) AS CBL_NET_AMT
FROM HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT
WHERE  MSR_CP_CODE  = DSR_CP_CODE
AND    MSR_NF_TYPE  = DSR_MSR_NF_TYPE
AND    MSR_DATE     = DSR_MSR_DATE
AND    MSR_NUM      = DSR_MSR_NUM
AND    MSR_PAT_TYPE = DSR_MSR_PAT_TYPE
AND    MSR_TYPE     = 'R'
AND    MSR_REF_TYPE = 'I'
AND    MSR_MPA_CODE IS NOT NULL
AND    MSR_NF_TYPE = 'N'
GROUP BY MSR_CP_CODE, MSR_NUM , MSR_MPA_CODE, MSR_DATE
UNION ALL
SELECT MSR_CP_CODE AS CBL_CP_CODE, MSR_REF_NUM AS CBL_SLIP_NUM, MSR_MPA_CODE AS CBL_MPA_CODE, 'OPD SRV-' || TO_CHAR(MSR_DATE,'MONYY') AS CBL_SLIP_TYPE, -1*SUM(NVL(DSR_RATE,0)*NVL(DSR_QTY,0)) AS CBL_NET_AMT
FROM HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SRV_RCPT
WHERE  MSR_CP_CODE  = DSR_CP_CODE
AND    MSR_NF_TYPE  = DSR_MSR_NF_TYPE
AND    MSR_DATE     = DSR_MSR_DATE
AND    MSR_NUM      = DSR_MSR_NUM
AND    MSR_PAT_TYPE = DSR_MSR_PAT_TYPE
AND    MSR_TYPE     = 'R'
AND    MSR_REF_TYPE = 'R'
AND    MSR_MPA_CODE IS NOT NULL
AND    MSR_NF_TYPE = 'N'
GROUP BY MSR_CP_CODE, MSR_REF_NUM , MSR_MPA_CODE, MSR_DATE
UNION ALL
SELECT MSR_CP_CODE AS CBL_CP_CODE, MSR_NUM AS CBL_SLIP_NUM, MSR_MPA_CODE AS CBL_MPA_CODE, 'OPD SUR-' || TO_CHAR(MSR_DATE,'MONYY') AS CBL_SLIP_TYPE, SUM(NVL(DOS_RATE,0)) AS CBL_NET_AMT
FROM    HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SUR_RCPT
WHERE   MSR_CP_CODE  = DOS_CP_CODE
AND  MSR_NF_TYPE  = DOS_MSR_NF_TYPE
AND  MSR_DATE     = DOS_MSR_DATE
AND  MSR_NUM      = DOS_MSR_NUM
AND  MSR_PAT_TYPE = DOS_MSR_PAT_TYPE
AND     MSR_TYPE     = 'R'
AND     MSR_REF_TYPE = 'I'
AND     MSR_NF_TYPE  = 'N'
AND     MSR_MPA_CODE IS NOT NULL
GROUP BY MSR_CP_CODE, MSR_NUM , MSR_MPA_CODE, MSR_DATE
UNION ALL
SELECT MSR_CP_CODE AS CBL_CP_CODE, MSR_REF_NUM AS CBL_SLIP_NUM, MSR_MPA_CODE AS CBL_MPA_CODE, 'OPD SUR-' || TO_CHAR(MSR_DATE,'MONYY') AS CBL_SLIP_TYPE, -1*SUM(NVL(DOS_RATE,0)) AS CBL_NET_AMT
FROM    HOS_TM_OPD_SRV_RCPT, HOS_TD_OPD_SUR_RCPT
WHERE   MSR_CP_CODE  = DOS_CP_CODE
AND  MSR_NF_TYPE  = DOS_MSR_NF_TYPE
AND  MSR_DATE     = DOS_MSR_DATE
AND  MSR_NUM      = DOS_MSR_NUM
AND  MSR_PAT_TYPE = DOS_MSR_PAT_TYPE
AND     MSR_TYPE     = 'R'
AND     MSR_REF_TYPE = 'R'
AND     MSR_NF_TYPE  = 'N'
AND     MSR_MPA_CODE IS NOT NULL
GROUP BY MSR_CP_CODE, MSR_REF_NUM , MSR_MPA_CODE, MSR_DATE)
GROUP BY CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE, CBL_SLIP_TYPE);

prompt
prompt Creating view PHARMACY_NETAMT
prompt =============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.PHARMACY_NETAMT AS
(
SELECT CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE, SUM(CBL_NET_AMT) AS CBL_NET_AMT
FROM (
SELECT MSL_CP_CODE CBL_CP_CODE, MSL_NUM AS CBL_SLIP_NUM, MSL_MPA_CODE CBL_MPA_CODE, SUM(ROUND(NVL(DSL_MIN_RATE,0)*NVL(DSL_MIN_QTY,0),0)-NVL(DSL_DISCOUNT,0)) AS CBL_NET_AMT
FROM HOS_TD_SALES, HOS_TM_SALES
WHERE DSL_CP_CODE  = MSL_CP_CODE
AND   DSL_MSL_NUM  = MSL_NUM
AND   DSL_MSL_TYPE = MSL_TYPE
AND   DSL_MSL_DATE = MSL_DATE
AND   MSL_SAL_TYPE = 'R'
AND   MSL_TYPE     = 'I'
AND   MSL_MPA_CODE IS NOT NULL
GROUP BY MSL_CP_CODE, MSL_NUM, MSL_MPA_CODE
UNION ALL
SELECT MSL_CP_CODE CBL_CP_CODE, MSL_REF_NUM AS CBL_SLIP_NUM, MSL_MPA_CODE CBL_MPA_CODE, -1* SUM(NVL(DSL_MIN_RATE,0) * NVL(DSL_MIN_QTY,0)) AS CBL_NET_AMT
FROM HOS_TD_SALES, HOS_TM_SALES
WHERE DSL_CP_CODE  = MSL_CP_CODE
AND   DSL_MSL_NUM  = MSL_NUM
AND   DSL_MSL_TYPE = MSL_TYPE
AND   DSL_MSL_DATE = MSL_DATE
AND   MSL_SAL_TYPE = 'R'
AND   MSL_TYPE     = 'R'
AND   MSL_MPA_CODE IS NOT NULL
GROUP BY MSL_CP_CODE, MSL_REF_NUM, MSL_MPA_CODE
)
GROUP BY CBL_CP_CODE, CBL_SLIP_NUM, CBL_MPA_CODE
HAVING ROUND(SUM(CBL_NET_AMT)) > 0
);

