prompt Creating view PPI_STOCK_LIST
prompt ============================
prompt
create or replace force view mdhsys.ppi_stock_list as
(select MIT_CODE , MIT_DESC , MIT_CTG_CODE , CTG_DESC , DIT_CP_CODE , DIT_CODE , DIT_DESC , MAN_CODE , MAN_DESC , GEN_CODE , GEN_DESC , SUP_CODE , SUP_DESC
, UOM_CODE , UOM_DESC , NVL(DIT_COM,'N') DIT_COM , NVL(DIT_FLAG,'N') DIT_FLAG , MIT_TYPE , UOM_CONV_FACT
, DIT_MIT_CODE ,MIT_CP_CODE
from PPI_SD_ITEM
LEFT JOIN PPI_SM_ITEM ON (MIT_CP_CODE = DIT_CP_CODE AND MIT_CODE = DIT_MIT_CODE)
LEFT JOIN PPI_SO_MANUFAC ON (MAN_CP_CODE = DIT_CP_CODE AND MAN_CODE = DIT_MANUFAC)
LEFT JOIN PPI_SO_GENERIC ON (GEN_CP_CODE = DIT_CP_CODE AND GEN_CODE = DIT_GENERIC)
LEFT JOIN PPI_SM_SUPPLIER ON (SUP_CP_CODE = DIT_CP_CODE AND SUP_CODE = DIT_RECOM_SUP)
LEFT JOIN PPI_SO_UOM ON (UOM_CP_CODE = DIT_CP_CODE AND UOM_CODE = DIT_UOM)
LEFT JOIN PPI_SO_ITEM_CATEGORY  ON (CTG_CP_CODE = MIT_CP_CODE AND CTG_CODE =  MIT_CTG_CODE));

