          FROM ACT_TM_VOUCHER
          WHERE MVH_VTP_TYPE = 'R'
          UNION
          SELECT LPAD(MCB_RCP_NUM, 15, 0)
          FROM HOS_TM_COMPANY_BILL
          WHERE MCB_TYPE = 'T'
          UNION
          SELECT LPAD(ISR_RCP_NUM, 15, 0)
          FROM ISR_XO_CONTROL));

