prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.STOCK_INQUIRY_ITEM AS
(SELECT  DIT_CP_CODE AS MPB_CP_CODE  ,  MIT_CODE , MIT_DESC ,MIT_CTG_CODE , CTG_DESC ,
        GEN_CODE     , GEN_DESC ,
        MAN_CODE     , MAN_DESC ,
        SUP_CODE     , SUP_DESC ,
        UOM_CODE     , UOM_DESC ,
        UOM_CONV_FACT  UOM_FACT ,
        DIT_DESC, DIT_CODE,
  GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'C') AS IPR_MIN_TRD_PRICE ,
  GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'R') AS IPR_MIN_RATE,
        SUM(MPB_BAL_QTY) MPB_BAL_QTY, SUM(MPB_MAX_BAL_QTY) MPB_MAX_BAL_QTY,
        GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'D') AS IPR_DATE,
         NVL(DIT_COM,'N') DIT_COM , NVL(DIT_FLAG,'N') DIT_FLAG
FROM    PPI_STOCK_LIST   LEFT JOIN   PPI_PM_BALANCE    ON ( DIT_CP_CODE  = MPB_CP_CODE  AND     DIT_CODE        = MPB_DIT_CODE)
AND     MPB_DATE    <=  SYSDATE
GROUP BY DIT_CP_CODE   ,  MIT_CODE , MIT_DESC , MIT_CTG_CODE , CTG_DESC ,
        GEN_CODE       , GEN_DESC ,
        MAN_CODE       , MAN_DESC ,
        SUP_CODE       , SUP_DESC ,
        UOM_CODE       , UOM_DESC ,
        UOM_CONV_FACT  , DIT_DESC ,
        DIT_CODE       , GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'C') ,
        GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'R') ,
        GET_ITEM_PRICE_INFO(DIT_CP_CODE, DIT_CODE, SYSDATE, 'D') ,
         NVL(DIT_COM,'N')  , NVL(DIT_FLAG,'N') );

