prompt Creating view UN_BALANCED_STOCK
prompt ===============================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.UN_BALANCED_STOCK AS
(SELECT  '[IN ] PM,PD' AS T_TYPE, MPB_DIT_CODE AS DIT_CODE,
 MPB_IN_NUM AS DOC_NUM, SUM(MPB_QTY) DOC_QTY,
 GET_PM_BAL(MPB_CP_CODE, MPB_IN_NUM, MPB_DIT_CODE,'BL', 'Q')  DOC_BAL_QTY,
 GET_PM_BAL(MPB_CP_CODE, MPB_IN_NUM, MPB_DIT_CODE,'TR', 'Q') AS PM_QTY,
 GET_PD_BAL(MPB_CP_CODE, MPB_IN_NUM, '%', MPB_DIT_CODE,'Q') AS PD_QTY,
 (GET_PM_BAL(MPB_CP_CODE, MPB_IN_NUM, MPB_DIT_CODE, 'TR', 'Q') -
 GET_PD_BAL(MPB_CP_CODE, MPB_IN_NUM, '%', MPB_DIT_CODE,'Q')) as DIFF
FROM   PPI_PM_BALANCE
GROUP BY MPB_DIT_CODE,MPB_IN_NUM, MPB_CP_CODE
HAVING GET_PM_BAL(MPB_CP_CODE, MPB_IN_NUM, MPB_DIT_CODE,'BL', 'Q') <>
 (GET_PM_BAL(MPB_CP_CODE, MPB_IN_NUM, MPB_DIT_CODE, 'TR','Q') -
 GET_PD_BAL(MPB_CP_CODE, MPB_IN_NUM, '%', MPB_DIT_CODE,'Q'))
UNION
SELECT  '[IN ] PM,PD,OB' AS T_TYPE, DOI_DIT_CODE AS DIT_CODE,
 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD') AS DOC_NUM, SUM(DOI_QTY) DOC_QTY,
 GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE,'BL', 'Q')  DOC_BAL_QTY,
 GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE,'TR', 'Q') AS PM_QTY,
 GET_PD_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), '%', DOI_DIT_CODE,'Q') AS PD_QTY,
 (GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE, 'TR', 'Q') -
 GET_PD_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), '%', DOI_DIT_CODE,'Q')) as DIFF
FROM   PPI_SD_ITEM_OPNBAL
GROUP BY DOI_DIT_CODE,'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_CP_CODE
HAVING GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE,'BL', 'Q') <>
 (GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE, 'TR','Q') -
 GET_PD_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), '%', DOI_DIT_CODE,'Q'))
OR GET_PM_BAL(DOI_CP_CODE, 'OB' || TO_CHAR(DOI_FYR_FM,'YYYYMMDD'), DOI_DIT_CODE, 'TR','Q') <>
SUM(DOI_QTY)
UNION
SELECT  '[IN ] PM,PD,GRN,TFR' AS T_TYPE, DST_DIT_CODE AS DIT_CODE,
 DST_MST_NUM AS DOC_NUM, SUM(NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0))  DOC_QTY,
 GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE,'BL', 'Q')  DOC_BAL_QTY,
 GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE,'TR', 'Q') AS PM_QTY,
 GET_PD_BAL(DST_CP_CODE, DST_MST_NUM, '%', DST_DIT_CODE,'Q') AS PD_QTY,
 (GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE, 'TR', 'Q') -
 GET_PD_BAL(DST_CP_CODE, DST_MST_NUM, '%', DST_DIT_CODE,'Q')) as DIFF
FROM   PPI_TD_STOCK
WHERE  SUBSTR(DST_MST_NUM,1,3) IN ('BGR','BTR')
GROUP BY DST_DIT_CODE,DST_MST_NUM, DST_CP_CODE
HAVING GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE,'BL', 'Q') <>
 (GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE, 'TR','Q') -
 GET_PD_BAL(DST_CP_CODE, DST_MST_NUM, '%', DST_DIT_CODE,'Q'))
OR GET_PM_BAL(DST_CP_CODE, DST_MST_NUM, DST_DIT_CODE, 'TR','Q') <>
SUM(NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0))
UNION
SELECT  '[OUT] PD,PRETU,TFR,WOFF' AS T_TYPE, DST_DIT_CODE AS DIT_CODE,
 DST_MST_NUM AS DOC_NUM, SUM(NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0))  DOC_QTY,
NULL  DOC_BAL_QTY,
NULL AS PM_QTY,
 GET_PD_BAL(DST_CP_CODE, '%', DST_MST_NUM, DST_DIT_CODE,'Q') AS PD_QTY,
(SUM(NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0))  -
 GET_PD_BAL(DST_CP_CODE, '%', DST_MST_NUM, DST_DIT_CODE,'Q')) as DIFF
FROM   PPI_TD_STOCK
WHERE  SUBSTR(DST_MST_NUM,1,3) IN ('BPR','BTR')
GROUP BY DST_DIT_CODE,DST_MST_NUM, DST_CP_CODE
HAVING GET_PD_BAL(DST_CP_CODE, '%', DST_MST_NUM, DST_DIT_CODE, 'Q') <>
SUM(NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0))
UNION
SELECT  '[IN ] PM,PD,S.RET' AS T_TYPE, DSL_DIT_CODE AS DIT_CODE,
 DSL_MSL_NUM AS DOC_NUM, SUM(NVL(DSL_MIN_QTY,0))  DOC_QTY,
 GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE,'BL', 'Q')  DOC_BAL_QTY,
 GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE,'TR', 'Q') AS PM_QTY,
 GET_PD_BAL(DSL_CP_CODE, DSL_MSL_NUM, '%', DSL_DIT_CODE,'Q') AS PD_QTY,
 (GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE, 'TR', 'Q') -
 GET_PD_BAL(DSL_CP_CODE, DSL_MSL_NUM, '%', DSL_DIT_CODE,'Q')) as DIFF
FROM   HOS_TD_SALES, HOS_TM_SALES
WHERE  MSL_TRN_TYPE = 'SR'
AND    DSL_MSL_NUM = MSL_NUM
GROUP BY DSL_DIT_CODE,DSL_MSL_NUM, DSL_CP_CODE
HAVING GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE,'BL', 'Q') <>
 (GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE, 'TR','Q') -
 GET_PD_BAL(DSL_CP_CODE, DSL_MSL_NUM, '%', DSL_DIT_CODE,'Q'))
OR GET_PM_BAL(DSL_CP_CODE, DSL_MSL_NUM, DSL_DIT_CODE, 'TR','Q') <>
SUM(NVL(DSL_MIN_QTY,0))
UNION
SELECT  '[OUT] PD,SALES' AS T_TYPE, DSL_DIT_CODE AS DIT_CODE,
 DSL_MSL_NUM AS DOC_NUM, SUM(NVL(DSL_MIN_QTY,0))  DOC_QTY,
 NULL AS DOC_BAL_QTY,
 NULL AS PM_QTY,
 GET_PD_BAL(DSL_CP_CODE, '%', DSL_MSL_NUM, DSL_DIT_CODE,'Q') AS PD_QTY,
 (SUM(NVL(DSL_MIN_QTY,0))  -
 GET_PD_BAL(DSL_CP_CODE, '%', DSL_MSL_NUM, DSL_DIT_CODE,'Q')) as DIFF
FROM   HOS_TD_SALES, HOS_TM_SALES
WHERE  MSL_TRN_TYPE = 'SL'
AND    DSL_MSL_NUM = MSL_NUM
GROUP BY DSL_DIT_CODE,DSL_MSL_NUM, DSL_CP_CODE
HAVING GET_PD_BAL(DSL_CP_CODE, '%', DSL_MSL_NUM, DSL_DIT_CODE, 'Q') <>
SUM(NVL(DSL_MIN_QTY,0))
UNION
SELECT  '[IN ] PM,PD,EXCESS' AS T_TYPE, DSE_DIT_CODE AS DIT_CODE,
 DSE_MSE_NUM AS DOC_NUM, SUM(ABS(NVL(DSE_DIF_MIN_QTY,0)))  DOC_QTY,
 GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE,'BL', 'Q')  DOC_BAL_QTY,
 GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE,'TR', 'Q') AS PM_QTY,
 GET_PD_BAL(DSE_CP_CODE, DSE_MSE_NUM, '%', DSE_DIT_CODE,'Q') AS PD_QTY,
 (GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE, 'TR', 'Q') -
 GET_PD_BAL(DSE_CP_CODE, DSE_MSE_NUM, '%', DSE_DIT_CODE,'Q')) as DIFF
FROM   PPI_TD_SHT_EXC, PPI_TM_SHT_EXC
WHERE  MSE_STATUS = 'P'
AND    DSE_MSE_NUM = MSE_NUM
AND    DSE_TYPE    = 'E'
GROUP BY DSE_DIT_CODE,DSE_MSE_NUM, DSE_CP_CODE
HAVING GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE,'BL', 'Q') <>
 (GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE, 'TR','Q') -
 GET_PD_BAL(DSE_CP_CODE, DSE_MSE_NUM, '%', DSE_DIT_CODE,'Q'))
OR GET_PM_BAL(DSE_CP_CODE, DSE_MSE_NUM, DSE_DIT_CODE, 'TR','Q') <>
SUM(ABS(NVL(DSE_DIF_MIN_QTY,0)))
UNION
SELECT  '[OUT] PD,SHORT' AS T_TYPE, DSE_DIT_CODE AS DIT_CODE,
 DSE_MSE_NUM AS DOC_NUM, SUM(ABS(NVL(DSE_DIF_MIN_QTY,0)))  DOC_QTY,
 NULL DOC_BAL_QTY,
 NULL AS PM_QTY,
 GET_PD_BAL(DSE_CP_CODE, '%', DSE_MSE_NUM, DSE_DIT_CODE,'Q') AS PD_QTY,
 (SUM(ABS(NVL(DSE_DIF_MIN_QTY,0))) -
 GET_PD_BAL(DSE_CP_CODE, '%', DSE_MSE_NUM, DSE_DIT_CODE,'Q')) as DIFF
FROM   PPI_TD_SHT_EXC, PPI_TM_SHT_EXC
WHERE  MSE_STATUS = 'P'
AND    DSE_MSE_NUM = MSE_NUM
AND    DSE_TYPE    = 'S'
GROUP BY DSE_DIT_CODE,DSE_MSE_NUM, DSE_CP_CODE
HAVING GET_PD_BAL(DSE_CP_CODE, '%', DSE_MSE_NUM, DSE_DIT_CODE, 'Q') <>
SUM(ABS(NVL(DSE_DIF_MIN_QTY,0)))
);

prompt
prompt Creating view VIEW_PM_BAL_BREAKUP
prompt =================================
prompt
CREATE OR REPLACE FORCE VIEW MDHSYS.VIEW_PM_BAL_BREAKUP AS
SELECT "MIT_CTG_CODE","DIT_COM","MPB_CP_CODE","MPB_DIT_CODE","MPB_LOC_CODE","MPB_IN_NUM","MPB_IN_SQN","MPB_DATE","MPB_RATE","MPB_QTY","MPB_AMT","SUM(MPB_QTY)","AMT"
FROM (SELECT    MIT_CTG_CODE , DIT_COM , MPB_CP_CODE, MPB_DIT_CODE, MPB_LOC_CODE, MPB_IN_NUM,
           MPB_IN_SQN, MPB_DATE, MPB_RATE, SUM(MPB_QTY) AS MPB_QTY,  SUM(MPB_QTY * MPB_RATE) AS MPB_AMT
        ,   SUM(MPB_QTY)
         ,  SUM(MPB_QTY * MPB_RATE) amt
FROM    PPI_PM_BALANCE  , PPI_STOCK_LIST
where   MPB_CP_CODE       = PPI_STOCK_LIST.DIT_CP_CODE
AND     MPB_DIT_CODE      = PPI_STOCK_LIST.DIT_CODE
AND   MPB_IN_NUM = MPB_IN_NUM
GROUP BY MIT_CTG_CODE , DIT_COM  , MPB_CP_CODE, MPB_DIT_CODE, MPB_LOC_CODE, MPB_DATE, MPB_IN_NUM, MPB_IN_SQN, MPB_RATE)
WHERE MPB_QTY > 0
ORDER BY 2;

