prompt Creating function BBM_GET_PRODUCTS_RATES
prompt ========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.BBM_GET_PRODUCTS_RATES(ARG_CP_CODE     VARCHAR2,
                                                  ARG_BR_CODE     VARCHAR2,
                                                  ARG_MPA_CODE    VARCHAR2,
                                                  ARG_BPD_CODE    VARCHAR2,
                                                  ARG_URGENT_FLAG VARCHAR2,
                                                  ARG_SLIP_TYPE   VARCHAR2)
  RETURN NUMBER IS
  LC_RATE NUMBER;
BEGIN

  IF ARG_SLIP_TYPE = 'R' THEN
    BEGIN
      SELECT DECODE(ARG_URGENT_FLAG,
                    'Y',
                    A.BPR_UGT_RATES,
                    'N',
                    A.BPR_NRM_RATES,
                    A.BPR_NRM_RATES)
        INTO LC_RATE
        FROM BBM_SO_PRODUCTS_RATES A
       WHERE A.BPR_CP_CODE = ARG_CP_CODE
         AND A.BPR_BR_CODE = ARG_BR_CODE
         AND A.BPR_BPD_CODE = ARG_BPD_CODE
         AND A.BPR_MPA_CODE = ARG_MPA_CODE
         AND A.BPR_MPA_TYPE = 'P'
         AND A.BPR_EFF_DATE =
             (SELECT MAX(B.BPR_EFF_DATE)
                FROM BBM_SO_PRODUCTS_RATES B
               WHERE B.BPR_CP_CODE = A.BPR_CP_CODE
                 AND B.BPR_BR_CODE = A.BPR_BR_CODE
                 AND B.BPR_BPD_CODE = A.BPR_BPD_CODE
                 AND B.BPR_MPA_CODE = A.BPR_MPA_CODE
                 AND B.BPR_MPA_TYPE = 'P');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        BEGIN
          SELECT DECODE(ARG_URGENT_FLAG,
                        'Y',
                        A.BPR_UGT_RATES,
                        'N',
                        A.BPR_NRM_RATES,
                        A.BPR_NRM_RATES)
            INTO LC_RATE
            FROM BBM_SO_PRODUCTS_RATES A

           WHERE A.BPR_CP_CODE = ARG_CP_CODE
             AND A.BPR_BR_CODE = ARG_BR_CODE
             AND A.BPR_BPD_CODE = ARG_BPD_CODE
             AND A.BPR_MPA_TYPE = 'B'
             AND A.BPR_EFF_DATE =
                 (SELECT MAX(B.BPR_EFF_DATE)
                    FROM BBM_SO_PRODUCTS_RATES B
                   WHERE B.BPR_CP_CODE = A.BPR_CP_CODE
                     AND B.BPR_BR_CODE = A.BPR_BR_CODE
                     AND B.BPR_BPD_CODE = A.BPR_BPD_CODE
                     AND B.BPR_MPA_TYPE = 'B');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN

            LC_RATE := 0;
        END;
    END;
  ELSE
    BEGIN
      SELECT DECODE(ARG_URGENT_FLAG,
                    'Y',
                    A.BPR_UGT_RATES,
                    'N',
                    A.BPR_NRM_RATES,
                    A.BPR_NRM_RATES)
        INTO LC_RATE
        FROM BBM_SO_PRODUCTS_RATES A

       WHERE A.BPR_CP_CODE = ARG_CP_CODE
         AND A.BPR_BR_CODE = ARG_BR_CODE
         AND A.BPR_BPD_CODE = ARG_BPD_CODE
         AND A.BPR_MPA_TYPE = 'B'
         AND A.BPR_EFF_DATE =
             (SELECT MAX(B.BPR_EFF_DATE)
                FROM BBM_SO_PRODUCTS_RATES B
               WHERE B.BPR_CP_CODE = A.BPR_CP_CODE
                 AND B.BPR_BR_CODE = A.BPR_BR_CODE
                 AND B.BPR_BPD_CODE = A.BPR_BPD_CODE
                 AND B.BPR_MPA_TYPE = 'B');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN

        LC_RATE := 0;
    END;
  END IF;
  RETURN(LC_RATE);
END;
/

