prompt Creating function CHK_LAST_BILL_DATE
prompt ====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.CHK_LAST_BILL_DATE(ARG_CP_CODE VARCHAR2, ARG_MPA_CODE VARCHAR2) RETURN DATE IS
  LC_DATE_FM DATE;
BEGIN
  BEGIN
    SELECT TO_CHAR(MAX(MCB_DATE_TO)+1,'DD-MON-YYYY')
    INTO   LC_DATE_FM
    FROM   HOS_TM_COMPANY_BILL
    WHERE  MCB_MPA_CODE = ARG_MPA_CODE
    AND    MCB_CP_CODE  = ARG_CP_CODE
    AND    MCB_TYPE     = 'V';
  EXCEPTION
    WHEN OTHERS THEN
          BEGIN
            SELECT TO_CHAR(TRUNC(MIN(CBL_SLIP_DATE),'MONTH'),'DD-MON-YYYY')
            INTO   LC_DATE_FM
            FROM   COMPANY_BILLING
            WHERE  CBL_MPA_CODE  = ARG_MPA_CODE
            AND    CBL_CP_CODE   = ARG_CP_CODE
            GROUP  BY CBL_MPA_CODE;
          EXCEPTION
            WHEN OTHERS THEN
            LC_DATE_FM := NULL;
          END;
  END;

  RETURN LC_DATE_FM;
END;
/

prompt
prompt Creating function DIS_GET_DONATION_BAL_AMOUNT
prompt =============================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.DIS_GET_DONATION_BAL_AMOUNT(ARG_CP_CODE VARCHAR2, ARG_BR_CODE VARCHAR2,
				ARG_MDR_NUM VARCHAR2, ARG_DNT_CODE VARCHAR2, ARG_DH5_CODE VARCHAR2, ARG_AMOUNT NUMBER) RETURN NUMBER IS

	LC_PAID_AMT NUMBER;
	LC_BAL_AMT  NUMBER;

BEGIN
	SELECT NVL(SUM(NVL(DDR_AMOUNT,0)),0)
	INTO   LC_PAID_AMT
	FROM (
	SELECT NVL(SUM(NVL(DDR_AMOUNT,0)),0) AS DDR_AMOUNT
	FROM   DIS_TM_DONATION_RECEIPT, DIS_TD_DONATION_RECEIPT
	WHERE   MDR_CP_CODE  = ARG_CP_CODE
	AND     MDR_BR_CODE  = ARG_BR_CODE
	AND     MDR_TYPE     = 'R'
	AND     MDR_REF_NUM  = ARG_MDR_NUM
	AND     DDR_CP_CODE  = MDR_CP_CODE

	AND 	DDR_BR_CODE  = MDR_BR_CODE

	AND	DDR_MDR_DATE = MDR_DATE

	AND 	DDR_MDR_NUM  = MDR_NUM
	AND     DDR_DNT_CODE = ARG_DNT_CODE
	AND     DDR_DH5_CODE = ARG_DH5_CODE
	UNION ALL
	SELECT NVL(SUM(NVL(DDP_AMOUNT,0)),0)
	FROM DIS_TD_DONATION_PAYMENT
	WHERE  	DDP_CP_CODE = ARG_CP_CODE
 	AND    	DDP_BR_CODE = ARG_BR_CODE
 	AND     DDP_MDR_NUM = ARG_MDR_NUM
 	AND     DDP_DNT_CODE= ARG_DNT_CODE
 	AND     DDP_DH5_CODE= ARG_DH5_CODE
	);

	LC_BAL_AMT := NVL(ARG_AMOUNT,0) - NVL(LC_PAID_AMT,0);

	RETURN LC_BAL_AMT;
END;
/

