prompt Creating function GENERATE_INPUT_INTERFACE
prompt ==========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GENERATE_INPUT_INTERFACE(ARG_CP_CODE VARCHAR2,
                                                    ARG_BR_CODE VARCHAR2,
                                                    ARG_DOC_NUM VARCHAR2,
                                                    ARG_DSD_CODE VARCHAR2,
                                                    ARG_PMT_CODE VARCHAR2,
                                                    ARG_TYPE VARCHAR2) RETURN VARCHAR2 IS
  CURSOR SRV_CRS IS
         SELECT MSR_CP_CODE AS CP_CODE,MSR_BR_CODE AS BR_CODE ,MSR_NUM AS DOC_NUM,DSR_DSC_CODE AS SRV_CODE,LTP_PMT_CODE AS PMT_CODE,
                MSR_LAB_SLIP_NUM AS LAB_SLIP_NUM,DMT_MACHINE_NAME AS MACHINE_NAME,DMT_TEST_NAME AS TEST_NAME
         FROM   HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT,LAB_SM_LTP_INFO,LAB_INT_SD_TEST_DETAILS
         WHERE  MSR_CP_CODE  = DSR_CP_CODE
         AND    MSR_NUM      = DSR_MSR_NUM
         AND    LTP_CP_CODE  = DMT_CP_CODE
         AND    LTP_SRV_CODE = DMT_MLI_SRV_CODE
         AND    LTP_PMT_CODE = DMT_LTP_PMT_CODE
         AND    DSR_CP_CODE  = LTP_CP_CODE
         AND    DSR_DSC_CODE = LTP_SRV_CODE
         AND    MSR_LAB_SLIP_NUM IS NOT NULL
         AND    LTP_TYPE     = 'D'
         AND    MSR_CP_CODE  = ARG_CP_CODE
         AND    MSR_BR_CODE  = ARG_BR_CODE
         AND    MSR_NUM      = ARG_DOC_NUM
         AND    DSR_DSC_CODE = NVL(ARG_DSD_CODE,DSR_DSC_CODE)
         AND    LTP_PMT_CODE = NVL(ARG_PMT_CODE,LTP_PMT_CODE)
         UNION
         SELECT MSR_CP_CODE AS CP_CODE,MSR_BR_CODE AS BR_CODE ,MSR_NUM AS DOC_NUM,DSR_DSC_CODE AS SRV_CODE,LTP_PMT_CODE AS PMT_CODE,
                MSC_SPC_BCODE AS LAB_SLIP_NUM,DMT_MACHINE_NAME AS MACHINE_NAME,DMT_TEST_NAME AS TEST_NAME
         FROM   HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT,LAB_SM_LTP_INFO,LAB_INT_SD_TEST_DETAILS,LAB_TM_SMN_COLL,LAB_TD_SMN_COLL
         WHERE  MSR_CP_CODE  = DSR_CP_CODE
         AND    MSR_NUM      = DSR_MSR_NUM
         AND    MSC_CP_CODE  = DSC_CP_CODE
         AND    MSC_SPC_NUM  = DSC_SPC_NUM
         AND    MSC_DOC_NUM  = DSC_DOC_NUM
         AND    DSR_CP_CODE  = DSC_CP_CODE
         AND    DSR_MSR_NUM  = DSC_DOC_NUM
         AND    DSR_DSC_CODE = DSC_DSC_CODE
         AND    DSC_CP_CODE  = LTP_CP_CODE
         AND    DSC_DSC_CODE = LTP_SRV_CODE
         AND    LTP_CP_CODE  = DMT_CP_CODE
         AND    LTP_SRV_CODE = DMT_MLI_SRV_CODE
         AND    LTP_PMT_CODE = DMT_LTP_PMT_CODE  
         AND    MSC_SPC_BCODE IS NOT NULL
         AND    LTP_TYPE     = 'D'
         AND    MSR_CP_CODE  = ARG_CP_CODE
         AND    MSR_BR_CODE  = ARG_BR_CODE
         AND    DSC_SPC_NUM  = ARG_DOC_NUM
         AND    DSC_DSC_CODE = NVL(ARG_DSD_CODE,DSR_DSC_CODE)
         AND    LTP_PMT_CODE = NVL(ARG_PMT_CODE,LTP_PMT_CODE)
         UNION
         SELECT MIS_CP_CODE,MIS_BR_CODE,MIS_SPC_NUM,DIS_DSC_CODE,LTP_PMT_CODE,MIS_LAB_SLIP_NUM,DMT_MACHINE_NAME,DMT_TEST_NAME
         FROM   LAB_TM_IPD_SRVS,LAB_TD_IPD_SRVS,LAB_SM_LTP_INFO,LAB_INT_SD_TEST_DETAILS
         WHERE  MIS_CP_CODE  = DIS_CP_CODE
         AND    MIS_SPC_NUM  = DIS_SPC_NUM
         AND    LTP_CP_CODE  = DMT_CP_CODE
         AND    LTP_SRV_CODE = DMT_MLI_SRV_CODE
         AND    LTP_PMT_CODE = DMT_LTP_PMT_CODE
         AND    DIS_CP_CODE  = LTP_CP_CODE
         AND    DIS_DSC_CODE = LTP_SRV_CODE
         AND    MIS_LAB_SLIP_NUM IS NOT NULL
         AND    LTP_TYPE     = 'D'
         AND    MIS_CP_CODE  = ARG_CP_CODE
         AND    MIS_BR_CODE  = ARG_BR_CODE
         AND    MIS_SPC_NUM  = ARG_DOC_NUM
         AND    DIS_DSC_CODE = NVL(ARG_DSD_CODE,DIS_DSC_CODE)
         AND    LTP_PMT_CODE = NVL(ARG_PMT_CODE,LTP_PMT_CODE)
         UNION
         SELECT MIS_CP_CODE,MIS_BR_CODE,MIS_SPC_NUM,DIS_DSC_CODE,LTP_PMT_CODE,MIS_SPC_BCODE,DMT_MACHINE_NAME,DMT_TEST_NAME
         FROM   LAB_TM_IPD_SRVS,LAB_TD_IPD_SRVS,LAB_SM_LTP_INFO,LAB_INT_SD_TEST_DETAILS
