  LC_RTN_VAL VARCHAR2(100);
  LC_ARG_VAL VARCHAR2(100);
  LC_VALUE   VARCHAR2(100);
BEGIN
 -- LC_VALUE := '1234567890';
  LC_VALUE := ARG_VALUE;
  IF ARG_FONT = 'CODE-128' OR ARG_FONT = 'CODE-128B' THEN
     LC_START   := 'Ì';
     LC_END     := 'Î';
     LC_CHR_VAL := 104;
     FOR A IN 1..LENGTH(LC_VALUE) LOOP
         LC_STRING := SUBSTR(LC_VALUE,A,1);
         BEGIN
           SELECT BRC_VALUE
           INTO   LC_VAL
           FROM   ISR_XO_BARCODE
           WHERE  BRC_FONT = 'CODE-128'
           AND    BRC_CHAR = LC_STRING;
         EXCEPTION
           WHEN OTHERS THEN
                LC_VAL := 0;
         END;
         LC_CAL := NVL(LC_CAL,0) + (LC_VAL * A);
    END LOOP;
    LC_CAL := LC_CAL + LC_CHR_VAL;
    SELECT BRC_CHAR
    INTO   LC_STRING
    FROM   ISR_XO_BARCODE
    WHERE  BRC_FONT  = 'CODE-128'
    AND    BRC_VALUE = LPAD(MOD(LC_CAL,103),2,0);
    LC_RTN_VAL := LC_START||LC_VALUE||LC_STRING||LC_END;
  ELSIF ARG_FONT = 'CODE-128A' THEN
     LC_START   := 'Ë';
     LC_END     := 'Î';
     LC_CHR_VAL := 103;
     FOR A IN 1..LENGTH(LC_VALUE) LOOP
         LC_STRING := SUBSTR(LC_VALUE,A,1);
         BEGIN
           SELECT BRC_VALUE
           INTO   LC_VAL
           FROM   ISR_XO_BARCODE
           WHERE  BRC_FONT = 'CODE-128'
           AND    BRC_CHAR = LC_STRING;
         EXCEPTION
           WHEN OTHERS THEN
                LC_VAL := 0;
         END;
         LC_CAL := NVL(LC_CAL,0) + (LC_VAL * A);
    END LOOP;
    LC_CAL := LC_CAL + LC_CHR_VAL;
    SELECT BRC_CHAR
    INTO   LC_STRING
    FROM   ISR_XO_BARCODE
    WHERE  BRC_FONT  = 'CODE-128'
    AND    BRC_VALUE = LPAD(MOD(LC_CAL,103),2,0);
    LC_RTN_VAL := LC_START||LC_VALUE||LC_STRING||LC_END;
  ELSIF ARG_FONT = 'CODE-128C' THEN
--     LC_VALUE :=  '987654';
     LC_START   := 'Í';
     LC_END     := 'Î';
     LC_CHR_VAL := 105;
--     IF MOD(ROUND(LENGTH(LC_VALUE) / 2),2) = 1 THEN
        IF MOD(LENGTH(LC_VALUE),2) = 1 THEN
       LC_ARG_VAL := '0'||LC_VALUE;        
     ELSE
       LC_ARG_VAL := LC_VALUE;
     END IF;
     DBMS_OUTPUT.PUT_LINE(LC_ARG_VAL||'  '||LC_VALUE);
     FOR A IN 1..LENGTH(LC_ARG_VAL) LOOP
         IF MOD(A,2) = 0 THEN
            LC_SNO := LC_SNO + 1;
            LC_STRING := SUBSTR(LC_ARG_VAL,A - 1,2);
            BEGIN
              SELECT BRC_CHAR
              INTO   LC_CVAL
              FROM   ISR_XO_BARCODE
              WHERE  BRC_FONT = 'CODE-128'
              AND    BRC_VALUE = LC_STRING;
            EXCEPTION
              WHEN OTHERS THEN
                   LC_CVAL := 0;
            END;
            LC_CAL := NVL(LC_CAL,0) + (LC_STRING * LC_SNO);
            LC_RTN_VAL := LC_RTN_VAL||LC_CVAL;
          END IF;
     END LOOP;
    LC_CAL := LC_CAL + LC_CHR_VAL;
    SELECT BRC_CHAR
    INTO   LC_STRING
    FROM   ISR_XO_BARCODE
    WHERE  BRC_FONT  = 'CODE-128'
    AND    BRC_VALUE = LPAD(MOD(LC_CAL,103),2,0);
    LC_RTN_VAL := LC_START||LC_RTN_VAL||LC_STRING||LC_END;
  END IF;
  RETURN LC_RTN_VAL;
END;
/

