prompt Creating function GET_ACTUAL_SALARY
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_ACTUAL_SALARY"(ARG_CP_CODE  VARCHAR2,
                                               ARG_EMP_CODE VARCHAR2,
                                               ARG_DATE     DATE,
                                               ARG_TYPE     VARCHAR2,
                                               ARG_AMT_TYPE VARCHAR2)

 RETURN NUMBER IS

  CURSOR CRS1 IS
    SELECT MON_CP_CODE, MON_EMP_CODE, MON_DATE
      FROM PAY_TM_MONTHLY
     WHERE MON_CP_CODE = ARG_CP_CODE
       AND MON_EMP_CODE LIKE NVL(ARG_EMP_CODE, '%')
       AND MON_DATE = ARG_DATE
    UNION
    SELECT FNL_CP_CODE, FNL_EMP_CODE, MONTH_LAST_DAY(FNL_DATE)
      FROM PAY_TM_EMP_FINAL
     WHERE FNL_CP_CODE = ARG_CP_CODE
       AND FNL_EMP_CODE LIKE NVL(ARG_EMP_CODE, '%')
       AND MONTH_LAST_DAY(FNL_DATE) = ARG_DATE;

  LC_TOT_AMT  NUMBER(13, 2);
  LC_EMP_AMT  NUMBER(13, 2);
  LC_INC_DATE DATE;
BEGIN

  FOR REC1 IN CRS1 LOOP

    BEGIN

      SELECT MAX(INC_DATE)
        INTO LC_INC_DATE
        FROM PAY_TM_INCREMENT
       WHERE INC_CP_CODE = REC1.MON_CP_CODE
         AND INC_EMP_CODE = REC1.MON_EMP_CODE
         AND INC_DATE <= REC1.MON_DATE;
    END;

      SELECT DECODE(ARG_AMT_TYPE, 'I', SUM(IAL_INC_AMT), SUM(IAL_AMT))
      INTO LC_EMP_AMT
      FROM PAY_TD_INC_ALLOWN, PAY_SM_ALLOWANCE
      WHERE IAL_CP_CODE = ALW_CP_CODE
      AND IAL_ALW_CODE = ALW_CODE
      AND IAL_CP_CODE = REC1.MON_CP_CODE
      AND IAL_EMP_CODE = REC1.MON_EMP_CODE
      AND IAL_INC_DATE = LC_INC_DATE
      AND ALW_REF_NUM LIKE NVL(ARG_TYPE, '%');

    LC_TOT_AMT := NVL(LC_TOT_AMT, 0) + NVL(LC_EMP_AMT, 0);

  END LOOP;


  RETURN LC_TOT_AMT;
END;
/

