prompt Creating function GET_AGE_YMWD
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_AGE_YMWD" (ARG_DATE DATE) RETURN VARCHAR2 IS
 LC_NUM NUMBER(13,2);
 LC_RETURN NUMBER(13,2);
 LC_AGE_TYPE VARCHAR2(1);
BEGIN
 LC_NUM := ROUND((TO_DATE(TO_CHAR(SYSDATE,'DD-MON-YYYY'))) - ARG_DATE) + 1;

 IF LC_NUM >= 365 THEN
  LC_AGE_TYPE := 'Y';
  LC_RETURN    := ROUND(LC_NUM / 365,2);
 ELSIF LC_NUM < 365 AND LC_NUM >= 29 THEN
  LC_AGE_TYPE := 'M';

  LC_RETURN    := ROUND(LC_NUM / 29,2);
 ELSIF LC_NUM < 30 AND LC_NUM >= 7 THEN
  LC_AGE_TYPE := 'W';
  LC_RETURN    := ROUND(LC_NUM / 7,2);
 ELSE
  LC_AGE_TYPE := 'D';
  LC_RETURN    := ROUND(LC_NUM,2);
 END IF;

 RETURN (LTRIM(RTRIM(LC_RETURN)) || LC_AGE_TYPE);


END;
/

