prompt Creating procedure GET_ROASTER_DETAILS
prompt ======================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS."GET_ROASTER_DETAILS" (RS_CP_CODE VARCHAR2,
                         RS_EMP_CODE VARCHAR2,
                         RS_EMP_TYPE VARCHAR2,
                         RS_DATE DATE,
                         RS_TIME VARCHAR2,
                         RS_IN_OUT VARCHAR2,
                         O_LC_SHF_DATE OUT DATE,
                         O_LC_SHF_DATE_OUT OUT DATE,
                         O_LC_DTY_IN OUT VARCHAR2,
                         O_LC_DTY_OUT OUT VARCHAR2,
                         O_LC_LCH_OUT OUT VARCHAR2,
                         O_LC_LCH_IN OUT VARCHAR2,

                         O_LC_DTY_HRS OUT NUMBER,
                         O_LC_MIN_OT_LIMIT OUT NUMBER,
                         O_LC_LATE_MARGIN OUT VARCHAR2,
                         O_LC_OFF_TYPE IN OUT VARCHAR2,
                         O_SHF_CODE IN OUT VARCHAR2,
                         O_ROSTER_FLAG OUT VARCHAR2)IS
LC_DTY_IN       VARCHAR2(10);
LC_DTY_OUT      VARCHAR2(10);
LC_LCH_OUT      VARCHAR2(10);
LC_LCH_IN       VARCHAR2(10);
LC_DTY_HRS      NUMBER(13,2);
LC_MIN_OT_LIMIT NUMBER(13,2);
LC_LATE_MARGIN  VARCHAR2(10);

LC_SHF_CODE     VARCHAR2(3);
LC_OFF_TYPE     VARCHAR2(1);
LC_SHF_DATE     DATE;
LC_SHF_DATE_OUT DATE;
LC_HRS_DIFF     NUMBER(13,2) := 0;
LC_ROSTER_FLAG  VARCHAR2(1);
LC_DSE_OFF_MON  VARCHAR2(1);
LC_DSE_OFF_TUE  VARCHAR2(1);
LC_DSE_OFF_WED  VARCHAR2(1);
LC_DSE_OFF_THU  VARCHAR2(1);
LC_DSE_OFF_FRI  VARCHAR2(1);
LC_DSE_OFF_SAT  VARCHAR2(1);
LC_DSE_OFF_SUN  VARCHAR2(1);

CNT_GH NUMBER;
CNT_AL NUMBER;
CNT NUMBER;
BEGIN
        SELECT COUNT(*)
        INTO   CNT
        FROM   PAY_SM_EMPLOYEE,PAY_SD_SHIFT_EMPLOYEE
        WHERE  EMP_CP_CODE      = DSE_CP_CODE
        AND    EMP_CODE         = DSE_EMP_CODE
        AND    DSE_CP_CODE      = RS_CP_CODE
        AND    DSE_EMP_CODE     = RS_EMP_CODE
        AND    DSE_EFF_DATE    <= RS_DATE
        AND    NVL(EMP_SHF_RS,'N') = 'N'
        AND    NVL(DSE_ACTIVE,'N') = 'Y';
        IF CNT > 0 THEN
            BEGIN

                SELECT  'S', NULL, WAG_SHF_CODE, WAG_DTY_IN, WAG_DTY_OUT, WAG_LCH_OUT, WAG_LCH_IN, WAG_DTY_HRS, WAG_MIN_OT_LIMIT, WAG_LATE_MARGIN,
                        DSE_OFF_MON, DSE_OFF_TUE, DSE_OFF_WED, DSE_OFF_THU, DSE_OFF_FRI, DSE_OFF_SAT, DSE_OFF_SUN
                INTO    LC_ROSTER_FLAG, LC_SHF_DATE, LC_SHF_CODE, LC_DTY_IN , LC_DTY_OUT, LC_LCH_OUT, LC_LCH_IN, LC_DTY_HRS, LC_MIN_OT_LIMIT, LC_LATE_MARGIN,
                        LC_DSE_OFF_MON, LC_DSE_OFF_TUE, LC_DSE_OFF_WED, LC_DSE_OFF_THU, LC_DSE_OFF_FRI, LC_DSE_OFF_SAT, LC_DSE_OFF_SUN
                FROM PAY_SM_EMPLOYEE A,PAY_SD_SHIFT_EMPLOYEE B,PAY_SO_WAGES_INFO C
                WHERE A.EMP_CP_CODE  = RS_CP_CODE
                AND   A.EMP_CP_CODE  = B.DSE_CP_CODE
                AND   A.EMP_CODE     = B.DSE_EMP_CODE
                AND   A.EMP_CODE     = RS_EMP_CODE
                AND   B.DSE_CP_CODE  = C.WAG_CP_CODE
                AND   B.DSE_SHF_CODE = C.WAG_SHF_CODE
                AND    NVL(EMP_SHF_RS,'N') = 'N'
                AND   C.WAG_FLAG     = 'Y'
                AND   C.WAG_EFF_DATE = (SELECT MAX(D.WAG_EFF_DATE)

                                         FROM PAY_SO_WAGES_INFO D
                                         WHERE WAG_CP_CODE   = A.EMP_CP_CODE
                                         AND   WAG_SHF_CODE  = B.DSE_SHF_CODE
                                         AND   WAG_EFF_DATE <= RS_DATE
                                         AND   WAG_FLAG      = 'Y')
                AND   B.DSE_EFF_DATE = (SELECT MAX(E.DSE_EFF_DATE)
                                         FROM PAY_SD_SHIFT_EMPLOYEE E
                                         WHERE E.DSE_CP_CODE   = A.EMP_CP_CODE

                                         AND   E.DSE_EFF_DATE <= RS_DATE
                                         AND   E.DSE_EMP_CODE  = A.EMP_CODE);
            EXCEPTION WHEN NO_DATA_FOUND THEN



                LC_SHF_DATE     := NULL;
                LC_SHF_DATE_OUT  := NULL;
                 LC_SHF_CODE      := NULL;
                 LC_DTY_IN       := NULL;
                 LC_DTY_OUT      := NULL;
                 LC_LCH_OUT      := NULL;
                 LC_LCH_IN       := NULL;
                 LC_DTY_HRS      := NULL;
                 LC_MIN_OT_LIMIT := NULL;
                 LC_LATE_MARGIN  := NULL;
                 LC_OFF_TYPE     := NULL;
                 LC_ROSTER_FLAG  := 'I';

            END ;
             LC_OFF_TYPE := 'W';
             IF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'MON' AND NVL(LC_DSE_OFF_MON,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'TUE' AND NVL(LC_DSE_OFF_TUE,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'WED' AND NVL(LC_DSE_OFF_WED,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'THU' AND NVL(LC_DSE_OFF_THU,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'FRI' AND NVL(LC_DSE_OFF_FRI,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'SAT' AND NVL(LC_DSE_OFF_SAT,'N') = 'Y' THEN

                LC_OFF_TYPE := 'O';
             ELSIF SUBSTR(UPPER(TO_CHAR(RS_DATE,'DAY')),1,3) = 'SUN' AND NVL(LC_DSE_OFF_SUN,'N') = 'Y' THEN
                LC_OFF_TYPE := 'O';
            END IF;
            IF LC_ROSTER_FLAG = 'S' THEN
                LC_SHF_DATE := RS_DATE;
                IF LC_DTY_IN >  LC_DTY_OUT AND RS_IN_OUT = 'I' THEN
                      LC_SHF_DATE_OUT := RS_DATE + 1;
                ELSIF LC_DTY_IN >  LC_DTY_OUT AND RS_IN_OUT = 'O' THEN
                      LC_SHF_DATE := RS_DATE - 1;
                      LC_SHF_DATE_OUT := RS_DATE;
                ELSE
                      LC_SHF_DATE_OUT := RS_DATE;

                END IF;
            END IF;
        ELSE
          IF RS_TIME IS NULL THEN
            BEGIN
                SELECT 'R', ROS_DATE, ROS_OUT_DATE, ROS_SHF_CODE, ROS_TIME_IN, ROS_TIME_OUT, ROS_LCH_OUT, ROS_LCH_IN, ROS_DUTY_HRS, ROS_MIN_OT_LIMIT, ROS_LATE_MARGIN,ROS_OFF_TYPE
                INTO   LC_ROSTER_FLAG, LC_SHF_DATE, LC_SHF_DATE_OUT, LC_SHF_CODE, LC_DTY_IN , LC_DTY_OUT, LC_LCH_OUT, LC_LCH_IN, LC_DTY_HRS, LC_MIN_OT_LIMIT, LC_LATE_MARGIN, LC_OFF_TYPE
                FROM   PAY_SM_EMPLOYEE A, PAY_EMP_ROASTER B
                WHERE  A.EMP_CP_CODE  = RS_CP_CODE
                AND    A.EMP_CP_CODE  = B.ROS_CP_CODE
                AND    A.EMP_CODE     = B.ROS_EMP_CODE
                AND    A.EMP_CODE     = RS_EMP_CODE
                AND    B.ROS_DATE = RS_DATE;

            EXCEPTION WHEN NO_DATA_FOUND THEN
                    LC_SHF_DATE     := NULL;
                    LC_SHF_DATE_OUT := NULL;
                     LC_SHF_CODE      := NULL;
                     LC_DTY_IN       := NULL;
                     LC_DTY_OUT      := NULL;
                     LC_LCH_OUT      := NULL;
                     LC_LCH_IN       := NULL;
                     LC_DTY_HRS      := NULL;
                     LC_MIN_OT_LIMIT := NULL;
                     LC_LATE_MARGIN  := NULL;
                     LC_OFF_TYPE     := 'U';
                     LC_ROSTER_FLAG  := 'I';

                END;
           ELSE
              BEGIN
                SELECT 'R', ROS_DATE, ROS_OUT_DATE, ROS_SHF_CODE, ROS_TIME_IN, ROS_TIME_OUT, ROS_LCH_OUT, ROS_LCH_IN, ROS_DUTY_HRS, ROS_MIN_OT_LIMIT, ROS_LATE_MARGIN,ROS_OFF_TYPE
                    INTO   LC_ROSTER_FLAG, LC_SHF_DATE, LC_SHF_DATE_OUT, LC_SHF_CODE, LC_DTY_IN , LC_DTY_OUT, LC_LCH_OUT, LC_LCH_IN, LC_DTY_HRS, LC_MIN_OT_LIMIT, LC_LATE_MARGIN, LC_OFF_TYPE
                    FROM   PAY_SM_EMPLOYEE A, PAY_EMP_ROASTER B
                    WHERE  A.EMP_CP_CODE  = RS_CP_CODE
                    AND    A.EMP_CP_CODE  = B.ROS_CP_CODE
                    AND    A.EMP_CODE     = B.ROS_EMP_CODE
                    AND    A.EMP_CODE     = RS_EMP_CODE
                    AND    (TO_CHAR(RS_DATE,'YYYYMMDD') || SUBSTR(RS_TIME,1,4)) BETWEEN (TO_CHAR(B.ROS_DATE,'YYYYMMDD') || ROS_TIME_IN)  AND  (TO_CHAR(B.ROS_OUT_DATE,'YYYYMMDD') || ROS_TIME_OUT);
                EXCEPTION WHEN TOO_MANY_ROWS THEN
                        LC_SHF_DATE     := NULL;

                        LC_SHF_DATE_OUT := NULL;
                         LC_SHF_CODE      := NULL;
                         LC_DTY_IN       := NULL;
                         LC_DTY_OUT      := NULL;
                         LC_LCH_OUT      := NULL;
                         LC_LCH_IN       := NULL;
                         LC_DTY_HRS      := NULL;
                         LC_MIN_OT_LIMIT := NULL;
                         LC_LATE_MARGIN  := NULL;
                         LC_OFF_TYPE     := NULL;
                         LC_ROSTER_FLAG  := 'I';
                WHEN NO_DATA_FOUND THEN
                    BEGIN

                        SELECT 'R', ROS_DATE, ROS_OUT_DATE, ROS_SHF_CODE, ROS_TIME_IN, ROS_TIME_OUT, ROS_LCH_OUT, ROS_LCH_IN, ROS_DUTY_HRS, ROS_MIN_OT_LIMIT, ROS_LATE_MARGIN,ROS_OFF_TYPE
                        INTO   LC_ROSTER_FLAG, LC_SHF_DATE_OUT, LC_SHF_DATE, LC_SHF_CODE, LC_DTY_IN , LC_DTY_OUT, LC_LCH_OUT, LC_LCH_IN, LC_DTY_HRS, LC_MIN_OT_LIMIT, LC_LATE_MARGIN, LC_OFF_TYPE
                        FROM   PAY_SM_EMPLOYEE A, PAY_EMP_ROASTER B
                        WHERE  A.EMP_CP_CODE  = RS_CP_CODE
                        AND    A.EMP_CP_CODE  = B.ROS_CP_CODE
                        AND    A.EMP_CODE     = B.ROS_EMP_CODE
                        AND    A.EMP_CODE     = RS_EMP_CODE
                        AND    DECODE(RS_IN_OUT,'I',B.ROS_DATE,DECODE(O_LC_OFF_TYPE,'W',B.ROS_OUT_DATE,B.ROS_DATE)) = RS_DATE
                        AND    ROS_SHF_CODE = DECODE(RS_IN_OUT,'I',ROS_SHF_CODE,O_SHF_CODE);
                    EXCEPTION WHEN OTHERS THEN
                        LC_SHF_DATE     := NULL;
                        LC_SHF_DATE_OUT := NULL;
                         LC_SHF_CODE      := NULL;

                         LC_DTY_IN       := NULL;
                         LC_DTY_OUT      := NULL;
                         LC_LCH_OUT      := NULL;
                         LC_LCH_IN       := NULL;
                         LC_DTY_HRS      := NULL;
                         LC_MIN_OT_LIMIT := NULL;
                         LC_LATE_MARGIN  := NULL;
                         LC_OFF_TYPE     := NULL;
                         LC_ROSTER_FLAG  := 'I';
                    END;
                END;
            END IF;
        END IF;

        SELECT COUNT(*)
        INTO   CNT_GH
        FROM   PAY_SM_WORK_HOLIDAY
         WHERE  HOL_CP_CODE    = RS_CP_CODE
        AND    HOL_DATE       = RS_DATE;
        IF CNT_GH > 0 THEN
          LC_OFF_TYPE := 'G';
        ELSE
          BEGIN
            SELECT SUM(TLA_DAYS)
            INTO   CNT_AL
            FROM   PAY_TO_LEAVE_APPROVED
             WHERE  TLA_CP_CODE    = RS_CP_CODE

             AND    TLA_EMP_CODE   = RS_EMP_CODE
            AND    TLA_EMP_TYPE   = RS_EMP_TYPE
            AND    RS_DATE         BETWEEN TLA_DATE_FM AND TLA_DATE_TO;
          EXCEPTION WHEN NO_DATA_FOUND THEN
            CNT_AL := NULL;
          END;
          IF CNT_AL IS NOT NULL THEN
              IF CNT_AL = .5 THEN
                LC_OFF_TYPE := 'H';
              ELSE
                LC_OFF_TYPE := 'A';
              END IF;
          END IF;

        END IF;
     IF LC_ROSTER_FLAG = 'S' THEN
        LC_ROSTER_FLAG := 'R';
     END IF;
     O_LC_SHF_DATE     := LC_SHF_DATE;
     O_LC_SHF_DATE_OUT := LC_SHF_DATE_OUT;
     O_LC_DTY_IN       := LC_DTY_IN;
     O_LC_DTY_OUT      := LC_DTY_OUT;
     O_LC_LCH_OUT      := LC_LCH_OUT;
     O_LC_LCH_IN       := LC_LCH_IN;
     O_LC_DTY_HRS      := LC_DTY_HRS;
     O_LC_MIN_OT_LIMIT := LC_MIN_OT_LIMIT;
     O_LC_LATE_MARGIN  := LC_LATE_MARGIN;

     O_SHF_CODE        := LC_SHF_CODE;
     O_LC_OFF_TYPE     := NVL(LC_OFF_TYPE,'U');
     O_ROSTER_FLAG     := LC_ROSTER_FLAG;
END;
/

