prompt Creating function IS_WORKING_DAY
prompt ================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."IS_WORKING_DAY" (ARG_CP_CODE VARCHAR2, ARG_EMP_CODE VARCHAR2, ARG_DATE DATE) RETURN VARCHAR2 IS

       LC_CNT NUMBER;
BEGIN
       SELECT COUNT(*)
       INTO   LC_CNT
       FROM   PAY_TO_EMP_ATTEND
       WHERE EAT_CP_CODE = ARG_CP_CODE
       AND   EAT_EMP_CODE = ARG_EMP_CODE
       AND   EAT_DATE     = ARG_DATE
       AND   EAT_OFF_TYPE = 'W';


       IF LC_CNT > 0 THEN
          RETURN 'Y';
       ELSE

          RETURN 'N';
       END IF;
END;
/

