prompt Creating function GET_ATTENDANCE_TYPE
prompt =====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_ATTENDANCE_TYPE" (ARG_CP_CODE  VARCHAR2,
                                                 ARG_EMP_CODE VARCHAR2,
                                                 ARG_EMP_TYPE VARCHAR2,
                                                 ARG_TRN_DATE DATE,
                                                 ARG_DATE_IN  DATE,
                                                 ARG_TIME_IN  VARCHAR2,
                                                 ARG_DATE_OUT DATE,
                                                 ARG_TIME_OUT VARCHAR2)
  RETURN VARCHAR2 IS
  LC_DTY_IN       VARCHAR2(10);
  LC_DTY_OUT      VARCHAR2(10);
  LC_LCH_OUT      VARCHAR2(10);

  LC_LCH_IN       VARCHAR2(10);
  LC_DTY_HRS      NUMBER(13, 2);
  LC_MIN_OT_LIMIT NUMBER(13, 2);
  LC_LATE_MARGIN  VARCHAR2(10);
  LC_SHF_CODE     VARCHAR2(3);
  LC_OFF_TYPE     VARCHAR2(1);
  LC_SHF_DATE     DATE;
  LC_SHF_DATE_OUT DATE;
  LC_HRS_DIFF     NUMBER(13, 2) := 0;

  LC_ROSTER_FLAG VARCHAR2(1);
  LC_DSE_OFF_MON VARCHAR2(1);
  LC_DSE_OFF_TUE VARCHAR2(1);

  LC_DSE_OFF_WED VARCHAR2(1);
  LC_DSE_OFF_THU VARCHAR2(1);
  LC_DSE_OFF_FRI VARCHAR2(1);
  LC_DSE_OFF_SAT VARCHAR2(1);
  LC_DSE_OFF_SUN VARCHAR2(1);
  CNT_GH         NUMBER;
  CNT_AL         NUMBER;
  CNT            NUMBER;
  LC_FLAG        VARCHAR2(1);
  LC_DIFF_HOURS  NUMBER(13, 2);

BEGIN
  GET_ROASTER_DETAILS(ARG_CP_CODE,

                      ARG_EMP_CODE,
                      ARG_EMP_TYPE,
                      ARG_TRN_DATE,
                      NULL,
                      'I',
                      LC_SHF_DATE,
                      LC_SHF_DATE_OUT,
                      LC_DTY_IN,
                      LC_DTY_OUT,
                      LC_LCH_OUT,
                      LC_LCH_IN,
                      LC_DTY_HRS,
                      LC_MIN_OT_LIMIT,

                      LC_LATE_MARGIN,
                      LC_OFF_TYPE,
                      LC_SHF_CODE,
                      LC_ROSTER_FLAG);

  IF LENGTH(LC_DTY_IN) = 4 THEN
    LC_DTY_OUT := LC_DTY_OUT || '00';
    LC_DTY_IN  := LC_DTY_IN || '00';
  END IF;

  IF ARG_TIME_IN IS NULL THEN
    LC_OFF_TYPE := 'W';
  END IF;
dbms_output.put_line(LC_OFF_TYPE);

  
  
  IF LC_OFF_TYPE = 'W' THEN
    IF (TO_CHAR(NVL(LC_SHF_DATE, ARG_TRN_DATE), 'YYYYMMDD') || LC_DTY_IN BETWEEN
       TO_CHAR(NVL(ARG_DATE_IN, LC_SHF_DATE), 'YYYYMMDD') ||
       NVL(ARG_TIME_IN, LC_DTY_IN) AND
       TO_CHAR(NVL(ARG_DATE_OUT, LC_SHF_DATE_OUT), 'YYYYMMDD') ||
       NVL(ARG_TIME_OUT, LC_DTY_OUT)) OR
       (TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT BETWEEN
       TO_CHAR(NVL(ARG_DATE_IN, LC_SHF_DATE), 'YYYYMMDD') ||
       NVL(ARG_TIME_IN, LC_DTY_IN) AND
       TO_CHAR(NVL(ARG_DATE_OUT, LC_SHF_DATE_OUT), 'YYYYMMDD') ||

       NVL(ARG_TIME_OUT, LC_DTY_OUT)) OR
       (TO_CHAR(NVL(ARG_DATE_IN, LC_SHF_DATE), 'YYYYMMDD') ||
       NVL(ARG_TIME_IN, LC_DTY_IN) BETWEEN
       TO_CHAR(NVL(LC_SHF_DATE, ARG_TRN_DATE), 'YYYYMMDD') || LC_DTY_IN AND
       TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT) OR
       (TO_CHAR(NVL(ARG_DATE_OUT, LC_SHF_DATE_OUT), 'YYYYMMDD') ||
       NVL(ARG_TIME_OUT, LC_DTY_OUT) BETWEEN
       TO_CHAR(NVL(LC_SHF_DATE, ARG_TRN_DATE), 'YYYYMMDD') || LC_DTY_IN AND
       TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT) THEN

      
      IF GET_HOURS_DIFF(ARG_DATE_IN,
                        ARG_TIME_IN,

                        LC_SHF_DATE_OUT,
                        LC_DTY_OUT) >= 0 AND
         GET_HOURS_DIFF(ARG_DATE_IN,
                        ARG_TIME_IN,
                        LC_SHF_DATE_OUT,
                        LC_DTY_OUT) <= 1 AND ARG_TIME_IN IS NOT NULL THEN
        
/*
        DBMS_OUTPUT.PUT_LINE(     GET_HOURS_DIFF(ARG_DATE_IN,
                        ARG_TIME_IN,
                        LC_SHF_DATE_OUT,
                        LC_DTY_OUT)||' - '||LC_DTY_OUT||' '||LC_SHF_DATE_OUT||' - '||ARG_TIME_IN);
        
*/
        IF IS_WORKING_DAY(ARG_CP_CODE, ARG_EMP_CODE, ARG_TRN_DATE) = 'N' THEN
          LC_FLAG := '4'; 
--dbms_Output.put_line(LC_FLAG);
        ELSE
          LC_FLAG := '5'; 
        END IF;

      ELSE

        





















        LC_FLAG := 'W'; 
      END IF;

    ELSIF ARG_DATE_IN IS NULL AND ARG_TIME_IN IS NULL AND
          ARG_DATE_OUT IS NULL AND ARG_TIME_OUT IS NULL THEN
      LC_FLAG := '6'; 
    ELSE
      IF IS_ABSENT(ARG_CP_CODE, ARG_EMP_CODE, 'E', ARG_TRN_DATE) = 'T' THEN

        
        LC_FLAG := '4'; 
      ELSE
        IF ((TO_CHAR(ARG_DATE_IN, 'YYYYMMDD') || ARG_TIME_IN BETWEEN

           TO_CHAR(LC_SHF_DATE, 'YYYYMMDD') || LC_DTY_IN AND
           TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT) OR
           (TO_CHAR(ARG_DATE_OUT, 'YYYYMMDD') || ARG_TIME_OUT BETWEEN
           TO_CHAR(LC_SHF_DATE, 'YYYYMMDD') || LC_DTY_IN AND
           TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT) OR
           (TO_CHAR(LC_SHF_DATE, 'YYYYMMDD') || LC_DTY_IN BETWEEN
           TO_CHAR(ARG_DATE_IN, 'YYYYMMDD') || ARG_TIME_IN AND
           TO_CHAR(ARG_DATE_OUT, 'YYYYMMDD') || ARG_TIME_OUT) OR
           (TO_CHAR(LC_SHF_DATE_OUT, 'YYYYMMDD') || LC_DTY_OUT BETWEEN
           TO_CHAR(ARG_DATE_IN, 'YYYYMMDD') || ARG_TIME_IN AND
           TO_CHAR(ARG_DATE_OUT, 'YYYYMMDD') || ARG_TIME_OUT)) OR
           IS_ABSENT(ARG_CP_CODE, ARG_EMP_CODE, 'E', ARG_TRN_DATE) = 'F' THEN
          IF IS_WORKING_DAY(ARG_CP_CODE, ARG_EMP_CODE, ARG_TRN_DATE) = 'N' THEN

            LC_FLAG := '4'; 
          ELSE
            LC_FLAG := '5'; 
          END IF;
        ELSE
          
          LC_FLAG := '4'; 
        END IF;

      END IF;
    END IF;

  ELSIF LC_OFF_TYPE = 'O' THEN

    IF ARG_DATE_IN IS NOT NULL OR ARG_DATE_OUT IS NOT NULL THEN
      LC_FLAG := 'O'; 
    ELSE
      LC_FLAG := '1'; 
    END IF;
  ELSIF LC_OFF_TYPE = 'G' THEN
    IF ARG_DATE_IN IS NOT NULL OR ARG_DATE_OUT IS NOT NULL THEN
      LC_FLAG := 'G'; 
    ELSE
      LC_FLAG := '2'; 
    END IF;
  ELSIF LC_OFF_TYPE IN ('A', 'H') THEN
    IF ARG_DATE_IN IS NOT NULL OR ARG_DATE_OUT IS NOT NULL THEN

      LC_FLAG := LC_OFF_TYPE; 
    ELSE
      LC_FLAG := '3'; 
    END IF;
  ELSE
    LC_FLAG := 'U';
  END IF;
  RETURN LC_FLAG;
END;
/

