prompt Creating function GET_COA_BR_AMT
prompt ================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_COA_BR_AMT  (RC_CP_CODE VARCHAR2, RC_BR_CODE VARCHAR2, RC_COA3_CODE VARCHAR2,
       RC_DP_CODE_FM VARCHAR2, RC_DP_CODE_TO VARCHAR2,
       RC_DATE_FM DATE, RC_DATE_TO DATE) RETURN NUMBER IS
 LC_AMT NUMBER(13,2);
BEGIN
 BEGIN
  SELECT SUM(NVL(DVH_DBT_OTH,0)) - SUM(NVL(DVH_CRD_OTH,0))
  INTO LC_AMT
  FROM ACT_TD_VOUCHER INNER JOIN ACT_TM_VOUCHER
  ON   (DVH_CP_CODE = MVH_CP_CODE
  AND   DVH_MVH_NUM = MVH_NUM
  AND    'P'        =  MVH_STATUS)
  where   DVH_CP_CODE   =  RC_CP_CODE
  AND   DVH_BR_CODE   = RC_BR_CODE
  --AND   (DVH_DP_CODE LIKE RC_DP_CODE_FM
  and  DVH_DP_CODE BETWEEN RC_DP_CODE_FM AND RC_DP_CODE_TO
  AND   DVH_COA3_CODE = RC_COA3_CODE
  AND   DVH_MVH_DATE  BETWEEN RC_DATE_FM AND RC_DATE_TO;


 EXCEPTION WHEN NO_DATA_FOUND THEN
  LC_AMT :=0;
 END;
 RETURN LC_AMT;

END;
/

prompt
prompt Creating function GET_COA_CURR_BAL
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_COA_CURR_BAL (ARG_CP_CODE VARCHAR2, ARG_BR_CODE VARCHAR2 , ARG_COA3_CODE VARCHAR2, ARG_DATE DATE, ARG_STATUS VARCHAR2) RETURN NUMBER IS
 LC_RETURN NUMBER;
 LC_DATE_FM DATE;
 LC_OPN_BAL NUMBER;
BEGIN
 IF ARG_STATUS = 'P' THEN
   BEGIN
       SELECT NVL(SUM(NVL(DCO_DBT_OTH,0)-NVL(DCO_CRD_OTH,0)),0), DCO_FYR_FM
       INTO LC_OPN_BAL, LC_DATE_FM
       FROM ACT_SD_COA_OPNBAL
       WHERE DCO_CP_CODE = ARG_CP_CODE
       AND   ARG_DATE BETWEEN DCO_FYR_FM AND DCO_FYR_TO
       AND   DCO_BR_CODE = ARG_BR_CODE
       AND   DCO_COA3_CODE = ARG_COA3_CODE
       GROUP BY DCO_FYR_FM;
   EXCEPTION WHEN NO_DATA_FOUND THEN       
      BEGIN
          SELECT MCO_FYR_FM
          INTO   LC_DATE_FM
          FROM ACT_SM_COA_OPNBAL           
          WHERE MCO_CP_CODE = ARG_CP_CODE
          AND   ARG_DATE BETWEEN MCO_FYR_FM AND MCO_FYR_TO;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          LC_DATE_FM := ARG_DATE;      
      END;
   END;

   SELECT NVL(SUM(NVL(DVH_DBT_OTH,0)-NVL(DVH_CRD_OTH,0)),0)
   INTO LC_RETURN
   FROM   ACT_TD_VOUCHER, ACT_TM_VOUCHER
   WHERE  MVH_CP_CODE   = ARG_CP_CODE
   AND     MVH_DATE      BETWEEN LC_DATE_FM AND ARG_DATE
   AND     MVH_STATUS    = ARG_STATUS
   AND     DVH_CP_CODE   = MVH_CP_CODE
   AND     DVH_MVH_NUM   = MVH_NUM
   AND     DVH_BR_CODE   = MVH_BR_CODE
   AND     DVH_BR_CODE   = ARG_BR_CODE
   AND     DVH_COA3_CODE = ARG_COA3_CODE;

   LC_RETURN := NVL(LC_OPN_BAL,0) + NVL(LC_RETURN,0);
 ELSE
   SELECT NVL(SUM(NVL(DVH_DBT_OTH,0)-NVL(DVH_CRD_OTH,0)),0)
   INTO LC_RETURN
   FROM   ACT_TD_VOUCHER, ACT_TM_VOUCHER
   WHERE  MVH_CP_CODE   = ARG_CP_CODE
   AND     MVH_DATE      <= ARG_DATE
   AND     MVH_STATUS    = ARG_STATUS
   AND     DVH_CP_CODE   = MVH_CP_CODE
   AND     DVH_MVH_NUM   = MVH_NUM
   AND     DVH_BR_CODE   = MVH_BR_CODE

   AND     DVH_BR_CODE   = ARG_BR_CODE
   AND     DVH_COA3_CODE = ARG_COA3_CODE;
 END IF;

 RETURN NVL(LC_RETURN,0);

END;
/

