prompt Creating function GET_EMP_CODE
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_EMP_CODE" (ARG_CP_CODE VARCHAR2,
                                        ARG_BR_CODE VARCHAR2)
  RETURN VARCHAR2 IS
  VEMP_CODE VARCHAR2(35);
  LC_BR_ALS_CODE VARCHAR2(1);
BEGIN

  BEGIN
    SELECT MAX(SUBSTR(EMP_CODE, -4)) MBP_BAR_CODE
      INTO VEMP_CODE
      FROM EMP_CODE_VIEW
     WHERE EMP_CP_CODE = ARG_CP_CODE
       AND EMP_BR_CODE = ARG_BR_CODE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      VEMP_CODE := NULL;
  END;

  BEGIN
     SELECT BR_ALS_CODE  LC_BR_ALS_CODE
     INTO   LC_BR_ALS_CODE
     FROM   ISR_XM_BRANCH
     WHERE  BR_CP_CODE = ARG_CP_CODE
     AND    BR_CODE = ARG_BR_CODE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      LC_BR_ALS_CODE := NULL;
  END;

  IF NVL(VEMP_CODE, '-') = '-' THEN
    VEMP_CODE := LC_BR_ALS_CODE || '0001';
  ELSE
    VEMP_CODE := LC_BR_ALS_CODE||LPAD(VEMP_CODE + 1,4,0);
  END IF;

    VEMP_CODE := VEMP_CODE;

  RETURN VEMP_CODE;
END;
/

