prompt Creating function GET_GROUP_VALIDATE
prompt ====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_GROUP_VALIDATE(ARG_CP_CODE VARCHAR2,ARG_DSC_CODE VARCHAR2,ARG_PDG_RPT_ID VARCHAR2,ARG_RCT_NUM VARCHAR2 DEFAULT NULL)RETURN VARCHAR2 IS
  LC_LTG_GROUP VARCHAR2(500);
  LC_PDG_GROUP VARCHAR2(500);
  LC_PDG       VARCHAR2(1000);
  CURSOR CRS1 IS
         SELECT DISTINCT   DSD_DSC_CODE , DECODE(LTG_GROUP, 'A', 'GROUP 1', 'B', 'GROUP 2', 'C', 'GROUP 3', 'D', 'GROUP 4', 'E', 'GROUP 5', 'F', 'GROUP 6', 'G', 'GROUP 7', 'H', 'GROUP 8', 'I', 'GROUP 9', 'J', 'GROUP 10') "LTG_GROUP1",LTG_GROUP, LTG_NUM
         FROM   LAB_TD_SRV_DIAG,LAB_SD_LT_GROUP
         WHERE  LTG_CP_CODE    = DSD_CP_CODE
         AND    LTG_SRV_CODE   = DSD_DSC_CODE
         AND    DSD_CP_CODE    = ARG_CP_CODE
         AND    DSD_RCT_NUM  = NVL(ARG_RCT_NUM,DSD_RCT_NUM)
         AND   (LTG_NUM IS NOT NULL
         AND    LTG_GROUP IS NOT NULL)
         AND    DSD_DSC_CODE   =  ARG_DSC_CODE
         ORDER BY LTG_GROUP;
  CURSOR CRS2(LC_DSC_CODE VARCHAR2, LC_GROUP VARCHAR2) IS
         SELECT PDG_RPT_ID  , PDG_DSC_CODE , PDG_LTP_GROUP , NVL(SUM(PDG_TST_RES),0) "PDG_TST_RES" , DECODE(PDG_LTP_GROUP, 'A', 'GROUP 1', 'B', 'GROUP 2', 'C', 'GROUP 3', 'D', 'GROUP 4', 'E', 'GROUP 5', 'F', 'GROUP 6', 'G', 'GROUP 7', 'H', 'GROUP 8', 'I', 'GROUP 9', 'J', 'GROUP 10') "PDG_LTP_GROUP1"
         FROM  LAB_TD_PMT_DIAG
         WHERE PDG_CP_CODE   =   ARG_CP_CODE
         AND   PDG_DSC_CODE  =   LC_DSC_CODE
         AND   PDG_RPT_ID    =   ARG_PDG_RPT_ID
         AND    PDG_RCT_NUM   = NVL(ARG_RCT_NUM,PDG_RCT_NUM)
         AND   PDG_LTP_GROUP  IS NOT NULL
         AND   PDG_LTP_GROUP =   LC_GROUP
         GROUP BY  PDG_RPT_ID  , PDG_DSC_CODE , PDG_LTP_GROUP;
BEGIN
  FOR REC1 IN CRS1 LOOP
      LC_LTG_GROUP := LC_LTG_GROUP||' '||REC1.LTG_GROUP1||' Should be '||REC1.LTG_NUM;
      FOR REC2 IN CRS2(REC1.DSD_DSC_CODE,REC1.LTG_GROUP) LOOP
          LC_PDG_GROUP := LC_PDG_GROUP||' '||REC2.PDG_LTP_GROUP1||' is  '||REC2.PDG_TST_RES;
      END LOOP;
  END LOOP;
  LC_PDG := 'Invalid value entered for Group'||CHR(10)||LC_PDG_GROUP||CHR(10)||LC_LTG_GROUP;
  RETURN LC_PDG;
EXCEPTION
  WHEN OTHERS THEN
       DBMS_OUTPUT.PUT_LINE(SQLERRM || ' ' || SQLCODE);
END;
/

