prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_HOS_SRV_CATEGORY (ARG_CP_CODE VARCHAR2,
ARG_DSC_CODE VARCHAR2) RETURN VARCHAR2 IS

	LC_HSC_CODE VARCHAR2(3);

BEGIN
  BEGIN
    SELECT DSC_HSC_CODE
    INTO   LC_HSC_CODE
    FROM   HOS_SD_SRV_CHARGES
    WHERE  DSC_CP_CODE = ARG_CP_CODE
    AND    DSC_CODE    = ARG_DSC_CODE;
  EXCEPTION WHEN NO_DATA_FOUND THEN
    LC_HSC_CODE := NULL;
  END;
  RETURN LC_HSC_CODE;
END;
/

