prompt
prompt Creating function GET_ITEM_CATEGORY
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_CATEGORY(AGR_CP_CODE VARCHAR2,
                                             ARG_ITEM    VARCHAR2)
  RETURN VARCHAR2 IS
  LC_CTG_CODE VARCHAR2(2);
BEGIN
  SELECT MIT_CTG_CODE
    INTO LC_CTG_CODE
    FROM PPI_SD_ITEM
   INNER JOIN PPI_SM_ITEM
      ON (PPI_SD_ITEM.DIT_CP_CODE = PPI_SM_ITEM.MIT_CP_CODE AND
         PPI_SD_ITEM.DIT_MIT_CODE = PPI_SM_ITEM.MIT_CODE)
     WHERE DIT_CP_CODE = AGR_CP_CODE
     AND DIT_CODE = ARG_ITEM
   GROUP BY MIT_CTG_CODE;
  RETURN LC_CTG_CODE;
EXCEPTION
  WHEN OTHERS THEN
    LC_CTG_CODE := NULL;
    RETURN LC_CTG_CODE;
END;
/

prompt
prompt Creating function GET_ITEM_ACTIVITY
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_ACTIVITY(ARG_CP_CODE  VARCHAR2,
                                             ARG_DIT_CODE VARCHAR2,
                                             ARG_DATE_FM  DATE,
                                             ARG_DATE_TO  DATE,
                                             ARG_LOC_CODE VARCHAR2,
                                             ARG_FLAG     VARCHAR2,
                                             ARG_TYPE     VARCHAR2,
                                             ARG_CTG_CODE VARCHAR2 DEFAULT NULL)
  RETURN NUMBER IS

  LC_QTY_OB_IN NUMBER(13, 2);
  LC_AMT_OB_IN NUMBER(13, 2);

  LC_RETURN NUMBER(13, 2);
BEGIN

  IF ARG_FLAG = 'PM' THEN   ---'Collecting UP Document'
    BEGIN
      SELECT SUM(NVL(MPB_QTY, 0)), SUM(NVL(MPB_QTY, 0) * NVL(MPB_RATE, 0))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PM_BALANCE
       WHERE MPB_CP_CODE = ARG_CP_CODE
         AND MPB_DIT_CODE = ARG_DIT_CODE
         AND MPB_DATE < ARG_DATE_FM
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
         AND MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'PD' THEN  ---'Collecting Down Document'
    BEGIN
      SELECT SUM(NVL(DPB_QTY, 0)), SUM(NVL(DPB_QTY, 0) * NVL(DPB_RATE, 0))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PD_BALANCE
       WHERE DPB_CP_CODE = ARG_CP_CODE
         AND DPB_DIT_CODE = ARG_DIT_CODE
         AND DPB_TRS_DATE < ARG_DATE_FM
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
         AND DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SP' THEN  ---'Collecting GRN'
    BEGIN
      SELECT SUM(NVL(MPB_QTY, 0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PM_BALANCE
       WHERE MPB_CP_CODE = ARG_CP_CODE
         AND MPB_DIT_CODE = ARG_DIT_CODE
         AND MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%')
         AND MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
         AND MPB_IN_TYPE = 'SP'; -- GRN - STOCK IN
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;


IF ARG_FLAG = 'SR' THEN  ---'Sales Return'
  BEGIN
        SELECT SUM(NVL(MPB_QTY,0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
       INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PM_BALANCE
        WHERE  MPB_CP_CODE  = ARG_CP_CODE
        AND    MPB_DIT_CODE = ARG_DIT_CODE
        AND    MPB_LOC_CODE  LIKE NVL(ARG_LOC_CODE, '%')
        AND    MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
        AND    MPB_IN_TYPE  = 'SR'; -- STOCK IN
         EXCEPTION
     WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'IN' THEN ---'Collecting Adjustments (PM) '
  BEGIN
        SELECT SUM(NVL(MPB_QTY,0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
        INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PM_BALANCE
        WHERE  MPB_CP_CODE  = ARG_CP_CODE
        AND    MPB_DIT_CODE = ARG_DIT_CODE
        AND    MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
        AND    MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
        AND    MPB_IN_TYPE  NOT IN ('SP','SR'); -- STOCK IN
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'SL' THEN  --- 'Collecting Sales'
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),  SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
        INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE
        WHERE  DPB_CP_CODE  =  ARG_CP_CODE
        AND    DPB_DIT_CODE =  ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE  NVL(ARG_LOC_CODE,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
        AND    DPB_OUT_TYPE  = 'SL';  -- SALE STOCK OUT
           EXCEPTION
    WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'PR' THEN  ---'Collecting Purchase Return'
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),   SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
          INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE
        WHERE  DPB_CP_CODE  = ARG_CP_CODE
        AND    DPB_DIT_CODE = ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
        AND    DPB_OUT_TYPE  = 'PR';  -- PURCHASE RETURN STOCK OUT
           EXCEPTION
   WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


    IF ARG_FLAG = 'OUT' THEN    --'Collecting Adjustment (PD) '
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),  SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
          INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE
        WHERE  DPB_CP_CODE  =  ARG_CP_CODE
        AND    DPB_DIT_CODE = ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE) = NVL(ARG_CTG_CODE,GET_ITEM_CATEGORY(ARG_CP_CODE,ARG_DIT_CODE))
        AND    DPB_OUT_TYPE NOT IN ('SL','PR');  -- STOCK OUT
        EXCEPTION
       WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
   END IF;

  IF ARG_TYPE = 'Q' THEN
    LC_RETURN := NVL(LC_QTY_OB_IN,0);

  ELSIF ARG_TYPE = 'A' THEN
    LC_RETURN := NVL(LC_AMT_OB_IN,0);
  END IF;

  RETURN LC_RETURN;
END;
/

prompt
prompt Creating function GET_ITEM_ACTIVITY_RPT
prompt =======================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_ACTIVITY_RPT(ARG_CP_CODE  VARCHAR2,
                                                 ARG_DIT_CODE VARCHAR2,
                                                 ARG_DATE_FM  DATE,
                                                 ARG_DATE_TO  DATE,
                                                 ARG_LOC_CODE VARCHAR2,
                                                 ARG_FLAG     VARCHAR2,
                                                 ARG_TYPE     VARCHAR2,
                                                 ARG_CTG_CODE VARCHAR2,
                                                 ARG_MANUFAC  VARCHAR2)
  RETURN NUMBER IS

  LC_QTY_OB_IN NUMBER(13, 2);
  LC_AMT_OB_IN NUMBER(13, 2);

  LC_RETURN NUMBER(13, 2);
BEGIN

  IF ARG_FLAG = 'PM' THEN   ---'Collecting UP Document'
    BEGIN
      SELECT SUM(NVL(MPB_QTY, 0)), SUM(NVL(MPB_QTY, 0) * NVL(MPB_RATE, 0))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PM_BALANCE, PPI_SD_ITEM
       WHERE MPB_CP_CODE  = ARG_CP_CODE
         AND MPB_CP_CODE  = DIT_CP_CODE
         AND MPB_DIT_CODE = DIT_CODE
         AND NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
         AND MPB_DIT_CODE = ARG_DIT_CODE
         AND MPB_DATE     < ARG_DATE_FM
         AND MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'PD' THEN  ---'Collecting Down Document'
    BEGIN
      SELECT SUM(NVL(DPB_QTY, 0)), SUM(NVL(DPB_QTY, 0) * NVL(DPB_RATE, 0))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PD_BALANCE, PPI_SD_ITEM
       WHERE DPB_CP_CODE = ARG_CP_CODE
         AND DPB_CP_CODE  = DIT_CP_CODE
         AND DPB_DIT_CODE = DIT_CODE
         AND NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
         AND DPB_DIT_CODE = ARG_DIT_CODE
         AND DPB_TRS_DATE < ARG_DATE_FM
         AND DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SP' THEN  ---'Collecting GRN'
    BEGIN
      SELECT SUM(NVL(MPB_QTY, 0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
        INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM PPI_PM_BALANCE, PPI_SD_ITEM
       WHERE MPB_CP_CODE = ARG_CP_CODE
         AND MPB_CP_CODE  = DIT_CP_CODE
         AND MPB_DIT_CODE = DIT_CODE
         AND NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
         AND GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
         AND MPB_DIT_CODE = ARG_DIT_CODE
         AND MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE, '%')
         AND MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
         AND MPB_IN_TYPE = 'SP'; -- GRN - STOCK IN
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
  END IF;


IF ARG_FLAG = 'SR' THEN  ---'Sales Return'
  BEGIN
        SELECT SUM(NVL(MPB_QTY,0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
       INTO LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PM_BALANCE, PPI_SD_ITEM
        WHERE  MPB_CP_CODE  = ARG_CP_CODE
        AND    MPB_CP_CODE  = DIT_CP_CODE
        AND    MPB_DIT_CODE = DIT_CODE
        AND    NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
        AND    GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
        AND    MPB_DIT_CODE = ARG_DIT_CODE
        AND    MPB_LOC_CODE  LIKE NVL(ARG_LOC_CODE, '%')
        AND    MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MPB_IN_TYPE  = 'SR'; -- STOCK IN
         EXCEPTION
     WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'IN' THEN ---'Collecting Adjustments (PM) '
  BEGIN
        SELECT SUM(NVL(MPB_QTY,0)),  SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4))
        INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PM_BALANCE, PPI_SD_ITEM
        WHERE  MPB_CP_CODE  = ARG_CP_CODE
        AND    MPB_CP_CODE  = DIT_CP_CODE
        AND    MPB_DIT_CODE = DIT_CODE
        AND    NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
        AND    GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
        AND    MPB_DIT_CODE = ARG_DIT_CODE
        AND    MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
        AND    MPB_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MPB_IN_TYPE  NOT IN ('SP','SR'); -- STOCK IN
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'SL' THEN  --- 'Collecting Sales'
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),  SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
        INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE, PPI_SD_ITEM
        WHERE  DPB_CP_CODE  =  ARG_CP_CODE
        AND    DPB_CP_CODE  = DIT_CP_CODE
        AND    DPB_DIT_CODE = DIT_CODE
        AND    NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
        AND    GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
        AND    DPB_DIT_CODE =  ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE  NVL(ARG_LOC_CODE,'%')
        AND    DPB_OUT_TYPE  = 'SL';  -- SALE STOCK OUT
           EXCEPTION
    WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


IF ARG_FLAG = 'PR' THEN  ---'Collecting Purchase Return'
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),   SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
          INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE, PPI_SD_ITEM
        WHERE  DPB_CP_CODE  = ARG_CP_CODE
        AND    DPB_CP_CODE  = DIT_CP_CODE
        AND    DPB_DIT_CODE = DIT_CODE
        AND    NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
        AND    GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
        AND    DPB_DIT_CODE = ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
        AND    DPB_OUT_TYPE  = 'PR';  -- PURCHASE RETURN STOCK OUT
           EXCEPTION
   WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
END IF;


    IF ARG_FLAG = 'OUT' THEN    --'Collecting Adjustment (PD) '
    BEGIN
        SELECT SUM(NVL(DPB_QTY,0)),  SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4))
          INTO   LC_QTY_OB_IN, LC_AMT_OB_IN
        FROM   PPI_PD_BALANCE, PPI_SD_ITEM
        WHERE  DPB_CP_CODE  =  ARG_CP_CODE
        AND    DPB_CP_CODE  = DIT_CP_CODE
        AND    DPB_DIT_CODE = DIT_CODE
        AND    NVL(DIT_MANUFAC,'%')  LIKE NVL(ARG_MANUFAC,'%')
        AND    GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE ARG_CTG_CODE
        AND    DPB_DIT_CODE = ARG_DIT_CODE
        AND    DPB_TRS_DATE BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
        AND    DPB_OUT_TYPE NOT IN ('SL','PR');  -- STOCK OUT
        EXCEPTION
       WHEN NO_DATA_FOUND THEN
        LC_QTY_OB_IN := 0;
        LC_AMT_OB_IN := 0;
    END;
   END IF;

  IF ARG_TYPE = 'Q' THEN
    LC_RETURN := NVL(LC_QTY_OB_IN,0);

  ELSIF ARG_TYPE = 'A' THEN
    LC_RETURN := NVL(LC_AMT_OB_IN,0);
  END IF;

  RETURN LC_RETURN;
END;
/

