prompt Creating function GET_ITEM_CATEGORY_TYPE
prompt ========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_CATEGORY_TYPE (AGR_CP_CODE VARCHAR2, ARG_ITEM VARCHAR2) RETURN VARCHAR2 IS
  LC_CTG_TYPE  VARCHAR2(1);
BEGIN
  SELECT CTG_TYPE
  INTO   LC_CTG_TYPE
  FROM   PPI_SD_ITEM
  INNER JOIN PPI_SM_ITEM
  ON    (PPI_SD_ITEM.DIT_CP_CODE  = PPI_SM_ITEM.MIT_CP_CODE
  AND    PPI_SD_ITEM.DIT_MIT_CODE = PPI_SM_ITEM.MIT_CODE)
  INNER JOIN PPI_SO_ITEM_CATEGORY
  ON    (PPI_SM_ITEM.MIT_CP_CODE  = PPI_SO_ITEM_CATEGORY.CTG_CP_CODE
  AND    PPI_SM_ITEM.MIT_CTG_CODE = PPI_SO_ITEM_CATEGORY.CTG_CODE)
  AND   DIT_CP_CODE = AGR_CP_CODE
  AND   DIT_CODE    = ARG_ITEM
  GROUP BY CTG_TYPE;

  RETURN LC_CTG_TYPE;
EXCEPTION
   WHEN OTHERS THEN
      LC_CTG_TYPE := NULL;
  RETURN LC_CTG_TYPE;
END;
/

prompt
prompt Creating function GET_ITEM_COGS
prompt ===============================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_COGS(ARG_CP_CODE  VARCHAR2,
                  ARG_DATE_FM  DATE,
                  ARG_DATE_TO  DATE,
                  ARG_LOC_CODE VARCHAR2,
                  ARG_CTG_CODE VARCHAR2,
                  ARG_SAL_TYPE VARCHAR2,
                  ARG_FLAG     VARCHAR2)
  RETURN NUMBER IS

  VAL_RETURN NUMBER(13, 2);
BEGIN

  IF ARG_FLAG = 'SL' THEN   ---'SALES DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SL'
       AND    MSL_SAL_TYPE LIKE ARG_SAL_TYPE
       AND    MSL_LOC_CODE = ARG_LOC_CODE
       AND DSL_CP_CODE  = MSL_CP_CODE
       AND DSL_MSL_NUM  = MSL_NUM
       AND DSL_MSL_TYPE = MSL_TYPE
       AND DSL_MSL_DATE = MSL_DATE
       AND DSL_CP_CODE  = MIT_CP_CODE
       AND SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SR' THEN   ---'SALES RETURN DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SR'
       AND    MSL_LOC_CODE = ARG_LOC_CODE
       AND DSL_CP_CODE  = MSL_CP_CODE
       AND DSL_MSL_NUM  = MSL_NUM
       AND DSL_MSL_TYPE = MSL_TYPE
       AND DSL_MSL_DATE = MSL_DATE
       AND DSL_CP_CODE  = MIT_CP_CODE
       AND SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SP' THEN  ---'GOOD RECEIPT NOTE'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_STOCK,PPI_TD_STOCK
      WHERE  MST_CP_CODE  = ARG_CP_CODE
      AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    MST_TYPE     = 'SP'
       AND    MST_LOC_IN = ARG_LOC_CODE
      AND DST_CP_CODE     = MST_CP_CODE
      AND DST_MST_NUM     = MST_NUM
      AND DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'PR' THEN  ---'GOOD RECEIPT NOTE RETURN'
    BEGIN
        SELECT NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0)
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK
        WHERE  MST_CP_CODE  = ARG_CP_CODE
        AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE     = 'PR'
               AND    MST_LOC_IN = ARG_LOC_CODE
        AND DST_CP_CODE     = MST_CP_CODE
        AND DST_MST_NUM     = MST_NUM
        AND DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
           EXCEPTION
       WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'EX' THEN ---'EXCESS'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DSE_DIF_MIN_QTY,0) * NVL(DSE_MIN_COST,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = DSE_CP_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'E'
             AND    MSE_LOC_CODE = ARG_LOC_CODE
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;


  IF ARG_FLAG = 'SH' THEN ---'SHORTAGE'
    BEGIN
      SELECT NVL(ROUND(SUM(DSE_VAL_AMT),0),0) * -1
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = DSE_CP_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'S'
       AND    MSE_LOC_CODE = ARG_LOC_CODE
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RP' THEN  ---'STOCK RECEIPT'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(MPB_RATE,0),2) * NVL(MPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PM_BALANCE,PPI_SM_ITEM
        WHERE  MPB_CP_CODE    = ARG_CP_CODE
        AND    MPB_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MPB_IN_TYPE    = 'ST'
               AND    MPB_LOC_CODE = ARG_LOC_CODE
        AND    MPB_CP_CODE     = MIT_CP_CODE
        AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
        AND    MIT_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RT' THEN  ---'STOCK TRANSFER'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(DPB_RATE,0),2) * NVL(DPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PD_BALANCE,PPI_SM_ITEM
        WHERE  DPB_CP_CODE    = ARG_CP_CODE
        AND    DPB_TRS_DATE   BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_OUT_TYPE   = 'ST'
               AND    DPB_LOC_CODE = ARG_LOC_CODE
        AND   DPB_CP_CODE    = MIT_CP_CODE
        AND   SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
        AND   MIT_CTG_CODE   LIKE  NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'P2' THEN  ---'PURCHASE RETURN 2'
      BEGIN
        SELECT NVL(SUM(ROUND((NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0)) * NVL(DST_RATE,0),0)),0)
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK
        WHERE  MST_CP_CODE    = ARG_CP_CODE
        AND    DST_CP_CODE    = MST_CP_CODE
        AND    DST_MST_NUM    = MST_NUM
        AND    MST_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE       = 'PR'
               AND    MST_LOC_OUT = ARG_LOC_CODE
        AND   DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'OS' THEN  ---'OPENING STOCK'
      IF ARG_DATE_FM <= '04-MAR-07' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE   = ARG_CP_CODE
          AND    MPB_DATE      = '04-MAR-07'
       AND    MPB_LOC_CODE = ARG_LOC_CODE
          AND   MPB_CP_CODE                = MIT_CP_CODE
          AND   SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND   MIT_CTG_CODE               LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSE
        IF ARG_SAL_TYPE = 'I' THEN
          BEGIN
              SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PM_BALANCE, PPI_SM_ITEM
              WHERE  MPB_CP_CODE      = ARG_CP_CODE
              AND    MPB_DATE         < ARG_DATE_FM
                     AND    MPB_LOC_CODE = ARG_LOC_CODE
              AND    MPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN  :=0;
            END;
          ELSIF ARG_SAL_TYPE = 'O' THEN
            BEGIN
              SELECT NVL(SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PD_BALANCE, PPI_SM_ITEM
              WHERE  DPB_CP_CODE  = ARG_CP_CODE
              AND    DPB_TRS_DATE < ARG_DATE_FM
                     AND    DPB_LOC_CODE = ARG_LOC_CODE
              AND    DPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN :=0;
            END;
          END IF;
      END IF;
  END IF;

  IF ARG_FLAG = 'CL' THEN  ---'CLOSING STOCK'
      IF ARG_SAL_TYPE = 'I' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE      = ARG_CP_CODE
          AND    MPB_DATE        <= ARG_DATE_TO
          AND    MPB_LOC_CODE = ARG_LOC_CODE
          AND    MPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSIF ARG_SAL_TYPE = 'O' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PD_BALANCE, PPI_SM_ITEM
          WHERE  DPB_CP_CODE   = ARG_CP_CODE
          AND    DPB_TRS_DATE <= ARG_DATE_TO
          AND    DPB_LOC_CODE = ARG_LOC_CODE
          AND    DPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN :=0;
        END;
      END IF;
  END IF;
  RETURN VAL_RETURN;
END;
/

prompt
prompt Creating function GET_ITEM_GRP_COGS
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_GRP_COGS
                          (ARG_CP_CODE  VARCHAR2,
                           ARG_BR_CODE  VARCHAR2,
                           ARG_DATE_FM  DATE,
                           ARG_DATE_TO  DATE,
                           ARG_LOC_CODE VARCHAR2,
                           ARG_CTG_CODE VARCHAR2,
                           ARG_MIT_CODE VARCHAR2,
                           ARG_SAL_TYPE VARCHAR2,
                           ARG_FLAG     VARCHAR2) RETURN NUMBER IS
  VAL_RETURN NUMBER(13, 2);
BEGIN

  IF ARG_FLAG = 'SL' THEN   ---'SALES DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_BR_CODE  = ARG_BR_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SL'
       AND    MSL_SAL_TYPE LIKE ARG_SAL_TYPE
       AND    MSL_LOC_CODE = NVL(ARG_LOC_CODE,MSL_LOC_CODE)
       AND    DSL_CP_CODE  = MSL_CP_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
       AND    DSL_MSL_NUM  = MSL_NUM
       AND    DSL_MSL_TYPE = MSL_TYPE
       AND    DSL_MSL_DATE = MSL_DATE
       AND    DSL_CP_CODE  = MIT_CP_CODE
       AND SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SR' THEN   ---'SALES RETURN DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_BR_CODE  = ARG_BR_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SR'
       AND    MSL_LOC_CODE = NVL(ARG_LOC_CODE,MSL_LOC_CODE)
       AND    DSL_CP_CODE  = MSL_CP_CODE
       AND    DSL_MSL_NUM  = MSL_NUM
       AND    DSL_MSL_TYPE = MSL_TYPE
       AND    MIT_CODE     = ARG_MIT_CODE
       AND    DSL_MSL_DATE = MSL_DATE
       AND    DSL_CP_CODE  = MIT_CP_CODE
       AND    SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SP' THEN  ---'GOOD RECEIPT NOTE'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_STOCK,PPI_TD_STOCK,PPI_SM_ITEM
      WHERE  MST_CP_CODE  = ARG_CP_CODE
      AND    MST_BR_CODE  = ARG_BR_CODE
      AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    MST_TYPE     = 'SP'
       AND    MIT_CODE     = ARG_MIT_CODE
       AND    DST_CP_CODE  = MIT_CP_CODE
       AND    SUBSTR(DST_DIT_CODE, 1, 3) = MIT_CODE
      AND    MST_LOC_IN  = NVL(ARG_LOC_CODE,MST_LOC_IN)
      AND    DST_CP_CODE     = MST_CP_CODE
      AND    DST_MST_NUM     = MST_NUM
      AND    DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'PR' THEN  ---'GOOD RECEIPT NOTE RETURN'
    BEGIN
        SELECT NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0)
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK,PPI_SM_ITEM
        WHERE  MST_CP_CODE  = ARG_CP_CODE
        AND    MST_BR_CODE  = ARG_BR_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
       AND    DST_CP_CODE  = MIT_CP_CODE
       AND    SUBSTR(DST_DIT_CODE, 1, 3) = MIT_CODE
        AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE     = 'PR'
        AND    MST_LOC_IN  = NVL(ARG_LOC_CODE,MST_LOC_IN)
        AND    DST_CP_CODE     = MST_CP_CODE
        AND DST_MST_NUM     = MST_NUM
        AND DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
           EXCEPTION
       WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'EX' THEN ---'EXCESS'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DSE_DIF_MIN_QTY,0) * NVL(DSE_MIN_COST,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_BR_CODE  = ARG_BR_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = MSE_CP_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'E'
      AND    MSE_LOC_CODE = NVL(ARG_LOC_CODE,MSE_LOC_CODE)
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;


  IF ARG_FLAG = 'SH' THEN ---'SHORTAGE'
    BEGIN
      SELECT NVL(ROUND(SUM(DSE_VAL_AMT),0),0) * -1
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_BR_CODE  = ARG_BR_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = MSE_CP_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'S'
      AND    MSE_LOC_CODE = NVL(ARG_LOC_CODE,MSE_LOC_CODE)
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RP' THEN  ---'STOCK RECEIPT'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(MPB_RATE,0),2) * NVL(MPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PM_BALANCE,PPI_SM_ITEM
        WHERE  MPB_CP_CODE    = ARG_CP_CODE
        AND    MPB_BR_CODE  = ARG_BR_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
        AND    MPB_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MPB_IN_TYPE    = 'ST'
        AND    MPB_LOC_CODE = NVL(ARG_LOC_CODE,MPB_LOC_CODE)
        AND    MPB_CP_CODE     = MIT_CP_CODE
        AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
        AND    MIT_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RT' THEN  ---'STOCK TRANSFER'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(DPB_RATE,0),2) * NVL(DPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PD_BALANCE,PPI_SM_ITEM
        WHERE  DPB_CP_CODE    = ARG_CP_CODE
        AND    DPB_BR_CODE  = ARG_BR_CODE
       AND    MIT_CODE     = ARG_MIT_CODE
        AND    DPB_TRS_DATE   BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_OUT_TYPE   = 'ST'
        AND    DPB_LOC_CODE = NVL(ARG_LOC_CODE,DPB_LOC_CODE)
        AND   DPB_CP_CODE    = MIT_CP_CODE
        AND   SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
        AND   MIT_CTG_CODE   LIKE  NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'P2' THEN  ---'PURCHASE RETURN 2'
      BEGIN
        SELECT NVL(SUM(ROUND((NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0)) * NVL(DST_RATE,0),0)),0)
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK,PPI_SM_ITEM
        WHERE  MST_CP_CODE    = ARG_CP_CODE
        AND    DST_CP_CODE    = MST_CP_CODE
        AND    MST_BR_CODE  = ARG_BR_CODE
        AND    DST_MST_NUM    = MST_NUM
       AND    MIT_CODE     = ARG_MIT_CODE
       AND    DST_CP_CODE  = MIT_CP_CODE
       AND    SUBSTR(DST_DIT_CODE, 1, 3) = MIT_CODE
        AND    MST_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE       = 'PR'
        AND    MST_LOC_OUT = NVL(ARG_LOC_CODE,MST_LOC_OUT)
        AND   DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'OS' THEN  ---'OPENING STOCK'
      IF ARG_DATE_FM <= '04-MAR-07' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE   = ARG_CP_CODE
          AND    MPB_BR_CODE  = ARG_BR_CODE
          AND    MIT_CODE     = ARG_MIT_CODE
          AND    MPB_DATE      = '04-MAR-07'
          AND    MPB_LOC_CODE = NVL(ARG_LOC_CODE,MPB_LOC_CODE)
          AND   MPB_CP_CODE                = MIT_CP_CODE
          AND   SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND   MIT_CTG_CODE               LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSE
        IF ARG_SAL_TYPE = 'I' THEN
          BEGIN
              SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PM_BALANCE, PPI_SM_ITEM
              WHERE  MPB_CP_CODE      = ARG_CP_CODE
              AND    MPB_BR_CODE  = ARG_BR_CODE
              AND    MIT_CODE     = ARG_MIT_CODE
              AND    MPB_DATE         < ARG_DATE_FM
              AND    MPB_LOC_CODE = NVL(ARG_LOC_CODE,MPB_LOC_CODE)
              AND    MPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN  :=0;
            END;
          ELSIF ARG_SAL_TYPE = 'O' THEN
            BEGIN
              SELECT NVL(SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PD_BALANCE, PPI_SM_ITEM
              WHERE  DPB_CP_CODE  = ARG_CP_CODE
              AND    DPB_BR_CODE  = ARG_BR_CODE
              AND    DPB_TRS_DATE < ARG_DATE_FM
              AND    MIT_CODE     = ARG_MIT_CODE
              AND    DPB_LOC_CODE = NVL(ARG_LOC_CODE,DPB_LOC_CODE)
              AND    DPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN :=0;
            END;
          END IF;
      END IF;
  END IF;

  IF ARG_FLAG = 'CL' THEN  ---'CLOSING STOCK'
      IF ARG_SAL_TYPE = 'I' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE      = ARG_CP_CODE
          AND    MPB_BR_CODE  = ARG_BR_CODE
          AND    MIT_CODE     = ARG_MIT_CODE
          AND    MPB_DATE        <= ARG_DATE_TO
          AND    MPB_LOC_CODE = NVL(ARG_LOC_CODE,MPB_LOC_CODE)
          AND    MPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSIF ARG_SAL_TYPE = 'O' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PD_BALANCE, PPI_SM_ITEM
          WHERE  DPB_CP_CODE   = ARG_CP_CODE
          AND    DPB_BR_CODE  = ARG_BR_CODE
          AND    MIT_CODE     = ARG_MIT_CODE
          AND    DPB_TRS_DATE <= ARG_DATE_TO
          AND    DPB_LOC_CODE = NVL(ARG_LOC_CODE,DPB_LOC_CODE)
          AND    DPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN :=0;
        END;
      END IF;
  END IF;
    DBMS_OUTPUT.PUT_LINE(ARG_FLAG||' '||TO_CHAR(SYSDATE,'HH24:MI:SS'));
  RETURN VAL_RETURN;
END;
/

prompt
prompt Creating function GET_ITEM_PRF_LOSS
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_ITEM_PRF_LOSS(ARG_CP_CODE  VARCHAR2,
                                             ARG_DATE_FM  DATE,
                                             ARG_DATE_TO  DATE,
                                             ARG_RPT_ID   VARCHAR2,
                                             ARG_CTG_CODE VARCHAR2,
                                             ARG_SAL_TYPE VARCHAR2,
                                             ARG_USR_NAME VARCHAR2,
                                             ARG_FLAG     VARCHAR2)
  RETURN NUMBER IS

  VAL_RETURN NUMBER(13, 2);
BEGIN

  IF ARG_FLAG = 'SL' THEN   ---'SALES DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SL'
       AND    MSL_SAL_TYPE LIKE ARG_SAL_TYPE
       AND    EXISTS          (SELECT 1
                               FROM   PPI_RPT_MULTIPLE_LOCATIONS
                               WHERE  RPT_CP_CODE  = ARG_CP_CODE
                               AND    RPT_ID       = ARG_RPT_ID
                               AND    RPT_USR_NAME = ARG_USR_NAME
                               AND    RPT_LOC_CODE = MSL_LOC_CODE)
       AND DSL_CP_CODE  = MSL_CP_CODE
       AND DSL_MSL_NUM  = MSL_NUM
       AND DSL_MSL_TYPE = MSL_TYPE
       AND DSL_MSL_DATE = MSL_DATE
       AND DSL_CP_CODE  = MIT_CP_CODE
       AND SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SR' THEN   ---'SALES RETURN DOCUMENT'
    BEGIN
       SELECT NVL(SUM(ROUND(NVL(DSL_MIN_QTY,0) * NVL(DSL_MIN_RATE,0),0)),0)
       INTO   VAL_RETURN
       FROM   HOS_TM_SALES,HOS_TD_SALES,PPI_SM_ITEM
       WHERE  MSL_CP_CODE  =  ARG_CP_CODE
       AND    MSL_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
       AND    MSL_TRN_TYPE = 'SR'
       AND    EXISTS      (SELECT 1
                           FROM   PPI_RPT_MULTIPLE_LOCATIONS
                           WHERE  RPT_CP_CODE  = ARG_CP_CODE
                           AND    RPT_ID       = ARG_RPT_ID
                           AND    RPT_USR_NAME = ARG_USR_NAME
                           AND    RPT_LOC_CODE = MSL_LOC_CODE)
       AND DSL_CP_CODE  = MSL_CP_CODE
       AND DSL_MSL_NUM  = MSL_NUM
       AND DSL_MSL_TYPE = MSL_TYPE
       AND DSL_MSL_DATE = MSL_DATE
       AND DSL_CP_CODE  = MIT_CP_CODE
       AND SUBSTR(DSL_DIT_CODE, 1, 3) = MIT_CODE
       AND MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'SP' THEN  ---'GOOD RECEIPT NOTE'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_STOCK,PPI_TD_STOCK
      WHERE  MST_CP_CODE  = ARG_CP_CODE
      AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    MST_TYPE     = 'SP'
      AND    EXISTS       (SELECT 1
                           FROM   PPI_RPT_MULTIPLE_LOCATIONS
                           WHERE  RPT_CP_CODE  = ARG_CP_CODE
                           AND    RPT_ID       = ARG_RPT_ID
                           AND    RPT_USR_NAME = ARG_USR_NAME
                           AND    RPT_LOC_CODE = MST_LOC_IN)
      AND DST_CP_CODE     = MST_CP_CODE
      AND DST_MST_NUM     = MST_NUM
      AND DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        VAL_RETURN := 0;
    END;
  END IF;

  IF ARG_FLAG = 'PR' THEN  ---'GOOD RECEIPT NOTE RETURN'
    BEGIN
        SELECT SUM(NVL(NVL(DST_QTY,0) * NVL(DST_RATE,0),0))--NVL(SUM(ROUND(NVL(DST_NET_AMT,0) + NVL(DST_SAL_TAX,0) + NVL(DST_SRV_CHARGES,0),0)),0) GM 23052025
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK
        WHERE  MST_CP_CODE  = ARG_CP_CODE
        AND    DST_CP_CODE     = MST_CP_CODE
        AND    DST_MST_NUM     = MST_NUM
        AND    MST_DATE     BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE     = 'PR'
        AND    EXISTS       (SELECT 1
                             FROM   PPI_RPT_MULTIPLE_LOCATIONS
                             WHERE  RPT_CP_CODE  = ARG_CP_CODE
                             AND    RPT_ID       = ARG_RPT_ID
                             AND    RPT_USR_NAME = ARG_USR_NAME
                            AND     RPT_LOC_CODE = MST_LOC_OUT)-- AND    RPT_LOC_CODE = MST_LOC_IN) -- GM 23052025
        AND DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
           EXCEPTION
       WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'EX' THEN ---'EXCESS'
    BEGIN
      SELECT NVL(SUM(ROUND(NVL(DSE_DIF_MIN_QTY,0) * NVL(DSE_MIN_COST,0),0)),0)
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = DSE_CP_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'E'
      AND    EXISTS        (SELECT 1
                            FROM   PPI_RPT_MULTIPLE_LOCATIONS
                            WHERE  RPT_CP_CODE  = ARG_CP_CODE
                            AND    RPT_ID       = ARG_RPT_ID
                            AND    RPT_USR_NAME = ARG_USR_NAME
                            AND    RPT_LOC_CODE = MSE_LOC_CODE)
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;


  IF ARG_FLAG = 'SH' THEN ---'SHORTAGE'
    BEGIN
      SELECT NVL(ROUND(SUM(DSE_VAL_AMT),0) * -1,0)
      INTO   VAL_RETURN
      FROM   PPI_TM_SHT_EXC,PPI_TD_SHT_EXC,PPI_SM_ITEM
      WHERE  MSE_CP_CODE   = ARG_CP_CODE
      AND    MSE_DATE      BETWEEN ARG_DATE_FM AND ARG_DATE_TO
      AND    DSE_CP_CODE   = DSE_CP_CODE
      AND    DSE_MSE_NUM   = MSE_NUM
      AND    DSE_MSE_DATE  = MSE_DATE
      AND    DSE_TYPE      = 'S'
      AND    EXISTS        (SELECT 1
                            FROM   PPI_RPT_MULTIPLE_LOCATIONS
                            WHERE  RPT_CP_CODE  = ARG_CP_CODE
                            AND    RPT_ID       = ARG_RPT_ID
                            AND    RPT_USR_NAME = ARG_USR_NAME
                            AND    RPT_LOC_CODE = MSE_LOC_CODE)
      AND    DSE_CP_CODE   = MIT_CP_CODE
      AND    SUBSTR(DSE_DIT_CODE, 1, 3) = MIT_CODE
      AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
          VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RP' THEN  ---'STOCK RECEIPT'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(MPB_RATE,0),2) * NVL(MPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PM_BALANCE,PPI_SM_ITEM
        WHERE  MPB_CP_CODE    = ARG_CP_CODE
        AND    MPB_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MPB_IN_TYPE    = 'ST'
        AND    EXISTS         (SELECT 1
                              FROM   PPI_RPT_MULTIPLE_LOCATIONS
                              WHERE  RPT_CP_CODE  = ARG_CP_CODE
                              AND    RPT_ID       = ARG_RPT_ID
                              AND    RPT_USR_NAME = ARG_USR_NAME
                              AND    RPT_LOC_CODE = MPB_LOC_CODE)
        AND    MPB_CP_CODE     = MIT_CP_CODE
        AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
        AND    MIT_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'RT' THEN  ---'STOCK TRANSFER'
      BEGIN
        SELECT NVL(ROUND(SUM(ROUND(NVL(DPB_RATE,0),2) * NVL(DPB_QTY,0)),0),0)
        INTO   VAL_RETURN
        FROM   PPI_PD_BALANCE,PPI_SM_ITEM
        WHERE  DPB_CP_CODE    = ARG_CP_CODE
        AND    DPB_TRS_DATE   BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    DPB_OUT_TYPE   = 'ST'
        AND    EXISTS        (SELECT 1
                              FROM   PPI_RPT_MULTIPLE_LOCATIONS
                              WHERE  RPT_CP_CODE  = ARG_CP_CODE
                              AND    RPT_ID       = ARG_RPT_ID
                              AND    RPT_USR_NAME = ARG_USR_NAME
                              AND    RPT_LOC_CODE = DPB_LOC_CODE)
        AND   DPB_CP_CODE    = MIT_CP_CODE
        AND   SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
        AND   MIT_CTG_CODE   LIKE  NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'P2' THEN  ---'PURCHASE RETURN 2'
      BEGIN
        SELECT NVL(SUM(ROUND((NVL(DST_QTY,0) + NVL(DST_BNS_MIN_QTY,0)) * NVL(DST_RATE,0),0)),0)
        INTO   VAL_RETURN
        FROM   PPI_TM_STOCK,PPI_TD_STOCK
        WHERE  MST_CP_CODE    = ARG_CP_CODE
        AND    DST_CP_CODE    = MST_CP_CODE
        AND    DST_MST_NUM    = MST_NUM
        AND    MST_DATE       BETWEEN ARG_DATE_FM AND ARG_DATE_TO
        AND    MST_TYPE       = 'PR'
        AND    EXISTS        (SELECT 1
                              FROM   PPI_RPT_MULTIPLE_LOCATIONS
                              WHERE  RPT_CP_CODE  = ARG_CP_CODE
                              AND    RPT_ID       = ARG_RPT_ID
                              AND    RPT_USR_NAME = ARG_USR_NAME
                              AND    RPT_LOC_CODE = MST_LOC_OUT)
        AND   DST_CTG_CODE    LIKE NVL(ARG_CTG_CODE,'%');
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             VAL_RETURN := 0;
      END;
  END IF;

  IF ARG_FLAG = 'OS' THEN  ---'OPENING STOCK'
      IF ARG_DATE_FM <= '04-MAR-07' THEN
        BEGIN
          SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE   = ARG_CP_CODE
          AND    MPB_DATE      = '04-MAR-07'
          AND    EXISTS        (SELECT 1
                                FROM   PPI_RPT_MULTIPLE_LOCATIONS
                                WHERE  RPT_CP_CODE  = ARG_CP_CODE
                                AND    RPT_ID       = ARG_RPT_ID
                                AND    RPT_USR_NAME = ARG_USR_NAME
                                AND    RPT_LOC_CODE = MPB_LOC_CODE)
          AND   MPB_CP_CODE                = MIT_CP_CODE
          AND   SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND   MIT_CTG_CODE               LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSE
        IF ARG_SAL_TYPE = 'I' THEN
          BEGIN
              SELECT NVL(SUM(ROUND(NVL(MPB_QTY,0) * NVL(MPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PM_BALANCE, PPI_SM_ITEM
              WHERE  MPB_CP_CODE      = ARG_CP_CODE
              AND    MPB_DATE         < ARG_DATE_FM
              AND    EXISTS          (SELECT 1
                                      FROM PPI_RPT_MULTIPLE_LOCATIONS
                                      WHERE RPT_CP_CODE  = ARG_CP_CODE
                                      AND   RPT_ID       = ARG_RPT_ID
                                      AND   RPT_USR_NAME = ARG_USR_NAME
                                      AND   RPT_LOC_CODE = MPB_LOC_CODE)
              AND    MPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN  :=0;
            END;
          ELSIF ARG_SAL_TYPE = 'O' THEN
            BEGIN
              SELECT NVL(SUM(ROUND(NVL(DPB_QTY,0) * NVL(DPB_RATE,0),4)),0)
              INTO   VAL_RETURN
              FROM   PPI_PD_BALANCE, PPI_SM_ITEM
              WHERE  DPB_CP_CODE  = ARG_CP_CODE
              AND    DPB_TRS_DATE < ARG_DATE_FM
              AND    EXISTS          (SELECT 1
                                      FROM PPI_RPT_MULTIPLE_LOCATIONS
                                      WHERE RPT_CP_CODE  = ARG_CP_CODE
                                      AND   RPT_ID       = ARG_RPT_ID
                                      AND   RPT_USR_NAME = ARG_USR_NAME
                                      AND   RPT_LOC_CODE = DPB_LOC_CODE)
              AND    DPB_CP_CODE      = MIT_CP_CODE
              AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
              AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
            EXCEPTION
              WHEN NO_DATA_FOUND THEN
              VAL_RETURN :=0;
            END;
          END IF;
      END IF;
  END IF;

  IF ARG_FLAG = 'CL' THEN  ---'CLOSING STOCK'
      IF ARG_SAL_TYPE = 'I' THEN
        BEGIN
          SELECT SUM(ROUND(MPB_QTY * MPB_RATE,4))
          INTO   VAL_RETURN
          FROM   PPI_PM_BALANCE, PPI_SM_ITEM
          WHERE  MPB_CP_CODE      = ARG_CP_CODE
          AND    MPB_DATE        <= ARG_DATE_TO
          AND    EXISTS          (SELECT 1
                                  FROM PPI_RPT_MULTIPLE_LOCATIONS
                                  WHERE RPT_CP_CODE  = ARG_CP_CODE
                                  AND   RPT_ID       = ARG_RPT_ID
                                  AND   RPT_USR_NAME = ARG_USR_NAME
                                  AND   RPT_LOC_CODE = MPB_LOC_CODE)
          AND    MPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(MPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE     LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN  :=0;
        END;
      ELSIF ARG_SAL_TYPE = 'O' THEN
        BEGIN
          SELECT SUM(ROUND(DPB_QTY * DPB_RATE,4))
          INTO   VAL_RETURN
          FROM   PPI_PD_BALANCE, PPI_SM_ITEM
          WHERE  DPB_CP_CODE   = ARG_CP_CODE
          AND    DPB_TRS_DATE <= ARG_DATE_TO
          AND    EXISTS          (SELECT 1
                                  FROM PPI_RPT_MULTIPLE_LOCATIONS
                                  WHERE RPT_CP_CODE  = ARG_CP_CODE
                                  AND   RPT_ID       = ARG_RPT_ID
                                  AND   RPT_USR_NAME = ARG_USR_NAME
                                  AND   RPT_LOC_CODE = DPB_LOC_CODE)
          AND    DPB_CP_CODE      = MIT_CP_CODE
          AND    SUBSTR(DPB_DIT_CODE, 1, 3) = MIT_CODE
          AND    MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          VAL_RETURN :=0;
        END;
      END IF;
  END IF;
  RETURN VAL_RETURN;
END;
/

