prompt Creating function GET_MPA_BRANCH
prompt ================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_MPA_BRANCH" (ARG_CP_CODE VARCHAR2, ARG_MPA_CODE VARCHAR2, ARG_BR_CODE VARCHAR2) RETURN VARCHAR2 IS
  LC_BR_CODE VARCHAR2(3);
BEGIN
  IF ARG_MPA_CODE IS NULL THEN
    RETURN ARG_BR_CODE;
  ELSE
    BEGIN
      SELECT MPA_BR_CODE
      INTO   LC_BR_CODE
      FROM   HOS_SM_PANEL
      WHERE  MPA_CP_CODE = ARG_CP_CODE
      AND    MPA_CODE    = ARG_MPA_CODE

      AND    MPA_BR_CODE IN (ARG_BR_CODE,'-')
      AND    MPA_TYPE <> 'W';
    EXCEPTION WHEN NO_DATA_FOUND THEN
      LC_BR_CODE  := NULL;
    END;

  END IF;

  RETURN LC_BR_CODE;

END;
/

