prompt Creating function GET_OPD_SRV_CURRENT_RATES
prompt ===========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_OPD_SRV_CURRENT_RATES" (ARG_CP_CODE VARCHAR2,
          ARG_MSR_TYPE VARCHAR2,
          ARG_OTH_COMP_CODE VARCHAR2,
          ARG_MPA_CODE VARCHAR2,
          ARG_WARD_CODE VARCHAR2,
          ARG_DSC_CODE VARCHAR2,
          ARG_DSC_TYPE VARCHAR2,
          ARG_DATE DATE,
          ARG_MCT_CODE VARCHAR2 DEFAULT NULL) RETURN NUMBER IS
  LC_RATE NUMBER(13,2) := NULL;
  LC_OPD_PCT   NUMBER;
  LC_IPD_PCT   NUMBER;
  LC_PKG_PCT   NUMBER;

  LC_COMP_CODE VARCHAR2(15);
  LC_DISC_TYPE HOS_SO_COMP_DISC_INFO.CDI_DISC_TYPE%TYPE;
BEGIN
  IF ARG_MSR_TYPE = 'R' OR ARG_OTH_COMP_CODE IS NOT NULL THEN

    IF ARG_OTH_COMP_CODE IS NOT NULL AND ARG_MSR_TYPE = 'C' THEN
        LC_COMP_CODE := ARG_OTH_COMP_CODE;
    ELSE
        LC_COMP_CODE := ARG_MPA_CODE;
    END IF;

    BEGIN
        SELECT DPH_RATE

        INTO   LC_RATE
        FROM   HOS_SD_PANEL_RATES_HLS A, HOS_SD_PANEL_RATES C
        WHERE  A.DPH_CP_CODE      = ARG_CP_CODE
        AND    A.DPH_DPA_MPA_CODE = LC_COMP_CODE
        AND    A.DPH_DPA_WARD_CODE = ARG_WARD_CODE
        AND    A.DPH_DSC_CODE     = ARG_DSC_CODE
        AND    C.DPA_CP_CODE      = A.DPH_CP_CODE
        AND    C.DPA_MPA_CODE     = A.DPH_DPA_MPA_CODE
        AND    C.DPA_WARD_CODE     = A.DPH_DPA_WARD_CODE
        AND    C.DPA_DATE_FM      = A.DPH_DPA_DATE_FM
        AND     A.DPH_MCT_CODE = NVL(ARG_MCT_CODE, '-')
        AND     NVL(C.DPA_ACTIVE,'N') = 'Y'
        AND    A.DPH_DPA_DATE_FM  = (SELECT MAX(B.DPH_DPA_DATE_FM)
                                     FROM   HOS_SD_PANEL_RATES_HLS B

                                     WHERE  B.DPH_CP_CODE      = A.DPH_CP_CODE
                                     AND    B.DPH_DPA_MPA_CODE = A.DPH_DPA_MPA_CODE
                                     AND    B.DPH_DPA_WARD_CODE = A.DPH_DPA_WARD_CODE
                                     AND    B.DPH_DSC_CODE      = A.DPH_DSC_CODE
                                     AND    B.DPH_DPA_DATE_FM <= ARG_DATE);
    EXCEPTION WHEN NO_DATA_FOUND THEN
        LC_RATE := 0;
        BEGIN
         SELECT NVL(A.CDI_OPD_PCT,0), NVL(A.CDI_DISC_TYPE,0)
         INTO   LC_OPD_PCT,  LC_DISC_TYPE
         FROM   HOS_SO_COMP_DISC_INFO A
         WHERE  A.CDI_CP_CODE   =   ARG_CP_CODE
         AND    A.CDI_MPA_CODE  =   LC_COMP_CODE

         AND    A.CDI_ACTIVE    =   'Y'
         AND    A.CDI_EFF_DATE  = (SELECT MAX(B.CDI_EFF_DATE)
                                   FROM   HOS_SO_COMP_DISC_INFO B
                                   WHERE  B.CDI_CP_CODE   = A.CDI_CP_CODE
                                   AND    B.CDI_MPA_CODE  = A.CDI_MPA_CODE
                                   AND    B.CDI_EFF_DATE <= ARG_DATE
                                   AND    B.CDI_ACTIVE    = 'Y');
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
          LC_OPD_PCT := 0;
          LC_IPD_PCT := 0;
          LC_PKG_PCT := 0;
        END;

    END;
  END IF;
  IF LC_DISC_TYPE = 'D' THEN
    LC_OPD_PCT := -1*LC_OPD_PCT;
  END IF;

  IF (ARG_MSR_TYPE = 'C' AND ARG_OTH_COMP_CODE IS NULL) OR NVL(LC_RATE, 0) = 0 THEN
    BEGIN
        SELECT DPH_RATE
        INTO  LC_RATE
        FROM   HOS_SD_PANEL_RATES_HLS A, HOS_SD_PANEL_RATES C
        WHERE  A.DPH_CP_CODE      = ARG_CP_CODE
        AND    A.DPH_DPA_MPA_CODE = ARG_WARD_CODE

        AND    A.DPH_DPA_WARD_CODE = ARG_WARD_CODE
        AND    A.DPH_DSC_CODE     = ARG_DSC_CODE
        AND    C.DPA_CP_CODE      = A.DPH_CP_CODE
        AND    C.DPA_MPA_CODE     = A.DPH_DPA_MPA_CODE
        AND    C.DPA_WARD_CODE     = A.DPH_DPA_WARD_CODE
        AND    C.DPA_DATE_FM      = A.DPH_DPA_DATE_FM
        AND     A.DPH_MCT_CODE = NVL(ARG_MCT_CODE, '-')
        AND     NVL(C.DPA_ACTIVE,'N') = 'Y'
        AND    A.DPH_DPA_DATE_FM  = (SELECT MAX(B.DPH_DPA_DATE_FM)
                                     FROM   HOS_SD_PANEL_RATES_HLS B
                                     WHERE  B.DPH_CP_CODE      = A.DPH_CP_CODE
                                     AND    B.DPH_DPA_MPA_CODE = A.DPH_DPA_MPA_CODE
                                     AND    B.DPH_DPA_WARD_CODE = A.DPH_DPA_WARD_CODE
                                     AND    B.DPH_DSC_CODE      = A.DPH_DSC_CODE

                                     AND    B.DPH_DPA_DATE_FM <= ARG_DATE);
    EXCEPTION WHEN NO_DATA_FOUND THEN
      BEGIN
          SELECT  DECODE(ARG_DSC_TYPE,'PH',NVL(DSR_HR_RATE,0),'PD',NVL(DSR_DAY_RATE,0),
                  'PU',NVL(DSR_UNIT_RATE,0))
          INTO  LC_RATE
          FROM   HOS_SD_SRV_CHARGES_RATES A
          WHERE  A.DSR_CP_CODE  = ARG_CP_CODE
          AND    A.DSR_DSC_CODE = ARG_DSC_CODE
          AND    A.DSR_EFF_DATE = (SELECT MAX(B.DSR_EFF_DATE)
                                    FROM   HOS_SD_SRV_CHARGES_RATES B
                                    WHERE  B.DSR_CP_CODE   = A.DSR_CP_CODE
                                    AND    B.DSR_DSC_CODE  = A.DSR_DSC_CODE

                                    AND    B.DSR_EFF_DATE <= ARG_DATE);
      EXCEPTION WHEN NO_DATA_FOUND THEN
          LC_RATE := 0;
      END;
    END;
  END IF;
  IF ARG_MSR_TYPE <> 'C' AND ABS(LC_RATE) > 0 THEN
     IF LC_OPD_PCT < 0 THEN
      LC_RATE := ROUND(NVL(LC_RATE,0)-((NVL(LC_RATE,0)*ABS(NVL(LC_OPD_PCT,0)))/100),0);
     ELSE
      LC_RATE := ROUND(NVL(LC_RATE,0)+((NVL(LC_RATE,0)*NVL(LC_OPD_PCT,0))/100),0);
     END IF;
  END IF;

  RETURN LC_RATE;
END;
/

