prompt Creating function GET_REQ_BAL_QTY
prompt =================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_REQ_BAL_QTY(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_DIT_CODE VARCHAR2) RETURN NUMBER IS
  LC_REQ_QTY NUMBER;
  LC_TRS_QTY NUMBER;
BEGIN
  SELECT NVL(SUM(NVL(DOT_APR_QTY,0)),0)
  INTO   LC_REQ_QTY
  FROM   PPI_TM_ORD_TRNS,PPI_TD_ORD_TRNS
  WHERE  MOT_CP_CODE = DOT_CP_CODE
  AND    MOT_NUM     = DOT_MOT_NUM
  AND    DOT_CP_CODE = ARG_CP_CODE
  AND    DOT_MOT_NUM = ARG_DOC_NUM
  AND    DOT_DIT_CODE = ARG_DIT_CODE;
  SELECT NVL(SUM(NVL(DST_QTY,0)),0)
  INTO   LC_TRS_QTY
  FROM   PPI_TM_STOCK,PPI_TD_STOCK
  WHERE  MST_CP_CODE = DST_CP_CODE
  AND    MST_NUM     = DST_MST_NUM
  AND    MST_CP_CODE = ARG_CP_CODE
  AND    MST_REF_NUM = ARG_DOC_NUM
  AND    DST_DIT_CODE = ARG_DIT_CODE;
  RETURN LC_REQ_QTY - LC_TRS_QTY;
END;
/

