prompt Creating function GET_SALES_TERM_ID
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_SALES_TERM_ID(ARG_DOC_NUM VARCHAR2) RETURN VARCHAR2 IS
      LC_TERM_ID VARCHAR2(1000);
      LC_MAX_DATE VARCHAR2(30);

BEGIN
      SELECT    MAX(TO_CHAR(A.AUD_DATE,'YYYYMMDD') || A.AUD_TIME)
      INTO      LC_MAX_DATE
      FROM      AKHSYS_AUD.HOS_TM_SALES_AUD A
      WHERE     A.MSL_NUM = ARG_DOC_NUM
      AND       A.AUD_ACTION IN ('I','U');

      SELECT    A.AUD_TERMINAL
      INTO     LC_TERM_ID
      FROM      AKHSYS_AUD.HOS_TM_SALES_AUD A
      WHERE     A.MSL_NUM = ARG_DOC_NUM
      AND       A.AUD_ACTION IN ('I','U')
      AND       TO_CHAR(A.AUD_DATE,'YYYYMMDD') || A.AUD_TIME = LC_MAX_DATE;

      RETURN LC_TERM_ID;
END;
/

prompt
prompt Creating function GET_SALE_QTY
prompt ==============================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_SALE_QTY(ARG_CP_CODE VARCHAR2, ARG_MSO_NUM VARCHAR2, ARG_DIT_CODE VARCHAR2,ARG_MPT_ID VARCHAR2) RETURN NUMBER IS
 LC_DEL_QTY    NUMBER(13,2);
 LC_BAL_QTY    NUMBER(13,2);
 LC_RET_QTY    NUMBER(13,2);
BEGIN
  ---------------------------------------- Sales aganist order
  SELECT NVL(SUM(NVL(DSL_MIN_QTY,0)),0)
  INTO   LC_DEL_QTY
  FROM   HOS_TM_SALES , HOS_TD_SALES
  WHERE  MSL_CP_CODE  = DSL_CP_CODE
  AND    MSL_NUM      = DSL_MSL_NUM
  AND    MSL_MSO_NUM  IS NOT NULL
  AND    MSL_TYPE     = 'I'
  AND    MSL_CP_CODE  = ARG_CP_CODE
  AND    MSL_MSO_NUM  = ARG_MSO_NUM
  AND    DSL_DIT_CODE = ARG_DIT_CODE
  AND    MSL_PAT_ID   = ARG_MPT_ID;

  ---------------------------------------- Sales Refund aganist order
  SELECT NVL(SUM(NVL(DSL_MIN_QTY,0)),0)
  INTO   LC_RET_QTY
  FROM   HOS_TM_SALES , HOS_TD_SALES
  WHERE  MSL_CP_CODE  = DSL_CP_CODE
  AND    MSL_NUM      = DSL_MSL_NUM
  AND    MSL_MSO_NUM IS NOT NULL
  AND    MSL_TYPE         = 'R'
  AND    MSL_CP_CODE      = ARG_CP_CODE
  AND    DSL_MSL_MSO_NUM  = ARG_MSO_NUM
  AND    DSL_DIT_CODE     = ARG_DIT_CODE
  AND    MSL_PAT_ID       = ARG_MPT_ID;

  LC_BAL_QTY := LC_DEL_QTY- LC_RET_QTY;

 RETURN LC_BAL_QTY;
END;
/

prompt
prompt Creating function GET_SERVICE_GROUP_VALIDATE
prompt ============================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_SERVICE_GROUP_VALIDATE(ARG_CP_CODE VARCHAR2,ARG_DSC_CODE VARCHAR2,ARG_PDG_RPT_ID VARCHAR2,ARG_SEQ_NUM NUMBER,ARG_RCT_NUM VARCHAR2 DEFAULT NULL)RETURN VARCHAR2 IS
  CURSOR CRS1 IS
         SELECT DISTINCT LTG_SRV_CODE , LTG_GROUP , LTG_NUM
         FROM   LAB_TD_SRV_DIAG,LAB_SD_LT_GROUP
         WHERE  LTG_CP_CODE  = DSD_CP_CODE
         AND    LTG_SRV_CODE = DSD_DSC_CODE
         AND    DSD_CP_CODE  = ARG_CP_CODE
         AND    DSD_SEQ_NUM  = ARG_SEQ_NUM
         AND    DSD_RCT_NUM  = NVL(ARG_RCT_NUM,DSD_RCT_NUM)
         AND    DSD_RPT_ID   = ARG_PDG_RPT_ID
         AND   (LTG_NUM IS NOT NULL
         AND    LTG_GROUP IS NOT NULL)
         AND    DSD_DSC_CODE = ARG_DSC_CODE;

  CURSOR CRS2(LC_DSC_CODE VARCHAR2, LC_GROUP VARCHAR2) IS
         SELECT PDG_RPT_ID  , PDG_DSC_CODE , PDG_LTP_GROUP , NVL(SUM(PDG_TST_RES),0) "PDG_TST_RES"
         FROM   LAB_TD_PMT_DIAG
         WHERE  PDG_CP_CODE   = ARG_CP_CODE
         AND    PDG_DSC_CODE  = LC_DSC_CODE
         AND    PDG_RPT_ID    = ARG_PDG_RPT_ID
         AND    PDG_RCT_NUM   = NVL(ARG_RCT_NUM,PDG_RCT_NUM)
         AND    PDG_LTP_GROUP IS NOT NULL
         AND    PDG_LTP_GROUP = LC_GROUP
         GROUP BY PDG_RPT_ID,PDG_DSC_CODE,PDG_LTP_GROUP;
  LC_FLAG VARCHAR2(1) := 'T';
BEGIN
  FOR REC1 IN CRS1 LOOP
      FOR REC2 IN CRS2(REC1.LTG_SRV_CODE,REC1.LTG_GROUP) LOOP
          IF REC2.PDG_TST_RES <> REC1.LTG_NUM THEN
             LC_FLAG  := 'F';
             RETURN LC_FLAG;
          END IF;
      END LOOP;
  END LOOP;
  RETURN LC_FLAG;
EXCEPTION
  WHEN OTHERS THEN
       RETURN LC_FLAG;
       DBMS_OUTPUT.PUT_LINE(SQLERRM || ' ' || SQLCODE);
END;
/

