prompt Creating function GET_SORDER_BAL_QTY
prompt ====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_SORDER_BAL_QTY" (ARG_CP_CODE VARCHAR2, ARG_MSO_NUM VARCHAR2, ARG_DIT_CODE VARCHAR2,ARG_MPT_ID VARCHAR2) RETURN NUMBER IS
 LC_SORDER_QTY NUMBER(13,2);
 LC_DEL_QTY    NUMBER(13,2);
 LC_BAL_QTY    NUMBER(13,2);
 LC_RET_QTY    NUMBER(13,2);
BEGIN
  ---------------------------------------- Order
  SELECT NVL(SUM(NVL(DSO_QTY,0)),0)
  INTO   LC_SORDER_QTY
  FROM   HOS_TM_SORDER, HOS_TD_SORDER
  WHERE  MSO_NUM      = DSO_MSO_NUM
  AND    MSO_CP_CODE  = DSO_CP_CODE
  AND    MSO_CP_CODE  = ARG_CP_CODE
  AND    MSO_NUM      = ARG_MSO_NUM
  AND    DSO_DIT_CODE = ARG_DIT_CODE
  AND    MSO_MPT_ID   = ARG_MPT_ID;

  ---------------------------------------- Sales aganist order
  SELECT NVL(SUM(NVL(DSL_MIN_QTY,0)),0)
  INTO   LC_DEL_QTY
  FROM   HOS_TM_SALES , HOS_TD_SALES
  WHERE  MSL_CP_CODE  = DSL_CP_CODE
  AND    MSL_NUM      = DSL_MSL_NUM
  AND    MSL_MSO_NUM IS NOT NULL
  AND    MSL_TYPE     = 'I'
  AND    MSL_CP_CODE  = ARG_CP_CODE
  AND    MSL_MSO_NUM  = ARG_MSO_NUM
  AND    DSL_DIT_CODE = ARG_DIT_CODE
  AND    MSL_PAT_ID   = ARG_MPT_ID;

  ---------------------------------------- Sales Refund aganist order
  SELECT NVL(SUM(NVL(DSL_MIN_QTY,0)),0)
  INTO   LC_RET_QTY
  FROM   HOS_TM_SALES , HOS_TD_SALES
  WHERE  MSL_CP_CODE  = DSL_CP_CODE
  AND    MSL_NUM      = DSL_MSL_NUM
  AND    MSL_MSO_NUM IS NOT NULL
  AND    MSL_TYPE         = 'R'
  AND    MSL_CP_CODE      = ARG_CP_CODE
  AND    DSL_MSL_MSO_NUM  = ARG_MSO_NUM
  AND    DSL_DIT_CODE     = ARG_DIT_CODE
  AND    MSL_PAT_ID       = ARG_MPT_ID;

  LC_BAL_QTY := LC_SORDER_QTY - LC_DEL_QTY;
  LC_BAL_QTY := LC_BAL_QTY + LC_RET_QTY;

 RETURN LC_BAL_QTY;
END;
/

