prompt Creating function GET_TRAN_CR_LIMIT
prompt ===================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.GET_TRAN_CR_LIMIT(ARG_CP_CODE  VARCHAR2 ,ARG_BR_CODE  VARCHAR2, ARG_MPA_CODE VARCHAR2 , ARG_DATE DATE , ARG_STATUS VARCHAR2) RETURN VARCHAR2 IS

  LC_FLAG             VARCHAR2(1);
  LC_MPA_BR_CODE      VARCHAR2(3);
  LC_MPA_MON_LIMIT    NUMBER;
  LC_MPA_LOCK_CRE_LIM VARCHAR2(1);
  LC_MPA_REC_COA3     VARCHAR2(10);
  LC_COA_CURR_BAL     NUMBER;
BEGIN

        BEGIN
          SELECT NVL(MPA_BR_CODE, '-'),NVL(MPA_MON_LIMIT, 0), NVL(MPA_LOCK_CRE_LIM, 'N'),NVL(MPA_REC_COA3, '-')
            INTO LC_MPA_BR_CODE,LC_MPA_MON_LIMIT,LC_MPA_LOCK_CRE_LIM,LC_MPA_REC_COA3
            FROM HOS_SM_PANEL
           WHERE MPA_CP_CODE = ARG_CP_CODE
             AND MPA_BR_CODE = ARG_BR_CODE
             AND MPA_CODE = ARG_MPA_CODE;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            LC_MPA_BR_CODE      := '-';
            LC_MPA_MON_LIMIT    := 0;
            LC_MPA_LOCK_CRE_LIM := 'N';
            LC_MPA_REC_COA3     := '-';
        END;

  IF LC_MPA_BR_CODE <> '-' AND LC_MPA_MON_LIMIT <> 0 AND LC_MPA_LOCK_CRE_LIM <> 'N' AND LC_MPA_REC_COA3 <> '-' THEN
     LC_COA_CURR_BAL := GET_COA_CURR_BAL(ARG_CP_CODE,LC_MPA_BR_CODE,LC_MPA_REC_COA3,ARG_DATE,'P');

            IF LC_MPA_MON_LIMIT < NVL(LC_COA_CURR_BAL, 0) THEN
              LC_FLAG := 'F';
            ELSE
              LC_FLAG := 'T';
            END IF;

  ELSE

    LC_FLAG := 'T';

  END IF;

RETURN   LC_FLAG;

EXCEPTION
  WHEN OTHERS THEN
     LC_FLAG := 'F';
END;
/

