prompt Creating function GET_VALIDATE_SHT_EXC
prompt ======================================
prompt
create or replace function mdhsys.GET_VALIDATE_SHT_EXC(ARG_CP_CODE VARCHAR2, ARG_LOC_IN VARCHAR2, ARG_LOC_OUT VARCHAR2)
RETURN VARCHAR2 IS
CHK NUMBER := 0;
begin
    BEGIN
        SELECT   COUNT(*) INTO CHK
        FROM     PPI_TM_SHT_EXC
        WHERE    MSE_CP_CODE = ARG_CP_CODE
        AND      MSE_LOC_CODE IN (ARG_LOC_IN , ARG_LOC_OUT)
        AND      NVL(MSE_STATUS,'U') = 'U';
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
        CHK := 0;
      END;
  return(CHK);
end ;
/

