prompt Creating function HRS_CALCULATION
prompt =================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."HRS_CALCULATION" (ARG_FM_DATE DATE, ARG_FM_TIME VARCHAR2,
   ARG_TO_DATE DATE, ARG_TO_TIME VARCHAR2) RETURN NUMBER IS
  LC_FM_DATE DATE := NVL(ARG_FM_DATE, TRUNC(SYSDATE));
  LC_TO_DATE DATE := NVL(ARG_TO_DATE, TRUNC(SYSDATE));
  VAL_RETURN NUMBER(13,2);
BEGIN
 LC_FM_DATE := TO_DATE((TO_CHAR(LC_FM_DATE,'DD/MM/YYYY')||ARG_FM_TIME), 'DD/MM/YYYYHH24MI');
 LC_TO_DATE := TO_DATE((TO_CHAR(LC_TO_DATE,'DD/MM/YYYY')||ARG_TO_TIME), 'DD/MM/YYYYHH24MI');
 VAL_RETURN := (LC_TO_DATE - LC_FM_DATE)*24;
 RETURN ABS(VAL_RETURN);
EXCEPTION WHEN OTHERS THEN
 RETURN 0;
END;
/

