prompt Creating function GET_WAGE_DTY_HRS
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."GET_WAGE_DTY_HRS"(IN_TIME  in VARCHAR2,
                                              OUT_TIME in VARCHAR2)

 return NUMBER is
  DUTY_HOURS   NUMBER(13, 2);
  IN_TIME_NUM  VARCHAR2(4);
  OUT_TIME_NUM VARCHAR2(4);
BEGIN
  IN_TIME_NUM  := SUBSTR(IN_TIME, 1, 2);
  OUT_TIME_NUM := SUBSTR(OUT_TIME, 1, 2);
  IF IN_TIME_NUM < OUT_TIME_NUM THEN
    DUTY_HOURS := HRS_CALCULATION('', IN_TIME, '', OUT_TIME);
  ELSIF IN_TIME_NUM >= OUT_TIME_NUM THEN
    DUTY_HOURS := HRS_CALCULATION('', IN_TIME, TRUNC(SYSDATE) + 1, OUT_TIME);
  END IF;

  RETURN DUTY_HOURS;
END;
/

