prompt Creating function IS_DE_VCH_EXISTS_DB
prompt =====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."IS_DE_VCH_EXISTS_DB"
(ARG_CP_CODE VARCHAR2, ARG_BR_CODE VARCHAR2 , ARG_FM_DATE DATE, ARG_TO_DATE DATE) RETURN CHAR IS

  LC_FLAG      VARCHAR2(1);
  CHK           NUMBER;
  LC_DAYS NUMBER;
  LC_CUR_DATE DATE;
  LC_CRV_VTP  VARCHAR2(100);
  LC_CRV_NUM  VARCHAR2(100);

BEGIN


    LC_DAYS := ARG_TO_DATE - ARG_FM_DATE+1;
    LC_CUR_DATE := ARG_FM_DATE;

    BEGIN
        SELECT OIC_CASH_VTP_CODE
        INTO    LC_CRV_VTP
        FROM   HOS_SO_OPD_IPD_COA3
        WHERE  OIC_BR_CODE = ARG_BR_CODE;
    EXCEPTION WHEN NO_DATA_FOUND THEN
         LC_CRV_VTP      := NULL;
    END;
    LC_FLAG := 'F';
          IF LC_CRV_VTP IS NOT NULL  AND LC_DAYS IS NOT NULL THEN

              FOR A IN 1 .. LC_DAYS LOOP

               LC_CRV_NUM :=  LC_CRV_VTP||TO_CHAR(LC_CUR_DATE,'YYYYMMDD')||'001';

                BEGIN
                    SELECT COUNT(*)
                    INTO   CHK
                    FROM   ACT_TM_VOUCHER
                    WHERE  MVH_CP_CODE = ARG_CP_CODE
                    AND    MVH_DATE = LC_CUR_DATE
                    AND    MVH_NUM  = LC_CRV_NUM;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN

                    CHK := 0;
                END;

                IF CHK > 0 THEN
                     LC_FLAG := 'T';
                END IF;
                LC_CUR_DATE := LC_CUR_DATE  + 1;
              END LOOP;
          END IF;
    RETURN LC_FLAG;
END;
/

