prompt Creating function IS_VALIDATE_SERVICE
prompt =====================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.IS_VALIDATE_SERVICE(ARG_CP_CODE  VARCHAR2,
                                    ARG_DOC_NUM  VARCHAR2,
                                    ARG_DSC_CODE VARCHAR2) RETURN VARCHAR2 IS
  CHK     NUMBER;
  LC_FLAG VARCHAR2(1);
BEGIN

  BEGIN
    SELECT COUNT(*)
      INTO   CHK
      FROM HOS_TM_OPD_SRV_RCPT
     INNER JOIN HOS_TD_OPD_SRV_RCPT
        ON (DSR_CP_CODE = MSR_CP_CODE 
       -- AND DSR_MSR_NF_TYPE = MSR_NF_TYPE
       --  AND DSR_MSR_PAT_TYPE = MSR_PAT_TYPE 
         AND DSR_MSR_DATE = MSR_DATE AND
           DSR_MSR_NUM = MSR_NUM)
     WHERE MSR_CP_CODE = ARG_CP_CODE
       AND MSR_NUM = ARG_DOC_NUM
       AND DSR_DSC_CODE = ARG_DSC_CODE
       AND DSR_SMN_FLAG = 'N'
       AND DSR_RFD_FLAG = 'N'
       AND NVL(MSR_PRT_FLAG, 'N') = 'Y';

    IF CHK > 0 THEN
      LC_FLAG := 'T';
    ELSE
      LC_FLAG := 'F';
    END IF;
  END;

  RETURN LC_FLAG;
END;
/

