prompt Creating function LAB_GET_MACHINE_VALUE
prompt =======================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.LAB_GET_MACHINE_VALUE (ARG_CP_CODE VARCHAR2, ARG_SLIP_NUM VARCHAR2, ARG_SRV_CODE VARCHAR2, ARG_PMT_CODE VARCHAR2,ARG_LAB_NUM VARCHAR2 DEFAULT NULL) RETURN VARCHAR2 IS
  CURSOR CRS_TBL IS
    SELECT MLI_CP_CODE  ,MLI_SRV_CODE ,MLI_TAB_NAME ,MLI_INS_DATE ,MLI_INS_USER ,MLI_UPD_DATE ,
           MLI_UPD_USER
    FROM   LAB_INT_SM_TEST
    WHERE  MLI_CP_CODE  = ARG_CP_CODE
    AND    MLI_ACTIVE   = 'Y'
    AND    MLI_SRV_CODE = ARG_SRV_CODE;

  CURSOR CRS_FLD(ARG_TBL_NAME VARCHAR2) IS
    SELECT DLI_CP_CODE , DLI_MLI_SRV_CODE  ,  DLI_MLI_TAB_NAME   ,   DLI_LTP_PMT_CODE    ,   DLI_SEQ_NUM   ,   DLI_FIELD_NAME        ,    DLI_INS_DATE           ,    DLI_INS_USER            ,     DLI_UPD_DATE    ,   DLI_UPD_USER
    FROM  LAB_INT_SD_TEST
    WHERE     DLI_CP_CODE   = ARG_CP_CODE

    AND  DLI_MLI_SRV_CODE = ARG_SRV_CODE
    AND     DLI_MLI_TAB_NAME = ARG_TBL_NAME
    AND     DLI_LTP_PMT_CODE = ARG_PMT_CODE;

LC_QUERY VARCHAR2(5000);
LC_LAB_DB_USER VARCHAR2(100);
LC_VALUE VARCHAR2(5000);
LC_LNUM VARCHAR2(100);

LC_DATE_TIME VARCHAR2(30);
LC_QUERY2 VARCHAR2(5000);
LC_TAB_NAME VARCHAR2(100);

BEGIN
  LC_QUERY := '-';

  SELECT ISR_LAB_DB_USER
  INTO   LC_LAB_DB_USER
  FROM   ISR_XO_CONTROL;

  IF LC_LAB_DB_USER IS NOT NULL THEN
    LC_LAB_DB_USER := LC_LAB_DB_USER ||'.';
  ELSE
    LC_LAB_DB_USER := ' ';
  END IF;

  FOR REC_TBL IN CRS_TBL LOOP
      LC_TAB_NAME := REC_TBL.MLI_TAB_NAME;
      IF REC_TBL.MLI_TAB_NAME = 'LAB_INT_XT4000I' THEN
          LC_QUERY2 := 'SELECT MAX(TO_CHAR(INS_DATE, '|| CHR(39) || 'YYYYMMDD' ||CHR(39)||')||Replace(INS_TIME,'||CHR(39)||':'||CHR(39)||',null)) AS DATE_TIME '
                       || ' FROM ' || LC_LAB_DB_USER ||REC_TBL.MLI_TAB_NAME
                       || ' WHERE SLIP_NUM = ' || CHR(39) || ARG_SLIP_NUM || CHR(39);

          LC_DATE_TIME := EXEC_DSQL(LC_QUERY2);

        IF LC_QUERY = '-' THEN
          LC_QUERY := 'SELECT ';
        ELSE
          LC_QUERY := LC_QUERY || ' UNION SELECT ';
        END IF;

        FOR REC_FLD IN CRS_FLD(REC_TBL.MLI_TAB_NAME) LOOP


          LC_QUERY := LC_QUERY || ' '
                || REC_FLD.DLI_FIELD_NAME || ' AS FLD_NAME'
                || ' FROM ' || LC_LAB_DB_USER ||REC_TBL.MLI_TAB_NAME
                || ' WHERE SLIP_NUM = ' || CHR(39) || ARG_SLIP_NUM || CHR(39)
                || ' AND   TO_CHAR(INS_DATE, '|| CHR(39) || 'YYYYMMDD' ||CHR(39)||')||Replace(INS_TIME,'||CHR(39)||':'||CHR(39)||',null) = ' || CHR(39) || LC_DATE_TIME || CHR(39);
        END LOOP;
      ELSE
        IF ARG_LAB_NUM IS NULL THEN
           BEGIN
             SELECT MAX(DSR_SPC_BCODE)
             INTO   LC_LNUM
             FROM   HOS_TD_OPD_SRV_RCPT
             WHERE  DSR_CP_CODE  = ARG_CP_CODE
             AND    DSR_MSR_NUM  = ARG_SLIP_NUM
             AND    DSR_DSC_CODE = ARG_SRV_CODE;
           EXCEPTION
             WHEN OTHERS THEN
                  LC_LNUM := NULL;
           END;
        ELSE
           LC_LNUM := ARG_LAB_NUM;
        END IF; 
        BEGIN
          SELECT  A.LAB_TEST_RESULT 
          INTO LC_VALUE
          FROM   MDHLAB.LAB_INT_INTERFACING A INNER JOIN  LAB_INT_SD_TEST_DETAILS B
          ON (   A.LAB_MACHINE_NAME   = B.DMT_MACHINE_NAME
          AND    A.LAB_TEST_NAME      = B.DMT_TEST_NAME)
              
          WHERE   (A.LAB_SLIP_NUM      = ARG_SLIP_NUM
          OR       A.LAB_SLIP_NUM      = LC_LNUM)
                  
          AND      B.DMT_MLI_SRV_CODE  = ARG_SRV_CODE
          AND      B.DMT_LTP_PMT_CODE  = ARG_PMT_CODE
          
          AND    TO_CHAR(A.LAB_DATE, 'YYYYMMDD')||Replace(A.LAB_TIME,':',null) = (SELECT MAX(TO_CHAR(C.LAB_DATE, 'YYYYMMDD')||Replace(C.LAB_TIME,':',null)) AS DATE_TIME
                                                                                  FROM   MDHLAB.LAB_INT_INTERFACING C
                                                                                  WHERE  C.LAB_MACHINE_NAME = B.DMT_MACHINE_NAME
                                                                                  AND    C.LAB_TEST_NAME    = B.DMT_TEST_NAME
                                                                                  AND   (C.LAB_SLIP_NUM     = ARG_SLIP_NUM
                                                                                  OR     C.LAB_SLIP_NUM     = LC_LNUM))         
          GROUP BY A.LAB_TEST_RESULT;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
               LC_VALUE := NULL;
          WHEN OTHERS THEN
               DBMS_OUTPUT.PUT_LINE(SQLERRM || ' ' || SQLCODE);
               LC_VALUE := NULL;
        END;
      END IF;
  END LOOP;

  --LC_QUERY := 'SELECT FLD_NAME FROM (SELECT SLIP_NUM, FLD_NAME, MAX(DATE_TIME) FROM (' || LC_QUERY || ') GROUP BY SLIP_NUM, FLD_NAME)';
  IF LC_TAB_NAME = 'LAB_INT_XT4000I' THEN
     DBMS_OUTPUT.put_line(LC_QUERY);
     LC_VALUE := EXEC_DSQL(LC_QUERY);
  END IF;
  RETURN LC_VALUE;
END;
/

prompt
prompt Creating function LAB_GET_MACHINE_VALUE_old
prompt ===========================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS."LAB_GET_MACHINE_VALUE_old" (ARG_CP_CODE VARCHAR2, ARG_SLIP_NUM VARCHAR2, ARG_SRV_CODE VARCHAR2, ARG_PMT_CODE VARCHAR2) RETURN VARCHAR2 IS
  CURSOR CRS_TBL IS
    SELECT MLI_CP_CODE  , MLI_SRV_CODE ,   MLI_TAB_NAME ,    MLI_INS_DATE ,  MLI_INS_USER ,  MLI_UPD_DATE , MLI_UPD_USER
    FROM  LAB_INT_SM_TEST
    WHERE  MLI_CP_CODE = ARG_CP_CODE
    AND    MLI_ACTIVE = 'Y'
    AND    MLI_SRV_CODE = ARG_SRV_CODE;

  CURSOR CRS_FLD(ARG_TBL_NAME VARCHAR2) IS
    SELECT DLI_CP_CODE , DLI_MLI_SRV_CODE  ,  DLI_MLI_TAB_NAME   ,   DLI_LTP_PMT_CODE    ,   DLI_SEQ_NUM   ,   DLI_FIELD_NAME        ,    DLI_INS_DATE           ,    DLI_INS_USER            ,     DLI_UPD_DATE    ,   DLI_UPD_USER
    FROM  LAB_INT_SD_TEST
    WHERE     DLI_CP_CODE   = ARG_CP_CODE

    AND  DLI_MLI_SRV_CODE = ARG_SRV_CODE
    AND     DLI_MLI_TAB_NAME = ARG_TBL_NAME
    AND     DLI_LTP_PMT_CODE = ARG_PMT_CODE;

LC_QUERY VARCHAR2(5000);
LC_LAB_DB_USER VARCHAR2(100);
LC_VALUE VARCHAR2(5000);

LC_DATE_TIME VARCHAR2(30);
LC_QUERY2 VARCHAR2(5000);
LC_TAB_NAME VARCHAR2(100);

BEGIN
  LC_QUERY := '-';

  SELECT ISR_LAB_DB_USER
  INTO   LC_LAB_DB_USER
  FROM   ISR_XO_CONTROL;

  IF LC_LAB_DB_USER IS NOT NULL THEN
    LC_LAB_DB_USER := LC_LAB_DB_USER ||'.';
  ELSE
    LC_LAB_DB_USER := ' ';
  END IF;

  FOR REC_TBL IN CRS_TBL LOOP
      LC_TAB_NAME := REC_TBL.MLI_TAB_NAME;
      IF REC_TBL.MLI_TAB_NAME = 'LAB_INT_XT4000I' THEN
          LC_QUERY2 := 'SELECT MAX(TO_CHAR(INS_DATE, '|| CHR(39) || 'YYYYMMDD' ||CHR(39)||')||Replace(INS_TIME,'||CHR(39)||':'||CHR(39)||',null)) AS DATE_TIME '
                       || ' FROM ' || LC_LAB_DB_USER ||REC_TBL.MLI_TAB_NAME
                       || ' WHERE SLIP_NUM = ' || CHR(39) || ARG_SLIP_NUM || CHR(39);

          LC_DATE_TIME := EXEC_DSQL(LC_QUERY2);

        IF LC_QUERY = '-' THEN
          LC_QUERY := 'SELECT ';
        ELSE
          LC_QUERY := LC_QUERY || ' UNION SELECT ';
        END IF;

        FOR REC_FLD IN CRS_FLD(REC_TBL.MLI_TAB_NAME) LOOP


          LC_QUERY := LC_QUERY || ' '
                || REC_FLD.DLI_FIELD_NAME || ' AS FLD_NAME'
                || ' FROM ' || LC_LAB_DB_USER ||REC_TBL.MLI_TAB_NAME
                || ' WHERE SLIP_NUM = ' || CHR(39) || ARG_SLIP_NUM || CHR(39)
                || ' AND   TO_CHAR(INS_DATE, '|| CHR(39) || 'YYYYMMDD' ||CHR(39)||')||Replace(INS_TIME,'||CHR(39)||':'||CHR(39)||',null) = ' || CHR(39) || LC_DATE_TIME || CHR(39);
        END LOOP;
      ELSE
          BEGIN
              SELECT   LAB_TEST_RESULT INTO LC_VALUE
              FROM     mdhlab.LAB_INT_INTERFACING, LAB_INT_SD_TEST_DETAILS
              WHERE    LAB_SLIP_NUM     = ARG_SLIP_NUM
              AND      LAB_MACHINE_NAME = DMT_MACHINE_NAME
              AND      LAB_TEST_NAME    = DMT_TEST_NAME
              AND      DMT_CP_CODE      = ARG_CP_CODE
              AND      DMT_MLI_SRV_CODE     = ARG_SRV_CODE
              AND      DMT_LTP_PMT_CODE     = ARG_PMT_CODE
              AND    TO_CHAR(LAB_DATE, 'YYYYMMDD')||Replace(LAB_TIME,':',null) = (SELECT MAX(TO_CHAR(LAB_DATE, 'YYYYMMDD')||Replace(LAB_TIME,':',null)) AS DATE_TIME
              FROM    MDHLAB.LAB_INT_INTERFACING
              WHERE   LAB_SLIP_NUM = ARG_SLIP_NUM);
          EXCEPTION
            WHEN NO_DATA_FOUND THEN
                 LC_VALUE := NULL;
            WHEN OTHERS THEN
                 DBMS_OUTPUT.PUT_LINE(SQLERRM || ' ' || SQLCODE);
                 LC_VALUE := NULL;
          END;
      END IF;
  END LOOP;

  --LC_QUERY := 'SELECT FLD_NAME FROM (SELECT SLIP_NUM, FLD_NAME, MAX(DATE_TIME) FROM (' || LC_QUERY || ') GROUP BY SLIP_NUM, FLD_NAME)';
  IF LC_TAB_NAME = 'LAB_INT_XT4000I' THEN
     DBMS_OUTPUT.put_line(LC_QUERY);
     LC_VALUE := EXEC_DSQL(LC_QUERY);
  END IF;
  RETURN LC_VALUE;
END;
/

