prompt Creating function STOCK_VALIDATION
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.STOCK_VALIDATION(ARG_CP_CODE VARCHAR2, ARG_LOC_CODE VARCHAR2,
                                             ARG_DATE    DATE    , ARG_DIT_CODE VARCHAR2)
                                             RETURN VARCHAR2 IS
VAL_RETURN   NUMBER;
LC_DIT_QTY   NUMBER;

CURSOR LOC_CRS IS
    SELECT DISTINCT MPB_LOC_CODE
    FROM    PPI_PM_BALANCE  , PPI_STOCK_LIST
    WHERE   MPB_CP_CODE       = PPI_STOCK_LIST.DIT_CP_CODE
    AND     MPB_DIT_CODE      = PPI_STOCK_LIST.DIT_CODE
    AND     MPB_CP_CODE = ARG_CP_CODE
    AND     MPB_DIT_CODE = ARG_DIT_CODE
    AND     MPB_LOC_CODE = NVL(ARG_LOC_CODE, MPB_LOC_CODE)
    AND     MPB_DATE    <= ARG_DATE
    ORDER BY 1;

CURSOR DIT_CRS (ARG_LOC_CODE VARCHAR2)  IS
    SELECT DISTINCT MPB_DIT_CODE
    FROM    PPI_PM_BALANCE  , PPI_STOCK_LIST
    WHERE   MPB_CP_CODE  = PPI_STOCK_LIST.DIT_CP_CODE
    AND     MPB_DIT_CODE = PPI_STOCK_LIST.DIT_CODE
    AND     MPB_CP_CODE  = ARG_CP_CODE
    AND     MPB_DIT_CODE = ARG_DIT_CODE
    AND     MPB_LOC_CODE = ARG_LOC_CODE
    AND     MPB_DATE    <= ARG_DATE
    ORDER BY 1;

BEGIN
    FOR LOC_REC IN LOC_CRS LOOP
        FOR DIT_REC IN  DIT_CRS(LOC_REC.MPB_LOC_CODE) LOOP
            LC_DIT_QTY := NVL(GET_IN_BAL (ARG_CP_CODE, ARG_DATE, ARG_DATE, DIT_REC.MPB_DIT_CODE, LOC_REC.MPB_LOC_CODE,'CL','Q'),0)
                        - NVL(GET_OUT_BAL(ARG_CP_CODE, ARG_DATE, ARG_DATE, DIT_REC.MPB_DIT_CODE, LOC_REC.MPB_LOC_CODE,'CL','Q'),0);
            IF NVL(LC_DIT_QTY,0) <> 0 THEN
                VAL_RETURN := NVL(VAL_RETURN,0) + NVL(LC_DIT_QTY,0);
            END IF;
        END LOOP;
    END LOOP;
    RETURN NVL(VAL_RETURN,0);
END;
/

