prompt Creating function UPDATE_GRN_PRICE
prompt ==================================
prompt
CREATE OR REPLACE FUNCTION MDHSYS.UPDATE_GRN_PRICE
(ARG_CP_CODE VARCHAR2 , ARG_BR_CODE VARCHAR2, ARG_DATE DATE ,
ARG_NUM VARCHAR2  , ARG_DIT_CODE  VARCHAR2  , ARG_TIME VARCHAR2 , ARG_USER VARCHAR2 , ARG_INS_DATE DATE , ARG_REMARKS VARCHAR2)
RETURN VARCHAR2 IS

  LC_DOT_DIT_CODE VARCHAR2(10);
  LC_FLAG   VARCHAR2(1) := 'F';
  LC_DOT_MAX_TRD_PRICE NUMBER;
  LC_DOT_MIN_TRD_PRICE NUMBER;
  LC_DOT_DIS_PCT       NUMBER;
  LC_DOT_RATE2         NUMBER;
  LC_DOT_RATE1         NUMBER;

  LC_DIFF_PCT          NUMBER;

  LC_BOX_RETAIL      NUMBER;
  LC_UNIT_RETAIL     NUMBER;
  LC_DOT_SR_DISC_PCT NUMBER;
  LC_SAL_RATE_BOX    NUMBER;
  LC_SAL_RATE_UNIT   NUMBER;

  LC_IPR_MIT_TYPE VARCHAR2(1);
  LC_IPR_CTG_TYPE VARCHAR2(1);
  ARG_REF_NUM VARCHAR2(20);
  CHK NUMBER;


BEGIN
      BEGIN
         SELECT MST_REF_NUM
        INTO ARG_REF_NUM
        FROM PPI_TM_STOCK
        WHERE MST_CP_CODE = ARG_CP_CODE
        AND   MST_NUM = ARG_NUM;
      EXCEPTION
    WHEN OTHERS THEN
        LC_FLAG  := NULL;
      END;
        DBMS_OUTPUT.PUT_LINE(ARG_REF_NUM);
  BEGIN

    SELECT DOT_DIT_CODE,
           DOT_MAX_TRD_PRICE "Box T.P",
           DOT_MIN_TRD_PRICE "Unit T.P",
           DOT_DIS_PCT "Disc. (%)  on T.P",
           DOT_RATE2 "Box Cost",
           DOT_RATE1 "Unit Cost",
           TO_NUMBER(DECODE(DOT_SR_DISC_PCT,
                            0,
                            0,
                            ABS(ROUND((DOT_OPN_MAX_RTL * 100 /
                                      DOT_MAX_TRD_PRICE) - 100,
                                      2)))) "Diff. b/wT.P. & R.P. (%)",
           DOT_OPN_MAX_RTL "R.P.Box Retail",

           DOT_OPN_MIN_RTL "R.P.Unit Retail",
           DOT_SR_DISC_PCT "Disc. (%)  on S.R",
           TO_NUMBER(
                            ROUND(DOT_OPN_MAX_RTL -
                                  (DOT_OPN_MAX_RTL * DOT_SR_DISC_PCT / 100),
                                  4)) "Sales Rate Box",
           TO_NUMBER(
                            ROUND(DOT_OPN_MIN_RTL -
                                  (DOT_OPN_MIN_RTL * DOT_SR_DISC_PCT / 100),
                                  4)) "Sales Rate Unit"
      INTO LC_DOT_DIT_CODE,
           LC_DOT_MAX_TRD_PRICE,
           LC_DOT_MIN_TRD_PRICE,

           LC_DOT_DIS_PCT,
           LC_DOT_RATE2,
           LC_DOT_RATE1,
           LC_DIFF_PCT,
           LC_BOX_RETAIL,
           LC_UNIT_RETAIL,
           LC_DOT_SR_DISC_PCT,
           LC_SAL_RATE_BOX,
           LC_SAL_RATE_UNIT
      FROM PPI_TM_ORD_TRNS, PPI_TD_ORD_TRNS
     WHERE PPI_TD_ORD_TRNS.DOT_CP_CODE = PPI_TM_ORD_TRNS.MOT_CP_CODE
       AND PPI_TD_ORD_TRNS.DOT_MOT_NUM = PPI_TM_ORD_TRNS.MOT_NUM
       AND MOT_CP_CODE = ARG_CP_CODE
       AND MOT_BR_CODE = ARG_BR_CODE
       AND DOT_MOT_NUM  = ARG_REF_NUM
       AND DOT_DIT_CODE = ARG_DIT_CODE;
  EXCEPTION
    WHEN OTHERS THEN
      --DBMS_OUTPUT.PUT_LINE(SQLERRM || ' ' || SQLCODE, 'Y');
        LC_FLAG  := NULL;
  END;

  --  SELECT TO_CHAR(SYSDATE,'HH24:MI:SS') INTO :DOT_INS_TIME FROM DUAL;

  BEGIN
    SELECT MIT_TYPE

      INTO LC_IPR_MIT_TYPE
      FROM PPI_SM_ITEM
     WHERE MIT_CP_CODE = ARG_CP_CODE
       AND MIT_CODE = SUBSTR(ARG_DIT_CODE, 1, 3);
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      --DIS_ERROR('Err. No Data Found', 'Y');
          LC_FLAG  := NULL;
      NULL;
  END;

  BEGIN
    SELECT CTG_TYPE

      INTO LC_IPR_CTG_TYPE
      FROM PPI_SO_ITEM_CATEGORY, PPI_SM_ITEM, PPI_SD_ITEM
     WHERE CTG_CP_CODE = ARG_CP_CODE
       AND CTG_CP_CODE = MIT_CP_CODE
       AND MIT_CTG_CODE = CTG_CODE
       AND MIT_CODE = DIT_MIT_CODE
       AND MIT_CP_CODE = DIT_CP_CODE
       AND DIT_CODE = ARG_DIT_CODE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      --DIS_ERROR('Err. No Data Found', 'Y');
          LC_FLAG  := NULL;
  END;


  SELECT COUNT(*)
    INTO CHK
    FROM PPI_SO_ITEM_PRICE
   WHERE IPR_DIT_CODE = ARG_DIT_CODE
     AND IPR_BR_CODE  = ARG_BR_CODE
     AND IPR_DATE     = ARG_DATE;
    DBMS_OUTPUT.PUT_LINE('No Manager');
  IF CHK = 0 THEN
    INSERT INTO PPI_SO_ITEM_PRICE
      (IPR_CP_CODE,
       IPR_DATE,
       IPR_DIT_CODE,
       IPR_MIT_TYPE,
       IPR_BR_CODE,
       IPR_CTG_TYPE,
       IPR_MIN_TRD_PRICE,
       IPR_MAX_TRD_PRICE,
       IPR_DISC_PCT,
       IPR_MIN_COST,
       IPR_MAX_COST,
       IPR_DIFF_PCT,
       IPR_MIN_RET_PRICE,
       IPR_MAX_RET_PRICE,
       IPR_PRD_DISC_PCT,
       IPR_MAX_RATE,
       IPR_MIN_RATE,
       IPR_FLAG,
       IPR_DAT_FLAG,
       IPR_BCH_NUM,
       IPR_INS_TIME,
       IPR_INS_USER,
       IPR_INS_DATE,
       IPR_REMARKS)
    VALUES
      (ARG_CP_CODE,
       ARG_DATE,
       ARG_DIT_CODE,
       LC_IPR_MIT_TYPE,
       ARG_BR_CODE,
       LC_IPR_CTG_TYPE,
       ROUND(LC_DOT_MIN_TRD_PRICE, 4),
       ROUND(LC_DOT_MAX_TRD_PRICE, 4),
       ROUND(LC_DOT_DIS_PCT, 2),
       ROUND(LC_DOT_RATE1, 4),
       ROUND(LC_DOT_RATE2, 4),
       LC_DIFF_PCT,
       ROUND(LC_UNIT_RETAIL, 4),
       ROUND(LC_BOX_RETAIL, 4),
       ROUND(NVL(LC_DOT_SR_DISC_PCT, 0), 2),
       LC_SAL_RATE_BOX,
       LC_SAL_RATE_UNIT,
       'Y',
       'I',
       '-',
       ARG_TIME,
       ARG_USER,
       ARG_INS_DATE,
       ARG_REMARKS);
  ELSE
       DBMS_OUTPUT.PUT_LINE('1111111111111');

    UPDATE PPI_SO_ITEM_PRICE
       SET IPR_MIN_TRD_PRICE = ROUND(LC_DOT_MIN_TRD_PRICE, 4),
           IPR_MAX_TRD_PRICE = ROUND(LC_DOT_MAX_TRD_PRICE, 4),
           IPR_DISC_PCT      = ROUND(LC_DOT_DIS_PCT, 2),
           IPR_MIN_COST = ROUND(LC_DOT_RATE1, 4),
           IPR_MAX_COST = ROUND(LC_DOT_RATE2, 4),
           IPR_DIFF_PCT = LC_DIFF_PCT,
           IPR_MIN_RET_PRICE = ROUND(LC_UNIT_RETAIL, 4),
           IPR_MAX_RET_PRICE = ROUND(LC_BOX_RETAIL, 4),
           IPR_PRD_DISC_PCT  = ROUND(NVL(LC_DOT_SR_DISC_PCT, 0), 2),
           IPR_MAX_RATE = LC_SAL_RATE_BOX,
           IPR_MIN_RATE = LC_SAL_RATE_UNIT,
           IPR_UPD_TIME =  ARG_TIME  ,
           IPR_UPD_USER  =   ARG_USER,
           IPR_UPD_DATE  =  ARG_INS_DATE,
           IPR_REMARKS  =  ARG_REMARKS
     WHERE IPR_CP_CODE  =  ARG_CP_CODE
       AND IPR_DIT_CODE =  ARG_DIT_CODE
       AND IPR_BR_CODE  = ARG_BR_CODE
       AND IPR_DATE     =  ARG_DATE;

  END IF;
  IF SQL%ROWCOUNT <> 0 THEN
    LC_FLAG := 'T';
  ELSE
        LC_FLAG := 'F';
  END IF;


  RETURN  LC_FLAG ;
END;
/

