CREATE OR REPLACE PROCEDURE MDHSYS.generate_hl7_message AS
  v_hl7_message VARCHAR2(4000); -- Adjust the size as needed

BEGIN
  -- Construct your HL7 message
  v_hl7_message :=
    'MSH|^~\&|YOUR_APP|YOUR_FACILITY|HL7_SYS|HL7_FACILITY|' ||
    '20220117120000||ADT^A08|MSGID12345|P|2.5|||||||||';

  -- Add more segments and fields as needed

  -- Print or store the HL7 message
  DBMS_OUTPUT.PUT_LINE(v_hl7_message);
END generate_hl7_message;
/

