prompt Creating procedure GEN_EMP_RS_FIX_SHF
prompt =====================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.GEN_EMP_RS_FIX_SHF(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_EMP_CODE VARCHAR2,ARG_DATE_FM DATE,ARG_DATE_TO DATE) AS

  LC_DATE      DATE;
  LC_SHF_CODE     VARCHAR2(3);
  LC_OFF_TYPE     VARCHAR2(1);
  LC_SHF_DATE     DATE;
  LC_SHF_DATE_OUT DATE;
  LC_ROSTER_FLAG  VARCHAR2(1);
  LC_DSE_OFF_MON  VARCHAR2(1);
  LC_DSE_OFF_TUE  VARCHAR2(1);
  LC_DSE_OFF_WED  VARCHAR2(1);
  LC_DSE_OFF_THU  VARCHAR2(1);
  LC_DSE_OFF_FRI  VARCHAR2(1);
  LC_DSE_OFF_SAT  VARCHAR2(1);
  LC_DSE_OFF_SUN  VARCHAR2(1);
  LC_DTY_IN       VARCHAR2(10);
  LC_DTY_OUT      VARCHAR2(10);
  LC_LCH_OUT      VARCHAR2(10);
  LC_LCH_IN       VARCHAR2(10);
  LC_DTY_HRS      NUMBER(13,2);
  LC_MIN_OT_LIMIT NUMBER(13,2);
  LC_LATE_MARGIN  VARCHAR2(10);
  LC_OFF_DAY_FLAG VARCHAR2(1);
BEGIN
  LC_DATE := ARG_DATE_FM - 1;
  FOR A IN 1..((ARG_DATE_TO - ARG_DATE_FM) + 1) LOOP
      LC_DATE := ((LC_DATE + 1));
      BEGIN
        SELECT  'R', NULL, WAG_SHF_CODE, WAG_DTY_IN, WAG_DTY_OUT, WAG_LCH_OUT, WAG_LCH_IN, WAG_DTY_HRS, WAG_MIN_OT_LIMIT, WAG_LATE_MARGIN,
                NVL(DSE_OFF_MON,'N'), NVL(DSE_OFF_TUE,'N'), NVL(DSE_OFF_WED,'N'), NVL(DSE_OFF_THU,'N'), NVL(DSE_OFF_FRI,'N'), NVL(DSE_OFF_SAT,'N'), NVL(DSE_OFF_SUN,'N')
        INTO    LC_ROSTER_FLAG, LC_SHF_DATE, LC_SHF_CODE, LC_DTY_IN , LC_DTY_OUT, LC_LCH_OUT, LC_LCH_IN, LC_DTY_HRS, LC_MIN_OT_LIMIT, LC_LATE_MARGIN,
                LC_DSE_OFF_MON, LC_DSE_OFF_TUE, LC_DSE_OFF_WED, LC_DSE_OFF_THU, LC_DSE_OFF_FRI, LC_DSE_OFF_SAT, LC_DSE_OFF_SUN
        FROM PAY_SM_EMPLOYEE A,PAY_SD_SHIFT_EMPLOYEE B,PAY_SO_WAGES_INFO C
        WHERE A.EMP_CP_CODE  = ARG_CP_CODE
        AND   A.EMP_CP_CODE  = B.DSE_CP_CODE
        AND   A.EMP_CODE     = B.DSE_EMP_CODE
        AND   A.EMP_CODE     = ARG_EMP_CODE
        AND   B.DSE_CP_CODE  = C.WAG_CP_CODE
        AND   B.DSE_SHF_CODE = C.WAG_SHF_CODE
        --AND    NVL(EMP_SHF_RS,'N') = 'Y'
        AND   C.WAG_FLAG     = 'Y'
        AND   C.WAG_EFF_DATE = (SELECT MAX(D.WAG_EFF_DATE)
                                FROM PAY_SO_WAGES_INFO D
                                WHERE WAG_CP_CODE   = A.EMP_CP_CODE
                                AND   WAG_SHF_CODE  = B.DSE_SHF_CODE
                                AND   WAG_EFF_DATE <= LC_DATE
                                AND   WAG_FLAG      = 'Y')
        AND   B.DSE_EFF_DATE = (SELECT MAX(E.DSE_EFF_DATE)
                                FROM PAY_SD_SHIFT_EMPLOYEE E
                                WHERE E.DSE_CP_CODE   = A.EMP_CP_CODE
                                AND   E.DSE_EFF_DATE <= LC_DATE
                                AND   E.DSE_EMP_CODE  = A.EMP_CODE);
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
           LC_SHF_DATE     := NULL;
           LC_SHF_DATE_OUT  := NULL;
           LC_SHF_CODE      := NULL;
           LC_DTY_IN       := NULL;
           LC_DTY_OUT      := NULL;
           LC_LCH_OUT      := NULL;
           LC_LCH_IN       := NULL;
           LC_DTY_HRS      := NULL;
           LC_MIN_OT_LIMIT := NULL;
           LC_LATE_MARGIN  := NULL;
           LC_OFF_TYPE     := NULL;
           LC_ROSTER_FLAG  := 'I';
    END;
    IF LC_SHF_CODE IS NOT NULL THEN
    /*SELECT COUNT(*)
    INTO   LC_CNT
    FROM   PAY_EMP_ROASTER
    WHERE  ROS_CP_CODE  = ARG_CP_CODE
    AND    ROS_EMP_CODE = ARG_EMP_CODE
    AND    ROS_DATE     = LC_DATE;*/
    BEGIN
      SELECT 'Y'
      INTO   LC_OFF_DAY_FLAG
      FROM   PAY_SM_WORK_HOLIDAY
      WHERE  HOL_CP_CODE    = ARG_CP_CODE
      AND    HOL_DATE       = LC_DATE;
      LC_OFF_TYPE := 'G';
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
           LC_OFF_DAY_FLAG := 'N';
           LC_OFF_TYPE     := 'W';
           LC_SHF_DATE_OUT := LC_DATE;
    END;

    IF LC_OFF_DAY_FLAG = 'N' THEN
       IF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'MON' AND NVL(LC_DSE_OFF_MON,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'TUE' AND NVL(LC_DSE_OFF_TUE,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'WED' AND NVL(LC_DSE_OFF_WED,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'THU' AND NVL(LC_DSE_OFF_THU,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'FRI' AND NVL(LC_DSE_OFF_FRI,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'SAT' AND NVL(LC_DSE_OFF_SAT,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
       ELSIF SUBSTR(UPPER(TO_CHAR(LC_DATE,'DAY')),1,3) = 'SUN' AND NVL(LC_DSE_OFF_SUN,'N') = 'Y' THEN
          LC_OFF_TYPE := 'O';
      END IF;
    END IF;
    IF LC_OFF_TYPE <> 'W' THEN
       LC_OFF_DAY_FLAG  := 'Y';
       LC_SHF_DATE_OUT  := NULL;
       LC_DTY_HRS      := NULL;
       LC_DTY_IN       := NULL;
       LC_DTY_OUT      := NULL;
       LC_MIN_OT_LIMIT := NULL;
       LC_LATE_MARGIN  := NULL;
    END IF;
    DELETE FROM PAY_EMP_ROASTER
    WHERE  ROS_CP_CODE  = ARG_CP_CODE
    AND    ROS_EMP_CODE = ARG_EMP_CODE
    AND    ROS_DATE     = LC_DATE;
    INSERT INTO PAY_EMP_ROASTER
          (ROS_CP_CODE,           ROS_EMP_CODE,            ROS_DATE,            ROS_OUT_DATE,           ROS_DAY,
           ROS_SHF_CODE,          ROS_TIME_IN,             ROS_TIME_OUT,        ROS_DUTY_HRS,           ROS_LATE_MARGIN,
           ROS_OFF_DAY,           ROS_MAN_CHG,             ROS_TRS_TYPE,        ROS_OFF_TYPE,           ROS_MIN_OT_LIMIT,
           ROS_BR_CODE)
    VALUES(ARG_CP_CODE,           ARG_EMP_CODE,            LC_DATE,             LC_SHF_DATE_OUT,        TO_CHAR(LC_DATE,'DAY'),
           LC_SHF_CODE,           LC_DTY_IN ,              LC_DTY_OUT,          LC_DTY_HRS,             LC_LATE_MARGIN,
           LC_OFF_DAY_FLAG,       'N',                     'R',                 LC_OFF_TYPE,            LC_MIN_OT_LIMIT,
           ARG_BR_CODE);
    COMMIT;
    END IF;
  END LOOP;
END;
/

