prompt Creating procedure GET_DEFICIENT_STOCK
prompt ======================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.GET_DEFICIENT_STOCK(ARG_CP_CODE VARCHAR2, ARG_USR_NAME VARCHAR2,
    ARG_SESSION VARCHAR2, ARG_PRG_CODE VARCHAR2, ARG_RPT_ID VARCHAR2,
    ARG_DATE DATE, ARG_LOC_CODE VARCHAR2, ARG_ERR OUT VARCHAR2) IS



  TYPE T_TR_TYPE    IS TABLE OF ISR_CHECK_DSTOCK.TR_TYPE%TYPE;
  TYPE T_TR_CP_CODE    IS TABLE OF ISR_CHECK_DSTOCK.TR_CP_CODE%TYPE;
  TYPE T_TR_LOC_CODE    IS TABLE OF ISR_CHECK_DSTOCK.TR_LOC_CODE%TYPE;
  TYPE T_TR_DIT_CODE    IS TABLE OF ISR_CHECK_DSTOCK.TR_DIT_CODE%TYPE;
  TYPE T_TR_BCH_NUM    IS TABLE OF ISR_CHECK_DSTOCK.TR_BCH_NUM%TYPE;
  TYPE T_TR_LOT_NUM    IS TABLE OF ISR_CHECK_DSTOCK.TR_LOT_NUM%TYPE;
  TYPE T_TR_EXP_DATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_EXP_DATE%TYPE;
  TYPE T_TR_DATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_DATE%TYPE;
  TYPE T_TR_DOC_NUM    IS TABLE OF ISR_CHECK_DSTOCK.TR_DOC_NUM%TYPE;
  TYPE T_TR_SEQ_NUM    IS TABLE OF ISR_CHECK_DSTOCK.TR_SEQ_NUM%TYPE;
  TYPE T_TR_TRN_TYPE    IS TABLE OF ISR_CHECK_DSTOCK.TR_TRN_TYPE%TYPE;
  TYPE T_TR_INS_TIME    IS TABLE OF ISR_CHECK_DSTOCK.TR_INS_TIME%TYPE;
  TYPE T_TR_INS_DATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_INS_DATE%TYPE;
  TYPE T_TR_MIN_QTY    IS TABLE OF ISR_CHECK_DSTOCK.TR_MIN_QTY%TYPE;
  TYPE T_TR_MAX_QTY    IS TABLE OF ISR_CHECK_DSTOCK.TR_MAX_QTY%TYPE;
  TYPE T_TR_MIN_RATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_MIN_RATE%TYPE;
  TYPE T_TR_MAX_RATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_MAX_RATE%TYPE;
  TYPE T_TR_AMT    IS TABLE OF ISR_CHECK_DSTOCK.TR_AMT%TYPE;
  TYPE T_TR_BR_CODE    IS TABLE OF ISR_CHECK_DSTOCK.TR_BR_CODE%TYPE;
  TYPE T_TR_DAT_FLAG    IS TABLE OF ISR_CHECK_DSTOCK.TR_DAT_FLAG%TYPE;
  TYPE T_TR_MIN_ADD_COST IS TABLE OF ISR_CHECK_DSTOCK.TR_MIN_ADD_COST%TYPE;
  TYPE T_TR_MAX_ADD_COST IS TABLE OF ISR_CHECK_DSTOCK.TR_MAX_ADD_COST%TYPE;
  TYPE T_TR_REF_NUM    IS TABLE OF ISR_CHECK_DSTOCK.TR_REF_NUM%TYPE;
  TYPE T_TR_FVL_FLAG    IS TABLE OF ISR_CHECK_DSTOCK.TR_FVL_FLAG%TYPE;
  TYPE T_TR_LOC_OUT    IS TABLE OF ISR_CHECK_DSTOCK.TR_LOC_OUT%TYPE;
  TYPE T_TR_TBL_TYPE    IS TABLE OF ISR_CHECK_DSTOCK.TR_TBL_TYPE%TYPE;
  TYPE T_TR_NATURE    IS TABLE OF ISR_CHECK_DSTOCK.TR_NATURE%TYPE;
  TYPE T_TR_VAL_QTY    IS TABLE OF ISR_CHECK_DSTOCK.TR_VAL_QTY%TYPE;
  TYPE T_TR_VAL_RATE    IS TABLE OF ISR_CHECK_DSTOCK.TR_VAL_RATE%TYPE;
  TYPE T_TR_VAL_AMT    IS TABLE OF ISR_CHECK_DSTOCK.TR_VAL_AMT%TYPE;
  TYPE T_TR_VAL_AMT2    IS TABLE OF ISR_CHECK_DSTOCK.TR_VAL_AMT2%TYPE;
  TYPE T_TR_REF_SQN    IS TABLE OF ISR_CHECK_DSTOCK.TR_REF_SQN%TYPE;
  TYPE T_TR_BAR_CODE    IS TABLE OF ISR_CHECK_DSTOCK.TR_BAR_CODE%TYPE;

  LC_TR_TYPE    T_TR_TYPE;
  LC_TR_CP_CODE    T_TR_CP_CODE;
  LC_TR_LOC_CODE    T_TR_LOC_CODE;
  LC_TR_DIT_CODE    T_TR_DIT_CODE;
  LC_TR_BCH_NUM    T_TR_BCH_NUM;
  LC_TR_LOT_NUM    T_TR_LOT_NUM;
  LC_TR_EXP_DATE    T_TR_EXP_DATE;
  LC_TR_DATE    T_TR_DATE;
  LC_TR_DOC_NUM    T_TR_DOC_NUM;
  LC_TR_SEQ_NUM    T_TR_SEQ_NUM;
  LC_TR_TRN_TYPE    T_TR_TRN_TYPE;
  LC_TR_INS_TIME    T_TR_INS_TIME;
  LC_TR_INS_DATE    T_TR_INS_DATE;
  LC_TR_MIN_QTY    T_TR_MIN_QTY;
  LC_TR_MAX_QTY    T_TR_MAX_QTY;
  LC_TR_MIN_RATE    T_TR_MIN_RATE;
  LC_TR_MAX_RATE    T_TR_MAX_RATE;
  LC_TR_AMT    T_TR_AMT;
  LC_TR_BR_CODE    T_TR_BR_CODE;
  LC_TR_DAT_FLAG    T_TR_DAT_FLAG;
  LC_TR_MIN_ADD_COST T_TR_MIN_ADD_COST;
  LC_TR_MAX_ADD_COST T_TR_MAX_ADD_COST;
  LC_TR_REF_NUM    T_TR_REF_NUM;
  LC_TR_FVL_FLAG    T_TR_FVL_FLAG;
  LC_TR_LOC_OUT    T_TR_LOC_OUT;
  LC_TR_TBL_TYPE    T_TR_TBL_TYPE;
  LC_TR_NATURE    T_TR_NATURE;
  LC_TR_VAL_QTY    T_TR_VAL_QTY;
  LC_TR_VAL_RATE    T_TR_VAL_RATE;
  LC_TR_VAL_AMT    T_TR_VAL_AMT;
  LC_TR_VAL_AMT2    T_TR_VAL_AMT2;
  LC_TR_REF_SQN    T_TR_REF_SQN;
  LC_TR_BAR_CODE    T_TR_BAR_CODE;



  TYPE T_RPT_NATURE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_NATURE%TYPE;
  TYPE T_RPT_TRN_TYPE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_TRN_TYPE%TYPE;
  TYPE T_RPT_DATE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_DATE%TYPE;
  TYPE T_RPT_DOC_NUM IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_DOC_NUM%TYPE;
  TYPE T_RPT_DIT_CODE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_DIT_CODE%TYPE;
  TYPE T_RPT_DIT_DESC IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_DIT_DESC%TYPE;
  TYPE T_RPT_QTY IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_QTY%TYPE;
  TYPE T_RPT_BCH_NUM IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_BCH_NUM%TYPE;
  TYPE T_RPT_LOT_NUM IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_LOT_NUM%TYPE;
  TYPE T_RPT_EXP_DATE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_EXP_DATE%TYPE;
  TYPE T_RPT_BAR_CODE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_BAR_CODE%TYPE;
  TYPE T_RPT_SEQ_NUM IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_SEQ_NUM%TYPE;
  TYPE T_RPT_LOC_CODE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_LOC_CODE%TYPE;
  TYPE T_RPT_IN_NUM IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_IN_NUM%TYPE;
  TYPE T_RPT_VAL_RATE IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_VAL_RATE%TYPE;
  TYPE T_RPT_VAL_AMT IS TABLE OF PPI_RO_DEFICIENT_STOCK.RPT_VAL_AMT%TYPE;


  LC_RPT_NATURE      T_RPT_NATURE;
  LC_RPT_TRN_TYPE    T_RPT_TRN_TYPE;
  LC_RPT_DATE        T_RPT_DATE;
  LC_RPT_DOC_NUM     T_RPT_DOC_NUM;
  LC_RPT_DIT_CODE    T_RPT_DIT_CODE;
  LC_RPT_DIT_DESC    T_RPT_DIT_DESC;
  LC_RPT_QTY         T_RPT_QTY;
  LC_RPT_SEQ_NUM     T_RPT_SEQ_NUM;
  LC_RPT_LOC_CODE    T_RPT_LOC_CODE;
  LC_RPT_IN_NUM      T_RPT_IN_NUM;
  LC_RPT_VAL_RATE    T_RPT_VAL_RATE;
  LC_RPT_VAL_AMT     T_RPT_VAL_AMT;
  LC_RPT_BCH_NUM     T_RPT_BCH_NUM;
  LC_RPT_LOT_NUM     T_RPT_LOT_NUM;
  LC_RPT_EXP_DATE    T_RPT_EXP_DATE;
  LC_RPT_BAR_CODE    T_RPT_BAR_CODE;

  LC_PROCESS VARCHAR2(500);
BEGIN
  LC_PROCESS := 'ALL STOCK';

/*
  SELECT TR_TYPE, TR_CP_CODE, TR_LOC_CODE, TR_DIT_CODE, TR_BCH_NUM,
    TR_LOT_NUM, TR_EXP_DATE, TR_DATE, TR_DOC_NUM, TR_SEQ_NUM, TR_TRN_TYPE, TR_INS_TIME,
    TR_INS_DATE, TR_MIN_QTY, TR_MAX_QTY, TR_MIN_RATE, TR_MAX_RATE, TR_AMT, TR_BR_CODE,
    TR_DAT_FLAG, TR_MIN_ADD_COST, TR_MAX_ADD_COST, TR_REF_NUM, TR_FVL_FLAG, TR_LOC_OUT,
    TR_TBL_TYPE, TR_NATURE, TR_VAL_QTY, TR_VAL_RATE, TR_VAL_AMT, TR_VAL_AMT2, TR_REF_SQN,
    TR_BAR_CODE
  BULK COLLECT
  INTO LC_TR_TYPE, LC_TR_CP_CODE, LC_TR_LOC_CODE, LC_TR_DIT_CODE, LC_TR_BCH_NUM,
    LC_TR_LOT_NUM, LC_TR_EXP_DATE, LC_TR_DATE, LC_TR_DOC_NUM, LC_TR_SEQ_NUM, LC_TR_TRN_TYPE, LC_TR_INS_TIME,
    LC_TR_INS_DATE, LC_TR_MIN_QTY, LC_TR_MAX_QTY, LC_TR_MIN_RATE, LC_TR_MAX_RATE, LC_TR_AMT, LC_TR_BR_CODE,
    LC_TR_DAT_FLAG, LC_TR_MIN_ADD_COST, LC_TR_MAX_ADD_COST, LC_TR_REF_NUM, LC_TR_FVL_FLAG, LC_TR_LOC_OUT,
    LC_TR_TBL_TYPE, LC_TR_NATURE, LC_TR_VAL_QTY, LC_TR_VAL_RATE, LC_TR_VAL_AMT, LC_TR_VAL_AMT2, LC_TR_REF_SQN,
    LC_TR_BAR_CODE
  FROM ALL_STOCK
  WHERE TR_DATE <= ARG_DATE
  AND   (TR_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
      OR TR_LOC_OUT  LIKE NVL(ARG_LOC_CODE,'%'))
  ORDER BY TR_DIT_CODE;


    FORALL I IN LC_TR_DIT_CODE.FIRST .. LC_TR_DIT_CODE.LAST
    INSERT INTO ISR_CHECK_DSTOCK (TR_TYPE, TR_CP_CODE, TR_LOC_CODE, TR_DIT_CODE, TR_BCH_NUM,
      TR_LOT_NUM, TR_EXP_DATE, TR_DATE, TR_DOC_NUM, TR_SEQ_NUM, TR_TRN_TYPE, TR_INS_TIME,
      TR_INS_DATE, TR_MIN_QTY, TR_MAX_QTY, TR_MIN_RATE, TR_MAX_RATE, TR_AMT, TR_BR_CODE,
      TR_DAT_FLAG, TR_MIN_ADD_COST, TR_MAX_ADD_COST, TR_REF_NUM, TR_FVL_FLAG, TR_LOC_OUT,
      TR_TBL_TYPE, TR_NATURE, TR_VAL_QTY, TR_VAL_RATE, TR_VAL_AMT, TR_VAL_AMT2, TR_REF_SQN,
      TR_BAR_CODE)
    VALUES ( LC_TR_TYPE(I),LC_TR_CP_CODE(I),LC_TR_LOC_CODE(I),LC_TR_DIT_CODE(I),LC_TR_BCH_NUM(I),
      LC_TR_LOT_NUM(I),LC_TR_EXP_DATE(I),LC_TR_DATE(I),LC_TR_DOC_NUM(I),LC_TR_SEQ_NUM(I),LC_TR_TRN_TYPE(I),LC_TR_INS_TIME(I),
      LC_TR_INS_DATE(I),LC_TR_MIN_QTY(I),LC_TR_MAX_QTY(I),LC_TR_MIN_RATE(I),LC_TR_MAX_RATE(I),LC_TR_AMT(I),LC_TR_BR_CODE(I),
      LC_TR_DAT_FLAG(I),LC_TR_MIN_ADD_COST(I),LC_TR_MAX_ADD_COST(I),LC_TR_REF_NUM(I),LC_TR_FVL_FLAG(I),LC_TR_LOC_OUT(I),
      LC_TR_TBL_TYPE(I),LC_TR_NATURE(I),LC_TR_VAL_QTY(I),LC_TR_VAL_RATE(I),LC_TR_VAL_AMT(I),LC_TR_VAL_AMT2(I),LC_TR_REF_SQN(I),
      LC_TR_BAR_CODE(I));

*/
  INSERT INTO ISR_CHECK_DSTOCK (TR_TYPE, TR_CP_CODE, TR_LOC_CODE, TR_DIT_CODE, TR_BCH_NUM,
         TR_LOT_NUM, TR_EXP_DATE, TR_DATE, TR_DOC_NUM, TR_SEQ_NUM, TR_TRN_TYPE, TR_INS_TIME,
         TR_INS_DATE, TR_MIN_QTY, TR_MAX_QTY, TR_MIN_RATE, TR_MAX_RATE, TR_AMT, TR_BR_CODE,
         TR_DAT_FLAG, TR_MIN_ADD_COST, TR_MAX_ADD_COST, TR_REF_NUM, TR_FVL_FLAG, TR_LOC_OUT,
         TR_TBL_TYPE, TR_NATURE, TR_VAL_QTY, TR_VAL_RATE, TR_VAL_AMT, TR_VAL_AMT2, TR_REF_SQN,
         TR_BAR_CODE)
  (SELECT TR_TYPE, TR_CP_CODE, TR_LOC_CODE, TR_DIT_CODE, TR_BCH_NUM,
          TR_LOT_NUM, TR_EXP_DATE, TR_DATE, TR_DOC_NUM, TR_SEQ_NUM, TR_TRN_TYPE, TR_INS_TIME,
          TR_INS_DATE, TR_MIN_QTY, TR_MAX_QTY, TR_MIN_RATE, TR_MAX_RATE, TR_AMT, TR_BR_CODE,
          TR_DAT_FLAG, TR_MIN_ADD_COST, TR_MAX_ADD_COST, TR_REF_NUM, TR_FVL_FLAG, TR_LOC_OUT,
          TR_TBL_TYPE, TR_NATURE, TR_VAL_QTY, TR_VAL_RATE, TR_VAL_AMT, TR_VAL_AMT2, TR_REF_SQN,
          TR_BAR_CODE
   FROM ALL_STOCK
   WHERE TR_DATE <= ARG_DATE
   AND   (TR_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%') OR TR_LOC_OUT LIKE NVL(ARG_LOC_CODE,'%'))
          );


------------ DATA EXISTS IN PM_BALANCE NOT IN TRANSACTION
  LC_PROCESS := '[-]TR[+]PM';

  SELECT '[-]TR[+]PM', MPB_IN_TYPE, MPB_DATE,
    TR_DOC_NUM, MPB_DIT_CODE, DIT_DESC,
    MPB_QTY, MPB_IN_SQN, MPB_LOC_CODE, MPB_IN_NUM,
    MPB_RATE, (NVL(MPB_RATE,0) * NVL(MPB_QTY,0)),
    MPB_BCH_NUM, MPB_LOT_NUM, MPB_EXP_DATE, MPB_BAR_CODE
  BULK COLLECT
  INTO  LC_RPT_NATURE, LC_RPT_TRN_TYPE, LC_RPT_DATE,
    LC_RPT_DOC_NUM, LC_RPT_DIT_CODE, LC_RPT_DIT_DESC,
    LC_RPT_QTY, LC_RPT_SEQ_NUM, LC_RPT_LOC_CODE, LC_RPT_IN_NUM,
    LC_RPT_VAL_RATE, LC_RPT_VAL_AMT,
    LC_RPT_BCH_NUM, LC_RPT_LOT_NUM, LC_RPT_EXP_DATE, LC_RPT_BAR_CODE
  FROM PPI_PM_BALANCE A
  INNER JOIN PPI_SD_ITEM ON (DIT_CP_CODE = MPB_CP_CODE AND DIT_CODE = MPB_DIT_CODE)
  LEFT JOIN ISR_CHECK_DSTOCK ON (TR_CP_CODE = MPB_CP_CODE
  AND TR_LOC_CODE = MPB_LOC_CODE
  AND TR_DOC_NUM  = MPB_IN_NUM
  AND TR_DIT_CODE = MPB_DIT_CODE
  AND TR_NATURE IN ('IN','IN/OUT'))
  WHERE TR_DOC_NUM IS NULL
  AND   MPB_DATE <= ARG_DATE
  ORDER BY MPB_IN_NUM;

    FORALL J IN LC_RPT_IN_NUM.FIRST .. LC_RPT_IN_NUM.LAST
    INSERT INTO PPI_RO_DEFICIENT_STOCK
      (RPT_CP_CODE, RPT_USR_NAME, RPT_SESSION, RPT_PRG_CODE, RPT_ID,
       RPT_NATURE, RPT_TRN_TYPE, RPT_DATE,
       RPT_DOC_NUM, RPT_DIT_CODE, RPT_DIT_DESC,
       RPT_QTY, RPT_SEQ_NUM, RPT_LOC_CODE, RPT_IN_NUM,
       RPT_VAL_RATE, RPT_VAL_AMT,
       RPT_BCH_NUM, RPT_LOT_NUM, RPT_EXP_DATE, RPT_BAR_CODE)
    VALUES (ARG_CP_CODE, ARG_USR_NAME, ARG_SESSION, ARG_PRG_CODE, ARG_RPT_ID,
      LC_RPT_NATURE(J), LC_RPT_TRN_TYPE(J), LC_RPT_DATE(J),
      LC_RPT_DOC_NUM(J), LC_RPT_DIT_CODE(J), LC_RPT_DIT_DESC(J),
      LC_RPT_QTY(J), LC_RPT_SEQ_NUM(J), LC_RPT_LOC_CODE(J), LC_RPT_IN_NUM(J),
      LC_RPT_VAL_RATE(J), LC_RPT_VAL_AMT(J),
      LC_RPT_BCH_NUM(J), LC_RPT_LOT_NUM(J), LC_RPT_EXP_DATE(J), LC_RPT_BAR_CODE(J));


------------ DATA EXISTS IN TRANSACTION NOT IN PM_BALANCE
  LC_PROCESS := '[+]TR[-]PM';

  SELECT '[+]TR[-]PM', TR_TRN_TYPE, TR_DATE,
    TR_DOC_NUM, TR_DIT_CODE, DIT_DESC,
    TR_MIN_QTY, TR_SEQ_NUM, TR_LOC_CODE, MPB_IN_NUM,
    TR_VAL_RATE, (NVL(TR_MIN_QTY,0) * NVL(TR_VAL_RATE,0)),
    TR_BCH_NUM, TR_LOT_NUM, TR_EXP_DATE, TR_BAR_CODE
  BULK COLLECT
  INTO  LC_RPT_NATURE, LC_RPT_TRN_TYPE, LC_RPT_DATE,
    LC_RPT_DOC_NUM, LC_RPT_DIT_CODE, LC_RPT_DIT_DESC,
    LC_RPT_QTY, LC_RPT_SEQ_NUM, LC_RPT_LOC_CODE, LC_RPT_IN_NUM,
    LC_RPT_VAL_RATE, LC_RPT_VAL_AMT,
    LC_RPT_BCH_NUM, LC_RPT_LOT_NUM, LC_RPT_EXP_DATE, LC_RPT_BAR_CODE
  FROM ISR_CHECK_DSTOCK A
  INNER JOIN PPI_SD_ITEM ON (DIT_CP_CODE = TR_CP_CODE AND DIT_CODE = TR_DIT_CODE)
  LEFT JOIN  PPI_PM_BALANCE  ON (TR_CP_CODE = MPB_CP_CODE
  AND TR_LOC_CODE = MPB_LOC_CODE
  AND TR_DOC_NUM  = MPB_IN_NUM
  AND TR_DIT_CODE = MPB_DIT_CODE)
  WHERE MPB_IN_NUM IS NULL
  AND TR_NATURE IN ('IN','IN/OUT')
  AND TR_DATE <= ARG_DATE
  ORDER BY TR_DOC_NUM;

    FORALL K IN LC_RPT_DOC_NUM.FIRST .. LC_RPT_DOC_NUM.LAST
    INSERT INTO PPI_RO_DEFICIENT_STOCK
      (RPT_CP_CODE, RPT_USR_NAME, RPT_SESSION, RPT_PRG_CODE, RPT_ID,
       RPT_NATURE, RPT_TRN_TYPE, RPT_DATE,
       RPT_DOC_NUM, RPT_DIT_CODE, RPT_DIT_DESC,
       RPT_QTY, RPT_SEQ_NUM, RPT_LOC_CODE, RPT_IN_NUM,
       RPT_VAL_RATE, RPT_VAL_AMT,
       RPT_BCH_NUM, RPT_LOT_NUM, RPT_EXP_DATE, RPT_BAR_CODE)
    VALUES (ARG_CP_CODE, ARG_USR_NAME, ARG_SESSION, ARG_PRG_CODE, ARG_RPT_ID,
      LC_RPT_NATURE(K), LC_RPT_TRN_TYPE(K), LC_RPT_DATE(K),
      LC_RPT_DOC_NUM(K), LC_RPT_DIT_CODE(K), LC_RPT_DIT_DESC(K),
      LC_RPT_QTY(K), LC_RPT_SEQ_NUM(K), LC_RPT_LOC_CODE(K), LC_RPT_IN_NUM(K),
      LC_RPT_VAL_RATE(K), LC_RPT_VAL_AMT(K),
      LC_RPT_BCH_NUM(K), LC_RPT_LOT_NUM(K), LC_RPT_EXP_DATE(K), LC_RPT_BAR_CODE(K));


------------ DATA EXISTS IN PD_BALANCE NOT IN TRANSACTION
  LC_PROCESS := '[-]TR[+]PD';

  SELECT '[-]TR[+]PD', DPB_OUT_TYPE, DPB_TRS_DATE,
    TR_DOC_NUM, DPB_DIT_CODE, DIT_DESC,
    DPB_QTY, DPB_OUT_SQN, DPB_LOC_CODE, DPB_OUT_NUM,
    DPB_RATE, (NVL(DPB_RATE,0) * NVL(DPB_QTY,0)),
    DPB_BCH_NUM, NULL, DPB_EXP_DATE, DPB_BAR_CODE
  BULK COLLECT
  INTO  LC_RPT_NATURE, LC_RPT_TRN_TYPE, LC_RPT_DATE,
    LC_RPT_DOC_NUM, LC_RPT_DIT_CODE, LC_RPT_DIT_DESC,
    LC_RPT_QTY, LC_RPT_SEQ_NUM, LC_RPT_LOC_CODE, LC_RPT_IN_NUM,
    LC_RPT_VAL_RATE, LC_RPT_VAL_AMT,
    LC_RPT_BCH_NUM, LC_RPT_LOT_NUM, LC_RPT_EXP_DATE, LC_RPT_BAR_CODE
  FROM PPI_PD_BALANCE A
  INNER JOIN PPI_SD_ITEM ON (DIT_CP_CODE = DPB_CP_CODE AND DIT_CODE = DPB_DIT_CODE)
  LEFT JOIN ISR_CHECK_DSTOCK ON (TR_CP_CODE = DPB_CP_CODE
  AND TR_LOC_OUT = DPB_LOC_CODE
  AND TR_DOC_NUM  = DPB_OUT_NUM
  AND TR_DIT_CODE = DPB_DIT_CODE
  AND TR_NATURE IN ('OUT','IN/OUT'))
  WHERE TR_DOC_NUM IS NULL
  AND   DPB_TRS_DATE <= ARG_DATE
  ORDER BY DPB_OUT_NUM;

    FORALL L IN LC_RPT_IN_NUM.FIRST .. LC_RPT_IN_NUM.LAST
    INSERT INTO PPI_RO_DEFICIENT_STOCK
      (RPT_CP_CODE, RPT_USR_NAME, RPT_SESSION, RPT_PRG_CODE, RPT_ID,
       RPT_NATURE, RPT_TRN_TYPE, RPT_DATE,
       RPT_DOC_NUM, RPT_DIT_CODE, RPT_DIT_DESC,
       RPT_QTY, RPT_SEQ_NUM, RPT_LOC_CODE, RPT_IN_NUM,
       RPT_VAL_RATE, RPT_VAL_AMT,
       RPT_BCH_NUM, RPT_LOT_NUM, RPT_EXP_DATE, RPT_BAR_CODE)
    VALUES (ARG_CP_CODE, ARG_USR_NAME, ARG_SESSION, ARG_PRG_CODE, ARG_RPT_ID,
      LC_RPT_NATURE(L), LC_RPT_TRN_TYPE(L), LC_RPT_DATE(L),
      LC_RPT_DOC_NUM(L), LC_RPT_DIT_CODE(L), LC_RPT_DIT_DESC(L),
      LC_RPT_QTY(L), LC_RPT_SEQ_NUM(L), LC_RPT_LOC_CODE(L), LC_RPT_IN_NUM(L),
      LC_RPT_VAL_RATE(L), LC_RPT_VAL_AMT(L),
      LC_RPT_BCH_NUM(L), LC_RPT_LOT_NUM(L), LC_RPT_EXP_DATE(L), LC_RPT_BAR_CODE(L));

------------ DATA EXISTS IN TRANSACTION NOT IN PD_BALANCE
  LC_PROCESS := '[+]TR[-]PD';

  SELECT '[+]TR[-]PD', TR_TRN_TYPE, TR_DATE,
    TR_DOC_NUM, TR_DIT_CODE, DIT_DESC,
    TR_MIN_QTY, TR_SEQ_NUM, TR_LOC_OUT, DPB_OUT_NUM,
    TR_VAL_RATE, (NVL(TR_MIN_QTY,0) * NVL(TR_VAL_RATE,0)),
    TR_BCH_NUM, TR_LOT_NUM, TR_EXP_DATE, TR_BAR_CODE
  BULK COLLECT
  INTO  LC_RPT_NATURE, LC_RPT_TRN_TYPE, LC_RPT_DATE,
    LC_RPT_DOC_NUM, LC_RPT_DIT_CODE, LC_RPT_DIT_DESC,
    LC_RPT_QTY, LC_RPT_SEQ_NUM, LC_RPT_LOC_CODE, LC_RPT_IN_NUM,
    LC_RPT_VAL_RATE, LC_RPT_VAL_AMT,
    LC_RPT_BCH_NUM, LC_RPT_LOT_NUM, LC_RPT_EXP_DATE, LC_RPT_BAR_CODE
  FROM ISR_CHECK_DSTOCK A
  INNER JOIN PPI_SD_ITEM ON (DIT_CP_CODE = TR_CP_CODE AND DIT_CODE = TR_DIT_CODE)
  LEFT JOIN PPI_PD_BALANCE ON (TR_CP_CODE = DPB_CP_CODE
  AND TR_LOC_OUT = DPB_LOC_CODE
  AND TR_DOC_NUM  = DPB_OUT_NUM
  AND TR_DIT_CODE = DPB_DIT_CODE)
  WHERE DPB_OUT_NUM IS NULL
  AND TR_NATURE IN ('OUT','IN/OUT')
  AND TR_DATE <= ARG_DATE
  ORDER BY TR_DOC_NUM;

    FORALL M IN LC_RPT_DOC_NUM.FIRST .. LC_RPT_DOC_NUM.LAST
    INSERT INTO PPI_RO_DEFICIENT_STOCK
      (RPT_CP_CODE, RPT_USR_NAME, RPT_SESSION, RPT_PRG_CODE, RPT_ID,
       RPT_NATURE, RPT_TRN_TYPE, RPT_DATE,
       RPT_DOC_NUM, RPT_DIT_CODE, RPT_DIT_DESC,
       RPT_QTY, RPT_SEQ_NUM, RPT_LOC_CODE, RPT_IN_NUM,
       RPT_VAL_RATE, RPT_VAL_AMT,
       RPT_BCH_NUM, RPT_LOT_NUM, RPT_EXP_DATE, RPT_BAR_CODE)
    VALUES (ARG_CP_CODE, ARG_USR_NAME, ARG_SESSION, ARG_PRG_CODE, ARG_RPT_ID,
      LC_RPT_NATURE(M), LC_RPT_TRN_TYPE(M), LC_RPT_DATE(M),
      LC_RPT_DOC_NUM(M), LC_RPT_DIT_CODE(M), LC_RPT_DIT_DESC(M),
      LC_RPT_QTY(M), LC_RPT_SEQ_NUM(M), LC_RPT_LOC_CODE(M), LC_RPT_IN_NUM(M),
      LC_RPT_VAL_RATE(M), LC_RPT_VAL_AMT(M),
      LC_RPT_BCH_NUM(M), LC_RPT_LOT_NUM(M), LC_RPT_EXP_DATE(M), LC_RPT_BAR_CODE(M));

  COMMIT;

  ARG_ERR := 'T';
EXCEPTION WHEN OTHERS THEN
  ARG_ERR := LC_PROCESS || ' ' || SQLCODE || ' ' || SQLERRM;
END;
/

