prompt Creating procedure GET_UPDATE_PRINT_FLAG
prompt ========================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.GET_UPDATE_PRINT_FLAG(LC_CP_CODE VARCHAR2,
                                                  LC_BR_CODE VARCHAR2) IS

  LC_DELAY NUMBER;

  LC_CNT NUMBER;

BEGIN

  BEGIN
    SELECT NVL(ISR_LAB_SMN_DELAY_MINUTES, 5)
      INTO LC_DELAY
      FROM ISR_XO_CONTROL;
  EXCEPTION
    WHEN OTHERS THEN
      LC_DELAY := 5;
  END;

     SELECT COUNT(*)
     INTO  LC_CNT
     FROM  HOS_TM_OPD_SRV_RCPT A
     WHERE A.MSR_CP_CODE = LC_CP_CODE
     AND   A.MSR_BR_CODE = LC_BR_CODE
     AND 0 <> (SELECT COUNT(*)
                 FROM HOS_TD_OPD_SRV_RCPT
                 WHERE DSR_CP_CODE = LC_CP_CODE
                 AND DSR_MSR_NUM = A.MSR_NUM)
     AND TO_DATE(TO_CHAR(A.MSR_INS_DATE, 'DD-MON-YYYY') || ' ' ||A.MSR_INS_TIME, 'DD-MON-YYYY HH24:MI:SS') <
         TO_DATE(TO_CHAR(SYSDATE - LC_DELAY / 60 / 24, 'DD-MM-YYYY HH24:MI:SS'), 'DD-MM-YYYY HH24:MI:SS')
     AND NVL(A.MSR_PRT_FLAG, 'N') = 'N';

  IF LC_CNT <> 0 THEN

    BEGIN
      UPDATE HOS_TM_OPD_SRV_RCPT A
         SET A.MSR_PRT_FLAG = 'Y'
       WHERE A.MSR_CP_CODE = LC_CP_CODE
         AND A.MSR_BR_CODE = LC_BR_CODE
         AND 0 <> (SELECT COUNT(*)
                     FROM HOS_TD_OPD_SRV_RCPT
                    WHERE DSR_CP_CODE = LC_CP_CODE
                      AND DSR_MSR_NUM = A.MSR_NUM)
         AND TO_DATE(TO_CHAR(A.MSR_INS_DATE, 'DD-MON-YYYY') || ' ' ||
                     A.MSR_INS_TIME,
                     'DD-MON-YYYY HH24:MI:SS') <
             TO_DATE(TO_CHAR(SYSDATE - LC_DELAY / 60 / 24,
                             'DD-MM-YYYY HH24:MI:SS'),
                     'DD-MM-YYYY HH24:MI:SS')
         AND NVL(A.MSR_PRT_FLAG, 'N') = 'N';

      COMMIT;
    END;
  END IF;
END;
/

