prompt Creating procedure ISR_AUD_UTL_GEN_QUERY
prompt ========================================
prompt
create or replace procedure mdhsys.ISR_AUD_utl_gen_query
(arg_tab_name varchar2, arg_user_name varchar2, arg_fm_date date, arg_to_date date, arg_action varchar2)
is
---------------- TMP
/*
DECLARE
   arg_tab_name  varchar2(30);
   arg_user_name varchar2(30);
   arg_fm_date   date;
   arg_to_date   date;
   arg_action    varchar2(1);  */
------------- TMP

   path          varchar2(30);
   file_name      varchar2(60);
   output_file   utl_file.file_type;
   tab_name      varchar2(30);
   syn_name      varchar2(50);
   lc_user_name  varchar2(30);

   lc_str_sel      varchar2(10000);
   lc_str_col      varchar2(10000);
   lc_hd_col       varchar2(10000);
   lc_where_clause varchar2(10000);

   lc_val          varchar2(10000);
   tot_rows        number;
   col_name        ISR_SD_TAB_INFO_AUD.dti_col_name%type;
   col_count       number;

   TYPE        CurTyp IS REF CURSOR;
   crs         CurTyp;

cursor sel_crs is
   select dti_col_name
   from   ISR_SD_TAB_INFO_AUD
   where  dti_mti_tab_name like tab_name
   and    dti_flag = 'Y';

begin
---------------  TMP
/*
arg_tab_name  := 'PAY_SM_SHIFT_INFO';
arg_user_name := 'SYSTEM';
arg_fm_date   := '23-SEP-2014';
arg_to_date   := '23-SEP-2014';
arg_action    := '';
*/
--------------- TMP
   DBMS_OUTPUT.PUT_LINE('INSIDE PROCEDURE ');
   path     := 'TEMP';

--DBMS_OUTPUT.PUT_LINE('FILENAME IS '||FILENAME);
   select user
   into   lc_user_name
   from dual;
   tab_name := arg_tab_name;
   file_name := tab_name||to_char(sysdate,'yyyymmdd');
   syn_name := lc_user_name||'_AUD'||'.'||arg_tab_name||'_AUD';



   select count(*) into tot_rows
   from   ISR_SD_TAB_INFO_AUD
   where  dti_mti_tab_name like tab_name
   and    dti_flag = 'Y';

   for sel_rec in sel_crs loop
      col_name := sel_rec.dti_col_name;
      col_count := nvl(col_count,0) + 1;
      lc_str_col := lc_str_col ||' '||COL_NAME;
      lc_hd_col  := lc_hd_col  ||' '||COL_NAME;
      if tot_rows <> col_count then
         lc_str_col := lc_str_col ||'||chr(9)||';
         lc_hd_col := ' '||lc_hd_col||' ' ||chr(9);
      end if;
      --dbms_output.put_line('lc_str_col  '||lc_str_col);
   end loop;

   lc_where_clause := ' where aud_user_name like NVL('||''''||arg_user_name ||''''||','||''''||'%'||''''||')'||
                      ' and aud_date between '||''''||arg_fm_date||''''||' and '||''''||arg_to_date||''''||
                      ' and  aud_action like NVL('||''''||arg_action ||''''||','||''''||'%'||''''||')'|| '';



   dbms_output.put_line(lc_where_clause);

   lc_str_sel := 'select '||lc_str_col|| ' from '||syn_name ||' '||lc_where_clause;

   dbms_output.put_line('lc_str_sel '||lc_str_sel);

   output_file := utl_file.fopen (path,file_name, 'W');
   dbms_output.put_line('will open the cursor ');
   OPEN crs FOR lc_str_sel;
   utl_file.put_line (output_file, lc_hd_col);
   LOOP
     FETCH crs INTO lc_val;
     EXIT WHEN crs%NOTFOUND;
     utl_file.put_line (output_file, lc_val);
   END LOOP;
   CLOSE crs;
   utl_file.fclose(output_file);
END;
/

