prompt Creating procedure SEND_MAIL
prompt ============================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.send_mail (p_to        IN VARCHAR2,
                                       p_from      IN VARCHAR2,
                                       p_subject   IN VARCHAR2,
                                       p_text_msg  IN VARCHAR2 DEFAULT NULL,
                                       p_html_msg  IN VARCHAR2 DEFAULT NULL,
                                       p_smtp_host IN VARCHAR2,
                                       p_smtp_port IN NUMBER DEFAULT 25)
AS
  l_mail_conn   UTL_SMTP.connection;
  l_boundary    VARCHAR2(50) := '----=*#abc1234321cba#*=';
BEGIN
  l_mail_conn := UTL_SMTP.open_connection(p_smtp_host, p_smtp_port);
  UTL_SMTP.helo(l_mail_conn, p_smtp_host);
  UTL_SMTP.mail(l_mail_conn, p_from);
  UTL_SMTP.rcpt(l_mail_conn, p_to);

  UTL_SMTP.open_data(l_mail_conn);

  UTL_SMTP.write_data(l_mail_conn, 'Date: ' || TO_CHAR(SYSDATE, 'DD-MON-YYYY HH24:MI:SS') || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'To: ' || p_to || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'From: ' || p_from || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Subject: ' || p_subject || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Reply-To: ' || p_from || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'MIME-Version: 1.0' || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Content-Type: multipart/alternative; boundary="' || l_boundary || '"' || UTL_TCP.crlf || UTL_TCP.crlf);

  IF p_text_msg IS NOT NULL THEN
    UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Type: text/plain; charset="iso-8859-1"' || UTL_TCP.crlf || UTL_TCP.crlf);

    UTL_SMTP.write_data(l_mail_conn, p_text_msg);
    UTL_SMTP.write_data(l_mail_conn, UTL_TCP.crlf || UTL_TCP.crlf);
  END IF;

  IF p_html_msg IS NOT NULL THEN
    UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Type: text/html; charset="iso-8859-1"' || UTL_TCP.crlf || UTL_TCP.crlf);

    UTL_SMTP.write_data(l_mail_conn, p_html_msg);
    UTL_SMTP.write_data(l_mail_conn, UTL_TCP.crlf || UTL_TCP.crlf);
  END IF;

  UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || '--' || UTL_TCP.crlf);
  UTL_SMTP.close_data(l_mail_conn);

  UTL_SMTP.quit(l_mail_conn);
END;
/

prompt
prompt Creating procedure SEND_MAIL_BLOB
prompt =================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.send_mail_blob (p_to          IN VARCHAR2,
                                       p_from        IN VARCHAR2,
                                       p_subject     IN VARCHAR2,
                                       p_text_msg    IN VARCHAR2 DEFAULT NULL,
                                       p_attach_name IN VARCHAR2 DEFAULT NULL,
                                       p_attach_mime IN VARCHAR2 DEFAULT NULL,
                                       p_attach_blob IN BLOB DEFAULT NULL,
                                       p_smtp_host   IN VARCHAR2,
                                       p_smtp_port   IN NUMBER DEFAULT 25)
AS
  l_mail_conn   UTL_SMTP.connection;
  l_boundary    VARCHAR2(50) := '----=*#abc1234321cba#*=';
  l_step        PLS_INTEGER  := 12000; -- make sure you set a multiple of 3 not higher than 24573
    v_username_b64 varchar2(2500);
   v_password_b64 varchar2(2500);
BEGIN

   v_username_b64 :=
        UTL_RAW.cast_to_varchar2(
            UTL_ENCODE.base64_encode(UTL_RAW.cast_to_raw('lab.akhn@alkhidmat.com'))
        );

    v_password_b64 :=
        UTL_RAW.cast_to_varchar2(
            UTL_ENCODE.base64_encode(UTL_RAW.cast_to_raw('lab.akhn'))
        );

    l_mail_conn := UTL_SMTP.open_connection(p_smtp_host, p_smtp_port);
    UTL_SMTP.ehlo(l_mail_conn, 'alkhidmat.com');    -- Must use EHLO  vs HELO
    UTL_SMTP.command(l_mail_conn, 'AUTH', 'LOGIN');  -- should receive a 334 response, prompting for username
    UTL_SMTP.command(l_mail_conn, v_username_b64);   -- should receive a 334 response, prompting for password
    UTL_SMTP.command(l_mail_conn, v_password_b64);   -- should receive a 235 response, you are authenticated


---  l_mail_conn := UTL_SMTP.open_connection(p_smtp_host, p_smtp_port);
  UTL_SMTP.helo(l_mail_conn, p_smtp_host);
  UTL_SMTP.mail(l_mail_conn, p_from);
  UTL_SMTP.rcpt(l_mail_conn, p_to);

  UTL_SMTP.open_data(l_mail_conn);

  UTL_SMTP.write_data(l_mail_conn, 'Date: ' || TO_CHAR(SYSDATE, 'DD-MON-YYYY HH24:MI:SS') || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'To: ' || p_to || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'From: ' || p_from || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Subject: ' || p_subject || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Reply-To: ' || p_from || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'MIME-Version: 1.0' || UTL_TCP.crlf);
  UTL_SMTP.write_data(l_mail_conn, 'Content-Type: multipart/mixed; boundary="' || l_boundary || '"' || UTL_TCP.crlf || UTL_TCP.crlf);

  IF p_text_msg IS NOT NULL THEN
    UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Type: text/plain; charset="iso-8859-1"' || UTL_TCP.crlf || UTL_TCP.crlf);

    UTL_SMTP.write_data(l_mail_conn, p_text_msg);
    UTL_SMTP.write_data(l_mail_conn, UTL_TCP.crlf || UTL_TCP.crlf);
  END IF;

  IF p_attach_name IS NOT NULL THEN
    UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Type: ' || p_attach_mime || '; name="' || p_attach_name || '"' || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Transfer-Encoding: base64' || UTL_TCP.crlf);
    UTL_SMTP.write_data(l_mail_conn, 'Content-Disposition: attachment; filename="' || p_attach_name || '"' || UTL_TCP.crlf || UTL_TCP.crlf);

    FOR i IN 0 .. TRUNC((DBMS_LOB.getlength(p_attach_blob) - 1 )/l_step) LOOP
      UTL_SMTP.write_data(l_mail_conn, UTL_RAW.cast_to_varchar2(UTL_ENCODE.base64_encode(DBMS_LOB.substr(p_attach_blob, l_step, i * l_step + 1))));
    END LOOP;

    UTL_SMTP.write_data(l_mail_conn, UTL_TCP.crlf || UTL_TCP.crlf);
  END IF;

  UTL_SMTP.write_data(l_mail_conn, '--' || l_boundary || '--' || UTL_TCP.crlf);
  UTL_SMTP.close_data(l_mail_conn);

  UTL_SMTP.quit(l_mail_conn);
END;
/

prompt
prompt Creating procedure SET_ITEM_ACTIVITY
prompt ====================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.SET_ITEM_ACTIVITY(ARG_CP_CODE     VARCHAR2,
                                              ARG_USR_NAME    VARCHAR2,
                                              ARG_SESSION     VARCHAR2,
                                              ARG_PRG_CODE    VARCHAR2,
                                              RPT_SEQ_NUM     VARCHAR2,
                                              ARG_DATE_FM     DATE,
                                              ARG_DATE_TO     DATE,
                                              ARG_DIT_CODE_FM VARCHAR2,
                                              ARG_DIT_CODE_TO VARCHAR2,
                                              ARG_LOC_CODE    VARCHAR2 , ARG_RPT_ID VARCHAR2 , ARG_CTG_CODE VARCHAR2) IS

  TYPE DIT_CODE_T IS TABLE OF PPI_SD_ITEM.DIT_CODE%TYPE;
  TYPE DIT_CP_CODE_T IS TABLE OF PPI_SD_ITEM.DIT_CP_CODE%TYPE;
  TYPE DIT_DESC_T IS TABLE OF PPI_SD_ITEM.DIT_DESC%TYPE;

  TYPE LC_QTY_OB_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SP_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_IN_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SL_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_PR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_OUT_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_STK_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;

  TYPE LC_AMT_OB_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SP_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_IN_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SL_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_PR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_OUT_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_STK_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;

  LC_DIT_CODE    DIT_CODE_T;
  LC_DIT_CP_CODE DIT_CP_CODE_T;
  LC_DIT_DESC    DIT_DESC_T;

  LC_QTY_OB  LC_QTY_OB_T;
  LC_QTY_SP  LC_QTY_SP_T;
  LC_QTY_SR  LC_QTY_SR_T;
  LC_QTY_IN  LC_QTY_IN_T;
  LC_QTY_SL  LC_QTY_SL_T;
  LC_QTY_PR  LC_QTY_PR_T;
  LC_QTY_OUT LC_QTY_OUT_T;
  LC_QTY_STK LC_QTY_STK_T;
  LC_AMT_OB  LC_AMT_OB_T;
  LC_AMT_SP  LC_AMT_SP_T;
  LC_AMT_SR  LC_AMT_SR_T;
  LC_AMT_IN  LC_AMT_IN_T;
  LC_AMT_SL  LC_AMT_SL_T;
  LC_AMT_PR  LC_AMT_PR_T;
  LC_AMT_OUT LC_AMT_OUT_T;
  LC_AMT_STK LC_AMT_STK_T;

BEGIN

  SELECT DIT_CODE,
         DIT_CP_CODE,
         DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,
         (LC_QTY_OB + LC_QTY_SP + LC_QTY_SR + LC_QTY_IN) -
         (LC_QTY_SL + LC_QTY_PR + LC_QTY_OUT) AS LC_QTY_STK,
         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,
         (LC_AMT_OB + LC_AMT_SP + LC_AMT_SR + LC_AMT_IN) -
         (LC_AMT_SL + LC_AMT_PR + LC_AMT_OUT) AS LC_AMT_STK BULK COLLECT

    INTO LC_DIT_CODE,
         LC_DIT_CP_CODE,
         LC_DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,

         LC_QTY_STK,

         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,

         LC_AMT_STK

    FROM (SELECT DIT_CODE,
                 DIT_CP_CODE,
                 DIT_DESC,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'Q',
                                   ARG_CTG_CODE) -
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_OB,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_SP,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_SR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_IN,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_SL,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_PR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'Q',
                                   ARG_CTG_CODE) AS LC_QTY_OUT,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'A',
                                   ARG_CTG_CODE) -
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_OB,

                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_SP,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_SR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_IN,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_SL,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_PR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'A',
                                   ARG_CTG_CODE) AS LC_AMT_OUT
            FROM PPI_SD_ITEM
           WHERE DIT_CP_CODE = ARG_CP_CODE
             AND (GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE)

                 LIKE NVL(GET_USER_CTG_DEPT(ARG_CP_CODE, ARG_USR_NAME, 'C'),NVL(ARG_CTG_CODE,'%'))
                 OR  NVL(DIT_COM,'N')  = 'Y'  )

             AND DIT_CODE BETWEEN ARG_DIT_CODE_FM  AND ARG_DIT_CODE_TO);

  FORALL I IN LC_DIT_CODE.FIRST .. LC_DIT_CODE.LAST

    INSERT INTO PPI_RO_ITEM_ACTVTY
      (RPT_CP_CODE,
       RPT_USR_NAME,
       RPT_SESSION,
       RPT_PRG_CODE,
       RPT_SEQ_NUM,
       RPT_DIT_CODE,
       RPT_DIT_DESC,
       RPT_QTY01,
       RPT_QTY02,
       RPT_QTY03,
       RPT_QTY04,
       RPT_QTY05,
       RPT_QTY06,
       RPT_QTY07,
       RPT_QTY_STK,
       RPT_AMT01,
       RPT_AMT02,
       RPT_AMT03,
       RPT_AMT04,
       RPT_AMT05,
       RPT_AMT06,
       RPT_AMT07,
       RPT_AMT_STK , RPT_RPT_ID )
    VALUES
      (ARG_CP_CODE,
       ARG_USR_NAME,
       ARG_SESSION,
       ARG_PRG_CODE,
       NULL,
       LC_DIT_CODE(I),
       LC_DIT_DESC(I),
       LC_QTY_OB(I),
       LC_QTY_SP(I),
       LC_QTY_SR(I),
       LC_QTY_IN(I),
       LC_QTY_SL(I),
       LC_QTY_PR(I),
       LC_QTY_OUT(I),
       LC_QTY_STK(I),
       LC_AMT_OB(I),
       LC_AMT_SP(I),
       LC_AMT_SR(I),
       LC_AMT_IN(I),
       LC_AMT_SL(I),
       LC_AMT_PR(I),
       LC_AMT_OUT(I),
       LC_AMT_STK(I) , ARG_RPT_ID );

  COMMIT;
END;
/

