BEGIN

  SELECT DIT_CODE,
         DIT_CP_CODE,
         DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,
         (LC_QTY_OB + LC_QTY_SP + LC_QTY_SR + LC_QTY_IN) -
         (LC_QTY_SL + LC_QTY_PR + LC_QTY_OUT) AS LC_QTY_STK,
         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,
         (LC_AMT_OB + LC_AMT_SP + LC_AMT_SR + LC_AMT_IN) -
         (LC_AMT_SL + LC_AMT_PR + LC_AMT_OUT) AS LC_AMT_STK BULK COLLECT

    INTO LC_DIT_CODE,
         LC_DIT_CP_CODE,
         LC_DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,

         LC_QTY_STK,

         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,

         LC_AMT_STK

    FROM (SELECT DIT_CODE,
                 DIT_CP_CODE,
                 DIT_DESC,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'Q') -
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'Q') AS LC_QTY_OB,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'Q') AS LC_QTY_SP,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'Q') AS LC_QTY_SR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'Q') AS LC_QTY_IN,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'Q') AS LC_QTY_SL,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'Q') AS LC_QTY_PR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'Q') AS LC_QTY_OUT,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'A') -
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'A') AS LC_AMT_OB,

                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'A') AS LC_AMT_SP,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'A') AS LC_AMT_SR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'A') AS LC_AMT_IN,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'A') AS LC_AMT_SL,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'A') AS LC_AMT_PR,
                 GET_ITEM_ACTIVITY(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'A') AS LC_AMT_OUT
            FROM PPI_SD_ITEM
           WHERE DIT_CP_CODE = ARG_CP_CODE
             AND (GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE) LIKE
                 NVL(GET_USER_CTG_DEPT(ARG_CP_CODE, ARG_USR_NAME, 'C'), '%') OR
                 NVL(DIT_COM, 'N') = 'Y')
             AND DIT_CODE BETWEEN ARG_DIT_CODE_FM  AND ARG_DIT_CODE_TO);

  FORALL I IN LC_DIT_CODE.FIRST .. LC_DIT_CODE.LAST

    INSERT INTO PPI_RO_ITEM_ACTVTY
      (RPT_CP_CODE,
       RPT_USR_NAME,
       RPT_SESSION,
       RPT_PRG_CODE,
       RPT_SEQ_NUM,
       RPT_DIT_CODE,
       RPT_DIT_DESC,
       RPT_QTY01,
       RPT_QTY02,
       RPT_QTY03,
       RPT_QTY04,
       RPT_QTY05,
       RPT_QTY06,
       RPT_QTY07,
       RPT_QTY_STK,
       RPT_AMT01,
       RPT_AMT02,
       RPT_AMT03,
       RPT_AMT04,
       RPT_AMT05,
       RPT_AMT06,
       RPT_AMT07,
       RPT_AMT_STK , RPT_RPT_ID )
    VALUES
      (ARG_CP_CODE,
       ARG_USR_NAME,
       ARG_SESSION,
       ARG_PRG_CODE,
       NULL,
       LC_DIT_CODE(I),
       LC_DIT_DESC(I),
       LC_QTY_OB(I),
       LC_QTY_SP(I),
       LC_QTY_SR(I),
       LC_QTY_IN(I),
       LC_QTY_SL(I),
       LC_QTY_PR(I),
       LC_QTY_OUT(I),
       LC_QTY_STK(I),
       LC_AMT_OB(I),
       LC_AMT_SP(I),
       LC_AMT_SR(I),
       LC_AMT_IN(I),
       LC_AMT_SL(I),
       LC_AMT_PR(I),
       LC_AMT_OUT(I),
       LC_AMT_STK(I) , ARG_RPT_ID );

  COMMIT;
END;
/

prompt
prompt Creating procedure SET_ITEM_ACTIVITY_RPT
prompt ========================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS.SET_ITEM_ACTIVITY_RPT(ARG_CP_CODE     VARCHAR2,
                                                  ARG_USR_NAME    VARCHAR2,
                                                  ARG_SESSION     VARCHAR2,
                                                  ARG_PRG_CODE    VARCHAR2,
                                                  RPT_SEQ_NUM     VARCHAR2,
                                                  ARG_DATE_FM     DATE,
                                                  ARG_DATE_TO     DATE,
                                                  ARG_DIT_CODE_FM VARCHAR2,
                                                  ARG_DIT_CODE_TO VARCHAR2,
                                                  ARG_LOC_CODE    VARCHAR2,
                                                  ARG_RPT_ID      VARCHAR2,
                                                  ARG_CTG_CODE    VARCHAR2,
                                                  ARG_MANUFAC     VARCHAR2) IS

  TYPE DIT_CODE_T IS TABLE OF PPI_SD_ITEM.DIT_CODE%TYPE;
  TYPE DIT_CP_CODE_T IS TABLE OF PPI_SD_ITEM.DIT_CP_CODE%TYPE;
  TYPE DIT_DESC_T IS TABLE OF PPI_SD_ITEM.DIT_DESC%TYPE;

  TYPE LC_QTY_OB_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SP_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_IN_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_SL_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_PR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_OUT_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_QTY_STK_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;

  TYPE LC_AMT_OB_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SP_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_IN_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_SL_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_PR_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_OUT_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;
  TYPE LC_AMT_STK_T IS TABLE OF PPI_RO_ITEM_ACTVTY.RPT_QTY01%TYPE;

  LC_DIT_CODE    DIT_CODE_T;
  LC_DIT_CP_CODE DIT_CP_CODE_T;
  LC_DIT_DESC    DIT_DESC_T;

  LC_QTY_OB  LC_QTY_OB_T;
  LC_QTY_SP  LC_QTY_SP_T;
  LC_QTY_SR  LC_QTY_SR_T;
  LC_QTY_IN  LC_QTY_IN_T;
  LC_QTY_SL  LC_QTY_SL_T;
  LC_QTY_PR  LC_QTY_PR_T;
  LC_QTY_OUT LC_QTY_OUT_T;
  LC_QTY_STK LC_QTY_STK_T;
  LC_AMT_OB  LC_AMT_OB_T;
  LC_AMT_SP  LC_AMT_SP_T;
  LC_AMT_SR  LC_AMT_SR_T;
  LC_AMT_IN  LC_AMT_IN_T;
  LC_AMT_SL  LC_AMT_SL_T;
  LC_AMT_PR  LC_AMT_PR_T;
  LC_AMT_OUT LC_AMT_OUT_T;
  LC_AMT_STK LC_AMT_STK_T;

BEGIN

  SELECT DIT_CODE,
         DIT_CP_CODE,
         DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,
         (LC_QTY_OB + LC_QTY_SP + LC_QTY_SR + LC_QTY_IN) -
         (LC_QTY_SL + LC_QTY_PR + LC_QTY_OUT) AS LC_QTY_STK,
         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,
         (LC_AMT_OB + LC_AMT_SP + LC_AMT_SR + LC_AMT_IN) -
         (LC_AMT_SL + LC_AMT_PR + LC_AMT_OUT) AS LC_AMT_STK BULK COLLECT

    INTO LC_DIT_CODE,
         LC_DIT_CP_CODE,
         LC_DIT_DESC,
         LC_QTY_OB,
         LC_QTY_SP,
         LC_QTY_SR,
         LC_QTY_IN,
         LC_QTY_SL,
         LC_QTY_PR,
         LC_QTY_OUT,

         LC_QTY_STK,

         LC_AMT_OB,
         LC_AMT_SP,
         LC_AMT_SR,
         LC_AMT_IN,
         LC_AMT_SL,
         LC_AMT_PR,
         LC_AMT_OUT,

         LC_AMT_STK

    FROM (SELECT DIT_CODE,
                 DIT_CP_CODE,
                 DIT_DESC,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) -
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_OB,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_SP,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_SR,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_IN,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_SL,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_PR,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'Q',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_QTY_OUT,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PM',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) -
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PD',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_OB,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SP',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_SP,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SR',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_SR,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'IN',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_IN,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'SL',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_SL,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'PR',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_PR,
                 GET_ITEM_ACTIVITY_RPT(DIT_CP_CODE,
                                   DIT_CODE,
                                   ARG_DATE_FM,
                                   ARG_DATE_TO,
                                   ARG_LOC_CODE,
                                   'OUT',
                                   'A',
                                   ARG_CTG_CODE,
                                   ARG_MANUFAC) AS LC_AMT_OUT
             FROM  PPI_SD_ITEM
             WHERE DIT_CP_CODE = ARG_CP_CODE
             AND  (GET_ITEM_CATEGORY(ARG_CP_CODE, PPI_SD_ITEM.DIT_CODE)
             LIKE  NVL(GET_USER_CTG_DEPT(ARG_CP_CODE, ARG_USR_NAME, 'C'),NVL(ARG_CTG_CODE,'%'))
             OR    NVL(DIT_COM,'N')  = 'Y'  )
             AND   NVL(DIT_MANUFAC,'%') LIKE NVL(ARG_MANUFAC,'%')
             AND   DIT_CODE BETWEEN ARG_DIT_CODE_FM  AND ARG_DIT_CODE_TO);

  FORALL I IN LC_DIT_CODE.FIRST .. LC_DIT_CODE.LAST

    INSERT INTO PPI_RO_ITEM_ACTVTY
      (RPT_CP_CODE,
       RPT_USR_NAME,
       RPT_SESSION,
       RPT_PRG_CODE,
       RPT_SEQ_NUM,
       RPT_DIT_CODE,
       RPT_DIT_DESC,
       RPT_QTY01,
       RPT_QTY02,
       RPT_QTY03,
       RPT_QTY04,
       RPT_QTY05,
       RPT_QTY06,
       RPT_QTY07,
       RPT_QTY_STK,
       RPT_AMT01,
       RPT_AMT02,
       RPT_AMT03,
       RPT_AMT04,
       RPT_AMT05,
       RPT_AMT06,
       RPT_AMT07,
       RPT_AMT_STK , RPT_RPT_ID )
    VALUES
      (ARG_CP_CODE,
       ARG_USR_NAME,
       ARG_SESSION,
       ARG_PRG_CODE,
       NULL,
       LC_DIT_CODE(I),
       LC_DIT_DESC(I),
       LC_QTY_OB(I),
       LC_QTY_SP(I),
       LC_QTY_SR(I),
       LC_QTY_IN(I),
       LC_QTY_SL(I),
       LC_QTY_PR(I),
       LC_QTY_OUT(I),
       LC_QTY_STK(I),
       LC_AMT_OB(I),
       LC_AMT_SP(I),
       LC_AMT_SR(I),
       LC_AMT_IN(I),
       LC_AMT_SL(I),
       LC_AMT_PR(I),
       LC_AMT_OUT(I),
       LC_AMT_STK(I) , ARG_RPT_ID );

  COMMIT;
END;
/

prompt
prompt Creating procedure SET_STOCK_BREAKUP
prompt ====================================
prompt
CREATE OR REPLACE PROCEDURE MDHSYS."SET_STOCK_BREAKUP" (ARG_CP_CODE VARCHAR2 ,
                                ARG_LOC_CODE VARCHAR2,
                                ARG_DIT_CODE_FM VARCHAR2,
                                ARG_DIT_CODE_TO VARCHAR2,
                                ARG_DATE DATE ,
                                ARG_CTG_CODE  VARCHAR2,
                                ARG_USR_NAME  VARCHAR2,
                                ARG_SESSION   VARCHAR2 ,
                                ARG_PRG_CODE  VARCHAR2,
                                ARG_RPT_ID    VARCHAR2) IS
  TYPE MPB_IN_NUM_T IS TABLE OF PPI_PM_BALANCE.MPB_IN_NUM%TYPE;
  TYPE MPB_DATE_T IS TABLE OF PPI_PM_BALANCE.MPB_DATE%TYPE;
  TYPE MPB_DIT_CODE_T IS TABLE OF PPI_PM_BALANCE.MPB_DIT_CODE%TYPE;


  TYPE MPB_QTY_T IS TABLE OF PPI_PM_BALANCE.MPB_QTY%TYPE;
  TYPE MPB_RATE_T IS TABLE OF PPI_PM_BALANCE.MPB_RATE%TYPE;
  TYPE MPB_AMT_T IS TABLE OF PPI_PM_BALANCE.MPB_BAL_AMT%TYPE;

  LC_IN_NUM   MPB_IN_NUM_T;
  LC_MPB_DATE     MPB_DATE_T;
  LC_MPB_DIT_CODE MPB_DIT_CODE_T;

  LC_MPB_QTY  MPB_QTY_T;
  LC_MPB_RATE MPB_RATE_T;
  LC_MPB_AMT  MPB_AMT_T;


BEGIN

  SELECT MPB_IN_NUM,
         MPB_DATE,
         MPB_DIT_CODE,
          mpb_QTY  - GET_PD_BAL_BREAKUP (MPB_DIT_CODE  , MPB_IN_NUM  , MPB_IN_SQN   , MPB_CP_CODE , ARG_DATE  , MPB_LOC_CODE , MPB_RATE , 'Q') AS   LC_QTY ,

        MPB_RATE ,
           amt - GET_PD_BAL_BREAKUP (MPB_DIT_CODE  , MPB_IN_NUM  , MPB_IN_SQN   , MPB_CP_CODE , ARG_DATE  , MPB_LOC_CODE  , MPB_RATE , 'A') AS   LC_AMOUNT
             BULK COLLECT
    INTO LC_IN_NUM,
         LC_MPB_DATE,
         LC_MPB_DIT_CODE,

         LC_MPB_QTY,
         LC_MPB_RATE,
         LC_MPB_AMT
FROM VIEW_PM_BAL_BREAKUP
WHERE      MPB_CP_CODE = ARG_CP_CODE
AND     (MIT_CTG_CODE LIKE NVL(ARG_CTG_CODE,'%')
OR       NVL(DIT_COM,'N')  = 'Y'  )
AND      MPB_LOC_CODE LIKE NVL(ARG_LOC_CODE,'%')
AND   MPB_DIT_CODE BETWEEN ARG_DIT_CODE_FM   AND ARG_DIT_CODE_TO
AND   MPB_IN_NUM = MPB_IN_NUM
AND   MPB_DATE <= ARG_DATE
and    mpb_QTY  - GET_PD_BAL_BREAKUP (MPB_DIT_CODE  , MPB_IN_NUM  , MPB_IN_SQN   , MPB_CP_CODE , ARG_DATE  , MPB_LOC_CODE  , MPB_RATE , 'Q')  > 0
ORDER BY 3;



  FORALL I IN LC_MPB_DIT_CODE.FIRST .. LC_MPB_DIT_CODE.LAST

    INSERT INTO PPI_RO_STOCK_BREAKUP
      (RPT_CP_CODE,
       RPT_USR_NAME,
       RPT_SESSION,
       RPT_PRG_CODE,
       RPT_IN_NUM,
       RPT_IN_DATE,
       RPT_DIT_CODE,
       RPT_QTY,

       RPT_RATE,
       RPT_AMOUNT, RPT_ID)
    VALUES
      (ARG_CP_CODE ,
       ARG_USR_NAME,
       ARG_SESSION,
       ARG_PRG_CODE,
       LC_IN_NUM(I),
       LC_MPB_DATE(I),
       LC_MPB_DIT_CODE(I),
       LC_MPB_QTY(I),
       LC_MPB_RATE(I),
       LC_MPB_AMT(I),ARG_RPT_ID);

  COMMIT;
END;
/

