prompt
CREATE OR REPLACE PROCEDURE MDHSYS.write_to_file AS
   v_file UTL_FILE.FILE_TYPE;
BEGIN
   v_file := UTL_FILE.FOPEN('c:\', 'your_hl7_file.txt', 'W');
   UTL_FILE.PUT_LINE(v_file, v_hl7_message);
   UTL_FILE.FCLOSE(v_file);
END write_to_file;
/

prompt
prompt Creating package body API_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.API_PKG AS
-----------------------------------------------------------------
--Error Log
-----------------------------------------------------------------
PROCEDURE ERROR_LOG(ARG_DIRECTORY VARCHAR2,ARG_ERROR VARCHAR2) AS
  LC_FILE   UTL_FILE.FILE_TYPE;
  FILE_NAME VARCHAR2(30);
BEGIN
  FILE_NAME := 'Errorlog_'||TO_CHAR(SYSDATE,'MMRRRR')||'.log';
  IF DBMS_LOB.FILEEXISTS(BFILENAME(ARG_DIRECTORY,FILE_NAME)) = 0 THEN
     LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
     UTL_FILE.FCLOSE(LC_FILE);
  END IF;
  LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
  UTL_FILE.PUT_LINE (LC_FILE,ARG_ERROR);
  UTL_FILE.FCLOSE(LC_FILE);
END;

-----------------------------------------------------------------
--Pad String /*Encrypt and Decrypt dep on pad string*/
-----------------------------------------------------------------
PROCEDURE PADSTRING(ARG_VALUE IN OUT VARCHAR2) IS
  LC_UNIT NUMBER;
BEGIN
  IF LENGTH(ARG_VALUE) MOD 8 > 0 THEN
      LC_UNIT := TRUNC(LENGTH(ARG_VALUE)/8) + 1;
      ARG_VALUE  := RPAD(ARG_VALUE, LC_UNIT * 8, G_PAD_CHR);
  END IF;
END;

-----------------------------------------------------------------
--Encrypt
-----------------------------------------------------------------
FUNCTION ENCRYPT(ARG_VALUE IN VARCHAR2)RETURN RAW IS
  LC_VALUE     VARCHAR2(32767) := ARG_VALUE;
  LC_ENCRYPTED RAW(32767);
BEGIN
  PADSTRING(LC_VALUE);
  DBMS_OBFUSCATION_TOOLKIT.DESENCRYPT(INPUT          => UTL_RAW.CAST_TO_RAW(LC_VALUE),
                                      KEY            => G_KEY,
                                      ENCRYPTED_DATA => LC_ENCRYPTED);
  RETURN LC_ENCRYPTED;
END;

-----------------------------------------------------------------
--Decrypt
-----------------------------------------------------------------
FUNCTION DECRYPT(ARG_VALUE IN RAW)RETURN VARCHAR2 IS
  LC_DECRYPTED VARCHAR2(32767);
BEGIN
  DBMS_OBFUSCATION_TOOLKIT.DESDECRYPT(INPUT          => ARG_VALUE,
                                      KEY            => G_KEY,
                                      DECRYPTED_DATA => LC_DECRYPTED);
  RETURN RTRIM(UTL_RAW.CAST_TO_VARCHAR2(LC_DECRYPTED),G_PAD_CHR);
END;
-----------------------------------------------------------------
--Get API User Details
-----------------------------------------------------------------
FUNCTION GET_USR_DTL(ARG_USR_NAME VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT '||ARG_COL_NAME||' FROM API_XO_USERS A WHERE USR_NAME = '''||ARG_USR_NAME||''''
            INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
    RETURN LC_VAL;
END;
-----------------------------------------------------------------
--Get Token Details
-----------------------------------------------------------------
FUNCTION GET_TKN_DTL(ARG_TKN VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT '||ARG_COL_NAME||' FROM API_TO_TOKEN A WHERE ATK_TOKEN = '''||ARG_TKN||''''
            INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
    RETURN LC_VAL;
END;
END API_PKG;
/

