prompt Creating package body ISR_GLOBAL
prompt ================================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.ISR_GLOBAL AS
--------------------------------------------------------------
--Run Program
--------------------------------------------------------------
FUNCTION RUN_PROG(ARG_PRG_CODE IN VARCHAR2) RETURN VARCHAR2 IS
  LC_APP_ALIAS VARCHAR2(100);
  LC_MOD_CODE  VARCHAR2(30);
  LC_PRG_CODE  VARCHAR2(100) := ARG_PRG_CODE;
  LC_URL       VARCHAR2(100);
BEGIN
  BEGIN
    SELECT PRG_MOD_CODE
    INTO   LC_MOD_CODE
    FROM   ISR_XO_PROGRAM
    WHERE  PRG_CODE = ARG_PRG_CODE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
         LC_PRG_CODE := NULL;
  END;
  BEGIN
    SELECT CP_SHT_NAME||'_'||LC_MOD_CODE
    INTO   LC_APP_ALIAS
    FROM   ISR_XO_COMPANY
    WHERE  CP_CODE = V('G_CP_CODE');
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
         LC_APP_ALIAS := NVL(V('APP_ALIAS'),V('APP_ID'));
  END;
  LC_URL := 'f?p='||LC_APP_ALIAS||':'||LC_PRG_CODE||':'||V('APP_SESSION')||'::NO:RP::';
  RETURN LC_URL;
END;

--------------------------------------------------------------
--Add Company User
--------------------------------------------------------------
FUNCTION ADD_CP_USR(ARG_CP_CODE VARCHAR2) RETURN VARCHAR2 IS
  CHK NUMBER;
  CURSOR PRG_CRS IS
         SELECT  PRG_CODE
         FROM    ISR_XO_PROGRAM
         WHERE  PRG_STATUS = 'Y'
         ORDER BY PRG_CODE;
BEGIN
  SELECT COUNT(*)
  INTO   CHK
  FROM   ISR_XO_CONTROL
  WHERE   ISR_CP_CODE = ARG_CP_CODE;
  IF CHK = 0 THEN
     INSERT INTO ISR_XO_CONTROL
           (ISR_CP_CODE,      ISR_PRJ_FLAG,    ISR_PRN_TYPE)
     VALUES(ARG_CP_CODE,      'N',             'DM');
  END IF;

  SELECT COUNT(*)
  INTO   CHK
  FROM   ISR_XM_BRANCH
  WHERE   BR_CODE = '-'
  AND     BR_CP_CODE = ARG_CP_CODE;
  IF CHK = 0 THEN
     INSERT INTO ISR_XM_BRANCH
           (BR_CP_CODE,        BR_CODE,      BR_FLAG)
     VALUES(ARG_CP_CODE,       '-',          'N');

     INSERT INTO ISR_XD_DEPT
           (DP_CP_CODE,       DP_BR_CODE,       DP_CODE,       DP_STATUS)
     VALUES(ARG_CP_CODE,      '-',              '-',           'N');
  END IF;

  SELECT COUNT(*)
  INTO   CHK
  FROM   ISR_XM_BRANCH
  WHERE   BR_CODE <> '-'
  AND     BR_CP_CODE = ARG_CP_CODE;
  IF CHK = 0 THEN
     INSERT INTO ISR_XM_BRANCH
           (BR_CP_CODE,         BR_CODE,         BR_FUL_NAME,        BR_SHT_NAME,      BR_FLAG)
     VALUES(ARG_CP_CODE,        'HOF',           'Head Office',      'Head Office',    'Y');
  END IF;

  SELECT COUNT(*)
  INTO   CHK
  FROM    ISR_XM_SECURITY
  WHERE  SEC_CODE    = '00'
  AND    SEC_CP_CODE = ARG_CP_CODE;
  IF CHK = 0 THEN
      INSERT INTO ISR_XM_SECURITY
            (SEC_CP_CODE,          SEC_CODE,           SEC_NAME)
      VALUES(ARG_CP_CODE,          '00',               'APPLICATION SUPER USER');
  END IF;

  SELECT COUNT(*)
  INTO   CHK
  FROM    ISR_XO_USERS
  WHERE  USR_NAME    = 'SYSTEM'
  AND    USR_CP_CODE = ARG_CP_CODE;
  IF CHK = 0 THEN
     INSERT INTO ISR_XO_USERS
           (USR_CP_CODE,            USR_NAME,           USR_PASS,          USR_SEC_CODE,          USR_STATUS)
     VALUES(ARG_CP_CODE,            'SYSTEM',           'USER',            '00',                  'Y');

     INSERT INTO ISR_XD_USERS_BRANCH
           (DBR_CP_CODE,         DBR_USR_NAME,         DBR_BR_CODE,          DBR_FLAG,           DBR_DAT_FLAG)
     VALUES(ARG_CP_CODE,         'SYSTEM',             'HOF',                'Y',                'I');
  END IF;

  FOR PRG_REC IN PRG_CRS LOOP
      SELECT COUNT(*)
      INTO   CHK
      FROM   ISR_XD_SECURITY
      WHERE   DSC_PRG_CODE = PRG_REC.PRG_CODE
      AND     DSC_SEC_CODE = '00'
      AND     DSC_CP_CODE  = ARG_CP_CODE;
      IF CHK = 0 THEN
         IF SUBSTR(PRG_REC.PRG_CODE,4,2) = 'XX' THEN
            INSERT INTO ISR_XD_SECURITY
                  (DSC_CP_CODE,           DSC_SEC_CODE,           DSC_PRG_CODE,          DSC_INS,           DSC_UPD,
                   DSC_DEL,               DSC_QRY,                DSC_EXE)
            VALUES(ARG_CP_CODE,           '00',                   PRG_REC.PRG_CODE,      'Y',               'Y',
                   'Y',                   'Y',                    'Y');
         ELSIF SUBSTR(PRG_REC.PRG_CODE,5,1) = 'S' THEN
            INSERT INTO ISR_XD_SECURITY
                  (DSC_CP_CODE,           DSC_SEC_CODE,           DSC_PRG_CODE,          DSC_INS,           DSC_UPD,
                   DSC_DEL,               DSC_QRY,                DSC_EXE)
            VALUES(ARG_CP_CODE,           '00',                   PRG_REC.PRG_CODE,      'Y',               'Y',
                   'Y',                   'Y',                    'N');
         ELSE
            INSERT INTO ISR_XD_SECURITY
                  (DSC_CP_CODE,           DSC_SEC_CODE,           DSC_PRG_CODE,          DSC_INS,           DSC_UPD,
                   DSC_DEL,               DSC_QRY,                DSC_EXE)
            VALUES(ARG_CP_CODE,           '00',                   PRG_REC.PRG_CODE,      'N',               'N',
                   'N',                   'N',                    'Y');
         END IF;
      END IF;
  END LOOP;
  RETURN 'T';
EXCEPTION
  WHEN OTHERS THEN
       RETURN 'F';
END;

--------------------------------------------------------------
--Check Percentage
--------------------------------------------------------------
FUNCTION CHK_PERCENTAGE (ARG_AMOUNT NUMBER, ARG_FLAG VARCHAR2) RETURN VARCHAR2 IS
  VAL_RETURN VARCHAR2(1);
BEGIN
  IF NVL(ARG_FLAG,'N') = 'Y' AND NVL(ARG_AMOUNT,0) > 100 THEN
     VAL_RETURN := 'F';
  ELSE
      VAL_RETURN := 'T';
  END IF;
  RETURN VAL_RETURN;
END;

--------------------------------------------------------------
--Check Privilges
--------------------------------------------------------------
FUNCTION CHK_PRIVL(ARG_FLAG VARCHAR2) RETURN VARCHAR2 IS
  RET_DATA    VARCHAR2(1);
  LC_CP_CODE  VARCHAR2(2);
  LC_SEC_CODE VARCHAR2(50);
  LC_PRG_CODE VARCHAR2(7);
BEGIN
  LC_CP_CODE     := V('G_CP_CODE');
  LC_SEC_CODE    := V('G_SEC_CODE');
  LC_PRG_CODE    := V('APP_PAGE_ALIAS');--V('G_PRG_CODE');
  IF ARG_FLAG = 'I' THEN
     BEGIN
       SELECT DSC_INS
       INTO   RET_DATA
       FROM   ISR_XD_SECURITY
       WHERE  DSC_CP_CODE  = LC_CP_CODE
       AND    DSC_SEC_CODE = LC_SEC_CODE
       AND    DSC_PRG_CODE = LC_PRG_CODE;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
            RET_DATA := 'N';
     END;
  ELSIF ARG_FLAG = 'U' THEN
     BEGIN
       SELECT DSC_UPD
       INTO   RET_DATA
       FROM   ISR_XD_SECURITY
       WHERE  DSC_CP_CODE  = LC_CP_CODE
       AND    DSC_SEC_CODE = LC_SEC_CODE
       AND    DSC_PRG_CODE = LC_PRG_CODE;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
            RET_DATA := 'N';
     END;
  ELSIF ARG_FLAG = 'D' THEN
     BEGIN
       SELECT DSC_DEL
       INTO   RET_DATA
       FROM   ISR_XD_SECURITY
       WHERE  DSC_CP_CODE  = LC_CP_CODE
       AND    DSC_SEC_CODE = LC_SEC_CODE
       AND    DSC_PRG_CODE = LC_PRG_CODE;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
            RET_DATA := 'N';
     END;
  ELSIF ARG_FLAG = 'Q' THEN
     BEGIN
       SELECT DSC_QRY
       INTO   RET_DATA
       FROM   ISR_XD_SECURITY
       WHERE  DSC_CP_CODE  = LC_CP_CODE
       AND    DSC_SEC_CODE = LC_SEC_CODE
       AND    DSC_PRG_CODE = LC_PRG_CODE;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
            RET_DATA := 'N';
     END;
  ELSIF ARG_FLAG = 'E' THEN
     BEGIN
       SELECT DSC_EXE
       INTO   RET_DATA
       FROM   ISR_XD_SECURITY
       WHERE  DSC_CP_CODE  = LC_CP_CODE
       AND    DSC_SEC_CODE = LC_SEC_CODE
       AND    DSC_PRG_CODE = LC_PRG_CODE;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
            RET_DATA := 'N';
     END;
  END IF;
  RETURN RET_DATA;
END;

--------------------------------------------------------------
--Delogin
--------------------------------------------------------------
PROCEDURE DELOGIN IS
  LC_CP_CODE VARCHAR2(2);
  LC_USR_NAME VARCHAR2(30);
  LC_SESSION VARCHAR2(2);
BEGIN
  LC_CP_CODE  := V('G_CP_CODE');
  LC_USR_NAME := V('G_USR_NAME');
  LC_SESSION  := V('G_SESSION');
  IF LC_SESSION IS NOT NULL THEN
     BEGIN
       DELETE FROM ISR_XO_LOGIN
       WHERE   LG_USER = LC_USR_NAME
       AND    LG_CP_CODE = LC_CP_CODE
       AND    LG_SESSION = LC_SESSION;
       COMMIT;
     EXCEPTION
       WHEN OTHERS THEN
            ROLLBACK;
     END;
  END IF;
  --DEL_USR_PRNFILES(LC_USR_NAME);
  --EXIT_FORM(NO_VALIDATE);
END;

