--------------------------------------------------------------
--First Day
--------------------------------------------------------------
FUNCTION FIRST_DAY(ARG_DATE Date) RETURN DATE IS
    LC_FIRST_DAY Date;
BEGIN
    LC_FIRST_DAY := ARG_DATE - TO_CHAR(ARG_DATE,'DD') + 1;
    RETURN LC_FIRST_DAY;
END;

--------------------------------------------------------------
--Application
--------------------------------------------------------------
FUNCTION GET_APP(ARG_MAP_CODE VARCHAR2) RETURN VARCHAR2 IS
  CHK NUMBER;
BEGIN
  SELECT COUNT(*)
  INTO   CHK
  FROM    ISR_XM_APPLICATION
  WHERE  MAP_CODE = ARG_MAP_CODE
  AND    MAP_FLAG = 'Y';
  IF CHK > 0 THEN
     RETURN 'T';
  ELSE
     RETURN 'F';
  END IF;
END;

--------------------------------------------------------------
--Get Control
--------------------------------------------------------------
FUNCTION GET_CONTROL(ARG_SEND VARCHAR2) RETURN VARCHAR2 IS
  VAL_RETURN VARCHAR2(256);
  LC_CP_CODE VARCHAR2(2);
BEGIN
  LC_CP_CODE := NVL(V('G_CP_CODE'),'01');
  -- SEND 'PA' PARAMETER FOR PROJECT WISE ACCOUNTING FLAG CHECKING
  IF ARG_SEND = 'PA' THEN
     SELECT ISR_PRJ_FLAG
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND 'DP' PARAMETER FOR DEFAULT PROJECT ACCOUNTING CHECKING
  ELSIF ARG_SEND = 'DP' THEN
     SELECT ISR_PRJ_CODE
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND 'PD' PARAMETER FOR DEFAULT PROJECT DESCRIPTION
  ELSIF ARG_SEND = 'PD' THEN
  /* GM 01-OCT-2018 TABLE-OR-VIEW DOES NOT EXISTS
     SELECT PRJ_FUL_NAME
     INTO   VAL_RETURN
     FROM   ACT_SO_PROJECT
     WHERE  PRJ_CP_CODE = LC_CP_CODE
     AND    PRJ_CODE    =(SELECT ISR_PRJ_CODE
                          FROM   ISR_XO_CONTROL
                          WHERE  ISR_CP_CODE = LC_CP_CODE);
  */
  -- SEND 'PL' PARAMETER FOR GETTING PROFIT AND LOSS ACCOUNT
     RETURN VAL_RETURN;
  ELSIF ARG_SEND = 'PL' THEN
     SELECT ISR_PL_COA3
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND 'PL' PARAMETER FOR GETTING PROFIT AND LOSS ACCOUNT
  ELSIF ARG_SEND = 'CD' THEN
   /*GM 01-OCT-2018 TABLE-OR-VIEW DOES NOT EXISTS
     SELECT COA3_DESC
     INTO   VAL_RETURN
     FROM   ACT_SD_COA_LEVEL3
     WHERE  COA3_CODE =(SELECT ISR_PL_COA3
                        FROM   ISR_XO_CONTROL
                        WHERE  ISR_CP_CODE = LC_CP_CODE);*/
     RETURN VAL_RETURN;
  -- SEND 'FA' PARAMETER FOR GETTING FIXED ASSET VOUCHER TYPE
  ELSIF ARG_SEND = 'FA' THEN
     SELECT ISR_FA_VTP
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND 'PT' PARAMETER FOR GETTING THE DEFAULT PRINTER TYPE
  ELSIF ARG_SEND = 'PT' THEN
     SELECT ISR_PRN_TYPE
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND ST1 FOR GETTING SALES TAX REGULAR PERCENTAGE
  ELSIF ARG_SEND = 'ST1' THEN
     SELECT NVL(ISR_STX1,0)
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND ST2 FOR GETTING ADDITIONAL SALES TAX PERCENTAGE
  ELSIF ARG_SEND = 'ST2' THEN
     SELECT NVL(ISR_STX2,0)
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  -- SEND SE FOR GETTING IF SALES TAX AMOUNT CAN BE EDITED ON FORM
  ELSIF ARG_SEND = 'SE' THEN
     SELECT ISR_STX_EDIT
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  ELSIF ARG_SEND = 'IM' THEN
     SELECT ISR_INV_METHOD
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  ELSIF ARG_SEND = 'HO' THEN
     SELECT ISR_HOF_CODE
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  ELSIF ARG_SEND = 'DEJ' THEN
     SELECT ISR_DEJ_VTP
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  ELSIF ARG_SEND = 'DER' THEN
      SELECT ISR_DER_VTP
      INTO   VAL_RETURN
      FROM   ISR_XO_CONTROL
      WHERE  ISR_CP_CODE = LC_CP_CODE;
  ELSIF ARG_SEND = 'COG' THEN
     SELECT ISR_COGS_VTP
     INTO   VAL_RETURN
     FROM   ISR_XO_CONTROL
     WHERE  ISR_CP_CODE = LC_CP_CODE;
  END IF;
  RETURN VAL_RETURN;
END;

--------------------------------------------------------------
--Get GLOBAL
--------------------------------------------------------------
FUNCTION GET_GLOBAL(ARG_TYPE VARCHAR2)RETURN VARCHAR2 IS
  LC_CP_CODE     VARCHAR2(2);
  LC_CP_FUL_NAME VARCHAR2(100);
  LC_BR_CODE     VARCHAR(3);
  LC_BR_NAME     VARCHAR(50);
  LC_SEC_CODE    VARCHAR2(50);
  LC_USR_NAME    VARCHAR2(30);
  LC_PRG_CODE    VARCHAR2(7);
  LC_PRG_DESC    VARCHAR2(60);
BEGIN
  LC_CP_CODE     := V('G_CP_CODE');
  LC_CP_FUL_NAME := V('G_FUL_NAME');
  LC_BR_CODE     := V('G_BR_CODE');
  LC_BR_NAME     := V('G_BR_NAME');
  LC_SEC_CODE    := V('G_SEC_CODE');
  LC_USR_NAME    := V('G_USR_NAME');
  LC_PRG_CODE    := V('G_PRG_CODE');
  IF ARG_TYPE='D' THEN
     BEGIN
       SELECT PRG_DESC
       INTO   LC_PRG_DESC
       FROM   ISR_XO_PROGRAM
       WHERE  PRG_CODE = LC_PRG_CODE;
       RETURN LC_PRG_DESC;
     END;
  ELSIF ARG_TYPE='N' THEN
     RETURN LC_CP_FUL_NAME;
  ELSIF ARG_TYPE='C' THEN
     RETURN LC_CP_CODE;
  ELSIF ARG_TYPE='P' THEN
     RETURN LC_PRG_CODE;
  ELSIF ARG_TYPE='U' THEN
     RETURN LC_USR_NAME;
  ELSIF ARG_TYPE='S' THEN
     RETURN LC_SEC_CODE;
  ELSIF ARG_TYPE='BC' THEN
     RETURN LC_BR_CODE;
  ELSIF ARG_TYPE='BN' THEN
     RETURN LC_BR_NAME;
  ELSE
     RETURN 'ERROR';
  END IF;
END;

--------------------------------------------------------------
--Get Printer Type
--------------------------------------------------------------
FUNCTION GET_PRINT_TYPE(ARG_USR_NAME IN VARCHAR2,ARG_PRG_CODE IN VARCHAR2) RETURN CHAR IS
  LC_PRN_TYPE VARCHAR2(1);
BEGIN
  BEGIN
    SELECT DSR_PRN_TYPE
    INTO   LC_PRN_TYPE
    FROM   ISR_XD_USERS_PRN
    WHERE  DSR_USR_NAME = ARG_USR_NAME
    AND    DSR_PRG_CODE = ARG_PRG_CODE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
         LC_PRN_TYPE := 'D';
  END;
  RETURN LC_PRN_TYPE;
END;

--------------------------------------------------------------
--De Voucher Exists
--------------------------------------------------------------
FUNCTION IS_DE_VCH_EXISTS(ARG_CP_CODE VARCHAR2, ARG_FM_DATE DATE, ARG_TO_DATE DATE) RETURN CHAR IS
  LC_AJV_TYPE VARCHAR2(100);
  LC_ACR_TYPE VARCHAR2(100);
  LC_AJV_NUM  VARCHAR2(100);
  LC_ACR_NUM  VARCHAR2(100);
  LC_FLAG     VARCHAR2(1):= 'F';
  CHK         NUMBER;
  LC_DAYS     NUMBER;
  LC_CUR_DATE DATE;
BEGIN
/* GM 01-OCT-2018 TABLE-OR-VIEW DOES NOT EXISTS
  SELECT ISR_DEJ_VTP, ISR_DER_VTP
  INTO   LC_AJV_TYPE, LC_ACR_TYPE
  FROM   ISR_XO_CONTROL
  WHERE  ISR_CP_CODE = ARG_CP_CODE;

  LC_DAYS := (ARG_TO_DATE - ARG_FM_DATE)+1;

  LC_CUR_DATE := ARG_FM_DATE;

  LC_FLAG := 'F';

  FOR A IN 1 .. LC_DAYS LOOP
      LC_AJV_NUM := LC_AJV_TYPE || TO_CHAR(LC_CUR_DATE,'YYYYMMDD') || '001';
      LC_ACR_NUM := LC_ACR_TYPE || TO_CHAR(LC_CUR_DATE,'YYYYMMDD') || '001';
      BEGIN
        SELECT COUNT(*)
        INTO   CHK
        FROM   ACT_TM_VOUCHER
        WHERE  MVH_CP_CODE = ARG_CP_CODE
        AND    MVH_DATE = LC_CUR_DATE
        AND    MVH_NUM IN (LC_AJV_NUM,LC_ACR_NUM);
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
             CHK := 0;
      END;

    IF CHK > 0 THEN
       LC_FLAG := 'T';
       EXIT;
    END IF;
    LC_CUR_DATE := LC_CUR_DATE  + 1;
  END LOOP;*/
  LC_FLAG := 'F';
  RETURN LC_FLAG;
END;

--------------------------------------------------------------
--Set Text
--------------------------------------------------------------
FUNCTION SETTEXT(RSVALUE VARCHAR2, RSREPLIVALUE VARCHAR2, RILEN NUMBER,RSALIGN VARCHAR2) RETURN VARCHAR2 IS
  LICNT    NUMBER;
  LSSTRING VARCHAR2(80);
  LICNT2   NUMBER;
BEGIN
  IF LENGTH(RSVALUE) = RILEN THEN
     LSSTRING := RSVALUE;
  ELSIF LENGTH(RSVALUE) > RILEN THEN
     LSSTRING := SUBSTR(RSVALUE, 1, RILEN);
  ELSE
     LSSTRING := RSVALUE;
     IF RSALIGN = 'L' THEN
        FOR LICNT IN LENGTH(RSVALUE) + 1 .. RILEN LOOP
            LSSTRING := LSSTRING || RSREPLIVALUE;
        END LOOP;
     ELSIF RSALIGN = 'R' THEN
        FOR LICNT IN LENGTH(RSVALUE) + 1 ..  RILEN LOOP
            LSSTRING := RSREPLIVALUE || LSSTRING;
        END LOOP;
     ELSIF RSALIGN = 'C' THEN
        LICNT2 := FLOOR((RILEN - LENGTH(RSVALUE)) / 2);
        FOR LICNT IN 1 .. LICNT2 LOOP
            LSSTRING := RSREPLIVALUE || LSSTRING;
        END LOOP;
        FOR LICNT IN LENGTH(LSSTRING) + 1 .. RILEN LOOP
            LSSTRING := LSSTRING || RSREPLIVALUE;
        END LOOP;
     END IF;
  END IF;
  RETURN LSSTRING;
END;

--------------------------------------------------------------
--Space
--------------------------------------------------------------
FUNCTION SPACE(ARG_VAL IN NUMBER) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(256):=NULL;
BEGIN
  FOR I IN 1..ARG_VAL LOOP
      LC_VAL :=LC_VAL||' ';
  END LOOP;
  RETURN LC_VAL;
END;

--------------------------------------------------------------
--To Words
--------------------------------------------------------------
FUNCTION TO_WORD(ARG_NUM IN NUMBER) RETURN VARCHAR2 IS
  LC_NUM   VARCHAR2(12);
  LC_LEN   NUMBER;
  LC_WORDS VARCHAR2(200);
BEGIN
  LC_WORDS := NULL;
  LC_NUM:= TO_CHAR(TRUNC(arg_num));
  LC_LEN:= LENGTH(lc_num);
  IF LC_LEN > 9 THEN
     IF TO_NUMBER(SUBSTR(LC_NUM,1,LC_LEN-9)) > 0 THEN
        LC_WORDS := TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,LC_LEN-9),'YYY'),'YYYSP ')||'BILLION ';
     END IF;
     LC_NUM:= SUBSTR(LC_NUM,LC_LEN-8);
     LC_LEN:= LENGTH(LC_NUM);
  END IF;
  IF LC_LEN > 6 THEN
     IF TO_NUMBER(SUBSTR(LC_NUM,1,LC_LEN-6)) > 0 THEN
        LC_WORDS := LC_WORDS||TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,LC_LEN-6),'YYY'),'YYYSP ')||'MILLION ';
     END IF;
     LC_NUM:= SUBSTR(LC_NUM,LC_LEN-5);
     LC_LEN := LENGTH(LC_NUM);
  END IF;
  IF LC_LEN > 3 THEN
     IF TO_NUMBER(SUBSTR(LC_NUM,1,LC_LEN-3)) > 0 THEN
        LC_WORDS := LC_WORDS||TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,LC_LEN-3),'YYY'),'YYYSP ')||'THOUSAND ';
     END IF;
     LC_NUM := SUBSTR(LC_NUM,LC_LEN-2);
     LC_LEN := LENGTH(LC_NUM);
  END IF;
  IF TO_NUMBER(LC_NUM) > 0 THEN
     LC_WORDS := LC_WORDS||TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,LC_LEN),'YYY'),'YYYSP ');
  END IF;
  LC_NUM  := TO_CHAR(ROUND((ARG_NUM-TRUNC(ARG_NUM))*100));
  IF TO_NUMBER(LC_NUM) = 0 AND LC_WORDS IS NOT NULL THEN
     LC_WORDS := LC_WORDS||'ONLY';
  ELSIF LC_WORDS IS NOT NULL THEN
     LC_WORDS := LC_WORDS||'AND ';
     LC_WORDS := LC_WORDS||TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,2),'YY'),'YYSP "PAISA"');
  ELSE
     LC_WORDS := LC_WORDS||TO_CHAR(TO_DATE(SUBSTR(LC_NUM,1,2),'YY'),'YYSP "PAISA"');
  END IF;
  RETURN LC_WORDS;
EXCEPTION
  WHEN OTHERS THEN
       RAISE_APPLICATION_ERROR(-20001,'Error In To Words');
END;

