--------------------------------------------------------------
--Security Detail
--------------------------------------------------------------
FUNCTION GET_SECURITY_DETAIL(ARG_SEC_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT '||ARG_COL_NAME||' FROM ISR_XM_SECURITY WHERE SEC_CP_CODE = '''||G_CP_CODE||''' AND SEC_CODE = '''||ARG_SEC_CODE||''''
    INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
