FUNCTION GET_CONTROL_VALUE(ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT '||ARG_COL_NAME||' FROM ISR_XO_CONTROL WHERE ISR_CP_CODE = '''||G_CP_CODE||''''
    INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
