FUNCTION GET_CONTROL_PARA(ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT JSON_VALUE(ISR_PARAMETER, ''$.'||ARG_COL_NAME||''') FROM ISR_XO_CONTROL A WHERE ISR_CP_CODE = '''||G_CP_CODE||''''
            INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
    RETURN LC_VAL;
END;
--------------------
FUNCTION GET_DP_CT_DS(ARG_CP_CODE VARCHAR2, ARG_DATE DATE,
                      ARG_EMP_CODE VARCHAR2, ARG_TYPE VARCHAR2) 
                      RETURN VARCHAR2 IS
    LC_VAL_RETURN VARCHAR2(6);
BEGIN
  --RAISE_APPLICATION_ERROR(-20001,ARG_CP_CODE);

    IF ARG_TYPE = 'D' THEN
       -- RAISE_APPLICATION_ERROR(-20001,'S');
        BEGIN
            SELECT  DED_DP_CODE 
            INTO    LC_VAL_RETURN
            FROM    MDHSYS.PAY_SD_EMP_DEPT
            WHERE   DED_CP_CODE  = ARG_CP_CODE
            AND     DED_EMP_CODE = ARG_EMP_CODE
            AND     DED_DATE     = (SELECT MAX(DED_DATE) FROM MDHSYS.PAY_SD_EMP_DEPT 
            WHERE   DED_CP_CODE  = ARG_CP_CODE
            AND     DED_EMP_CODE = ARG_EMP_CODE
              AND    DED_DATE    <= ARG_DATE);
          --  RAISE_APPLICATION_ERROR(-20001,'A'||LC_VAL_RETURN);
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
                LC_VAL_RETURN := '-';
        END;   
    ELSIF ARG_TYPE = 'C' THEN
        BEGIN
            SELECT  INC_CT_CODE
            INTO    LC_VAL_RETURN
            FROM    MDHSYS.PAY_TM_INCREMENT
            WHERE   INC_CP_CODE  = ARG_CP_CODE
            AND     INC_EMP_CODE = ARG_EMP_CODE
            AND     INC_DATE     = (SELECT MAX(INC_DATE) FROM MDHSYS.PAY_TM_INCREMENT
            WHERE   INC_CP_CODE  = ARG_CP_CODE
            AND     INC_EMP_CODE = ARG_EMP_CODE
            AND     INC_DATE    <= ARG_DATE);
        EXCEPTION
            WHEN OTHERS THEN
                LC_VAL_RETURN := '-';
        END;   
    ELSE
        BEGIN
            SELECT  INC_DS_CODE
            INTO    LC_VAL_RETURN
            FROM    MDHSYS.PAY_TM_INCREMENT
            WHERE   INC_CP_CODE  = ARG_CP_CODE
            AND     INC_EMP_CODE = ARG_EMP_CODE
            AND     INC_DATE     = (SELECT MAX(INC_DATE) FROM MDHSYS.PAY_TM_INCREMENT
            WHERE   INC_CP_CODE  = ARG_CP_CODE
            AND     INC_EMP_CODE = ARG_EMP_CODE
            AND     INC_DATE    <= ARG_DATE);
        EXCEPTION
            WHEN OTHERS THEN
                LC_VAL_RETURN := '-';
        END;   
    END IF;
    RETURN LC_VAL_RETURN;
END;
------------------------
FUNCTION PROC_RPT RETURN VARCHAR2 IS
    LC_FLAG VARCHAR2(1);
    LC_SEQ_NUM NUMBER(9);
    LC_CODE VARCHAR2(6);
    LC_TOT_AMT NUMBER(13,2);
    LC_TOT_DED  NUMBER(13,2);
    LC_ABSENT   NUMBER(13,2);
    LC_ABSENT_AMT NUMBER(13,2);
    LC_DAYS NUMBER;
            
    chk number;
    
    LC_AMT NUMBER(13,2);
    LC_DP_CODE VARCHAR2(6);
    LC_CT_CODE VARCHAR2(3);
    LC_DS_CODE VARCHAR2(3);
    LC_GRS_SAL NUMBER(13,2);
    
    CURSOR MON_CRS IS
        SELECT DISTINCT MON_EMP_CODE
        FROM MDHSYS.PAY_TM_MONTHLY, MDHSYS.PAY_SM_EMPLOYEE
        WHERE MON_CP_CODE = V('G_CP_CODE')
        AND   MON_EMP_CODE BETWEEN V('P501_LC_CODE_FM')
        AND   V('P501_LC_CODE_TO')
        AND   MON_DATE BETWEEN V('P501_LC_FM_DATE')
        AND   V('P501_LC_TO_DATE')
        AND   EMP_CP_CODE = MON_CP_CODE
        AND   EMP_CODE = MON_EMP_CODE
        AND   EMP_PAY_TYPE = V('P501_LC_PAY_TYPE')
        ORDER BY MON_EMP_CODE;
    CURSOR ALW_CRS IS
        SELECT DISTINCT MAL_ALW_CODE AS ALW_CODE , ALW_NAME
        FROM MDHSYS.PAY_TD_MON_ALLOWN, MDHSYS.PAY_SM_ALLOWANCE 
        WHERE MAL_CP_CODE = V('G_CP_CODE')
        AND MAL_EMP_CODE BETWEEN V('P501_LC_CODE_FM') AND V('P501_LC_CODE_TO')
        AND MAL_MON_DATE BETWEEN V('P501_LC_FM_DATE') AND V('P501_LC_TO_DATE')
        AND ALW_CP_CODE = MAL_CP_CODE
        AND ALW_CODE = MAL_ALW_CODE
        AND MAL_STATUS = 'R'
        ORDER BY MAL_ALW_CODE;
    CURSOR DED_CRS IS
        SELECT DISTINCT MDN_DED_CODE AS DED_CODE , DED_NAME
        FROM MDHSYS.PAY_TD_MON_DEDUCT ,MDHSYS.PAY_SM_DEDUCTION
        WHERE MDN_CP_CODE = V('G_CP_CODE')
        AND MDN_EMP_CODE BETWEEN V('P501_LC_CODE_FM') AND V('P501_LC_CODE_TO')
        AND MDN_MON_DATE BETWEEN V('P501_LC_FM_DATE') AND V('P501_LC_TO_DATE')
        AND DED_CP_CODE = MDN_CP_CODE
        AND DED_CODE = MDN_DED_CODE
        AND MDN_STATUS = 'R'
        ORDER BY MDN_DED_CODE;
    CURSOR MAL_CRS(LC_EMP_CODE VARCHAR2, LC_ALW_CODE VARCHAR2) IS 
        SELECT MAL_EMP_CODE, MAL_ALW_CODE, 
        SUM(DECODE(V('P501_LC_TYPE'),'R',MAL_AMT,'A', MAL_ARR_AMT, 
        'B',MAL_AMT + MAL_ARR_AMT)) AS ALW_AMT 
        FROM MDHSYS.PAY_TD_MON_ALLOWN 
        WHERE MAL_CP_CODE = V('G_CP_CODE')
        AND MAL_EMP_CODE = LC_EMP_CODE
        AND MAL_ALW_CODE = LC_ALW_CODE
        AND MAL_MON_DATE BETWEEN V('P501_LC_FM_DATE') AND V('P501_LC_TO_DATE')
        AND MAL_STATUS = 'R' 
        GROUP BY MAL_EMP_CODE, MAL_ALW_CODE;
    CURSOR MDN_CRS(LC_EMP_CODE VARCHAR2, LC_DED_CODE VARCHAR2) IS
        SELECT MDN_EMP_CODE, MDN_DED_CODE, 
        SUM(DECODE(V('P501_LC_TYPE'),'R',MDN_AMT,'A', MDN_ARR_AMT,
        'B',MDN_AMT + MDN_ARR_AMT)) AS DED_AMT 
        FROM MDHSYS.PAY_TD_MON_DEDUCT 
        WHERE MDN_CP_CODE = V('G_CP_CODE')
        AND MDN_EMP_CODE = LC_EMP_CODE
        AND MDN_DED_CODE = LC_DED_CODE
        AND MDN_MON_DATE BETWEEN V('P501_LC_FM_DATE') AND V('P501_LC_TO_DATE')
        AND MDN_STATUS = 'R' 
        GROUP BY MDN_EMP_CODE, MDN_DED_CODE;
        
        
    CURSOR ALL_ALW_CRS IS
    SELECT DISTINCT RPS_ALW_CODE, RPS_TYPE,
          RPS_ALW_NAME
    FROM MDHSYS.PAY_RO_SALARY
    WHERE RPS_CP_CODE   = V('G_CP_CODE')
    AND   RPS_USR_NAME  = V('G_USR_NAME')
    AND   RPS_SESSION   = V('G_SESSION')
    AND   RPS_PRG_CODE  = V('G_PRG_CODE')
    ORDER BY RPS_TYPE, RPS_ALW_CODE;
    
    CURSOR ALL_EMP_CRS IS
    SELECT DISTINCT RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
            RPS_EMP_CODE, RPS_DATE, RPS_GRP_CODE,
            RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE
    FROM MDHSYS.PAY_RO_SALARY
    WHERE RPS_CP_CODE   = V('G_CP_CODE')
    AND   RPS_USR_NAME  = V('G_USR_NAME')
    AND   RPS_SESSION   = V('G_SESSION')
    AND   RPS_PRG_CODE  = V('G_PRG_CODE');

BEGIN
    LC_SEQ_NUM := 1;
    LC_FLAG := 'F';
    DELETE FROM MDHSYS.PAY_RO_SALARY
    WHERE RPS_CP_CODE   = V('G_CP_CODE')
    AND   RPS_USR_NAME  = V('G_USR_NAME')
    AND   RPS_PRG_CODE  = V('G_PRG_CODE');
    
    COMMIT;
    
    FOR MON_REC IN MON_CRS LOOP
        LC_DP_CODE := GET_DP_CT_DS(V('G_CP_CODE'),V('P501_LC_TO_DATE'),MON_REC.MON_EMP_CODE,'D');
        LC_CT_CODE := GET_DP_CT_DS(V('G_CP_CODE'),V('P501_LC_TO_DATE'),MON_REC.MON_EMP_CODE,'C');
        LC_DS_CODE := GET_DP_CT_DS(V('G_CP_CODE'),V('P501_LC_TO_DATE'),MON_REC.MON_EMP_CODE,'P');
        --RAISE_APPLICATION_ERROR(-20001,LC_DP_CODE);
        LC_TOT_AMT := 0;
        LC_TOT_DED := 0;
        FOR ALW_REC IN ALW_CRS LOOP
            LC_AMT := 0;
            FOR MAL_REC IN MAL_CRS(MON_REC.MON_EMP_CODE, ALW_REC.ALW_CODE) LOOP
                LC_AMT := NVL(MAL_REC.ALW_AMT,0);
               -- RAISE_APPLICATION_ERROR(-20001,'EMP: '||MON_REC.MON_EMP_CODE||' TOTAL_AMT: '||LC_AMT);
                LC_TOT_AMT := LC_TOT_AMT + LC_AMT;
                
            END LOOP;
            IF NVL(LC_AMT,0) <> 0 THEN
                INSERT INTO MDHSYS.PAY_RO_SALARY
                (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
                RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE, 
                RPS_ALW_NAME, RPS_GRP_CODE,RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
                VALUES
                (V('G_CP_CODE'), V('G_PRG_CODE'), V('G_USR_NAME'), V('G_SESSION'),
                MON_REC.MON_EMP_CODE, SYSDATE, LC_SEQ_NUM, ALW_REC.ALW_CODE, 'A', 
                ALW_REC.ALW_NAME, 
                DECODE(V('P501_LC_GRP_BY'),'C',LC_CT_CODE ,'D',LC_DS_CODE, 'P', LC_DP_CODE),LC_AMT, LC_DP_CODE, LC_CT_CODE, LC_DS_CODE);
             --  RAISE_APPLICATION_ERROR(-20001,'EMP: '||MON_REC.MON_EMP_CODE||' TOTAL_AMT: '||LC_TOT_AMT);
            END IF;
            LC_AMT := 0;
           --RAISE_APPLICATION_ERROR(-20001,'EMP: '||MON_REC.MON_EMP_CODE||' TOTAL_AMT: '||LC_TOT_AMT);
            LC_SEQ_NUM := LC_SEQ_NUM + 1;
            LC_FLAG := 'T';
        END LOOP;
       -- RAISE_APPLICATION_ERROR(-20001,'EMP: '||MON_REC.MON_EMP_CODE||' TOTAL_AMT: '||LC_TOT_AMT);
        INSERT INTO MDHSYS.PAY_RO_SALARY
        (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
        RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE, 
        RPS_ALW_NAME, RPS_GRP_CODE,RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
        VALUES
        (V('G_CP_CODE'), V('G_PRG_CODE'), V('G_USR_NAME'), V('G_SESSION'),
        MON_REC.MON_EMP_CODE, SYSDATE, LC_SEQ_NUM, 'ZZZ', 'A', 
        'Gross Salary', 
        DECODE(V('P501_LC_GRP_BY'),'C',LC_CT_CODE ,'D',LC_DS_CODE, 'P', LC_DP_CODE),LC_TOT_AMT, LC_DP_CODE, LC_CT_CODE, LC_DS_CODE);
      --  RAISE_APPLICATION_ERROR(-20001,'EMP: '||MON_REC.MON_EMP_CODE||' TOTAL_AMT: '||LC_TOT_AMT);
        LC_SEQ_NUM := LC_SEQ_NUM  + 1;

        FOR DED_REC IN DED_CRS LOOP
            LC_AMT := 0;
          --  LC_TOT_DED := 0;
            FOR MDN_REC IN MDN_CRS(MON_REC.MON_EMP_CODE, DED_REC.DED_CODE) LOOP
                LC_AMT := NVL(MDN_REC.DED_AMT,0);
                LC_TOT_DED := LC_TOT_DED + LC_AMT;
                LC_TOT_AMT := LC_TOT_AMT - LC_AMT;
            END LOOP;
            IF NVL(LC_AMT,0) <> 0 THEN
                INSERT INTO MDHSYS.PAY_RO_SALARY
                (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
                RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE,
                RPS_ALW_NAME, 
                RPS_GRP_CODE, RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
                VALUES
                (V('G_CP_CODE'), V('G_PRG_CODE'), V('G_USR_NAME'), V('G_SESSION'),
                MON_REC.MON_EMP_CODE, SYSDATE, LC_SEQ_NUM, DED_REC.DED_CODE, 'D', 
                DED_REC.DED_NAME, 
                DECODE(V('P501_LC_GRP_BY'),'C',LC_CT_CODE ,'D',LC_DS_CODE, 'P', LC_DP_CODE),LC_AMT, LC_DP_CODE, LC_CT_CODE, LC_DS_CODE);
            END IF;
            LC_AMT := 0;
            LC_SEQ_NUM := LC_SEQ_NUM + 1;
            LC_FLAG := 'T';
        END LOOP;
        
        INSERT INTO MDHSYS.PAY_RO_SALARY
        (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
        RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE, 
        RPS_ALW_NAME, RPS_GRP_CODE,RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
        VALUES
        (V('G_CP_CODE'), V('G_PRG_CODE'), V('G_USR_NAME'), V('G_SESSION'),
        MON_REC.MON_EMP_CODE, SYSDATE, LC_SEQ_NUM, 'ZZZ', 'D', 
        'Total Deduct', 
        DECODE(V('P501_LC_GRP_BY'),'C',LC_CT_CODE ,'D',LC_DS_CODE, 'P', LC_DP_CODE),NVL(LC_TOT_DED,0), LC_DP_CODE, LC_CT_CODE, LC_DS_CODE);
        LC_SEQ_NUM := LC_SEQ_NUM + 1;
        INSERT INTO MDHSYS.PAY_RO_SALARY
        (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
        RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE, 
        RPS_ALW_NAME, RPS_GRP_CODE,RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
        VALUES
        (V('G_CP_CODE'), V('G_PRG_CODE'), V('G_USR_NAME'), V('G_SESSION'),
        MON_REC.MON_EMP_CODE, SYSDATE + 1, LC_SEQ_NUM, 'ZZY', 'W', 
        'Net Salary', 
        DECODE(V('P501_LC_GRP_BY'),'C',LC_CT_CODE ,'D',LC_DS_CODE, 'P', LC_DP_CODE),LC_TOT_AMT, LC_DP_CODE, LC_CT_CODE, LC_DS_CODE);


      --THIS IS FOR ABSENT DAYS AMOUNT
        SELECT SUM(NVL(A.IAL_AMT,0))
        INTO  LC_GRS_SAL 
        FROM  MDHSYS.PAY_TD_INC_ALLOWN A
        WHERE A.IAL_CP_CODE = V('G_CP_CODE')
        AND   A.IAL_EMP_CODE = MON_REC.MON_EMP_CODE
        AND   A.IAL_INC_DATE = (SELECT  MAX(B.IAL_INC_DATE) 
                                FROM    MDHSYS.PAY_TD_INC_ALLOWN B
                                WHERE   B.IAL_CP_CODE = A.IAL_CP_CODE
                                AND     B.IAL_EMP_CODE = A.IAL_EMP_CODE
                                AND     B.IAL_INC_DATE <= V('P501_LC_FM_DATE'));

        BEGIN
            SELECT  EAT_ABSENT
            INTO    LC_ABSENT
            FROM    MDHSYS.PAY_TD_EMP_ATEND
            WHERE   EAT_CP_CODE = V('G_CP_CODE')
            AND     EAT_EMP_CODE = MON_REC.MON_EMP_CODE
            AND     EAT_DATE = V('P501_LC_FM_DATE');
        EXCEPTION WHEN NO_DATA_FOUND THEN
          LC_ABSENT := 0;
        END;

         LC_DAYS := TO_NUMBER(
              TO_CHAR(
                  TO_DATE(V('P501_LC_FM_DATE'),'DD/MM/YYYY'),
              'DD')
           );
        
        IF LC_ABSENT > 0 THEN
            LC_ABSENT_AMT := ROUND((LC_GRS_SAL/LC_DAYS) * LC_ABSENT,0);
        ELSE
            LC_ABSENT_AMT :=0;
        END IF;


    END LOOP;

    FOR ALL_EMP_REC IN ALL_EMP_CRS LOOP
      FOR ALL_ALW_REC IN ALL_ALW_CRS LOOP
          
          SELECT COUNT(*) 
          INTO CHK
          FROM MDHSYS.PAY_RO_SALARY
          WHERE RPS_CP_CODE   = V('G_CP_CODE')
          AND   RPS_USR_NAME  = V('G_USR_NAME')
          AND   RPS_SESSION   = V('G_SESSION')
          AND   RPS_PRG_CODE  = V('G_PRG_CODE')
          AND   RPS_ALW_CODE  = ALL_ALW_REC.RPS_ALW_CODE
          AND   RPS_EMP_CODE  = ALL_EMP_REC.RPS_EMP_CODE
          AND   RPS_TYPE      = ALL_ALW_REC.RPS_TYPE
          AND   RPS_ALW_NAME  = ALL_ALW_REC.RPS_ALW_NAME;
          
          --MESSAGE(ALL_ALW_REC.RPS_ALW_CODE || );PAUSE;
              --  MESSAGE(CHK);PAUSE;

          IF CHK = 0 THEN
                INSERT INTO MDHSYS.PAY_RO_SALARY
                (RPS_CP_CODE, RPS_PRG_CODE, RPS_USR_NAME, RPS_SESSION,
                RPS_EMP_CODE, RPS_DATE, RPS_SEQ_NUM, RPS_ALW_CODE, RPS_TYPE, 
                RPS_ALW_NAME, RPS_GRP_CODE,RPS_AMT01,RPS_DP_CODE,RPS_CT_CODE,RPS_DS_CODE)
                VALUES
                (ALL_EMP_REC.RPS_CP_CODE, ALL_EMP_REC.RPS_PRG_CODE, ALL_EMP_REC.RPS_USR_NAME, 
                ALL_EMP_REC.RPS_SESSION,ALL_EMP_REC.RPS_EMP_CODE, ALL_EMP_REC.RPS_DATE, LC_SEQ_NUM,
                ALL_ALW_REC.RPS_ALW_CODE, ALL_ALW_REC.RPS_TYPE, 
                ALL_ALW_REC.RPS_ALW_NAME, ALL_EMP_REC.RPS_GRP_CODE,0,
                ALL_EMP_REC.RPS_DP_CODE,ALL_EMP_REC.RPS_CT_CODE,
                ALL_EMP_REC.RPS_DS_CODE);
                LC_SEQ_NUM := LC_SEQ_NUM + 1;
          END IF;
      END LOOP;
    END LOOP;
    LC_FLAG := 'T';
   -- RAISE_APPLICATION_ERROR(-20001,LC_FLAG);
    COMMIT;
    RETURN LC_FLAG;
    
END;
END ISR_GLOBAL;
/

prompt
prompt Creating package body ISR_UTL_PKG
prompt =================================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.ISR_UTL_PKG AS

-----------------------------------------------------------------
--Error Log
-----------------------------------------------------------------
PROCEDURE ERROR_LOG(ARG_DIRECTORY VARCHAR2,ARG_ERROR VARCHAR2) AS
  LC_FILE   UTL_FILE.FILE_TYPE;
  FILE_NAME VARCHAR2(30);
BEGIN
  FILE_NAME := 'Errorlog_'||TO_CHAR(SYSDATE,'MMRRRR')||'.log';
  IF DBMS_LOB.FILEEXISTS(BFILENAME(ARG_DIRECTORY,FILE_NAME)) = 0 THEN
     LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
     UTL_FILE.FCLOSE(LC_FILE);
  END IF;
  LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
  UTL_FILE.PUT_LINE (LC_FILE,ARG_ERROR);
  UTL_FILE.FCLOSE(LC_FILE);
END;

-----------------------------------------------------------------
--Pad String /*Encrypt and Decrypt dep on pad string
-----------------------------------------------------------------
PROCEDURE PADSTRING(ARG_VALUE IN OUT VARCHAR2) IS
  LC_UNIT NUMBER;
BEGIN
  IF LENGTH(ARG_VALUE) MOD 8 > 0 THEN
      LC_UNIT := TRUNC(LENGTH(ARG_VALUE)/8) + 1;
      ARG_VALUE  := RPAD(ARG_VALUE, LC_UNIT * 8, G_PAD_CHR);
  END IF;
END;

-----------------------------------------------------------------
--Encrypt
-----------------------------------------------------------------
FUNCTION ENCRYPT(ARG_VALUE IN VARCHAR2)RETURN RAW IS
  LC_VALUE     VARCHAR2(32767) := ARG_VALUE;
  LC_ENCRYPTED RAW(32767);
BEGIN
  PADSTRING(LC_VALUE);
  DBMS_OBFUSCATION_TOOLKIT.DESENCRYPT(INPUT          => UTL_RAW.CAST_TO_RAW(LC_VALUE),
                                      KEY            => G_KEY,
                                      ENCRYPTED_DATA => LC_ENCRYPTED);
  RETURN LC_ENCRYPTED;
END;

-----------------------------------------------------------------
--Decrypt
-----------------------------------------------------------------
FUNCTION DECRYPT(ARG_VALUE IN RAW)RETURN VARCHAR2 IS
  LC_DECRYPTED VARCHAR2(32767);
BEGIN
  DBMS_OBFUSCATION_TOOLKIT.DESDECRYPT(INPUT          => ARG_VALUE,
                                      KEY            => G_KEY,
                                      DECRYPTED_DATA => LC_DECRYPTED);
  RETURN RTRIM(UTL_RAW.CAST_TO_VARCHAR2(LC_DECRYPTED),G_PAD_CHR);
END;
--------------------------------------------------------------
--Get Config Value
--------------------------------------------------------------
FUNCTION GET_CONFIG_VALUE(ARG_TYPE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
    LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    SELECT CFG_FLAG
    INTO   LC_VAL
    FROM   ISR_XO_CONFIG
    WHERE  CFG_CP_CODE = '01'
    AND    CFG_TYPE    = NVL(ARG_TYPE,CFG_TYPE)
    AND    CFG_NAME    = ARG_COL_NAME;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
END ISR_UTL_PKG;
/

