prompt Creating package body LAB_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.LAB_PKG AS
FUNCTION GET_SPC_RCV_FLAG(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2  , ARG_DSC_CODE VARCHAR2) RETURN VARCHAR2 IS
  LC_FLAG         VARCHAR2(1);
  LC_SMN_FLAG     VARCHAR2(1);
  LC_CNT_SMN      NUMBER;
  LC_MSC_SPC_NUM  VARCHAR2(15);
  LC_MSC_SRV_GRP  VARCHAR2(4);
  LC_MSC_SSB_TYPE VARCHAR2(1);
  LC_WFLOW_FLAG   VARCHAR2(1);
BEGIN
  BEGIN
    SELECT COUNT(*)     ,   MSC_SPC_NUM      , MSC_SRV_GRP       , MSC_SSB_TYPE
    INTO   LC_CNT_SMN   ,  LC_MSC_SPC_NUM    , LC_MSC_SRV_GRP    , LC_MSC_SSB_TYPE
    FROM  (SELECT  'OPD' ,  MSC_SPC_NUM    , MSC_SRV_GRP    , MSC_SSB_TYPE
           FROM   LAB_TM_SMN_COLL SM  , LAB_TD_SMN_COLL SD
           WHERE  SD.DSC_CP_CODE  = SM.MSC_CP_CODE
           AND    SD.DSC_SPC_NUM  = SM.MSC_SPC_NUM
           AND    SD.DSC_SPC_DATE = SM.MSC_SPC_DATE
           AND    SD.DSC_DOC_NUM  = SM.MSC_DOC_NUM
           AND    SM.MSC_SPC_BCODE IS NOT NULL
           AND    SM.MSC_CP_CODE     = ARG_CP_CODE
           AND    SD.DSC_DSC_CODE    = ARG_DSC_CODE
           --AND    SM.MSC_BR_CODE     = ARG_BR_CODE
           AND    SM.MSC_DOC_NUM     = ARG_DOC_NUM
           UNION ALL
           SELECT  'IPD' , MIS_SPC_NUM , MIS_SRV_GRP , MIS_SSB_TYPE
           FROM  LAB_TM_IPD_SRVS, LAB_TD_IPD_SRVS
           WHERE MIS_CP_CODE    = DIS_CP_CODE
           AND   MIS_SPC_NUM    = DIS_SPC_NUM
           AND   DIS_COL_FLAG   = 'Y'
           AND   MIS_PRG_CODE   = 'HOSAS26'
           AND   MIS_SPC_BCODE IS NOT NULL
           AND   MIS_CP_CODE    = ARG_CP_CODE
           AND   DIS_DSC_CODE   = ARG_DSC_CODE
           --AND   MIS_BR_CODE    = ARG_BR_CODE
           AND   MIS_DOC_NUM    = ARG_DOC_NUM)
    GROUP BY MSC_SPC_NUM      , MSC_SRV_GRP       , MSC_SSB_TYPE ;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
         LC_CNT_SMN      := 0;
         LC_MSC_SPC_NUM  := NULL;
         LC_MSC_SRV_GRP  := NULL;
         LC_MSC_SSB_TYPE := NULL;
  END;
  BEGIN
    SELECT DISTINCT NVL(LTI_SMN_FLAG,'N')
    INTO   LC_SMN_FLAG
    FROM   LAB_SM_LT_INFO
    WHERE  LTI_CP_CODE     = ARG_CP_CODE
    AND    LTI_SRV_CODE    = ARG_DSC_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_SMN_FLAG := 'N';
  END;
  ---  LC_SMN_FLAG   -----check Specimen Flag
  ---  LC_CNT_SMN    ---Check Count Speciimen Collected OPD & IPD
  IF LC_SMN_FLAG = 'Y' AND NVL(LC_CNT_SMN,0) > 0 THEN
     BEGIN
       SELECT DISTINCT NVL(TSB_LSR_FLAG,'N')
       INTO   LC_FLAG
       FROM   LAB_TO_SPC_BTR
       WHERE  TSB_CP_CODE                = ARG_CP_CODE
       --AND    NVL(TSB_BR_TO, TSB_BR_FM)  = ARG_BR_CODE
       AND    TSB_DOC_NUM                = ARG_DOC_NUM
       AND    TSB_LSR_SRV_GRP            = LC_MSC_SRV_GRP
       AND    TSB_SPC_NUM                = LC_MSC_SPC_NUM
       --AND    TSB_TYPE                   = LC_MSC_SSB_TYPE
       GROUP BY TSB_LSR_FLAG;
     EXCEPTION
       WHEN NO_DATA_FOUND THEN
         /*
            IF LC_FLAG = 'N' THEN
               BEGIN
                 SELECT NVL(TSB_LSR_FLAG,'N')
                 INTO   LC_FLAG
                 FROM   LAB_TO_SPC_BTR
                 WHERE  TSB_CP_CODE                = ARG_CP_CODE
                 --AND    NVL(TSB_BR_TO, TSB_BR_FM)  = ARG_BR_CODE
                 AND    TSB_DOC_NUM                = ARG_DOC_NUM
                 AND    TSB_LSR_SRV_GRP            = LC_MSC_SRV_GRP
                 AND    TSB_SPC_NUM                = LC_MSC_SPC_NUM;
                 GROUP BY TSB_LSR_FLAG;
               EXCEPTION
                  WHEN OTHERS THEN
                       LC_FLAG := 'N';
               END;
            END IF;
            */
            LC_FLAG := 'N';
       WHEN OTHERS THEN
            LC_FLAG := 'N';
     END;
  ELSE
     LC_FLAG := 'Y';
  END IF;
  SELECT ISR_SPC_WORKFLOW_FLAG
  INTO   LC_WFLOW_FLAG
  FROM   ISR_XO_CONTROL
  WHERE  ISR_CP_CODE = ARG_CP_CODE;
  IF LC_WFLOW_FLAG = 'N' THEN
     LC_FLAG := 'Y';
  END IF;
  RETURN LC_FLAG;
END;
-------------------------------------------
FUNCTION GET_SRV_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    SELECT DECODE(ARG_COL_NAME,
                  'DSC_MSC_CODE',DSC_MSC_CODE,
                  'MSC_CODE',MSC_CODE,
                  'MSC_TYPE',MSC_TYPE,
                  'DSC_DESC',DSC_DESC,
                  'MSC_DESC',MSC_DESC,
           NULL)
    INTO   LC_VAL
    FROM   HOS_SM_SRV_CHARGES,HOS_SD_SRV_CHARGES
    WHERE  MSC_CP_CODE = DSC_CP_CODE
    AND    MSC_CODE    = DSC_MSC_CODE
    AND    MSC_CP_CODE = ARG_CP_CODE
    AND    DSC_CODE    = ARG_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
-------------------------------------------
FUNCTION GET_SRV_MAP_INFO(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_SRV_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    SELECT DECODE(ARG_COL_NAME,
                  'SSB_BR_OTH',SSB_BR_OTH,
                  'SSB_LOC_CODE',SSB_LOC_CODE,
                  'SSB_TYPE',SSB_TYPE,
                  'SSB_FLAG',SSB_FLAG,
           NULL)
    INTO   LC_VAL
    FROM   LAB_SO_SPC_SRV_BRN
    WHERE  SSB_CP_CODE  = ARG_CP_CODE
    AND    SSB_DSC_CODE = ARG_SRV_CODE
    AND    SSB_BR_CODE  = ARG_BR_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  IF ARG_COL_NAME = 'SSB_TYPE' THEN
     IF ARG_BR_CODE = LAB_PKG.GET_CONTROL_VALUE(ARG_CP_CODE,'ISR_DFT_SPC_TRN_BR') AND NVL(LC_VAL,'I') <> 'O' THEN
        LC_VAL := 'I';
     ELSIF ARG_BR_CODE <> LAB_PKG.GET_CONTROL_VALUE(ARG_CP_CODE,'ISR_DFT_SPC_TRN_BR') THEN
        IF LC_VAL IS NULL THEN
           LC_VAL := 'E';
        ELSE
           LC_VAL := LC_VAL;
        END IF;
     END IF;
  END IF;
  RETURN LC_VAL;
END;
-------------------------------------------
FUNCTION GET_CONTROL_VALUE(ARG_CP_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    SELECT DECODE(ARG_COL_NAME,
                  'ISR_DFT_SPC_TRN_BR',ISR_DFT_SPC_TRN_BR,
           NULL)
    INTO   LC_VAL
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE  = ARG_CP_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
-------------------------------------------
FUNCTION GEN_DOC_NUM(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_PRG_CODE VARCHAR2,ARG_TRN_TYPE VARCHAR2,ARG_ACT_TYPE VARCHAR2,ARG_TAB_NAME VARCHAR2,ARG_DATE DATE) RETURN VARCHAR2 IS
  LC_DAL_ALS_CODE   VARCHAR2(3);
  LC_DAL_PRG_CODE   VARCHAR2(7);
  LC_DAL_TRN_TYPE   VARCHAR2(1);
  LC_DAL_ACT_TYPE   VARCHAR2(1);
  LC_DAL_DOC_FORMAT VARCHAR2(15);
  LC_DOC_NUM        VARCHAR2(15) := NULL;
  LC_NUM            VARCHAR2(5);
BEGIN
  BEGIN
    SELECT DAL_ALS_CODE  ,  DAL_PRG_CODE     , DAL_TRN_TYPE    , DAL_ACT_TYPE    , DAL_DOC_FORMAT
    INTO   LC_DAL_ALS_CODE ,  LC_DAL_PRG_CODE  , LC_DAL_TRN_TYPE , LC_DAL_ACT_TYPE , LC_DAL_DOC_FORMAT
    FROM   ISR_XO_DOC_ALIAS
    WHERE  DAL_CP_CODE    =   ARG_CP_CODE
    AND    DAL_BR_CODE    =   ARG_BR_CODE
    AND    DAL_PRG_CODE   =   ARG_PRG_CODE
    AND    DECODE(DAL_TRN_TYPE,'%',ARG_TRN_TYPE, DAL_TRN_TYPE)  = ARG_TRN_TYPE
    AND    DECODE(DAL_ACT_TYPE,'%',ARG_ACT_TYPE,DAL_ACT_TYPE)   = ARG_ACT_TYPE;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
         LC_DAL_ALS_CODE   := NULL;
         LC_DAL_PRG_CODE   := NULL;
         LC_DAL_TRN_TYPE   := NULL;
         LC_DAL_ACT_TYPE   := NULL;
         LC_DAL_DOC_FORMAT := NULL;
         Raise_application_error(-20000, 'Unable to generate document number, alias information not exists..');
  END;
  IF ARG_TAB_NAME = 'LAB_TM_SPC_BTR' THEN
     SELECT LC_DAL_ALS_CODE||TO_CHAR(ARG_DATE,'RRMMDD')||LPAD(NVL(MAX(NVL(SUBSTR(MSB_NUM,10),0)),0)+1,5,0)
     INTO   LC_DOC_NUM
     FROM   LAB_TM_SPC_BTR
     WHERE  MSB_CP_CODE      = ARG_CP_CODE
     AND    DECODE(MSB_TYPE,'T',MSB_BR_FM,MSB_BR_TO) = ARG_BR_CODE
     AND    SUBSTR(MSB_NUM,1,3) = LC_DAL_ALS_CODE
     AND    MSB_DATE         = ARG_DATE;
  ELSIF ARG_TAB_NAME = 'LAB_TO_SPC_BTR' THEN
     SELECT TO_CHAR(ARG_DATE,'RRMMDD')||LPAD(NVL(MAX(NVL(SUBSTR(TSB_NUM,7),0)),0)+1,5,0)
     INTO   LC_DOC_NUM
     FROM   LAB_TO_SPC_BTR
     WHERE  TSB_CP_CODE      = ARG_CP_CODE
     AND    TSB_BR_FM        = ARG_BR_CODE
     AND    SUBSTR(TSB_NUM,1,6) = TO_CHAR(ARG_DATE,'RRMMDD');
  END IF;
  RETURN LC_DOC_NUM;
END;
--------------------------------------------------------------------------------------
PROCEDURE GEN_TRAN_FROM_COLL(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_RCT_NUM VARCHAR2,ARG_COL_NUM VARCHAR2,ARG_DSC_CODE VARCHAR2 DEFAULT NULL) AS
  CURSOR C1 IS
         SELECT MSC_CP_CODE,MSC_BR_CODE,MSC_INS_USER,MSC_DOC_NUM,MSC_SPC_NUM,MSC_SRV_GRP,DSC_DSC_CODE,MSC_SPC_BCODE
         FROM   LAB_TM_SMN_COLL,LAB_TD_SMN_COLL,HOS_TM_OPD_SRV_RCPT
         WHERE  MSC_CP_CODE  = MSR_CP_CODE
         AND    MSC_BR_CODE  = MSR_BR_CODE
         AND    MSC_DOC_NUM  = MSR_NUM
         AND    MSC_CP_CODE  = DSC_CP_CODE
         AND    MSC_SPC_NUM  = DSC_SPC_NUM
         AND    MSR_PRG_CODE = 'HOSAS26'
         AND    MSR_CP_CODE  = ARG_CP_CODE
         --AND    MSR_BR_CODE  = ARG_BR_CODE
         AND    MSC_DOC_NUM  = ARG_RCT_NUM
         AND    MSC_SPC_NUM  = NVL(ARG_COL_NUM,MSC_SPC_NUM)
         AND    MSC_SRV_GRP  = NVL(ARG_DSC_CODE,MSC_SRV_GRP)
         AND    NOT EXISTS(SELECT 1
                           FROM   LAB_TO_SPC_BTR
                           WHERE  TSB_CP_CODE = MSC_CP_CODE
                           AND    TSB_DOC_NUM = MSC_DOC_NUM
                           AND    TSB_SPC_NUM = MSC_SPC_NUM
                           AND    TSB_LST_SRV_GRP = MSC_SRV_GRP)
         UNION
         SELECT MIS_CP_CODE,MIS_BR_CODE,MIS_INS_USER,MIS_DOC_NUM,MIS_SPC_NUM,MIS_SRV_GRP,DIS_DSC_CODE,MIS_SPC_BCODE
         FROM   LAB_TM_IPD_SRVS,LAB_TD_IPD_SRVS,LAB_SM_LT_INFO
         WHERE  MIS_CP_CODE  = DIS_CP_CODE
         AND    MIS_SPC_NUM  = DIS_SPC_NUM
         AND    DIS_CP_CODE  = LTI_CP_CODE
         AND    DIS_DSC_CODE = LTI_SRV_CODE
         AND    LTI_SMN_FLAG = 'Y'
         AND    DIS_COL_FLAG = 'Y'
         AND    MIS_PRG_CODE = 'HOSAS26'
         AND    MIS_CP_CODE  = ARG_CP_CODE
         --AND    MIS_BR_CODE  = ARG_BR_CODE
         AND    MIS_DOC_NUM  = ARG_RCT_NUM
         AND    MIS_SPC_NUM  = NVL(ARG_COL_NUM,MIS_SPC_NUM)
         AND    MIS_SRV_GRP  = NVL(ARG_DSC_CODE,MIS_SRV_GRP)
         AND    NOT EXISTS(SELECT 1
                           FROM   LAB_TO_SPC_BTR
                           WHERE  TSB_CP_CODE = MIS_CP_CODE
                           AND    TSB_DOC_NUM = MIS_DOC_NUM
                           AND    TSB_SPC_NUM = MIS_SPC_NUM
                           AND    TSB_LST_SRV_GRP = MIS_SRV_GRP);
  LC_DSC_TYPE VARCHAR2(1);
  LC_LOC_CODE VARCHAR2(10);
  LC_BR_OTH   VARCHAR2(3);
  LC_MSB_NUM  VARCHAR2(15);
  LC_DOC_NUM  VARCHAR2(15);
  LC_CNT      NUMBER;
  LC_SEQ_NUM  NUMBER;
BEGIN
  FOR A IN C1 LOOP
      LC_DSC_TYPE := NVL(LAB_PKG.GET_SRV_MAP_INFO(A.MSC_CP_CODE,A.MSC_BR_CODE,A.DSC_DSC_CODE,'SSB_TYPE'),'E');
      LC_BR_OTH   := NVL(LAB_PKG.GET_SRV_MAP_INFO(A.MSC_CP_CODE,A.MSC_BR_CODE,A.DSC_DSC_CODE,'SSB_BR_OTH'),LAB_PKG.GET_CONTROL_VALUE(A.MSC_CP_CODE,'ISR_DFT_SPC_TRN_BR'));
      IF A.MSC_BR_CODE = LC_BR_OTH AND LC_DSC_TYPE = 'E' THEN
         LC_DSC_TYPE := 'I';
      END IF;
      IF LC_DSC_TYPE = 'E' THEN
         LC_LOC_CODE := NULL;
         LC_BR_OTH   := NVL(LAB_PKG.GET_SRV_MAP_INFO(A.MSC_CP_CODE,A.MSC_BR_CODE,A.DSC_DSC_CODE,'SSB_BR_OTH'),LAB_PKG.GET_CONTROL_VALUE(A.MSC_CP_CODE,'ISR_DFT_SPC_TRN_BR'));
      ELSIF LC_DSC_TYPE = 'O' THEN
         LC_LOC_CODE := LAB_PKG.GET_SRV_MAP_INFO(A.MSC_CP_CODE,A.MSC_BR_CODE,A.DSC_DSC_CODE,'SSB_LOC_CODE');
         LC_BR_OTH   := NVL(LAB_PKG.GET_SRV_MAP_INFO(A.MSC_CP_CODE,A.MSC_BR_CODE,A.DSC_DSC_CODE,'SSB_BR_OTH'),LAB_PKG.GET_CONTROL_VALUE(A.MSC_CP_CODE,'ISR_DFT_SPC_TRN_BR'));
      ELSIF LC_DSC_TYPE = 'I' THEN
         LC_LOC_CODE := NULL;
         LC_BR_OTH   := NULL;
      END IF;
      IF LC_DSC_TYPE IN ('E','O') THEN
         SELECT COUNT(*),MAX(MSB_NUM)
         INTO   LC_CNT,LC_MSB_NUM
         FROM   LAB_TM_SPC_BTR
         WHERE  MSB_CP_CODE  = A.MSC_CP_CODE
         AND    MSB_BR_FM    = A.MSC_BR_CODE
         AND    MSB_BR_TO    = LC_BR_OTH
--         AND    NVL(MSB_LOC_CODE,'-') = NVL(LC_LOC_CODE,'-')
         AND    MSB_MNL_SYS  = 'S'
         AND    MSB_TYPE     = 'T'
         AND    MSB_STP_USR IS NULL;
         IF LC_CNT = 0 THEN
            LC_MSB_NUM := LAB_PKG.GEN_DOC_NUM(A.MSC_CP_CODE,A.MSC_BR_CODE ,'LABAS12','%','%','LAB_TM_SPC_BTR',TO_DATE(SYSDATE));
            INSERT INTO LAB_TM_SPC_BTR
                  (MSB_CP_CODE,         MSB_BR_CODE,            MSB_TYPE,            MSB_DATE,            MSB_NUM,
                   MSB_BR_FM,           MSB_BR_TO,              MSB_STATUS,          MSB_MNL_SYS,
                   MSB_INS_DTIME,       MSB_INS_USR)
            VALUES(A.MSC_CP_CODE,       A.MSC_BR_CODE,          'T',                 TO_DATE(SYSDATE),    LC_MSB_NUM,
                   A.MSC_BR_CODE,       LC_BR_OTH,              'U',                 'S',
                   SYSDATE,             A.MSC_INS_USER);
         END IF;
         --DBMS_OUTPUT.PUT_LINE(A.DSC_DSC_CODE||' '||LC_MSB_NUM||' '||LC_DSC_TYPE);
         IF LC_MSB_NUM IS NOT NULL THEN
/*            SELECT COUNT(*)
            INTO   LC_CNT
            FROM   LAB_TD_SPC_BTR
            WHERE  DSB_CP_CODE   = A.MSC_CP_CODE
            AND    DSB_SPC_NUM   = A.MSC_SPC_NUM
            AND    DSB_DOC_NUM   = A.MSC_DOC_NUM
            AND    DSB_SPC_BCODE = A.MSC_SPC_BCODE;*/
            SELECT COUNT(*)
            INTO   LC_CNT
            FROM   LAB_TM_SPC_BTR,LAB_TD_SPC_BTR
            WHERE  MSB_CP_CODE   = DSB_CP_CODE
            AND    MSB_NUM       = DSB_MSB_NUM
            AND    MSB_BR_FM     = A.MSC_BR_CODE
            AND    MSB_BR_TO     = LC_BR_OTH
            AND    NVL(DSB_LOC_CODE,'-') = NVL(LC_LOC_CODE,'-')
            AND    DSB_CP_CODE   = A.MSC_CP_CODE
            AND    DSB_SPC_NUM   = A.MSC_SPC_NUM
            AND    DSB_DOC_NUM   = A.MSC_DOC_NUM;
            IF LC_CNT = 0 THEN
               SELECT NVL(MAX(NVL(DSB_SEQ_NUM,0)),0) + 1
               INTO   LC_SEQ_NUM
               FROM   LAB_TD_SPC_BTR
               WHERE  DSB_CP_CODE = A.MSC_CP_CODE
               AND    DSB_MSB_NUM = LC_MSB_NUM;
               INSERT INTO LAB_TD_SPC_BTR
                     (DSB_CP_CODE,          DSB_MSB_NUM,        DSB_SEQ_NUM,      DSB_SRV_GRP,         DSB_SPC_NUM,
                      DSB_SPC_BCODE,        DSB_DOC_NUM,        DSB_FAK_FLAG,     DSB_DTIME,           DSB_USR,
                      DSB_LOC_CODE,         DSB_SSB_TYPE)
               VALUES(A.MSC_CP_CODE,        LC_MSB_NUM,         LC_SEQ_NUM,       A.MSC_SRV_GRP,       A.MSC_SPC_NUM,
                      A.MSC_SPC_BCODE,      A.MSC_DOC_NUM,      'N',              SYSDATE,             A.MSC_INS_USER,
                      LC_LOC_CODE,          LC_DSC_TYPE);
            END IF;
         END IF;
      ELSE
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   LAB_TO_SPC_BTR
        WHERE  TSB_CP_CODE  = A.MSC_CP_CODE
        AND    TSB_BR_FM    = A.MSC_BR_CODE
        AND    NVL(TSB_BR_TO,'-')    = NVL(LC_BR_OTH,'-')
        AND    TSB_TYPE     = LC_DSC_TYPE
        AND    TSB_LST_SRV_GRP = A.MSC_SRV_GRP
        AND    NVL(TSB_LOC_CODE,'-') = NVL(LC_LOC_CODE,'-')
        AND    TSB_SPC_NUM   = A.MSC_SPC_NUM
        AND    TSB_DOC_NUM   = A.MSC_DOC_NUM;
        IF LC_CNT = 0 THEN
           LC_DOC_NUM := LAB_PKG.GEN_DOC_NUM(A.MSC_CP_CODE,A.MSC_BR_CODE ,'LABAS15','%','%','LAB_TO_SPC_BTR',TO_DATE(SYSDATE));
           INSERT INTO LAB_TO_SPC_BTR
                 (TSB_CP_CODE,       TSB_NUM,          TSB_BR_FM,        TSB_BR_TO,       TSB_LOC_CODE,
                  TSB_TYPE,          TSB_DOC_NUM,      TSB_SPC_NUM,      TSB_LST_USR,     TSB_LST_DTIME,
                  TSB_LST_SRV_GRP,   TSB_LSR_SRV_GRP,  TSB_LSR_FLAG)
           VALUES(A.MSC_CP_CODE,     LC_DOC_NUM,       A.MSC_BR_CODE,    LC_BR_OTH,       LC_LOC_CODE,
                  LC_DSC_TYPE,       A.MSC_DOC_NUM,    A.MSC_SPC_NUM,    A.MSC_INS_USER,  SYSDATE,
                  A.MSC_SRV_GRP,     A.MSC_SRV_GRP,    'N');
        END IF;
      END IF;
  END LOOP;
  COMMIT;
END;
----------------------------------------------------------------------------------------------------
PROCEDURE GEN_RCVD_FROM_TRNS(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_USER VARCHAR2) AS
  LC_MSB_NUM VARCHAR2(15);
BEGIN
  BEGIN
    IF ARG_BR_CODE = LAB_PKG.GET_CONTROL_VALUE(ARG_CP_CODE,'ISR_DFT_SPC_TRN_BR') THEN
       BEGIN
         SELECT MSB_NUM
         INTO   LC_MSB_NUM
         FROM   LAB_TM_SPC_BTR
         WHERE  MSB_CP_CODE = ARG_CP_CODE
         AND    MSB_REF_NUM = ARG_DOC_NUM;
       EXCEPTION
         WHEN OTHERS THEN
              LC_MSB_NUM := NULL;
       END;
       IF LC_MSB_NUM IS NULL THEN
       LC_MSB_NUM := LAB_PKG.GEN_DOC_NUM(ARG_CP_CODE,ARG_BR_CODE ,'LABAS13','%','%','LAB_TM_SPC_BTR',TO_DATE(SYSDATE));
       INSERT INTO LAB_TM_SPC_BTR
             (MSB_CP_CODE,            MSB_BR_CODE,           MSB_TYPE,              MSB_DATE,             MSB_NUM,
              MSB_REF_NUM,            MSB_BR_FM,             MSB_BR_TO,             MSB_LOC_CODE,         MSB_STATUS,
              MSB_MNL_SYS,            MSB_INS_DTIME,         MSB_INS_USR)
       SELECT MSB_CP_CODE,            ARG_BR_CODE,           'R',                   TO_DATE(SYSDATE),     LC_MSB_NUM,
              MSB_NUM,                MSB_BR_FM,             MSB_BR_TO,             MSB_LOC_CODE,         'U',
              'S',                    SYSDATE,               ARG_USER
       FROM   LAB_TM_SPC_BTR
       WHERE  MSB_CP_CODE = ARG_CP_CODE
       AND    MSB_NUM     = ARG_DOC_NUM;
       END IF;
    ELSE
       BEGIN
         SELECT MSB_NUM
         INTO   LC_MSB_NUM
         FROM   LAB_TM_SPC_BTR
         WHERE  MSB_CP_CODE = ARG_CP_CODE
         AND    MSB_REF_NUM = ARG_DOC_NUM;
       EXCEPTION
         WHEN OTHERS THEN
              LC_MSB_NUM := NULL;
       END;
    END IF;
    IF LC_MSB_NUM IS NOT NULL THEN
       INSERT INTO LAB_TD_SPC_BTR
             (DSB_CP_CODE,            DSB_MSB_NUM,          DSB_SEQ_NUM,           DSB_SEQ_REF,        DSB_SRV_GRP,
              DSB_SPC_NUM,            DSB_SPC_BCODE,        DSB_DOC_NUM,           DSB_DTIME,          DSB_USR,
              DSB_SSB_TYPE,           DSB_LOC_CODE,         DSB_FAK_FLAG,          DSB_FAK_DTIME)
       SELECT DSB_CP_CODE,            LC_MSB_NUM,           DSB_SEQ_NUM,           DSB_SEQ_NUM,        DSB_SRV_GRP,
              DSB_SPC_NUM,            DSB_SPC_BCODE,        DSB_DOC_NUM,           SYSDATE,            ARG_USER,
              DSB_SSB_TYPE,           DSB_LOC_CODE,         'Y',                   SYSDATE
       FROM   LAB_TD_SPC_BTR A
       WHERE  DSB_CP_CODE = ARG_CP_CODE
       AND    DSB_MSB_NUM = ARG_DOC_NUM
       AND    EXISTS(SELECT 1
                     FROM   LAB_TM_SPC_BTR
                     WHERE  MSB_CP_CODE = ARG_CP_CODE
                     AND    MSB_NUM     = ARG_DOC_NUM)
       AND    NOT EXISTS(SELECT 1
                         FROM   LAB_TM_SPC_BTR,LAB_TD_SPC_BTR B
                         WHERE  B.DSB_CP_CODE = MSB_CP_CODE
                         AND    B.DSB_MSB_NUM = MSB_NUM
                         AND    MSB_TYPE      = 'R'
                         AND    MSB_CP_CODE   = A.DSB_CP_CODE
                         AND    MSB_REF_NUM   = A.DSB_MSB_NUM
                         AND    B.DSB_DOC_NUM = A.DSB_DOC_NUM
                         AND    B.DSB_SPC_NUM = A.DSB_SPC_NUM);
       /*
       UPDATE LAB_TM_SPC_BTR
       SET    MSB_STATUS   = 'P',
              MSB_TR_DTIME = SYSDATE,
              MSB_TR_USR   = ARG_USER
       WHERE  MSB_CP_CODE  = ARG_CP_CODE
       AND    MSB_NUM      = ARG_DOC_NUM;
       */
       COMMIT;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
         ROLLBACK;
         RAISE_APPLICATION_ERROR(-20001,SQLERRM);
  END;
END;
----------------------------
PROCEDURE DEL_TRN_SPC_TO_NEW(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_TRN_NUM VARCHAR2,ARG_RCT_NUM VARCHAR2,ARG_SPC_NUM VARCHAR2,ARG_USER VARCHAR2) AS
  LC_MBTR_REC LAB_TM_SPC_BTR%ROWTYPE;
  LC_DBTR_REC LAB_TD_SPC_BTR%ROWTYPE;
  LC_SEQ_NUM  NUMBER;
  LC_CNT      NUMBER;
  LC_MSB_NUM  VARCHAR2(15);
BEGIN
  --RAISE_APPLICATION_ERROR(-20001,'1'||ARG_TRN_NUM||' '||LC_MBTR_REC.MSB_BR_FM);
  BEGIN
    SELECT *
    INTO   LC_MBTR_REC
    FROM   LAB_TM_SPC_BTR
    WHERE  MSB_CP_CODE = ARG_CP_CODE
    AND    MSB_NUM     = ARG_TRN_NUM;
  EXCEPTION
    WHEN OTHERS THEN
         LC_MBTR_REC := NULL;
  END;
--  RAISE_APPLICATION_ERROR(-20001,ARG_TRN_NUM||' '||LC_MBTR_REC.MSB_BR_FM);
  SELECT COUNT(*),MAX(MSB_NUM)
  INTO   LC_CNT,LC_MSB_NUM
  FROM   LAB_TM_SPC_BTR
  WHERE  MSB_CP_CODE  = LC_MBTR_REC.MSB_CP_CODE
  AND    MSB_BR_FM    = LC_MBTR_REC.MSB_BR_FM
  AND    MSB_BR_TO    = LC_MBTR_REC.MSB_BR_TO
  AND    MSB_MNL_SYS  = 'S'
  AND    MSB_TYPE     = 'T'
  AND    MSB_STP_USR IS NULL;
--  RAISE_APPLICATION_ERROR(-20001,LC_CNT||' '||LC_MSB_NUM);
  IF LC_CNT = 0 THEN
     LC_MSB_NUM := LAB_PKG.GEN_DOC_NUM(LC_MBTR_REC.MSB_CP_CODE,LC_MBTR_REC.MSB_BR_FM ,'LABAS12','%','%','LAB_TM_SPC_BTR',TO_DATE(SYSDATE));
     INSERT INTO LAB_TM_SPC_BTR
           (MSB_CP_CODE,             MSB_BR_CODE,             MSB_TYPE,                 MSB_DATE,            MSB_NUM,
            MSB_BR_FM,               MSB_BR_TO,               MSB_LOC_CODE,             MSB_STATUS,          MSB_MNL_SYS,
            MSB_INS_DTIME,           MSB_INS_USR)
     VALUES(LC_MBTR_REC.MSB_CP_CODE, LC_MBTR_REC.MSB_BR_CODE, 'T',                      TO_DATE(SYSDATE),    LC_MSB_NUM,
            LC_MBTR_REC.MSB_BR_FM,   LC_MBTR_REC.MSB_BR_TO,   LC_MBTR_REC.MSB_LOC_CODE, 'U',                 'S',
            SYSDATE,                 ARG_USER);
  END IF;
  BEGIN
    SELECT *
    INTO   LC_DBTR_REC
    FROM   LAB_TD_SPC_BTR
    WHERE  DSB_CP_CODE = ARG_CP_CODE
    AND    DSB_MSB_NUM = ARG_TRN_NUM
    AND    DSB_DOC_NUM = ARG_RCT_NUM
    AND    DSB_SPC_NUM = ARG_SPC_NUM;
  EXCEPTION
    WHEN OTHERS THEN
         LC_DBTR_REC := NULL;
  END;
--    RAISE_APPLICATION_ERROR(-20001,'2 '||ARG_TRN_NUM||' - '||LC_MSB_NUM||' - '||LC_CNT);
  IF ARG_TRN_NUM <> LC_MSB_NUM THEN
     IF LC_MSB_NUM IS NOT NULL THEN
        SELECT NVL(MAX(NVL(DSB_SEQ_NUM,0)),0) + 1
        INTO   LC_SEQ_NUM
        FROM   LAB_TD_SPC_BTR
        WHERE  DSB_CP_CODE = ARG_CP_CODE
        AND    DSB_MSB_NUM = LC_MSB_NUM;
        INSERT INTO LAB_TD_SPC_BTR
              (DSB_CP_CODE,               DSB_MSB_NUM,             DSB_SEQ_NUM,              DSB_SRV_GRP,             DSB_SPC_NUM,
               DSB_SPC_BCODE,             DSB_DOC_NUM,             DSB_FAK_FLAG,             DSB_DTIME,               DSB_USR,
               DSB_SFT_FLAG,              DSB_SFT_REF,             DSB_SSB_TYPE,             DSB_LOC_CODE)
        VALUES(LC_DBTR_REC.DSB_CP_CODE,   LC_MSB_NUM,              LC_SEQ_NUM,               LC_DBTR_REC.DSB_SRV_GRP, LC_DBTR_REC.DSB_SPC_NUM,
               LC_DBTR_REC.DSB_SPC_BCODE, LC_DBTR_REC.DSB_DOC_NUM, 'N',                      SYSDATE,                 ARG_USER,
               'Y',                       LC_DBTR_REC.DSB_MSB_NUM, LC_DBTR_REC.DSB_SSB_TYPE, LC_DBTR_REC.DSB_LOC_CODE);
     END IF;
     DELETE FROM LAB_TD_SPC_BTR
     WHERE  DSB_CP_CODE = ARG_CP_CODE
     AND    DSB_MSB_NUM = ARG_TRN_NUM
     AND    DSB_DOC_NUM = ARG_RCT_NUM
     AND    DSB_SPC_NUM = ARG_SPC_NUM;
  END IF;
END;
-------------------------------------------------
PROCEDURE GEN_IDPT_RCVD_FROM_RCVD(ARG_CP_CODE VARCHAR2,ARG_BR_CODE VARCHAR2,ARG_TRN_NUM VARCHAR2,ARG_RCT_NUM VARCHAR2,ARG_SPC_NUM VARCHAR2,ARG_USER VARCHAR2) AS
  CURSOR C1 IS
         SELECT *
         FROM   LAB_TM_SPC_BTR,LAB_TD_SPC_BTR
         WHERE  MSB_CP_CODE  = DSB_CP_CODE
         AND    MSB_NUM      = DSB_MSB_NUM
         AND    MSB_CP_CODE  = ARG_CP_CODE
         AND    MSB_BR_FM    = ARG_BR_CODE
         AND    MSB_REF_NUM  = ARG_TRN_NUM
         AND    DSB_DOC_NUM  = NVL(ARG_RCT_NUM,DSB_DOC_NUM)
         AND    DSB_SPC_NUM  = NVL(ARG_SPC_NUM,DSB_SPC_NUM)
         AND    MSB_TYPE     = 'R'
         AND    DSB_FAK_FLAG = 'Y';
 -- LC_DSC_TYPE VARCHAR2(1);
  LC_DOC_NUM  VARCHAR2(100);
  LC_CNT      NUMBER;
BEGIN
  FOR A IN C1 LOOP
      SELECT COUNT(*)
      INTO   LC_CNT
      FROM   LAB_TO_SPC_BTR
      WHERE  TSB_CP_CODE  = A.MSB_CP_CODE
      AND    TSB_BR_FM    = A.MSB_BR_FM
      AND    TSB_BR_TO    = A.MSB_BR_TO
      AND    TSB_TYPE     = A.DSB_SSB_TYPE
      AND    TSB_LST_SRV_GRP = A.DSB_SRV_GRP
      AND    NVL(TSB_LOC_CODE,'-') = NVL(A.DSB_LOC_CODE,'-')
      AND    TSB_SPC_NUM   = A.DSB_SPC_NUM
      AND    TSB_DOC_NUM   = A.DSB_DOC_NUM;
      IF LC_CNT = 0 THEN
         LC_DOC_NUM := LAB_PKG.GEN_DOC_NUM(A.MSB_CP_CODE,A.MSB_BR_FM ,'LABAS15','%','%','LAB_TO_SPC_BTR',TO_DATE(SYSDATE));
         INSERT INTO LAB_TO_SPC_BTR
               (TSB_CP_CODE,        TSB_NUM,            TSB_BR_FM,        TSB_BR_TO,       TSB_LOC_CODE,
                TSB_TYPE,           TSB_DOC_NUM,        TSB_SPC_NUM,      TSB_LST_USR,     TSB_LST_DTIME,
                TSB_LST_SRV_GRP,    TSB_LSR_FLAG,       TSB_LSR_SRV_GRP,  TSB_REF_NUM)
         VALUES(A.MSB_CP_CODE,      LC_DOC_NUM,         A.MSB_BR_FM,      A.MSB_BR_TO,     A.DSB_LOC_CODE,
                A.DSB_SSB_TYPE,     A.DSB_DOC_NUM,      A.DSB_SPC_NUM,    ARG_USER,        SYSDATE,
                A.DSB_SRV_GRP,      'N',                A.DSB_SRV_GRP,    A.MSB_NUM);
      END IF;

  END LOOP;
  UPDATE LAB_TM_SPC_BTR
  SET    MSB_STATUS   = 'P',
         MSB_TR_DTIME = SYSDATE,
         MSB_TR_USR   = ARG_USER
  WHERE  MSB_CP_CODE  = ARG_CP_CODE
  AND    MSB_NUM      = LC_DOC_NUM
  AND    MSB_BR_CODE  = ARG_BR_CODE;
END;
-------------------------------------------------
FUNCTION GET_COL_TYPE_RIGHTS(ARG_CP_CODE VARCHAR2,ARG_USR_NAME VARCHAR2,ARG_TYPE VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(100);
BEGIN
  IF ARG_TYPE IS NULL THEN
     LC_VAL := 'Y';
  ELSE
     BEGIN
       SELECT DECODE(ARG_TYPE,'I',USR_COL_INT_FLAG,'E',USR_COL_EXT_FLAG,'O',USR_COL_OTS_FLAG,'N')
       INTO   LC_VAL
       FROM   ISR_XO_USERS
       WHERE  USR_CP_CODE = ARG_CP_CODE
       AND    USR_NAME    = ARG_USR_NAME;
     EXCEPTION
       WHEN OTHERS THEN
            LC_VAL := 'N';
     END;
  END IF;
  RETURN LC_VAL;
END;
----------------------------------------------------------------------------------------
FUNCTION GET_SPC_BCODE(ARG_CP_CODE VARCHAR2,ARG_PRG_CODE VARCHAR2,ARG_DATE DATE) RETURN VARCHAR2 IS
  LC_SPC_BCODE VARCHAR2(10);
BEGIN
  BEGIN
    SELECT TO_CHAR(ARG_DATE,'RR')||LPAD(NVL(MAX(NVL(SUBSTR(SLIP_NUM,3),0)),0) + 1,7,0)
    INTO   LC_SPC_BCODE
    FROM  (SELECT MSR_LAB_SLIP_NUM AS SLIP_NUM
           FROM   HOS_TM_OPD_SRV_RCPT
           WHERE  MSR_CP_CODE  = ARG_CP_CODE
           AND    MSR_PRG_CODE = ARG_PRG_CODE
           AND    MSR_DATE BETWEEN ARG_DATE - 30 AND ARG_DATE + 30
           AND    TO_CHAR(MSR_DATE,'RR') = TO_CHAR(ARG_DATE,'RR')
           UNION
           SELECT MIS_LAB_SLIP_NUM AS SLIP_NUM
           FROM   LAB_TM_IPD_SRVS
           WHERE  MIS_CP_CODE  = ARG_CP_CODE
           AND    MIS_PRG_CODE = ARG_PRG_CODE
           AND    MIS_SPC_DATE BETWEEN ARG_DATE - 30 AND ARG_DATE + 30
           AND    TO_CHAR(MIS_SPC_DATE,'RR') = TO_CHAR(ARG_DATE,'RR')
           UNION
           SELECT MIS_SPC_BCODE AS SLIP_NUM
           FROM   LAB_TM_IPD_SRVS
           WHERE  MIS_CP_CODE  = ARG_CP_CODE
           AND    MIS_PRG_CODE = ARG_PRG_CODE
           AND    MIS_SPC_DATE BETWEEN ARG_DATE - 30 AND ARG_DATE + 30
           AND    TO_CHAR(MIS_SPC_DATE,'RR') = TO_CHAR(ARG_DATE,'RR')
           UNION
           SELECT DSR_SPC_BCODE AS SLIP_NUM
           FROM   HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT
           WHERE  MSR_CP_CODE  = DSR_CP_CODE
           AND    MSR_NUM      = DSR_MSR_NUM
           AND    MSR_CP_CODE  = ARG_CP_CODE
           AND    MSR_PRG_CODE = ARG_PRG_CODE
           AND    MSR_DATE BETWEEN ARG_DATE - 30 AND ARG_DATE + 30
           AND    TO_CHAR(MSR_DATE,'RR') = TO_CHAR(ARG_DATE,'RR')
           UNION
           SELECT MSC_SPC_BCODE AS SLIP_NUM
           FROM   HOS_TM_OPD_SRV_RCPT,LAB_TM_SMN_COLL
           WHERE  MSR_CP_CODE  = MSC_CP_CODE
           AND    MSR_NUM      = MSC_DOC_NUM
           AND    MSR_CP_CODE  = ARG_CP_CODE
           AND    MSR_PRG_CODE = ARG_PRG_CODE
           AND    MSR_DATE BETWEEN ARG_DATE - 30 AND ARG_DATE + 30
           AND    TO_CHAR(MSR_DATE,'RR') = TO_CHAR(ARG_DATE,'RR'));
  END;
  RETURN LC_SPC_BCODE;
END;
----------------------------------------------------------------------------------------
FUNCTION GET_RCT_NUM(ARG_CP_CODE VARCHAR2,ARG_SPC_BCODE VARCHAR2) RETURN VARCHAR2 IS
  LC_RCT_NUM VARCHAR2(15);
BEGIN
  BEGIN
    SELECT DSR_MSR_NUM
    INTO   LC_RCT_NUM
    FROM   HOS_TD_OPD_SRV_RCPT
    WHERE  DSR_CP_CODE   = ARG_CP_CODE
    AND    DSR_SPC_BCODE = ARG_SPC_BCODE
    GROUP BY DSR_MSR_NUM;
  EXCEPTION
    WHEN OTHERS THEN
         LC_RCT_NUM := NULL;
  END;
  IF LC_RCT_NUM IS NULL THEN
     BEGIN
       SELECT MIS_SPC_NUM
       INTO   LC_RCT_NUM
       FROM   LAB_TM_IPD_SRVS
       WHERE  MIS_CP_CODE   = ARG_CP_CODE
       AND    MIS_SPC_BCODE = ARG_SPC_BCODE
       GROUP BY MIS_SPC_NUM;
     EXCEPTION
       WHEN OTHERS THEN
            LC_RCT_NUM := NULL;
     END;
  END IF;
  RETURN LC_RCT_NUM;
END;
----------------------------------------------------------------------------------------
PROCEDURE GEN_WF_MISSING_TRANS(ARG_CP_CODE VARCHAR2,ARG_RCT_NUM VARCHAR2) AS
  CURSOR C1 IS
         SELECT MSR_CP_CODE,MSR_BR_CODE,DSC_DOC_NUM,DSC_SPC_NUM
         FROM   HOS_TM_OPD_SRV_RCPT,HOS_TD_OPD_SRV_RCPT,LAB_TD_SMN_COLL
         WHERE  MSR_CP_CODE  = DSR_CP_CODE
         AND    MSR_NUM      = DSR_MSR_NUM
         AND    DSC_CP_CODE  = DSR_CP_CODE
         AND    DSC_DOC_NUM  = DSR_MSR_NUM
         AND    DSC_DSC_CODE = DSR_DSC_CODE
         AND    DSC_CP_CODE  = ARG_CP_CODE
         AND    DSC_DOC_NUM  = ARG_RCT_NUM
         AND    NOT EXISTS (SELECT 1
                            FROM   LAB_TO_SPC_BTR
                            WHERE  TSB_CP_CODE = DSC_CP_CODE
                            AND    TSB_DOC_NUM = DSC_DOC_NUM
                            AND    TSB_SPC_NUM = DSC_SPC_NUM)
         AND    NOT EXISTS (SELECT 1
                            FROM LAB_TD_SPC_BTR
                            WHERE  DSB_CP_CODE = DSC_CP_CODE
                            AND    DSB_DOC_NUM = DSC_DOC_NUM
                            AND    DSB_SPC_NUM = DSC_SPC_NUM)
         GROUP BY MSR_CP_CODE,MSR_BR_CODE,DSC_DOC_NUM,DSC_SPC_NUM;
BEGIN
  DELETE FROM LAB_TO_SPC_BTR
  WHERE  TSB_CP_CODE = ARG_CP_CODE
  AND    TSB_DOC_NUM  = ARG_RCT_NUM
  AND    NOT EXISTS(SELECT 1
                    FROM   LAB_TD_SMN_COLL
                    WHERE  DSC_CP_CODE = TSB_CP_CODE 
                    AND    DSC_DOC_NUM = TSB_DOC_NUM 
                    AND    DSC_SPC_NUM = TSB_SPC_NUM 
                    AND    NVL(DSC_COLL_FLAG,'N') = 'Y');
  DELETE FROM LAB_TD_SMN_COLL
  WHERE  DSC_CP_CODE = ARG_CP_CODE
  AND    DSC_DOC_NUM = ARG_RCT_NUM
  AND    NVL(DSC_COLL_FLAG,'N') = 'N';
  DELETE FROM LAB_TM_SMN_COLL
  WHERE  MSC_CP_CODE = ARG_CP_CODE
  AND    MSC_DOC_NUM = ARG_RCT_NUM
  AND    NOT EXISTS(SELECT 1
                    FROM   LAB_TD_SMN_COLL
                    WHERE  DSC_CP_CODE = MSC_CP_CODE
                    AND    DSC_DOC_NUM = MSC_DOC_NUM
                    AND    DSC_SPC_NUM = MSC_SPC_NUM);
  UPDATE HOS_TD_OPD_SRV_RCPT
  SET    DSR_SMN_FLAG = 'Y'
  WHERE  DSR_CP_CODE  = ARG_CP_CODE
  AND    DSR_MSR_NUM  = ARG_RCT_NUM
  AND    DSR_SMN_FLAG = 'N'
  AND    DSR_DSC_CODE IN (SELECT DSC_DSC_CODE
                          FROM   LAB_TD_SMN_COLL
                          WHERE  DSC_CP_CODE = DSR_CP_CODE
                          AND    DSC_DOC_NUM = DSR_MSR_NUM);
  COMMIT;
  FOR A IN C1 LOOP
      LAB_PKG.GEN_TRAN_FROM_COLL(A.MSR_CP_CODE,A.MSR_BR_CODE,A.DSC_DOC_NUM,A.DSC_SPC_NUM);
  END LOOP;
END;
END LAB_PKG;
/

prompt
prompt Creating package body OLR_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.OLR_PKG AS
-----------------------------------------------------------------
--Error Log
-----------------------------------------------------------------
PROCEDURE ERROR_LOG(ARG_DIRECTORY VARCHAR2,ARG_ERROR VARCHAR2) AS
  LC_FILE   UTL_FILE.FILE_TYPE;
  FILE_NAME VARCHAR2(30);
BEGIN
  FILE_NAME := 'Errorlog_'||TO_CHAR(SYSDATE,'MMRRRR')||'.log';
  IF DBMS_LOB.FILEEXISTS(BFILENAME(ARG_DIRECTORY,FILE_NAME)) = 0 THEN
     LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
     UTL_FILE.FCLOSE(LC_FILE);
  END IF;
  LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
  UTL_FILE.PUT_LINE (LC_FILE,ARG_ERROR);
  UTL_FILE.FCLOSE(LC_FILE);
END;

-----------------------------------------------------------------
--Pad String /*Encrypt and Decrypt dep on pad string*/
-----------------------------------------------------------------
PROCEDURE PADSTRING(ARG_VALUE IN OUT VARCHAR2) IS
  LC_UNIT NUMBER;
BEGIN
  IF LENGTH(ARG_VALUE) MOD 8 > 0 THEN
      LC_UNIT := TRUNC(LENGTH(ARG_VALUE)/8) + 1;
      ARG_VALUE  := RPAD(ARG_VALUE, LC_UNIT * 8, G_PAD_CHR);
  END IF;
END;

-----------------------------------------------------------------
--Encrypt
-----------------------------------------------------------------
FUNCTION ENCRYPT(ARG_VALUE IN VARCHAR2)RETURN RAW IS
  LC_VALUE     VARCHAR2(32767) := ARG_VALUE;
  LC_ENCRYPTED RAW(32767);
BEGIN
  PADSTRING(LC_VALUE);
  DBMS_OBFUSCATION_TOOLKIT.DESENCRYPT(INPUT          => UTL_RAW.CAST_TO_RAW(LC_VALUE),
                                      KEY            => G_KEY,
                                      ENCRYPTED_DATA => LC_ENCRYPTED);
  RETURN LC_ENCRYPTED;
END;

-----------------------------------------------------------------
--Decrypt
-----------------------------------------------------------------
FUNCTION DECRYPT(ARG_VALUE IN RAW)RETURN VARCHAR2 IS
  LC_DECRYPTED VARCHAR2(32767);
BEGIN
  DBMS_OBFUSCATION_TOOLKIT.DESDECRYPT(INPUT          => ARG_VALUE,
                                      KEY            => G_KEY,
                                      DECRYPTED_DATA => LC_DECRYPTED);
  RETURN RTRIM(UTL_RAW.CAST_TO_VARCHAR2(LC_DECRYPTED),G_PAD_CHR);
END;
-----------------------------------------------------------------
--UPDATE PASSWORD
-----------------------------------------------------------------
PROCEDURE UPDATE_PASSWORD AS
  CURSOR C1 IS
        SELECT DISTINCT TOR_CP_CODE,TOR_RCT_NUM,TOR_PAT_ID
        FROM   LAB_TO_OL_REPORTING_PQ
        WHERE  TOR_CP_CODE = '01'
        AND    TOR_PASS IS NULL;
  LC_PASS VARCHAR2(100);
BEGIN
  FOR A IN C1 LOOP
      LC_PASS := DBMS_RANDOM.STRING('U',5);
      UPDATE HOS_TM_OPD_SRV_RCPT
      SET    MSR_PASS    = LC_PASS
      WHERE  MSR_CP_CODE = A.TOR_CP_CODE
      AND    MSR_NUM     = A.TOR_RCT_NUM;
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_PASS    = LC_PASS
      WHERE  TOR_CP_CODE = A.TOR_CP_CODE
      AND    TOR_RCT_NUM = A.TOR_RCT_NUM;
      IF A.TOR_PAT_ID IS NOT NULL THEN
         UPDATE HOS_SM_PATIENT
         SET    MPT_PASS    = LC_PASS
         WHERE  MPT_CP_CODE = A.TOR_CP_CODE
         AND    MPT_ID      = A.TOR_PAT_ID;
      END IF;
      COMMIT;
  END LOOP;
END;
-----------------------------------------------------------------
--Pending Queue
-----------------------------------------------------------------
PROCEDURE PENDING_QUEUE(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL)AS
  LC_CNT       NUMBER;
  LC_DIRECTORY VARCHAR2(100);
  LC_FLAG      VARCHAR2(1) := 'T';
  LC_ERROR VARCHAR2(500);
  CURSOR PAT_CUR IS
         SELECT A.*,A.ROWID
         FROM   HOS_SM_PATIENT_PQ A
         WHERE  MPT_CP_CODE = ARG_CP_CODE
         AND 1 =2 
         ORDER BY MPT_INS_DATE,MPT_INS_TIME;

  CURSOR CON_CUR IS
         SELECT A.*,A.ROWID
         FROM   HOS_SM_CONSULTANT_PQ A
         WHERE  MCT_CP_CODE = ARG_CP_CODE;

  CURSOR RPQ_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_OL_REPORTING_PQ A
         WHERE  TOR_CP_CODE  = NVL(ARG_CP_CODE,TOR_CP_CODE)
         AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)
         AND    NVL(TOR_FLAG,'Y') = 'Y';
       /*  AND    NOT EXISTS(SELECT 1
                           FROM   LAB_TO_OL_REPORTING_OLVW B
                           WHERE  B.TOR_CP_CODE  = A.TOR_CP_CODE
                           AND    B.TOR_RPT_ID   = A.TOR_RPT_ID
                           AND    B.TOR_DSC_CODE = A.TOR_DSC_CODE
                           AND    B.TOR_FILE_NAME = A.TOR_FILE_NAME);*/

  CURSOR LDF_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_DOWNLOAD_FILE_PQ A
         WHERE  LDF_CP_CODE  = NVL(ARG_CP_CODE,LDF_CP_CODE)
         AND    LDF_RPT_ID   = NVL(ARG_RPT_ID,LDF_RPT_ID)
         AND    LDF_DSC_CODE = NVL(ARG_DSC_CODE,LDF_DSC_CODE)
         AND    LDF_FILE_NAME =  NVL(ARG_FILE_NAME,LDF_FILE_NAME);
BEGIN

--insert into t25012021 values('1');
  BEGIN
    SELECT ISR_LAB_RPT_DIR
    INTO   LC_DIRECTORY
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = NVL(ARG_CP_CODE,ISR_CP_CODE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;

--insert into t25012021 values('2');
  ------------------------------------------------------
  --Patient Info
  ------------------------------------------------------
  FOR PAT_REC IN PAT_CUR LOOP
      BEGIN
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   HOS_SM_PATIENT_OLVW--HOS_SM_PATIENT@ISROLAKH
        WHERE  MPT_ID      = PAT_REC.MPT_ID
        AND    MPT_CP_CODE = PAT_REC.MPT_CP_CODE;
        IF LC_CNT = 0 THEN
           INSERT INTO HOS_SM_PATIENT_OLVW
                 (MPT_CP_CODE,                  MPT_REG_DATE,                  MPT_ID,                  MPT_NAME,
                  MPT_RELT_FLAG,                MPT_FATHER_NAME,               MPT_SEX,                 MPT_DOB,
                  MPT_AGE,                      MPT_AGE_TYPE,                  MPT_STATUS,              MPT_ACTIVE,
                  MPT_PASS,                     MPT_MOBILE)
           VALUES(PAT_REC.MPT_CP_CODE,          PAT_REC.MPT_REG_DATE,          PAT_REC.MPT_ID,          PAT_REC.MPT_NAME,
                  PAT_REC.MPT_RELT_FLAG,        PAT_REC.MPT_FATHER_NAME,       PAT_REC.MPT_SEX,         PAT_REC.MPT_DOB,
                  PAT_REC.MPT_AGE,              PAT_REC.MPT_AGE_TYPE,          PAT_REC.MPT_STATUS,      PAT_REC.MPT_ACTIVE,
                  PAT_REC.MPT_PASS,             PAT_REC.MPT_MOBILE);
        ELSE
           UPDATE HOS_SM_PATIENT_OLVW--HOS_SM_PATIENT@ISROLAKH
           SET    MPT_NAME      = PAT_REC.MPT_NAME,
                  MPT_STATUS    = PAT_REC.MPT_STATUS,
                  MPT_ACTIVE    = PAT_REC.MPT_ACTIVE,
                  MPT_AGE_TYPE  = PAT_REC.MPT_AGE_TYPE,
                  MPT_AGE       = PAT_REC.MPT_AGE,
                  MPT_PASS      = PAT_REC.MPT_PASS,
                  MPT_MOBILE    = PAT_REC.MPT_MOBILE
           WHERE  MPT_CP_CODE   = PAT_REC.MPT_CP_CODE
           AND    MPT_ID        = PAT_REC.MPT_ID;
        END IF;
        DELETE FROM HOS_SM_PATIENT_PQ
        WHERE  MPT_CP_CODE = PAT_REC.MPT_CP_CODE
        AND    MPT_ID      = PAT_REC.MPT_ID;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Patient info inserting. '||SQLERRM);
      END;
  END LOOP;

--insert into t25012021 values('3');
  ------------------------------------------------------
  --Consultant Info
  ------------------------------------------------------
  FOR CON_REC IN CON_CUR LOOP
      BEGIN
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   HOS_SM_CONSULTANT_OLVW--HOS_SM_CONSULTANT@ISROLAKH
        WHERE  MCT_CP_CODE = CON_REC.MCT_CP_CODE
        AND    MCT_CODE    = CON_REC.MCT_CODE;
        IF LC_CNT = 0 THEN
           INSERT INTO HOS_SM_CONSULTANT_OLVW
                 (MCT_CP_CODE,                MCT_DEP_CODE,                MCT_CODE,                MCT_NAME,
                  MCT_ID_CARD,                MCT_DAYS_TIMINGS,            MCT_TYPE,                MCT_SEX,
                  MCT_DOJ,                    MCT_ACTIVE,                  MCT_BR_CODE,             MCT_PASS)
           VALUES(CON_REC.MCT_CP_CODE,        CON_REC.MCT_DEP_CODE,        CON_REC.MCT_CODE,        CON_REC.MCT_NAME,
                  CON_REC.MCT_ID_CARD,        CON_REC.MCT_DAYS_TIMINGS,    CON_REC.MCT_TYPE,        CON_REC.MCT_SEX,
                  CON_REC.MCT_DOJ,            CON_REC.MCT_ACTIVE,          CON_REC.MCT_BR_CODE,     CON_REC.MCT_PASS);
        ELSE
           UPDATE HOS_SM_CONSULTANT_OLVW--HOS_SM_CONSULTANT@ISROLAKH
           SET    MCT_NAME         = CON_REC.MCT_NAME,
                  MCT_DAYS_TIMINGS = CON_REC.MCT_DAYS_TIMINGS,
                  MCT_ACTIVE       = CON_REC.MCT_ACTIVE,
                  MCT_PASS         = CON_REC.MCT_PASS
           WHERE  MCT_CP_CODE      = CON_REC.MCT_CP_CODE
           AND    MCT_CODE         = CON_REC.MCT_CODE;
        END IF;
        DELETE FROM HOS_SM_CONSULTANT_PQ
        WHERE  MCT_CP_CODE = CON_REC.MCT_CP_CODE
        AND    MCT_CODE    = CON_REC.MCT_CODE;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Consultant info inserting. '||SQLERRM);
      END;
  END LOOP;

--insert into t25012021 values('4');
  ------------------------------------------------------
  --Lab Info
  ------------------------------------------------------
   UPDATE LAB_TO_OL_REPORTING_PQ A
   SET    TOR_FLAG     = 'N'
   WHERE  TOR_CP_CODE  = NVL(ARG_CP_CODE,TOR_CP_CODE)
   AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
   AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
   AND    NVL(TOR_FLAG,'Y') = 'Y'
   AND DBMS_LOB.FILEEXISTS(BFILENAME('MDH_LAB_REPORT',OLR_PKG.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 0;

--insert into t25012021 values('5');
  FOR RPQ_REC IN RPQ_CUR LOOP
      BEGIN
        INSERT INTO LAB_TO_OL_REPORTING_OLVW
              (TOR_CP_CODE,                TOR_RPT_ID,                  TOR_RPT_DATE,            TOR_RCT_NUM,
               TOR_PAT_ID,                 TOR_PAT_NAME,                TOR_PAT_AGE,             TOR_AGE_TYPE,
               TOR_PAT_GND,                TOR_MCT_CODE,                TOR_MCT_NAME,            TOR_TYPE,
               TOR_COL_NUM,                TOR_SPC_NUM,                 TOR_DSC_CODE,            TOR_DSC_DESC,
               TOR_DLV_DATE,               TOR_DLV_TIME,                TOR_FNL_USER,            TOR_FNL_DATE,
               TOR_FNL_TIME,               TOR_FILE_NAME,               TOR_MIME_TYPE,           TOR_DATE,
               TOR_TIME,                   TOR_PRG_CODE,                TOR_PRG_DESC,
               TOR_MSC_TYPE,               TOR_RESULT,                  TOR_BR_CODE,             TOR_PASS,
               TOR_ID)
        VALUES(RPQ_REC.TOR_CP_CODE,        RPQ_REC.TOR_RPT_ID,          RPQ_REC.TOR_RPT_DATE,    RPQ_REC.TOR_RCT_NUM,
               RPQ_REC.TOR_PAT_ID,         RPQ_REC.TOR_PAT_NAME,        RPQ_REC.TOR_PAT_AGE,     RPQ_REC.TOR_AGE_TYPE,
               RPQ_REC.TOR_PAT_GND,        RPQ_REC.TOR_MCT_CODE,        RPQ_REC.TOR_MCT_NAME,    RPQ_REC.TOR_TYPE,
               RPQ_REC.TOR_COL_NUM,        RPQ_REC.TOR_SPC_NUM,         RPQ_REC.TOR_DSC_CODE,    REPLACE(RPQ_REC.TOR_DSC_DESC,','),
               RPQ_REC.TOR_DLV_DATE,       RPQ_REC.TOR_DLV_TIME,        RPQ_REC.TOR_FNL_USER,    RPQ_REC.TOR_FNL_DATE,
               RPQ_REC.TOR_FNL_TIME,       RPQ_REC.TOR_FILE_NAME,       RPQ_REC.TOR_MIME_TYPE,   TO_DATE(SYSDATE),
               TO_CHAR(SYSDATE,'HH24:MI:SS'), RPQ_REC.TOR_PRG_CODE,     RPQ_REC.TOR_PRG_DESC,
               RPQ_REC.TOR_MSC_TYPE,       RPQ_REC.TOR_RESULT,          RPQ_REC.TOR_BR_CODE,     RPQ_REC.TOR_PASS,
               RPQ_REC.TOR_ID);
               --insert into t25012021 values('5.1');commit;
         OLR_PKG.UPLOAD_OL_LAB_REPORTS(RPQ_REC.TOR_CP_CODE,RPQ_REC.TOR_RPT_ID,RPQ_REC.TOR_DSC_CODE,RPQ_REC.TOR_FILE_NAME);
         --insert into t25012021 values('5.2');commit;
         SMS_PKG.SENT_SMS_LAB_REPORT(RPQ_REC.TOR_CP_CODE,RPQ_REC.TOR_FILE_NAME);
         --insert into t25012021 values('5.3');commit;
         DELETE FROM LAB_TO_OL_REPORTING_PQ
         WHERE  ROWID = RPQ_REC.ROWID;
         --insert into t25012021 values('5.4');commit;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             LC_ERROR := SQLERRM;
             --insert into t25012021 values(LC_ERROR);commit;
             OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue lab reporting inserting. ('||REPLACE(REPLACE(RPQ_REC.TOR_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
      END;
  END LOOP;

--insert into t25012021 values('6');
  ------------------------------------------------------
  --Download File
  ------------------------------------------------------
  FOR LDF_REC IN LDF_CUR LOOP
      BEGIN
        INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLMDH
              (LDF_CP_CODE,                LDF_RPT_ID,                  LDF_DSC_CODE,            LDF_FILE,
               LDF_MIME_TYPE,              LDF_FILE_NAME)
        SELECT LDF_CP_CODE,                LDF_RPT_ID,                  LDF_DSC_CODE,            LDF_FILE,
               LDF_MIME_TYPE,              LDF_FILE_NAME
        FROM   LAB_TO_DOWNLOAD_FILE_PQ
        WHERE  LDF_CP_CODE   = LDF_REC.LDF_CP_CODE
        AND    LDF_RPT_ID    = LDF_REC.LDF_RPT_ID
        AND    LDF_DSC_CODE  = LDF_REC.LDF_DSC_CODE
        AND    LDF_FILE_NAME = LDF_REC.LDF_FILE_NAME;

        DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
        WHERE  LDF_CP_CODE   = LDF_REC.LDF_CP_CODE
        AND    LDF_RPT_ID    = LDF_REC.LDF_RPT_ID
        AND    LDF_DSC_CODE  = LDF_REC.LDF_DSC_CODE
        AND    LDF_FILE_NAME = LDF_REC.LDF_FILE_NAME;
      EXCEPTION
         WHEN OTHERS THEN
              LC_FLAG := 'F';
              OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Downloading file inserting. ('||REPLACE(REPLACE(LDF_REC.LDF_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
      END;
  END LOOP;

--insert into t25012021 values('7');
  COMMIT;
END;

-----------------------------------------------------------------
--Upload Online Lab Report
-----------------------------------------------------------------
PROCEDURE UPLOAD_OL_LAB_REPORTS(ARG_CP_CODE VARCHAR2,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL) AS
  LC_BLOB       BLOB;
  LC_SRC_LOC    BFILE;
  LC_AMOUNT     INTEGER;
  LC_TIME       VARCHAR2(100);
  LC_DIRECTORY  VARCHAR2(30);
  LC_ERROR      VARCHAR2(1000);
  LC_DELAY_TIME NUMBER;
  LC_RPT_PQ_FLAG VARCHAR2(1);
BEGIN
  BEGIN
    SELECT ISR_LAB_RPT_DIR,ISR_LAB_DELAY_SEC
    INTO   LC_DIRECTORY,LC_DELAY_TIME
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = ARG_CP_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;
  BEGIN
    SELECT NVL(ISR_LAB_RPT_PQ_FLAG,'Y')
    INTO   LC_RPT_PQ_FLAG
    FROM   ISR_XO_CONTROL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_RPT_PQ_FLAG := 'Y';
  END;
  IF LC_DIRECTORY IS NULL THEN
     ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' 1Directory not define. '||SQLERRM);
     RAISE_APPLICATION_ERROR(-20001,'Directory must be define');
  END IF;
  IF LC_RPT_PQ_FLAG = 'N' THEN
  BEGIN
    FOR OLR_REC IN (SELECT *
                    FROM   LAB_TO_OL_REPORTING_OLVW
                    WHERE  TOR_CP_CODE   = ARG_CP_CODE
                    AND    TOR_RPT_ID    = NVL(ARG_RPT_ID,TOR_RPT_ID)
                    AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                    AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP

        LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
        LOOP--Timer
           EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
        END LOOP;

        INSERT INTO LAB_TO_UPLOAD_FILE
              (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
               LUF_MIME_TYPE,                 LUF_FILE_NAME)
        VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
               OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
        RETURN LUF_FILE INTO LC_BLOB;
        LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
        DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
        LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
        DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
        DBMS_LOB.CLOSE(LC_SRC_LOC);
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
         OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Upload File inserting. ('||REPLACE(REPLACE(ARG_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
         FOR OLR_REC IN (SELECT *
                         FROM   LAB_TO_OL_REPORTING_PQ
                         WHERE  TOR_CP_CODE  = ARG_CP_CODE
                         AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
                         AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP
             LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
             LOOP--Timer
                EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
             END LOOP;
             INSERT INTO LAB_TO_UPLOAD_FILE
                   (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
                    LUF_MIME_TYPE,                 LUF_FILE_NAME)
             VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
                    OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
             RETURN LUF_FILE INTO LC_BLOB;
             LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
             DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
             LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
             DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
             DBMS_LOB.CLOSE(LC_SRC_LOC);
         END LOOP;
  END;
  ELSE
     FOR OLR_REC IN (SELECT *
                     FROM   LAB_TO_OL_REPORTING_PQ
                     WHERE  TOR_CP_CODE  = ARG_CP_CODE
                     AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
                     AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                     AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP
         /*
         LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
         LOOP--Timer
            EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
         END LOOP;
         */
         INSERT INTO LAB_TO_UPLOAD_FILE
               (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
                LUF_MIME_TYPE,                 LUF_FILE_NAME)
         VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
                OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
         RETURN LUF_FILE INTO LC_BLOB;
         LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
         DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
         LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
         DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
         DBMS_LOB.CLOSE(LC_SRC_LOC);
     END LOOP;
  END IF;
  IF LC_RPT_PQ_FLAG = 'N' THEN
  BEGIN
    INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLMDH
    SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,'N'
    FROM   LAB_TO_UPLOAD_FILE
    WHERE  LUF_CP_CODE  = ARG_CP_CODE
    AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
    AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
    AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
    /*
    DELETE FROM LAB_TO_UPLOAD_FILE PURGE
    WHERE  LUF_CP_CODE  = ARG_CP_CODE
    AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
    AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
    AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
    */
  EXCEPTION
    WHEN OTHERS THEN
         LC_ERROR := SQLERRM;
         OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Downloading file inserting. ('||REPLACE(REPLACE(ARG_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
         INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
         SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
         FROM   LAB_TO_UPLOAD_FILE
         WHERE  LUF_CP_CODE   = ARG_CP_CODE
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
         AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
         /*
         DELETE FROM LAB_TO_UPLOAD_FILE PURGE
         WHERE  LUF_CP_CODE  = ARG_CP_CODE
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
         AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
         */
  END;
  ELSE
     INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
     SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
     FROM   LAB_TO_UPLOAD_FILE
     WHERE  LUF_CP_CODE   = ARG_CP_CODE
     AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
     AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
     AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
  END IF;
END;
-----------------------------------------------------------------
--Delete Lab Reports
-----------------------------------------------------------------
PROCEDURE DELETE_LAB_REPORTS(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL) AS
  LC_CNT        NUMBER;
  LC_DIRECTORY  VARCHAR2(30);
  LC_BLOB       BLOB;
  LC_SRC_LOC    BFILE;
  LC_AMOUNT     INTEGER;
  LC_ERROR      VARCHAR2(1000);
  CURSOR LUF_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_UPLOAD_FILE A
         WHERE  LUF_CP_CODE   = NVL(ARG_CP_CODE,LUF_CP_CODE)
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE);

BEGIN
  BEGIN
    SELECT ISR_LAB_RPT_DIR
    INTO   LC_DIRECTORY
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = NVL(ARG_CP_CODE,ISR_CP_CODE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;
  IF LC_DIRECTORY IS NULL THEN
     ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Directory not define. '||SQLERRM);
     RAISE_APPLICATION_ERROR(-20001,'Directory must be define');
  END IF;
  FOR LUF_REC IN LUF_CUR LOOP
      BEGIN
      SELECT COUNT(*)
      INTO   LC_CNT
      FROM   LAB_TO_UPLOAD_FILE
      WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
      AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
      AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
      AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME
      AND    DBMS_LOB.GETLENGTH(LUF_FILE) = DBMS_LOB.GETLENGTH(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(LUF_REC.LUF_FILE_NAME,'.pdf'))||'.tmp'));

      IF LC_CNT > 0 THEN
         DELETE FROM LAB_TO_UPLOAD_FILE PURGE
         WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
         AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
         AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
         AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;
      ELSE
         UPDATE LAB_TO_UPLOAD_FILE
         SET    LUF_FILE = EMPTY_BLOB()
         WHERE  ROWID = LUF_REC.ROWID
         RETURN LUF_FILE INTO LC_BLOB;
         LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(LUF_REC.LUF_FILE_NAME,'.pdf'))||'.tmp');
         DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
         LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
         DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
         DBMS_LOB.CLOSE(LC_SRC_LOC);
         BEGIN
           DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
           WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

           DELETE FROM LAB_TO_DOWNLOAD_FILE@ISROLMDH
           WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

           INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLMDH
           SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,'N'
           FROM   LAB_TO_UPLOAD_FILE
           WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

          DELETE FROM LAB_TO_UPLOAD_FILE PURGE
          WHERE  LUF_CP_CODE  = ARG_CP_CODE
          AND    LUF_RPT_ID    = NVL(LUF_REC.LUF_RPT_ID,LUF_RPT_ID)
          AND    LUF_DSC_CODE  = NVL(LUF_REC.LUF_DSC_CODE,LUF_DSC_CODE)
          AND    LUF_FILE_NAME = NVL(LUF_REC.LUF_FILE_NAME,LUF_FILE_NAME);
        EXCEPTION
          WHEN OTHERS THEN
               LC_ERROR := SQLERRM;
               OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Downloading file inserting. ('||REPLACE(REPLACE(LUF_REC.LUF_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
               DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
               WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
               AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
               AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
               AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;
               INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
               SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
               FROM   LAB_TO_UPLOAD_FILE
               WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
               AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
               AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
               AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

               DELETE FROM LAB_TO_UPLOAD_FILE PURGE
               WHERE  LUF_CP_CODE  = ARG_CP_CODE
               AND    LUF_RPT_ID    = NVL(LUF_REC.LUF_RPT_ID,LUF_RPT_ID)
               AND    LUF_DSC_CODE  = NVL(LUF_REC.LUF_DSC_CODE,LUF_DSC_CODE)
               AND    LUF_FILE_NAME = NVL(LUF_REC.LUF_FILE_NAME,LUF_FILE_NAME);
        END;
      END IF;
      EXCEPTION
        WHEN OTHERS THEN
             ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' File not exists. '||LUF_REC.LUF_FILE_NAME||SQLERRM);
      END;
      COMMIT;
  END LOOP;
END;
-----------------------------------------------------------------
--No Of Record Transfered from Pending Queue
-----------------------------------------------------------------
PROCEDURE UPLOAD_PENDING_QUEUE(ARG_NO_ROWS NUMBER) AS
  CURSOR RPT_CUR IS
         SELECT *
         FROM  (SELECT *
                FROM   LAB_TO_OL_REPORTING_PQ a
                WHERE  TO_DATE(TOR_DATE||' '||TOR_TIME,'DD/MM/RRRR HH24:MI:SS') < SYSDATE
                AND    NVL(TOR_FLAG,'Y') = 'Y'
                AND    TOR_GEN_RPT   = 'Y'
                AND    TOR_PASS IS NOT NULL
                --AND    TOR_DATE = TO_DATE(SYSDATE)
                --AND    TOR_DSC_CODE NOT IN('PYCT0004','CHPA0021')
               -- AND    TOR_DSC_CODE NOT IN('PYCT0004')
                ORDER BY TO_DATE(TOR_DATE||' '||TOR_TIME,'DD/MM/RRRR HH24:MI:SS')) A
         WHERE  ROWNUM <= NVL(ARG_NO_ROWS,10)
         AND   (SELECT COUNT(*)
                FROM   LAB_TO_OL_REPORTING_PQ
                WHERE  NVL(TOR_FLAG,'Y') = 'Y'
                AND    TOR_GEN_RPT   = 'Y') > 0;
/*
         AND    NOT EXISTS(SELECT 1
                           FROM   LAB_TO_OL_REPORTING_OLVW B
                           WHERE  B.TOR_CP_CODE  = A.TOR_CP_CODE
                           AND    B.TOR_RPT_ID   = A.TOR_RPT_ID
                           AND    B.TOR_DSC_CODE = A.TOR_DSC_CODE
                           AND    B.TOR_FILE_NAME = A.TOR_FILE_NAME);*/
BEGIN
--  STOP_PQ_JOB;
  --STOP_PQ_JOB;
  FOR RPT_REC IN RPT_CUR LOOP
 --   DBMS_OUTPUT.PUT_LINE(RPT_REC.TOR_FILE_NAME);
      OLR_PKG.PENDING_QUEUE(RPT_REC.TOR_CP_CODE,RPT_REC.TOR_RPT_ID,RPT_REC.TOR_DSC_CODE,RPT_REC.TOR_FILE_NAME);
  END LOOP;
END;

-----------------------------------------------------------------
--No Of Record Transfered from Pending Queue
-----------------------------------------------------------------
PROCEDURE GENERATE_REPORT(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL,ARG_DEV VARCHAR2 DEFAULT '10g') AS
  LC_RPT_NAME    VARCHAR2(30);
  LC_DES_NAME    VARCHAR2(4000);
  LC_DEV_DIR     VARCHAR2(4000);
  LC_APP_DIR     VARCHAR2(4000);
  LC_PARAMETER   VARCHAR2(4000);
  LC_CONNECTION  VARCHAR2(1000);
  CURSOR C1 IS
         SELECT *
         FROM   LAB_TD_SRV_DIAG,LAB_TO_OL_REPORTING_PQ
         WHERE  TOR_CP_CODE   = DSD_CP_CODE
         AND    TOR_RPT_ID    = DSD_RPT_ID
         AND    TOR_DSC_CODE  = DSD_DSC_CODE
         AND    TOR_RCT_NUM   = DSD_RCT_NUM
         --AND    TOR_SPC_NUM   = DSD_SPC_NUM
         --AND    TOR_FLAG      = 'N'
         AND    TOR_CP_CODE   = ARG_CP_CODE
         AND    TOR_RPT_ID    = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME);
BEGIN
  FOR A IN C1 LOOP
      begin
      LC_RPT_NAME := 'LABAR01'||A.DSD_REP_TYPE||'LP';
      BEGIN
        SELECT DECRYPT(usr_auth),'"'||REPLACE(LAB_RPT_DIR,'\\192.168.0.108\','D:\')||'"',REPLACE(APP_DIR||'\Reports\','\\')||LC_RPT_NAME||'.rep',DEV_DIR||DECODE(ARG_DEV,'10g','\RWRUN.EXE','\RWRUN60.EXE')
        INTO   LC_CONNECTION,LC_DES_NAME,LC_APP_DIR,LC_DEV_DIR
        FROM   SYSTEM.V$HW_SPEC;
      EXCEPTION
        WHEN OTHERS THEN
             LC_DES_NAME := NULL;
      END;
      LC_DES_NAME := LC_DES_NAME||OLR_PKG.ENCRYPT(A.TOR_PAT_ID||'_'||A.TOR_RPT_ID||'_'||A.TOR_DSC_CODE||'_'||TO_CHAR(A.TOR_FNL_DATE,'DDMMRRRR')||'_'||REPLACE(A.TOR_FNL_TIME,':'))||'.tmp';

      LC_PARAMETER := ' LC_CP_CODE="'||A.TOR_CP_CODE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_USR_NAME="'||A.TOR_FNL_USER||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DSC_CODE="'||A.TOR_DSC_CODE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_REP_TYPE="'||A.DSD_REP_TYPE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_LTI_REP_TYPE="'||A.DSD_LTI_REP_TYPE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DATE_FM="'||A.TOR_RPT_DATE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DATE_TO="'||A.TOR_RPT_DATE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_RCT_ID="'||A.TOR_RCT_NUM||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_CODE_FM="'||A.TOR_RPT_ID||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_CODE_TO="'||A.TOR_RPT_ID||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_COL_FM="'||NVL(A.TOR_COL_NUM, '-')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_COL_TO="'||NVL(A.TOR_COL_NUM, '-')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_TYPE="'||NVL(A.TOR_TYPE, 'OPD')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_PRINT_HF="'||'Y'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_GEN_MODE="'||'S'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_SIGN="'||'N'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_FNL_DATE_TIME="'||TO_CHAR(TO_DATE(A.TOR_FNL_DATE||'  '||A.TOR_FNL_TIME,'DD/MM/RRRR HH24:MI:SS'),'DD/MM/RRRR - HH:MI AM')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_FNL_USER="Reported by : '||A.TOR_FNL_USER||'"';
      LC_PARAMETER := LC_DEV_DIR||' REPORT='||LC_APP_DIR||' USERID='||LC_CONNECTION||' '||LC_PARAMETER||' BATCH=YES DESFORMAT=PDF DESTYPE=FILE DESNAME="'||REPLACE(LC_DES_NAME,'"')||'"';
      HOST_COMMAND(LC_PARAMETER);
      DBMS_OUTPUT.PUT_LINE(LC_PARAMETER);
      --UPLOAD_OL_LAB_REPORTS('01',NULL,NULL,A.TOR_FILE_NAME);
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_FLAG     = 'Y'
      WHERE  TOR_CP_CODE  = A.TOR_CP_CODE
      AND    TOR_RPT_ID   = A.TOR_RPT_ID
      AND    TOR_DSC_CODE = A.TOR_DSC_CODE
      AND    NVL(TOR_FLAG,'Y') = 'N'
      AND    DBMS_LOB.FILEEXISTS(BFILENAME('MDH_LAB_REPORT',OLR_PKG.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1;
      COMMIT;
    exception
      when others then
           NULL;
    end;
  END LOOP;
END;
---------------------------------------------------------------------------------------------
PROCEDURE GENERATE_REPORT_JOB(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL) AS
  CURSOR C1 IS
         SELECT *
         FROM   LAB_TO_OL_REPORTING_PQ M
         WHERE  TOR_CP_CODE = ARG_CP_CODE
         AND    TOR_RPT_ID  = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME  = NVL(ARG_FILE_NAME,TOR_FILE_NAME)
         AND    TOR_GEN_RPT = 'N'
         AND    TOR_FNL_DATE is not null
         and    tor_fnl_time is not null
         AND    TO_DATE(TOR_FNL_DATE||' '||TOR_FNL_TIME,'DD/MM/RRRR HH24:MI:SS') <= SYSDATE - INTERVAL '3' MINUTE
         AND    TO_CHAR(TOR_FNL_DATE,'RRRRMMDD')||REPLACE(TOR_FNL_TIME,':') IN
               (SELECT MAX(TO_CHAR(D.TOR_FNL_DATE,'RRRRMMDD')||REPLACE(D.TOR_FNL_TIME,':'))
                FROM   LAB_TO_OL_REPORTING_PQ D
                WHERE  D.TOR_CP_CODE = M.TOR_CP_CODE
                AND    D.TOR_RPT_ID  = M.TOR_RPT_ID
                AND    D.TOR_DSC_CODE = M.TOR_DSC_CODE
                AND    D.TOR_GEN_RPT = 'N');
BEGIN
  OLR_PKG.UPDATE_PASSWORD;
  FOR A IN C1 LOOP
      BEGIN
        OLR_PKG.GENERATE_REPORT(A.TOR_CP_CODE,A.TOR_RPT_ID,A.TOR_DSC_CODE,A.TOR_FILE_NAME,'10g');
        UPDATE LAB_TO_OL_REPORTING_PQ
        SET    TOR_GEN_RPT   = 'Y'
        WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
        AND    TOR_RPT_ID    = A.TOR_RPT_ID
        AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
        AND    TOR_GEN_RPT = 'N'
        AND    DBMS_LOB.FILEEXISTS(BFILENAME('MDH_LAB_REPORT',OLR_PKG.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1;
      EXCEPTION
        WHEN OTHERS THEN
             UPDATE LAB_TO_OL_REPORTING_PQ
             SET    TOR_GEN_RPT   = 'E'
             WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
             AND    TOR_RPT_ID    = A.TOR_RPT_ID
             AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
             AND    TOR_GEN_RPT = 'N'
             AND    DBMS_LOB.FILEEXISTS(BFILENAME('MDH_LAB_REPORT',OLR_PKG.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 0;
      END;
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_GEN_RPT   = 'C'
      WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
      AND    TOR_RPT_ID    = A.TOR_RPT_ID
      AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
      AND    TOR_GEN_RPT = 'N';
  END LOOP;
  COMMIT;
END;
-----------------------------------
PROCEDURE UPLOAD_SERVICES_PQ (ARG_CP_CODE VARCHAR2,ARG_RCT_NUM VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL) AS
BEGIN
  UPDATE HOS_TO_OPD_SRV_RCPT_PQ
  SET    TSR_UPL_FLAG = '-'
  WHERE  TSR_CP_CODE  = ARG_CP_CODE
  AND    TSR_MSR_NUM  = NVL(ARG_RCT_NUM,TSR_MSR_NUM)
  AND    NVL(TSR_DSC_CODE,'-') = NVL(ARG_DSC_CODE,NVL(TSR_DSC_CODE,'-'));

  DELETE FROM HOS_TO_OPD_SRV_RCPT_OLVW B
  WHERE  EXISTS(SELECT 1
                FROM   HOS_TO_OPD_SRV_RCPT_PQ A
                WHERE  A.TSR_CP_CODE  = ARG_CP_CODE
                AND    A.TSR_MSR_NUM  = NVL(ARG_RCT_NUM,A.TSR_MSR_NUM)
                AND    NVL(A.TSR_DSC_CODE,'-') = NVL(ARG_DSC_CODE,NVL(A.TSR_DSC_CODE,'-'))
                AND    A.TSR_CP_CODE  = B.TSR_CP_CODE
                AND    A.TSR_MSR_NUM  = B.TSR_MSR_NUM
                AND    A.TSR_DSC_CODE = B.TSR_DSC_CODE
                AND    TSR_ACTION     = 'D'
                AND    TSR_UPL_FLAG   = '-');

  INSERT INTO HOS_TO_OPD_SRV_RCPT_OLVW
        (TSR_CP_CODE,               TSR_MSR_DATE,               TSR_MSR_NUM,               TSR_BR_CODE,
         TSR_PAT_ID,                TSR_NAME,                   TSR_PRG_CODE,              TSR_PRG_DESC,
         TSR_DSC_CODE,              TSR_DSC_DESC,               TSR_DLV_DATE,              TSR_DLV_TIME,
         TSR_PASS,                  TSR_DOC_NUM,                TSR_PHONE)
  SELECT TSR_CP_CODE,               TSR_MSR_DATE,               TSR_MSR_NUM,               TSR_BR_CODE,
         TSR_PAT_ID,                TSR_NAME,                   TSR_PRG_CODE,              TSR_PRG_DESC,
         TSR_DSC_CODE,              TSR_DSC_DESC,               TSR_DLV_DATE,              TSR_DLV_TIME,
         TSR_PASS,                  TSR_DOC_NUM,                TSR_PHONE
  FROM   HOS_TO_OPD_SRV_RCPT_PQ
  WHERE  TSR_CP_CODE  = ARG_CP_CODE
  AND    TSR_MSR_NUM  = NVL(ARG_RCT_NUM,TSR_MSR_NUM)
  AND    NVL(TSR_DSC_CODE,'-') = NVL(ARG_DSC_CODE,NVL(TSR_DSC_CODE,'-'))
  AND    TSR_ACTION   = 'U'
  AND    TSR_UPL_FLAG = '-';

  DELETE FROM HOS_TO_OPD_SRV_RCPT_PQ
  WHERE  TSR_CP_CODE  = ARG_CP_CODE
  AND    TSR_MSR_NUM  = NVL(ARG_RCT_NUM,TSR_MSR_NUM)
  AND    NVL(TSR_DSC_CODE,'-') = NVL(ARG_DSC_CODE,NVL(TSR_DSC_CODE,'-'))
  AND    TSR_UPL_FLAG = '-';
END;/*
