CREATE OR REPLACE PACKAGE BODY MDHSYS.OLR_PKG_BKP AS
-----------------------------------------------------------------
--Error Log
-----------------------------------------------------------------
PROCEDURE ERROR_LOG(ARG_DIRECTORY VARCHAR2,ARG_ERROR VARCHAR2) AS
  LC_FILE   UTL_FILE.FILE_TYPE;
  FILE_NAME VARCHAR2(30);
BEGIN
  FILE_NAME := 'Errorlog_'||TO_CHAR(SYSDATE,'MMRRRR')||'.log';
  IF DBMS_LOB.FILEEXISTS(BFILENAME(ARG_DIRECTORY,FILE_NAME)) = 0 THEN
     LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
     UTL_FILE.FCLOSE(LC_FILE);
  END IF;
  LC_FILE := UTL_FILE.FOPEN(ARG_DIRECTORY,FILE_NAME,'A');
  UTL_FILE.PUT_LINE (LC_FILE,ARG_ERROR);
  UTL_FILE.FCLOSE(LC_FILE);
END;

-----------------------------------------------------------------
--Pad String /*Encrypt and Decrypt dep on pad string*/
-----------------------------------------------------------------
PROCEDURE PADSTRING(ARG_VALUE IN OUT VARCHAR2) IS
  LC_UNIT NUMBER;
BEGIN
  IF LENGTH(ARG_VALUE) MOD 8 > 0 THEN
      LC_UNIT := TRUNC(LENGTH(ARG_VALUE)/8) + 1;
      ARG_VALUE  := RPAD(ARG_VALUE, LC_UNIT * 8, G_PAD_CHR);
  END IF;
END;

-----------------------------------------------------------------
--Encrypt
-----------------------------------------------------------------
FUNCTION ENCRYPT(ARG_VALUE IN VARCHAR2)RETURN RAW IS
  LC_VALUE     VARCHAR2(32767) := ARG_VALUE;
  LC_ENCRYPTED RAW(32767);
BEGIN
  PADSTRING(LC_VALUE);
  DBMS_OBFUSCATION_TOOLKIT.DESENCRYPT(INPUT          => UTL_RAW.CAST_TO_RAW(LC_VALUE),
                                      KEY            => G_KEY,
                                      ENCRYPTED_DATA => LC_ENCRYPTED);
  RETURN LC_ENCRYPTED;
END;

-----------------------------------------------------------------
--Decrypt
-----------------------------------------------------------------
FUNCTION DECRYPT(ARG_VALUE IN RAW)RETURN VARCHAR2 IS
  LC_DECRYPTED VARCHAR2(32767);
BEGIN
  DBMS_OBFUSCATION_TOOLKIT.DESDECRYPT(INPUT          => ARG_VALUE,
                                      KEY            => G_KEY,
                                      DECRYPTED_DATA => LC_DECRYPTED);
  RETURN RTRIM(UTL_RAW.CAST_TO_VARCHAR2(LC_DECRYPTED),G_PAD_CHR);
END;
-----------------------------------------------------------------
--UPDATE PASSWORD
-----------------------------------------------------------------
PROCEDURE UPDATE_PASSWORD AS
  CURSOR C1 IS
        SELECT DISTINCT TOR_CP_CODE,TOR_RCT_NUM,TOR_PAT_ID
        FROM   LAB_TO_OL_REPORTING_PQ
        WHERE  TOR_CP_CODE = '01'
        AND    TOR_PASS IS NULL;
  LC_PASS VARCHAR2(100);
BEGIN
  FOR A IN C1 LOOP
      LC_PASS := DBMS_RANDOM.STRING('U',5);
      UPDATE HOS_TM_OPD_SRV_RCPT
      SET    MSR_PASS    = LC_PASS
      WHERE  MSR_CP_CODE = A.TOR_CP_CODE
      AND    MSR_NUM     = A.TOR_RCT_NUM;
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_PASS    = LC_PASS
      WHERE  TOR_CP_CODE = A.TOR_CP_CODE
      AND    TOR_RCT_NUM = A.TOR_RCT_NUM;
      IF A.TOR_PAT_ID IS NOT NULL THEN
         UPDATE HOS_SM_PATIENT
         SET    MPT_PASS    = LC_PASS
         WHERE  MPT_CP_CODE = A.TOR_CP_CODE
         AND    MPT_ID      = A.TOR_PAT_ID;
      END IF;
      COMMIT;
  END LOOP;
END;
-----------------------------------------------------------------
--Pending Queue
-----------------------------------------------------------------
PROCEDURE PENDING_QUEUE(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL)AS
  LC_CNT       NUMBER;
  LC_DIRECTORY VARCHAR2(100);
  LC_FLAG      VARCHAR2(1) := 'T';
  CURSOR PAT_CUR IS
         SELECT A.*,A.ROWID
         FROM   HOS_SM_PATIENT_PQ A
         WHERE  MPT_CP_CODE = ARG_CP_CODE
         ORDER BY MPT_INS_DATE,MPT_INS_TIME;

  CURSOR CON_CUR IS
         SELECT A.*,A.ROWID
         FROM   HOS_SM_CONSULTANT_PQ A
         WHERE  MCT_CP_CODE = ARG_CP_CODE;

  CURSOR RPQ_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_OL_REPORTING_PQ A
         WHERE  TOR_CP_CODE  = NVL(ARG_CP_CODE,TOR_CP_CODE)
         AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)
         AND    NVL(TOR_FLAG,'Y') = 'Y';

  CURSOR LDF_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_DOWNLOAD_FILE_PQ A
         WHERE  LDF_CP_CODE  = NVL(ARG_CP_CODE,LDF_CP_CODE)
         AND    LDF_RPT_ID   = NVL(ARG_RPT_ID,LDF_RPT_ID)
         AND    LDF_DSC_CODE = NVL(ARG_DSC_CODE,LDF_DSC_CODE)
         AND    LDF_FILE_NAME =  NVL(ARG_FILE_NAME,LDF_FILE_NAME);
BEGIN

insert into t25012021 values('1');
  BEGIN
    SELECT ISR_LAB_RPT_DIR
    INTO   LC_DIRECTORY
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = NVL(ARG_CP_CODE,ISR_CP_CODE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;

insert into t25012021 values('2');
  ------------------------------------------------------
  --Patient Info
  ------------------------------------------------------
  FOR PAT_REC IN PAT_CUR LOOP
      BEGIN
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   HOS_SM_PATIENT_OLVW--HOS_SM_PATIENT@ISROLAKH
        WHERE  MPT_ID      = PAT_REC.MPT_ID
        AND    MPT_CP_CODE = PAT_REC.MPT_CP_CODE;
        IF LC_CNT = 0 THEN
           INSERT INTO HOS_SM_PATIENT_OLVW
                 (MPT_CP_CODE,                  MPT_REG_DATE,                  MPT_ID,                  MPT_NAME,
                  MPT_RELT_FLAG,                MPT_FATHER_NAME,               MPT_SEX,                 MPT_DOB,
                  MPT_AGE,                      MPT_AGE_TYPE,                  MPT_STATUS,              MPT_ACTIVE,
                  MPT_PASS,                     MPT_MOBILE)
           VALUES(PAT_REC.MPT_CP_CODE,          PAT_REC.MPT_REG_DATE,          PAT_REC.MPT_ID,          PAT_REC.MPT_NAME,
                  PAT_REC.MPT_RELT_FLAG,        PAT_REC.MPT_FATHER_NAME,       PAT_REC.MPT_SEX,         PAT_REC.MPT_DOB,
                  PAT_REC.MPT_AGE,              PAT_REC.MPT_AGE_TYPE,          PAT_REC.MPT_STATUS,      PAT_REC.MPT_ACTIVE,
                  PAT_REC.MPT_PASS,             PAT_REC.MPT_MOBILE);
        ELSE
           UPDATE HOS_SM_PATIENT_OLVW--HOS_SM_PATIENT@ISROLAKH
           SET    MPT_NAME      = PAT_REC.MPT_NAME,
                  MPT_STATUS    = PAT_REC.MPT_STATUS,
                  MPT_ACTIVE    = PAT_REC.MPT_ACTIVE,
                  MPT_AGE_TYPE  = PAT_REC.MPT_AGE_TYPE,
                  MPT_AGE       = PAT_REC.MPT_AGE,
                  MPT_PASS      = PAT_REC.MPT_PASS,
                  MPT_MOBILE    = PAT_REC.MPT_MOBILE
           WHERE  MPT_CP_CODE   = PAT_REC.MPT_CP_CODE
           AND    MPT_ID        = PAT_REC.MPT_ID;
        END IF;
        DELETE FROM HOS_SM_PATIENT_PQ
        WHERE  MPT_CP_CODE = PAT_REC.MPT_CP_CODE
        AND    MPT_ID      = PAT_REC.MPT_ID;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Patient info inserting. '||SQLERRM);
      END;
  END LOOP;

insert into t25012021 values('3');
  ------------------------------------------------------
  --Consultant Info
  ------------------------------------------------------
  FOR CON_REC IN CON_CUR LOOP
      BEGIN
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   HOS_SM_CONSULTANT_OLVW--HOS_SM_CONSULTANT@ISROLAKH
        WHERE  MCT_CP_CODE = CON_REC.MCT_CP_CODE
        AND    MCT_CODE    = CON_REC.MCT_CODE;
        IF LC_CNT = 0 THEN
           INSERT INTO HOS_SM_CONSULTANT_OLVW
                 (MCT_CP_CODE,                MCT_DEP_CODE,                MCT_CODE,                MCT_NAME,
                  MCT_ID_CARD,                MCT_DAYS_TIMINGS,            MCT_TYPE,                MCT_SEX,
                  MCT_DOJ,                    MCT_ACTIVE,                  MCT_BR_CODE,             MCT_PASS)
           VALUES(CON_REC.MCT_CP_CODE,        CON_REC.MCT_DEP_CODE,        CON_REC.MCT_CODE,        CON_REC.MCT_NAME,
                  CON_REC.MCT_ID_CARD,        CON_REC.MCT_DAYS_TIMINGS,    CON_REC.MCT_TYPE,        CON_REC.MCT_SEX,
                  CON_REC.MCT_DOJ,            CON_REC.MCT_ACTIVE,          CON_REC.MCT_BR_CODE,     CON_REC.MCT_PASS);
        ELSE
           UPDATE HOS_SM_CONSULTANT_OLVW--HOS_SM_CONSULTANT@ISROLAKH
           SET    MCT_NAME         = CON_REC.MCT_NAME,
                  MCT_DAYS_TIMINGS = CON_REC.MCT_DAYS_TIMINGS,
                  MCT_ACTIVE       = CON_REC.MCT_ACTIVE,
                  MCT_PASS         = CON_REC.MCT_PASS
           WHERE  MCT_CP_CODE      = CON_REC.MCT_CP_CODE
           AND    MCT_CODE         = CON_REC.MCT_CODE;
        END IF;
        DELETE FROM HOS_SM_CONSULTANT_PQ
        WHERE  MCT_CP_CODE = CON_REC.MCT_CP_CODE
        AND    MCT_CODE    = CON_REC.MCT_CODE;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Consultant info inserting. '||SQLERRM);
      END;
  END LOOP;

insert into t25012021 values('4');
  ------------------------------------------------------
  --Lab Info
  ------------------------------------------------------
   UPDATE LAB_TO_OL_REPORTING_PQ A
   SET    TOR_FLAG     = 'N'
   WHERE  TOR_CP_CODE  = NVL(ARG_CP_CODE,TOR_CP_CODE)
   AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
   AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
   AND    NVL(TOR_FLAG,'Y') = 'Y'
   AND DBMS_LOB.FILEEXISTS(BFILENAME('AKH_LAB_REPORT',OLR_PKG_BKP.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 0;

insert into t25012021 values('5');
  FOR RPQ_REC IN RPQ_CUR LOOP
      BEGIN
        INSERT INTO LAB_TO_OL_REPORTING_OLVW
              (TOR_CP_CODE,                TOR_RPT_ID,                  TOR_RPT_DATE,            TOR_RCT_NUM,
               TOR_PAT_ID,                 TOR_PAT_NAME,                TOR_PAT_AGE,             TOR_AGE_TYPE,
               TOR_PAT_GND,                TOR_MCT_CODE,                TOR_MCT_NAME,            TOR_TYPE,
               TOR_COL_NUM,                TOR_SPC_NUM,                 TOR_DSC_CODE,            TOR_DSC_DESC,
               TOR_DLV_DATE,               TOR_DLV_TIME,                TOR_FNL_USER,            TOR_FNL_DATE,
               TOR_FNL_TIME,               TOR_FILE_NAME,               TOR_MIME_TYPE,           TOR_DATE,
               TOR_TIME,                   TOR_PRG_CODE,                TOR_PRG_DESC,
               TOR_MSC_TYPE,               TOR_RESULT,                  TOR_BR_CODE,             TOR_PASS,
               TOR_ID)
        VALUES(RPQ_REC.TOR_CP_CODE,        RPQ_REC.TOR_RPT_ID,          RPQ_REC.TOR_RPT_DATE,    RPQ_REC.TOR_RCT_NUM,
               RPQ_REC.TOR_PAT_ID,         RPQ_REC.TOR_PAT_NAME,        RPQ_REC.TOR_PAT_AGE,     RPQ_REC.TOR_AGE_TYPE,
               RPQ_REC.TOR_PAT_GND,        RPQ_REC.TOR_MCT_CODE,        RPQ_REC.TOR_MCT_NAME,    RPQ_REC.TOR_TYPE,
               RPQ_REC.TOR_COL_NUM,        RPQ_REC.TOR_SPC_NUM,         RPQ_REC.TOR_DSC_CODE,    REPLACE(RPQ_REC.TOR_DSC_DESC,','),
               RPQ_REC.TOR_DLV_DATE,       RPQ_REC.TOR_DLV_TIME,        RPQ_REC.TOR_FNL_USER,    RPQ_REC.TOR_FNL_DATE,
               RPQ_REC.TOR_FNL_TIME,       RPQ_REC.TOR_FILE_NAME,       RPQ_REC.TOR_MIME_TYPE,   TO_DATE(SYSDATE),
               TO_CHAR(SYSDATE,'HH24:MI:SS'), RPQ_REC.TOR_PRG_CODE,     RPQ_REC.TOR_PRG_DESC,
               RPQ_REC.TOR_MSC_TYPE,       RPQ_REC.TOR_RESULT,          RPQ_REC.TOR_BR_CODE,     RPQ_REC.TOR_PASS,
               RPQ_REC.TOR_ID);
               insert into t25012021 values('5.1');commit;
         OLR_PKG_BKP.UPLOAD_OL_LAB_REPORTS(RPQ_REC.TOR_CP_CODE,RPQ_REC.TOR_RPT_ID,RPQ_REC.TOR_DSC_CODE,RPQ_REC.TOR_FILE_NAME);
         insert into t25012021 values('5.2');commit;
         --SMS_PKG.SENT_SMS_LAB_REPORT(RPQ_REC.TOR_CP_CODE,RPQ_REC.TOR_FILE_NAME);
         insert into t25012021 values('5.3');commit;
         DELETE FROM LAB_TO_OL_REPORTING_PQ
         WHERE  ROWID = RPQ_REC.ROWID;
         insert into t25012021 values('5.4');commit;
      EXCEPTION
        WHEN OTHERS THEN
             LC_FLAG := 'F';
             OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue lab reporting inserting. ('||REPLACE(REPLACE(RPQ_REC.TOR_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
      END;
  END LOOP;

insert into t25012021 values('6');
  ------------------------------------------------------
  --Download File
  ------------------------------------------------------
  FOR LDF_REC IN LDF_CUR LOOP
      BEGIN
        INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLAKH
              (LDF_CP_CODE,                LDF_RPT_ID,                  LDF_DSC_CODE,            LDF_FILE,
               LDF_MIME_TYPE,              LDF_FILE_NAME)
        SELECT LDF_CP_CODE,                LDF_RPT_ID,                  LDF_DSC_CODE,            LDF_FILE,
               LDF_MIME_TYPE,              LDF_FILE_NAME
        FROM   LAB_TO_DOWNLOAD_FILE_PQ
        WHERE  LDF_CP_CODE   = LDF_REC.LDF_CP_CODE
        AND    LDF_RPT_ID    = LDF_REC.LDF_RPT_ID
        AND    LDF_DSC_CODE  = LDF_REC.LDF_DSC_CODE
        AND    LDF_FILE_NAME = LDF_REC.LDF_FILE_NAME;

        DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
        WHERE  LDF_CP_CODE   = LDF_REC.LDF_CP_CODE
        AND    LDF_RPT_ID    = LDF_REC.LDF_RPT_ID
        AND    LDF_DSC_CODE  = LDF_REC.LDF_DSC_CODE
        AND    LDF_FILE_NAME = LDF_REC.LDF_FILE_NAME;
      EXCEPTION
         WHEN OTHERS THEN
              LC_FLAG := 'F';
              OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Pending Queue Downloading file inserting. ('||REPLACE(REPLACE(LDF_REC.LDF_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
      END;
  END LOOP;

insert into t25012021 values('7');
  COMMIT;
END;

-----------------------------------------------------------------
--Upload Online Lab Report
-----------------------------------------------------------------
PROCEDURE UPLOAD_OL_LAB_REPORTS(ARG_CP_CODE VARCHAR2,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL) AS
  LC_BLOB       BLOB;
  LC_SRC_LOC    BFILE;
  LC_AMOUNT     INTEGER;
  LC_TIME       VARCHAR2(100);
  LC_DIRECTORY  VARCHAR2(30);
  LC_ERROR      VARCHAR2(1000);
  LC_DELAY_TIME NUMBER;
  LC_RPT_PQ_FLAG VARCHAR2(1);
BEGIN
  BEGIN
    SELECT ISR_LAB_RPT_DIR,ISR_LAB_DELAY_SEC
    INTO   LC_DIRECTORY,LC_DELAY_TIME
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = ARG_CP_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;
  BEGIN
    SELECT NVL(ISR_LAB_RPT_PQ_FLAG,'Y')
    INTO   LC_RPT_PQ_FLAG
    FROM   ISR_XO_CONTROL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_RPT_PQ_FLAG := 'Y';
  END;
  IF LC_DIRECTORY IS NULL THEN
     ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' 1Directory not define. '||SQLERRM);
     RAISE_APPLICATION_ERROR(-20001,'Directory must be define');
  END IF;
  IF LC_RPT_PQ_FLAG = 'N' THEN
  BEGIN
    FOR OLR_REC IN (SELECT *
                    FROM   LAB_TO_OL_REPORTING_OLVW
                    WHERE  TOR_CP_CODE   = ARG_CP_CODE
                    AND    TOR_RPT_ID    = NVL(ARG_RPT_ID,TOR_RPT_ID)
                    AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                    AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP

        LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
        LOOP--Timer
           EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
        END LOOP;

        INSERT INTO LAB_TO_UPLOAD_FILE
              (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
               LUF_MIME_TYPE,                 LUF_FILE_NAME)
        VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
               OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
        RETURN LUF_FILE INTO LC_BLOB;
        LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
        DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
        LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
        DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
        DBMS_LOB.CLOSE(LC_SRC_LOC);
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
         OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Upload File inserting. ('||REPLACE(REPLACE(ARG_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
         FOR OLR_REC IN (SELECT *
                         FROM   LAB_TO_OL_REPORTING_PQ
                         WHERE  TOR_CP_CODE  = ARG_CP_CODE
                         AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
                         AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP
             LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
             LOOP--Timer
                EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
             END LOOP;
             INSERT INTO LAB_TO_UPLOAD_FILE
                   (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
                    LUF_MIME_TYPE,                 LUF_FILE_NAME)
             VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
                    OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
             RETURN LUF_FILE INTO LC_BLOB;
             LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
             DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
             LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
             DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
             DBMS_LOB.CLOSE(LC_SRC_LOC);
         END LOOP;
  END;
  ELSE
     FOR OLR_REC IN (SELECT *
                     FROM   LAB_TO_OL_REPORTING_PQ
                     WHERE  TOR_CP_CODE  = ARG_CP_CODE
                     AND    TOR_RPT_ID   = NVL(ARG_RPT_ID,TOR_RPT_ID)
                     AND    TOR_DSC_CODE = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
                     AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME)) LOOP
         /*
         LC_TIME :=  ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS');
         LOOP--Timer
            EXIT WHEN DBMS_LOB.FILEEXISTS(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1 AND ((TO_CHAR(SYSDATE,'HH24') * 60) * 60) + (TO_CHAR(SYSDATE,'MI') * 60) + TO_CHAR(SYSDATE,'SS') - LC_TIME >= LC_DELAY_TIME;
         END LOOP;
         */
         INSERT INTO LAB_TO_UPLOAD_FILE
               (LUF_CP_CODE,                   LUF_RPT_ID,                   LUF_DSC_CODE,               LUF_FILE,
                LUF_MIME_TYPE,                 LUF_FILE_NAME)
         VALUES(OLR_REC.TOR_CP_CODE,           OLR_REC.TOR_RPT_ID,           OLR_REC.TOR_DSC_CODE,       EMPTY_BLOB(),
                OLR_REC.TOR_MIME_TYPE,         OLR_REC.TOR_FILE_NAME)
         RETURN LUF_FILE INTO LC_BLOB;
         LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(OLR_REC.TOR_FILE_NAME,'.pdf'))||'.tmp');
         DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
         LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
         DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
         DBMS_LOB.CLOSE(LC_SRC_LOC);
     END LOOP;
  END IF;
  IF LC_RPT_PQ_FLAG = 'N' THEN
  BEGIN
    INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLAKH
    SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,'N'
    FROM   LAB_TO_UPLOAD_FILE
    WHERE  LUF_CP_CODE  = ARG_CP_CODE
    AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
    AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
    AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
    /*
    DELETE FROM LAB_TO_UPLOAD_FILE PURGE
    WHERE  LUF_CP_CODE  = ARG_CP_CODE
    AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
    AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
    AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
    */
  EXCEPTION
    WHEN OTHERS THEN
         LC_ERROR := SQLERRM;
         OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Downloading file inserting. ('||REPLACE(REPLACE(ARG_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
         INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
         SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
         FROM   LAB_TO_UPLOAD_FILE
         WHERE  LUF_CP_CODE   = ARG_CP_CODE
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
         AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
         /*
         DELETE FROM LAB_TO_UPLOAD_FILE PURGE
         WHERE  LUF_CP_CODE  = ARG_CP_CODE
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
         AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
         */
  END;
  ELSE
     INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
     SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
     FROM   LAB_TO_UPLOAD_FILE
     WHERE  LUF_CP_CODE   = ARG_CP_CODE
     AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
     AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE)
     AND    LUF_FILE_NAME = NVL(ARG_FILE_NAME,LUF_FILE_NAME);
  END IF;
END;
-----------------------------------------------------------------
--Delete Lab Reports
-----------------------------------------------------------------
PROCEDURE DELETE_LAB_REPORTS(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL) AS
  LC_CNT        NUMBER;
  LC_DIRECTORY  VARCHAR2(30);
  LC_BLOB       BLOB;
  LC_SRC_LOC    BFILE;
  LC_AMOUNT     INTEGER;
  LC_ERROR      VARCHAR2(1000);
  CURSOR LUF_CUR IS
         SELECT A.*,A.ROWID
         FROM   LAB_TO_UPLOAD_FILE A
         WHERE  LUF_CP_CODE   = NVL(ARG_CP_CODE,LUF_CP_CODE)
         AND    LUF_RPT_ID    = NVL(ARG_RPT_ID,LUF_RPT_ID)
         AND    LUF_DSC_CODE  = NVL(ARG_DSC_CODE,LUF_DSC_CODE);

BEGIN
  BEGIN
    SELECT ISR_LAB_RPT_DIR
    INTO   LC_DIRECTORY
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = NVL(ARG_CP_CODE,ISR_CP_CODE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_DIRECTORY := NULL;
  END;
  IF LC_DIRECTORY IS NULL THEN
     ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Directory not define. '||SQLERRM);
     RAISE_APPLICATION_ERROR(-20001,'Directory must be define');
  END IF;
  FOR LUF_REC IN LUF_CUR LOOP
      BEGIN
      SELECT COUNT(*)
      INTO   LC_CNT
      FROM   LAB_TO_UPLOAD_FILE
      WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
      AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
      AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
      AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME
      AND    DBMS_LOB.GETLENGTH(LUF_FILE) = DBMS_LOB.GETLENGTH(BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(LUF_REC.LUF_FILE_NAME,'.pdf'))||'.tmp'));

      IF LC_CNT > 0 THEN
         DELETE FROM LAB_TO_UPLOAD_FILE PURGE
         WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
         AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
         AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
         AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;
      ELSE
         UPDATE LAB_TO_UPLOAD_FILE
         SET    LUF_FILE = EMPTY_BLOB()
         WHERE  ROWID = LUF_REC.ROWID
         RETURN LUF_FILE INTO LC_BLOB;
         LC_SRC_LOC := BFILENAME(LC_DIRECTORY,ENCRYPT(REPLACE(LUF_REC.LUF_FILE_NAME,'.pdf'))||'.tmp');
         DBMS_LOB.OPEN(LC_SRC_LOC, DBMS_LOB.LOB_READONLY);
         LC_AMOUNT := DBMS_LOB.GETLENGTH(LC_SRC_LOC);
         DBMS_LOB.LOADFROMFILE(LC_BLOB, LC_SRC_LOC, LC_AMOUNT);
         DBMS_LOB.CLOSE(LC_SRC_LOC);
         BEGIN
           DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
           WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

           DELETE FROM LAB_TO_DOWNLOAD_FILE@ISROLAKH
           WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

           INSERT INTO LAB_TO_DOWNLOAD_FILE@ISROLAKH
           SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,'N'
           FROM   LAB_TO_UPLOAD_FILE
           WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
           AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
           AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
           AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

          DELETE FROM LAB_TO_UPLOAD_FILE PURGE
          WHERE  LUF_CP_CODE  = ARG_CP_CODE
          AND    LUF_RPT_ID    = NVL(LUF_REC.LUF_RPT_ID,LUF_RPT_ID)
          AND    LUF_DSC_CODE  = NVL(LUF_REC.LUF_DSC_CODE,LUF_DSC_CODE)
          AND    LUF_FILE_NAME = NVL(LUF_REC.LUF_FILE_NAME,LUF_FILE_NAME);
        EXCEPTION
          WHEN OTHERS THEN
               LC_ERROR := SQLERRM;
               OLR_PKG_BKP.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in Downloading file inserting. ('||REPLACE(REPLACE(LUF_REC.LUF_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
               DELETE FROM LAB_TO_DOWNLOAD_FILE_PQ
               WHERE  LDF_CP_CODE   = LUF_REC.LUF_CP_CODE
               AND    LDF_RPT_ID    = LUF_REC.LUF_RPT_ID
               AND    LDF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
               AND    LDF_FILE_NAME = LUF_REC.LUF_FILE_NAME;
               INSERT INTO LAB_TO_DOWNLOAD_FILE_PQ
               SELECT LUF_CP_CODE,LUF_RPT_ID,LUF_DSC_CODE,LUF_FILE,LUF_MIME_TYPE,LUF_FILE_NAME,LC_ERROR
               FROM   LAB_TO_UPLOAD_FILE
               WHERE  LUF_CP_CODE   = LUF_REC.LUF_CP_CODE
               AND    LUF_RPT_ID    = LUF_REC.LUF_RPT_ID
               AND    LUF_DSC_CODE  = LUF_REC.LUF_DSC_CODE
               AND    LUF_FILE_NAME = LUF_REC.LUF_FILE_NAME;

               DELETE FROM LAB_TO_UPLOAD_FILE PURGE
               WHERE  LUF_CP_CODE  = ARG_CP_CODE
               AND    LUF_RPT_ID    = NVL(LUF_REC.LUF_RPT_ID,LUF_RPT_ID)
               AND    LUF_DSC_CODE  = NVL(LUF_REC.LUF_DSC_CODE,LUF_DSC_CODE)
               AND    LUF_FILE_NAME = NVL(LUF_REC.LUF_FILE_NAME,LUF_FILE_NAME);
        END;
      END IF;
      EXCEPTION
        WHEN OTHERS THEN
             ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' File not exists. '||LUF_REC.LUF_FILE_NAME||SQLERRM);
      END;
      COMMIT;
  END LOOP;
END;
-----------------------------------------------------------------
--No Of Record Transfered from Pending Queue
-----------------------------------------------------------------
PROCEDURE UPLOAD_PENDING_QUEUE(ARG_NO_ROWS NUMBER) AS
  CURSOR RPT_CUR IS
         SELECT *
         FROM  (SELECT *
                FROM   LAB_TO_OL_REPORTING_PQ
                WHERE  TO_DATE(TOR_DATE||' '||TOR_TIME,'DD/MM/RRRR HH24:MI:SS') < SYSDATE
                AND    NVL(TOR_FLAG,'Y') = 'Y'
                AND    TOR_GEN_RPT   = 'Y'
                AND    TOR_PASS IS NOT NULL
                --AND    TOR_DATE = TO_DATE(SYSDATE)
                --AND    TOR_DSC_CODE NOT IN('PYCT0004','CHPA0021')
                AND    TOR_DSC_CODE NOT IN('PYCT0004')
                ORDER BY TO_DATE(TOR_DATE||' '||TOR_TIME,'DD/MM/RRRR HH24:MI:SS'))
         WHERE  ROWNUM <= NVL(ARG_NO_ROWS,10)
         AND   (SELECT COUNT(*)
                FROM   LAB_TO_OL_REPORTING_PQ
                WHERE  NVL(TOR_FLAG,'Y') = 'Y'
                AND    TOR_GEN_RPT   = 'Y') > 0;
BEGIN
  FOR RPT_REC IN RPT_CUR LOOP
 --   DBMS_OUTPUT.PUT_LINE(RPT_REC.TOR_FILE_NAME);
      OLR_PKG_BKP.PENDING_QUEUE(RPT_REC.TOR_CP_CODE,RPT_REC.TOR_RPT_ID,RPT_REC.TOR_DSC_CODE,RPT_REC.TOR_FILE_NAME);
  END LOOP;
END;

-----------------------------------------------------------------
--No Of Record Transfered from Pending Queue
-----------------------------------------------------------------
PROCEDURE GENERATE_REPORT(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL,ARG_DEV VARCHAR2 DEFAULT '10g') AS
  LC_RPT_NAME    VARCHAR2(30);
  LC_DES_NAME    VARCHAR2(4000);
  LC_DEV_DIR     VARCHAR2(4000);
  LC_APP_DIR     VARCHAR2(4000);
  LC_PARAMETER   VARCHAR2(4000);
  LC_CONNECTION  VARCHAR2(1000);
  CURSOR C1 IS
         SELECT *
         FROM   LAB_TD_SRV_DIAG,LAB_TO_OL_REPORTING_PQ
         WHERE  TOR_CP_CODE   = DSD_CP_CODE
         AND    TOR_RPT_ID    = DSD_RPT_ID
         AND    TOR_DSC_CODE  = DSD_DSC_CODE
         AND    TOR_RCT_NUM   = DSD_RCT_NUM
         --AND    TOR_SPC_NUM   = DSD_SPC_NUM
         --AND    TOR_FLAG      = 'N'
         AND    TOR_CP_CODE   = ARG_CP_CODE
         AND    TOR_RPT_ID    = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME = NVL(ARG_FILE_NAME,TOR_FILE_NAME);
BEGIN
  FOR A IN C1 LOOP
      begin
      LC_RPT_NAME := 'LABAR01'||A.DSD_REP_TYPE||'LP';
      BEGIN
        SELECT DECRYPT(usr_auth),'"'||REPLACE(LAB_RPT_DIR,'\\192.168.0.108\','D:\')||'"',REPLACE(APP_DIR||'\Reports\','\\')||LC_RPT_NAME||'.rep',DEV_DIR||DECODE(ARG_DEV,'10g','\RWRUN.EXE','\RWRUN60.EXE')
        INTO   LC_CONNECTION,LC_DES_NAME,LC_APP_DIR,LC_DEV_DIR
        FROM   SYSTEM.V$HW_SPEC;
      EXCEPTION
        WHEN OTHERS THEN
             LC_DES_NAME := NULL;
      END;
      LC_DES_NAME := LC_DES_NAME||OLR_PKG_BKP.ENCRYPT(A.TOR_PAT_ID||'_'||A.TOR_RPT_ID||'_'||A.TOR_DSC_CODE||'_'||TO_CHAR(A.TOR_FNL_DATE,'DDMMRRRR')||'_'||REPLACE(A.TOR_FNL_TIME,':'))||'.tmp';

      LC_PARAMETER := ' LC_CP_CODE="'||A.TOR_CP_CODE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_USR_NAME="'||A.TOR_FNL_USER||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DSC_CODE="'||A.TOR_DSC_CODE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_REP_TYPE="'||A.DSD_REP_TYPE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_LTI_REP_TYPE="'||A.DSD_LTI_REP_TYPE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DATE_FM="'||A.TOR_RPT_DATE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_DATE_TO="'||A.TOR_RPT_DATE||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_RCT_ID="'||A.TOR_RCT_NUM||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_CODE_FM="'||A.TOR_RPT_ID||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_CODE_TO="'||A.TOR_RPT_ID||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_COL_FM="'||NVL(A.TOR_COL_NUM, '-')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_COL_TO="'||NVL(A.TOR_COL_NUM, '-')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_TYPE="'||NVL(A.TOR_TYPE, 'OPD')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_PRINT_HF="'||'Y'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_GEN_MODE="'||'S'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_SIGN="'||'N'||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_FNL_DATE_TIME="'||TO_CHAR(TO_DATE(A.TOR_FNL_DATE||'  '||A.TOR_FNL_TIME,'DD/MM/RRRR HH24:MI:SS'),'DD/MM/RRRR - HH:MI AM')||'"';
      LC_PARAMETER := LC_PARAMETER||' LC_FNL_USER="Reported by : '||A.TOR_FNL_USER||'"';
      LC_PARAMETER := LC_DEV_DIR||' REPORT='||LC_APP_DIR||' USERID='||LC_CONNECTION||' '||LC_PARAMETER||' BATCH=YES DESFORMAT=PDF DESTYPE=FILE DESNAME="'||REPLACE(LC_DES_NAME,'"')||'"';
      HOST_COMMAND(LC_PARAMETER);
--      DBMS_OUTPUT.PUT_LINE(LC_PARAMETER);
      --UPLOAD_OL_LAB_REPORTS('01',NULL,NULL,A.TOR_FILE_NAME);
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_FLAG     = 'Y'
      WHERE  TOR_CP_CODE  = A.TOR_CP_CODE
      AND    TOR_RPT_ID   = A.TOR_RPT_ID
      AND    TOR_DSC_CODE = A.TOR_DSC_CODE
      AND    NVL(TOR_FLAG,'Y') = 'N'
      AND    DBMS_LOB.FILEEXISTS(BFILENAME('AKH_LAB_REPORT',OLR_PKG_BKP.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1;
      COMMIT;
    exception
      when others then
           NULL;
    end;
  END LOOP;
END;
---------------------------------------------------------------------------------------------
PROCEDURE GENERATE_REPORT_JOB(ARG_CP_CODE VARCHAR2 DEFAULT NULL,ARG_RPT_ID VARCHAR2 DEFAULT NULL,ARG_DSC_CODE VARCHAR2 DEFAULT NULL,ARG_FILE_NAME VARCHAR2 DEFAULT NULL) AS
  CURSOR C1 IS
         SELECT *
         FROM   LAB_TO_OL_REPORTING_PQ M
         WHERE  TOR_CP_CODE = ARG_CP_CODE
         AND    TOR_RPT_ID  = NVL(ARG_RPT_ID,TOR_RPT_ID)
         AND    TOR_DSC_CODE  = NVL(ARG_DSC_CODE,TOR_DSC_CODE)
         AND    TOR_FILE_NAME  = NVL(ARG_FILE_NAME,TOR_FILE_NAME)
         AND    TOR_GEN_RPT = 'N'
         AND    TO_DATE(TOR_FNL_DATE||' '||TOR_FNL_TIME,'DD/MM/RRRR HH24:MI:SS') <= SYSDATE - INTERVAL '3' MINUTE
         AND    TO_CHAR(TOR_FNL_DATE,'RRRRMMDD')||REPLACE(TOR_FNL_TIME,':') IN
               (SELECT MAX(TO_CHAR(D.TOR_FNL_DATE,'RRRRMMDD')||REPLACE(D.TOR_FNL_TIME,':'))
                FROM   LAB_TO_OL_REPORTING_PQ D
                WHERE  D.TOR_CP_CODE = M.TOR_CP_CODE
                AND    D.TOR_RPT_ID  = M.TOR_RPT_ID
                AND    D.TOR_DSC_CODE = M.TOR_DSC_CODE
                AND    D.TOR_GEN_RPT = 'N');
BEGIN
  OLR_PKG_BKP.UPDATE_PASSWORD;
  FOR A IN C1 LOOP
      BEGIN
        OLR_PKG_BKP.GENERATE_REPORT(A.TOR_CP_CODE,A.TOR_RPT_ID,A.TOR_DSC_CODE,A.TOR_FILE_NAME,'10g');
        UPDATE LAB_TO_OL_REPORTING_PQ
        SET    TOR_GEN_RPT   = 'Y'
        WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
        AND    TOR_RPT_ID    = A.TOR_RPT_ID
        AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
        AND    TOR_GEN_RPT = 'N'
        AND    DBMS_LOB.FILEEXISTS(BFILENAME('AKH_LAB_REPORT',OLR_PKG_BKP.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 1;
      EXCEPTION
        WHEN OTHERS THEN
             UPDATE LAB_TO_OL_REPORTING_PQ
             SET    TOR_GEN_RPT   = 'E'
             WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
             AND    TOR_RPT_ID    = A.TOR_RPT_ID
             AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
             AND    TOR_GEN_RPT = 'N'
             AND    DBMS_LOB.FILEEXISTS(BFILENAME('AKH_LAB_REPORT',OLR_PKG_BKP.ENCRYPT(REPLACE(TOR_FILE_NAME,'.pdf'))||'.tmp')) = 0;
      END;
      UPDATE LAB_TO_OL_REPORTING_PQ
      SET    TOR_GEN_RPT   = 'C'
      WHERE  TOR_CP_CODE   = A.TOR_CP_CODE
      AND    TOR_RPT_ID    = A.TOR_RPT_ID
      AND    TOR_DSC_CODE  = A.TOR_DSC_CODE
      AND    TOR_GEN_RPT = 'N';
  END LOOP;
  COMMIT;
END;
END OLR_PKG_BKP;
/

