prompt Creating package body PAY_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.PAY_PKG AS
--------------------------------------------------------------------
FUNCTION GET_EMP_DP(ARG_CP_CODE VARCHAR2,ARG_EMP_CODE VARCHAR2,ARG_DATE DATE) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(100);
BEGIN
  BEGIN
    SELECT DED_DP_CODE
    INTO   LC_VAL
    FROM   PAY_SD_EMP_DEPT A
    WHERE  DED_CP_CODE  = ARG_CP_CODE
    AND    DED_EMP_CODE = ARG_EMP_CODE
    AND    DED_DATE     = (SELECT MAX(B.DED_DATE)
                           FROM   PAY_SD_EMP_DEPT B
                           WHERE  B.DED_CP_CODE  = A.DED_CP_CODE
                           AND    B.DED_EMP_CODE = A.DED_EMP_CODE
                           AND    B.DED_DATE <= ARG_DATE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_EMP_CT(ARG_CP_CODE VARCHAR2,ARG_EMP_CODE VARCHAR2,ARG_DATE DATE) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(100);
BEGIN
  BEGIN
    SELECT INC_CT_CODE
    INTO   LC_VAL
    FROM   PAY_TM_INCREMENT A
    WHERE  INC_CP_CODE  = ARG_CP_CODE
    AND    INC_EMP_CODE = ARG_EMP_CODE
    AND    INC_DATE     = (SELECT MAX(B.INC_DATE)
                           FROM   PAY_TM_INCREMENT B
                           WHERE  B.INC_CP_CODE  = A.INC_CP_CODE
                           AND    B.INC_EMP_CODE = A.INC_EMP_CODE
                           AND    B.INC_DATE <= ARG_DATE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_EMP_DS(ARG_CP_CODE VARCHAR2,ARG_EMP_CODE VARCHAR2,ARG_DATE DATE) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(100);
BEGIN
  BEGIN
    SELECT INC_DS_CODE
    INTO   LC_VAL
    FROM   PAY_TM_INCREMENT A
    WHERE  INC_CP_CODE  = ARG_CP_CODE
    AND    INC_EMP_CODE = ARG_EMP_CODE
    AND    INC_DATE     = (SELECT MAX(B.INC_DATE)
                           FROM   PAY_TM_INCREMENT B
                           WHERE  B.INC_CP_CODE  = A.INC_CP_CODE
                           AND    B.INC_EMP_CODE = A.INC_EMP_CODE
                           AND    B.INC_DATE <= ARG_DATE);
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_DP_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT DP_'||ARG_COL_NAME||' FROM ISR_XD_DEPT WHERE DP_CP_CODE = '''||ARG_CP_CODE||''' AND DP_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_CT_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT CT_'||ARG_COL_NAME||' FROM PAY_SO_CATEGORY WHERE CT_CP_CODE = '''||ARG_CP_CODE||''' AND CT_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_DS_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT DS_'||ARG_COL_NAME||' FROM PAY_SO_DESIG WHERE DS_CP_CODE = '''||ARG_CP_CODE||''' AND DS_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
END PAY_PKG;
/

