prompt Creating package body PPI_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.PPI_PKG AS
FUNCTION GET_ROT_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT ROT_'||ARG_COL_NAME||' FROM PPI_SO_ROUTE WHERE ROT_CP_CODE = '''||ARG_CP_CODE||''' AND ROT_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
-------------------------------------------------
FUNCTION GET_FRQ_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT FRQ_'||ARG_COL_NAME||' FROM PPI_SO_FREQUENCY WHERE FRQ_CP_CODE = '''||ARG_CP_CODE||''' AND FRQ_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
-------------------------------------------------
FUNCTION GET_ITEM_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  BEGIN
    EXECUTE IMMEDIATE 'SELECT DIT_'||ARG_COL_NAME||' FROM PPI_SD_ITEM WHERE DIT_CP_CODE = '''||ARG_CP_CODE||''' AND DIT_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_VAL := NULL;
  END;
  RETURN LC_VAL;
END;
-------------------------------------------------
FUNCTION GET_ISO_DYS_SPD_CNT(ARG_CP_CODE VARCHAR2,ARG_MSO_NUM VARCHAR2,ARG_DIT_CODE VARCHAR2,ARG_DATE DATE DEFAULT NULL) RETURN NUMBER IS
  LC_VAL NUMBER;
BEGIN
  SELECT COUNT(DISTINCT MSL_DATE)
  INTO   LC_VAL
  FROM   HOS_TM_SALES,HOS_TD_SALES
  WHERE  MSL_CP_CODE  = DSL_CP_CODE
  AND    MSL_NUM      = DSL_MSL_NUM
  AND    MSL_CP_CODE  = ARG_CP_CODE
  AND    MSL_MSO_NUM  = ARG_MSO_NUM
  AND    DSL_DIT_CODE = ARG_DIT_CODE
  AND    MSL_DATE     = NVL(ARG_DATE,MSL_DATE) ;
  RETURN LC_VAL;
END;
-------------------------------------------------
FUNCTION GET_ISO_ITM_FLAG(ARG_CP_CODE VARCHAR2,ARG_MSO_NUM VARCHAR2,ARG_DIT_CODE VARCHAR2) RETURN VARCHAR2 IS
BEGIN
 RETURN NULL;
END;
END PPI_PKG;
/

