prompt
prompt Creating package body SMS_PKG
prompt =============================
prompt
CREATE OR REPLACE PACKAGE BODY MDHSYS.SMS_PKG AS
--------------------------------------------------------------------
FUNCTION GET_CONTROL_INFO(ARG_CP_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  EXECUTE IMMEDIATE 'SELECT ISR_'||ARG_COL_NAME||' FROM ISR_XO_CONTROL WHERE ISR_CP_CODE = '''||ARG_CP_CODE||'''' INTO LC_VAL;
  RETURN LC_VAL;
END;
--------------------------------------------------------------------
FUNCTION GET_TEMPLATE_INFO(ARG_CP_CODE VARCHAR2,ARG_CODE VARCHAR2,ARG_COL_NAME VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(4000);
BEGIN
  EXECUTE IMMEDIATE 'SELECT STM_'||ARG_COL_NAME||' FROM ISR_SO_SMS_TEMPLATE WHERE STM_CP_CODE = '''||ARG_CP_CODE||''' AND STM_CODE = '''||ARG_CODE||'''' INTO LC_VAL;
  RETURN LC_VAL;
END;

  PROCEDURE SENT_SMS_LAB_REPORT(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2) AS
    LC_LAB_REC  LAB_TO_OL_REPORTING_PQ%ROWTYPE;
    HTTP_REQ    UTL_HTTP.REQ;
    HTTP_RESP   UTL_HTTP.RESP;
    LC_PASS     VARCHAR2(100);
    URL_TEXT    VARCHAR2(32767);
    URL         VARCHAR2(2000);
    SMS_MSG     VARCHAR2(400);
    PHONE_NO    VARCHAR2(15);
    LC_ECODE    VARCHAR2(100);
    LC_FLAG     VARCHAR2(1);
    LC_LOG_FLAG VARCHAR2(100);
    LC_LOG      VARCHAR2(1);
  BEGIN
    BEGIN
      SELECT *
      INTO   LC_LAB_REC
      FROM   LAB_TO_OL_REPORTING_PQ
      WHERE  TOR_CP_CODE   = ARG_CP_CODE
      AND    TOR_FILE_NAME = ARG_DOC_NUM;
    EXCEPTION
      WHEN OTHERS THEN
           LC_LAB_REC := NULL;
    END;
    BEGIN
      SELECT MSR_PHONE,MSR_PASS
      INTO   PHONE_NO,LC_PASS
      FROM   HOS_TM_OPD_SRV_RCPT
      WHERE  MSR_CP_CODE = ARG_CP_CODE
      AND    MSR_NUM     = LC_LAB_REC.TOR_RCT_NUM;
    EXCEPTION
      WHEN OTHERS THEN
           SELECT MPF_CONT_NO,MPF_PASS
           INTO   PHONE_NO,LC_PASS
           FROM   HOS_TM_PATIENT_FILE
           WHERE  MPF_CP_CODE = ARG_CP_CODE
           AND    MPF_FILE_NUM = LC_LAB_REC.TOR_COL_NUM;    
    END;
    IF PHONE_NO IS NULL THEN
    BEGIN
      SELECT MPT_MOBILE,MPT_PASS
      INTO   PHONE_NO,LC_PASS
      FROM   HOS_SM_PATIENT
      WHERE  MPT_CP_CODE = ARG_CP_CODE
      AND    MPT_ID      = LC_LAB_REC.TOR_PAT_ID;
    EXCEPTION
      WHEN OTHERS THEN
           PHONE_NO := NULL;
           LC_PASS  := NULL;
    END;
    END IF;

    SELECT NVL(ISR_SMS_LOG_FLAG,'N'),NVL(ISR_SMS_LAB_RPT_FLAG,'N'),ISR_SMS_LAB_RPT_TEXT,NVL(ISR_SMS_LAB_RPT_LOG_FLAG,'N')
    INTO   LC_LOG_FLAG,LC_FLAG,SMS_MSG,LC_LOG
    FROM   ISR_XO_CONTROL;
    IF PHONE_NO IS NOT NULL AND LC_FLAG = 'Y' THEN
       BEGIN
         /*
         REPORT_ID = TOR_RPT_ID,
         REPORT_DATE = TOR_RPT_DATE,
         RECEIPT_NO = TOR_RCT_NUM,
         PATIENT_ID = TOR_PAT_ID,
         PATIENT = TOR_PAT_NAME,
         PASSWORD = LC_PASS
         CONSULTANT = TOR_MCT_NAME,
         COLLECTION_NO = TOR_SPC_NUM,
         SERVICE = TOR_DSC_DESC,
         FINAL_USER = TOR_FNL_USER,
         FINAL_DATE = TOR_FNL_DATE,
         FINAL_TIME = TOR_FNL_TIME
         */
         SMS_MSG  := REPLACE(SMS_MSG,'#REPORT_ID#',LC_LAB_REC.TOR_RPT_ID);
         SMS_MSG  := REPLACE(SMS_MSG,'#REPORT_DATE#',TO_CHAR(LC_LAB_REC.TOR_RPT_DATE,'DD-MM-RRRR'));
         SMS_MSG  := REPLACE(SMS_MSG,'#RECEIPT_NO#',LC_LAB_REC.TOR_RCT_NUM);
         SMS_MSG  := REPLACE(SMS_MSG,'#PATIENT_ID#',LC_LAB_REC.TOR_PAT_ID);
         SMS_MSG  := REPLACE(SMS_MSG,'#PASSWORD#',LC_PASS);
         IF LC_LAB_REC.TOR_PAT_ID IS NULL THEN
            SMS_MSG  := REPLACE(SMS_MSG,'#SIGNIN_ID#',LC_LAB_REC.TOR_RCT_NUM);
         ELSE
            SMS_MSG  := REPLACE(SMS_MSG,'#SIGNIN_ID#',LC_LAB_REC.TOR_PAT_ID);
         END IF;
         SMS_MSG  := REPLACE(SMS_MSG,'#PATIENT#',LC_LAB_REC.TOR_PAT_NAME);
         SMS_MSG  := REPLACE(SMS_MSG,'#CONSULTANT#',LC_LAB_REC.TOR_MCT_NAME);
         SMS_MSG  := REPLACE(SMS_MSG,'#COLLECTION_NO#',LC_LAB_REC.TOR_SPC_NUM);
         SMS_MSG  := REPLACE(SMS_MSG,'#SERVICE#',LC_LAB_REC.TOR_DSC_DESC);
         SMS_MSG  := REPLACE(SMS_MSG,'#FINAL_USER#',LC_LAB_REC.TOR_FNL_USER);
         SMS_MSG  := REPLACE(SMS_MSG,'#FINAL_DATE#',TO_CHAR(LC_LAB_REC.TOR_FNL_DATE,'DD-MM-RRRR'));
         SMS_MSG  := REPLACE(SMS_MSG,'#FINAL_TIME#',LC_LAB_REC.TOR_FNL_TIME);

         DBMS_OUTPUT.ENABLE(1000000);
         ---  -------------------------------------------
--         URL := 'http://csms.dotklick.com/api_sms/api.php?key=fc8794d37a8499d5a57c076d1b4d9a1d'||CHR(38)||'receiver='||PHONE_NO||CHR(38)||'msgdata='||UTL_URL.Escape(SMS_MSG,TRUE);
--         URL := 'http://bsms.telecard.com.pk/SMSPortal/Customer/apikey.aspx?apikey=37d1e3d24df94a7493770867923fa2b3'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;
         URL := 'http://bsms.telecard.com.pk/SMSportal/Customer/apikey.aspx?apikey=58fab9c8953f4553828f724a841496a8'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;
         HTTP_REQ  := UTL_HTTP.BEGIN_REQUEST(URL);

         UTL_HTTP.SET_HEADER(HTTP_REQ, 'User-Agent', 'Mozilla/4.0');
         HTTP_RESP := UTL_HTTP.GET_RESPONSE(HTTP_REQ);

         LOOP
           BEGIN
             URL_TEXT := null;
             UTL_HTTP.READ_LINE(HTTP_RESP, URL_TEXT, TRUE);
--             LC_ECODE := SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11,INSTR(SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11),'"')-1);
             LC_ECODE := URL_TEXT;
             IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
                IF LC_ECODE = 'OK' THEN
                   INSERT INTO ISR_TO_SMS_LOG
                         (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                          ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                          ISL_OI_TYPE)
                   VALUES(LC_LAB_REC.TOR_FNL_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                          URL_TEXT,                 REPLACE(PHONE_NO,','),    'Y',                     ARG_DOC_NUM,
                          LC_LAB_REC.TOR_TYPE);
                   COMMIT;
                ELSE
                   INSERT INTO ISR_TO_SMS_LOG
                         (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                          ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                          ISL_OI_TYPE)
                   VALUES(LC_LAB_REC.TOR_FNL_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                          URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     ARG_DOC_NUM,
                          LC_LAB_REC.TOR_TYPE);
                   COMMIT;
                END IF;
             END IF;
           EXCEPTION
             WHEN OTHERS THEN
                  EXIT;
           END;
         END LOOP;
         UTL_HTTP.END_RESPONSE(HTTP_RESP);
       EXCEPTION
         WHEN OTHERS THEN
              URL_TEXT := SQLCODE||' - '||SQLERRM;
              IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_LAB_REC.TOR_FNL_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     ARG_DOC_NUM,
                        LC_LAB_REC.TOR_TYPE);
                 COMMIT;
              END IF;
       END;
    END IF;
  END;
 --=====================================================================================================================
 PROCEDURE SENT_SMS_OPD_SERVICES(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2) AS
    LC_OPD_REC  HOS_TM_OPD_SRV_RCPT%ROWTYPE;
    LC_MPT_NAME VARCHAR2(100);
    HTTP_REQ    UTL_HTTP.REQ;
    HTTP_RESP   UTL_HTTP.RESP;
    URL_TEXT    VARCHAR2(32767);
    URL         VARCHAR2(2000);
    SMS_MSG     VARCHAR2(400);
    PHONE_NO    VARCHAR2(15);
    LC_ECODE    VARCHAR2(100);
    LC_FLAG     VARCHAR2(1);
    LC_LOG_FLAG VARCHAR2(100);
    LC_LOG      VARCHAR2(1);
    LC_CNT       NUMBER; 
    LC_COVID_CNT NUMBER; 
  BEGIN
    BEGIN
      SELECT *
      INTO   LC_OPD_REC
      FROM   HOS_TM_OPD_SRV_RCPT
      WHERE  MSR_CP_CODE   = ARG_CP_CODE
      AND    MSR_NUM        = ARG_DOC_NUM;
    EXCEPTION
      WHEN OTHERS THEN
           LC_OPD_REC := NULL;
    END;
    SELECT COUNT(*),NVL(SUM(DECODE(SUBSTR(DSR_DSC_CODE,1,4),'VIRO',1,0)),0)
    INTO   LC_CNT,LC_COVID_CNT
    FROM   HOS_TD_OPD_SRV_RCPT
    WHERE  DSR_CP_CODE = ARG_CP_CODE
    AND    DSR_MSR_NUM = ARG_DOC_NUM;
    BEGIN
      SELECT MPT_NAME||' '||MPT_RELT_FLAG||' '||MPT_FATHER_NAME
      INTO   LC_MPT_NAME
      FROM   HOS_SM_PATIENT
      WHERE  MPT_CP_CODE = ARG_CP_CODE
      AND    MPT_ID      = LC_OPD_REC.MSR_PAT_ID;
    EXCEPTION
      WHEN OTHERS THEN
           LC_MPT_NAME := NULL;
    END;
    PHONE_NO := LC_OPD_REC.MSR_PHONE;
    SELECT NVL(ISR_SMS_LOG_FLAG,'N'),NVL(ISR_SMS_OPD_SRV_FLAG,'N'),DECODE(LC_CNT,LC_COVID_CNT,ISR_SMS_OPD_SRV_COVID_TEXT,ISR_SMS_OPD_SRV_TEXT),NVL(ISR_SMS_OPD_SRV_LOG_FLAG,'N')
    INTO   LC_LOG_FLAG,LC_FLAG,SMS_MSG,LC_LOG
    FROM   ISR_XO_CONTROL;
    IF PHONE_NO IS NOT NULL AND LC_FLAG = 'Y' THEN
       BEGIN
         /*
         PATIENT_ID = LC_OPD_REC.MSR_PAT_ID,
         PATIENT = LC_MPT_NAME,
         PASSWORD = LC_OPD_REC.MSR_PASS
         */
         SMS_MSG  := REPLACE(SMS_MSG,'#PATIENT_ID#',LC_OPD_REC.MSR_PAT_ID);
         SMS_MSG  := REPLACE(SMS_MSG,'#PATIENT#',LC_MPT_NAME);
         SMS_MSG  := REPLACE(SMS_MSG,'#PASSWORD#',LC_OPD_REC.MSR_PASS);
         SMS_MSG  := REPLACE(SMS_MSG,'#NET_AMOUNT#',LC_OPD_REC.MSR_NET_AMT);

         DBMS_OUTPUT.ENABLE(1000000);
         ---  -------------------------------------------
--         URL := 'http://csms.dotklick.com/api_sms/api.php?key=fc8794d37a8499d5a57c076d1b4d9a1d'||CHR(38)||'receiver='||PHONE_NO||CHR(38)||'msgdata='||UTL_URL.Escape(SMS_MSG,TRUE);
         --URL := 'http://bsms.telecard.com.pk/SMSPortal/Customer/ProcessSMS.aspx?userid=testalkkhi'||CHR(38)||'pwd=testalkkhi123'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;
         URL := 'http://bsms.tel5ecard.com.pk/SMSPortal/Customer/ProcessSMS.aspx?userid=aklabkhi'||CHR(38)||'pwd=aklabkhi123'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;

         HTTP_REQ  := UTL_HTTP.BEGIN_REQUEST(URL);

         UTL_HTTP.SET_HEADER(HTTP_REQ, 'User-Agent', 'Mozilla/4.0');
         HTTP_RESP := UTL_HTTP.GET_RESPONSE(HTTP_REQ);

         LOOP
           BEGIN
             URL_TEXT := null;
             UTL_HTTP.READ_LINE(HTTP_RESP, URL_TEXT, TRUE);
             --LC_ECODE := SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11,INSTR(SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11),'"')-1);
             LC_ECODE := URL_TEXT;
             IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
                IF LC_ECODE = 'OK' THEN
                   INSERT INTO ISR_TO_SMS_LOG
                         (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                          ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                          ISL_OI_TYPE)
                   VALUES(LC_OPD_REC.MSR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                          URL_TEXT,                 REPLACE(PHONE_NO,','),    'Y',                     ARG_DOC_NUM,
                          'O');
                   COMMIT;
                ELSE
                   INSERT INTO ISR_TO_SMS_LOG
                         (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                          ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                          ISL_OI_TYPE)
                   VALUES(LC_OPD_REC.MSR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                          URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     ARG_DOC_NUM,
                          'O');
                   COMMIT;
                END IF;
             END IF;
           EXCEPTION
             WHEN OTHERS THEN
                  EXIT;
           END;
         END LOOP;
         UTL_HTTP.END_RESPONSE(HTTP_RESP);
       EXCEPTION
         WHEN OTHERS THEN
              URL_TEXT := SQLCODE||' - '||SQLERRM;
              IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_OPD_REC.MSR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     ARG_DOC_NUM,
                        'O');
                 COMMIT;
              END IF;
       END;
    END IF;
  END;
