PROCEDURE SENT_SMS_OPD_CONSULTANT_SLIP(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2) AS
  LC_CON_REC  HOS_TM_OPD_CON_RCPT%ROWTYPE;
  HTTP_REQ    UTL_HTTP.REQ;
  HTTP_RESP   UTL_HTTP.RESP;
  URL_TEXT    VARCHAR2(32767);
  URL         VARCHAR2(2000);
  SMS_MSG     VARCHAR2(400);
  PHONE_NO    VARCHAR2(15);
  LC_ECODE    VARCHAR2(100);
  LC_FLAG     VARCHAR2(1);
  LC_MPT_NAME VARCHAR2(100);
  LC_MCT_NAME VARCHAR2(100);
  LC_LOG_FLAG VARCHAR2(100);
  LC_LOG      VARCHAR2(1);
BEGIN
   BEGIN
    SELECT *
    INTO   LC_CON_REC
    FROM   HOS_TM_OPD_CON_RCPT
    WHERE  MCR_CP_CODE = ARG_CP_CODE
    AND    MCR_NUM     = ARG_DOC_NUM;
  EXCEPTION
    WHEN OTHERS THEN
         LC_CON_REC := NULL;
  END;
 
 BEGIN
    SELECT MPT_NAME,REPLACE(MPT_MOBILE,'-')
    INTO   LC_MPT_NAME,PHONE_NO
    FROM   HOS_SM_PATIENT
    WHERE  MPT_CP_CODE = ARG_CP_CODE
    AND    MPT_ID      = LC_CON_REC.MCR_MPT_ID;
  EXCEPTION
    WHEN OTHERS THEN
         PHONE_NO := NULL;
  END;
 
  BEGIN
    SELECT MCT_NAME
    INTO   LC_MCT_NAME
    FROM   HOS_SM_CONSULTANT
    WHERE  MCT_CP_CODE = ARG_CP_CODE
    AND    MCT_CODE    = LC_CON_REC.MCR_MCT_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_MCT_NAME := NULL;
  END;
 
  LC_LOG_FLAG := GET_CONTROL_INFO('01','SMS_LOG_FLAG');
  LC_FLAG     := GET_TEMPLATE_INFO('01','OCS','FLAG');
  SMS_MSG     := GET_TEMPLATE_INFO('01','OCS','TEXT');
  LC_LOG      := GET_TEMPLATE_INFO('01','OCS','LOG_FLAG');
  SMS_MSG  := REPLACE(SMS_MSG,'#RECEIPT_DATE#',TO_CHAR(LC_CON_REC.MCR_DATE,'DD-MM-RRRR'));
  SMS_MSG  := REPLACE(SMS_MSG,'#RECEIPT_NO#',LC_CON_REC.MCR_NUM);
  SMS_MSG  := REPLACE(SMS_MSG,'#PATIENT#',LC_MPT_NAME);
  SMS_MSG  := REPLACE(SMS_MSG,'#TOKEN_NO#',LC_CON_REC.MCR_TOKEN_NBR);
  SMS_MSG  := REPLACE(SMS_MSG,'#AMOUNT#',LC_CON_REC.MCR_RCVD_AMT);
  SMS_MSG  := REPLACE(SMS_MSG,'#CONSULTANT#',LC_MCT_NAME);
 
  IF PHONE_NO IS NOT NULL AND LC_FLAG = 'Y' THEN

     BEGIN
       DBMS_OUTPUT.ENABLE(1000000);
       URL := 'http://bsms.telecard.com.pk/SMSportal/Customer/apikey.aspx?apikey=58fab9c8953f4553828f724a841496a8'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;
--dbms_output.put_line(URL);
       HTTP_REQ  := UTL_HTTP.BEGIN_REQUEST(URL);

       UTL_HTTP.SET_HEADER(HTTP_REQ, 'User-Agent', 'Mozilla/4.0');
       HTTP_RESP := UTL_HTTP.GET_RESPONSE(HTTP_REQ);

       LOOP
         BEGIN
           URL_TEXT := null;
           UTL_HTTP.READ_LINE(HTTP_RESP, URL_TEXT, TRUE);
           LC_ECODE := URL_TEXT;--SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11,INSTR(SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11),'"')-1);
           IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
              IF LC_ECODE = 'OK' THEN
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_CON_REC.MCR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'Y',                     LC_CON_REC.MCR_NUM,
                        'OPD');
                 COMMIT;
              ELSE
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_CON_REC.MCR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     LC_CON_REC.MCR_NUM,
                        'OPD');
                 COMMIT;
              END IF;
           END IF;
         EXCEPTION
           WHEN OTHERS THEN
                EXIT;
         END;
       END LOOP;
       UTL_HTTP.END_RESPONSE(HTTP_RESP);
     EXCEPTION
       WHEN OTHERS THEN
            URL_TEXT := SQLCODE||' - '||SQLERRM;
            IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
               INSERT INTO ISR_TO_SMS_LOG
                     (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                      ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                      ISL_OI_TYPE)
               VALUES(LC_CON_REC.MCR_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                      URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     LC_CON_REC.MCR_NUM,
                      'OPD');
               COMMIT;
            END IF;
     END;

  END IF;
 COMMIT;
END;

