PROCEDURE SENT_SMS_CONS_PAYMENT(ARG_CP_CODE   VARCHAR2,ARG_DOC_NUM VARCHAR2, ARG_TOT_SHARE VARCHAR2,
                                ARG_SHARE_RFD VARCHAR2,ARG_NET_SHARE VARCHAR2) AS
                                
  LC_SHR_REC  HOS_TO_CONS_PAYMENT%ROWTYPE;
  HTTP_REQ    UTL_HTTP.REQ;
  HTTP_RESP   UTL_HTTP.RESP;
  URL_TEXT    VARCHAR2(32767);
  URL         VARCHAR2(2000);
  SMS_MSG     VARCHAR2(400);
  PHONE_NO    VARCHAR2(15);
  LC_ECODE    VARCHAR2(100);
  LC_FLAG     VARCHAR2(1);
  LC_MCT_NAME VARCHAR2(100);
  LC_LOG_FLAG VARCHAR2(100);
  LC_LOG      VARCHAR2(1);
BEGIN
  
  BEGIN
    SELECT *
    INTO   LC_SHR_REC
    FROM   HOS_TO_CONS_PAYMENT
    WHERE  CPT_CP_CODE = ARG_CP_CODE
    AND    CPT_NUM     = ARG_DOC_NUM;
  EXCEPTION
    WHEN OTHERS THEN
         LC_SHR_REC := NULL;
  END;

  BEGIN
    SELECT MCT_NAME   , REPLACE(MCT_CONTACT_NOS,'-')
    INTO   LC_MCT_NAME, PHONE_NO
    FROM   HOS_SM_CONSULTANT
    WHERE  MCT_CP_CODE = ARG_CP_CODE
    AND    MCT_CODE    = LC_SHR_REC.CPT_MCT_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_MCT_NAME := NULL;
         PHONE_NO    := NULL;
  END;
  
  LC_LOG_FLAG := GET_CONTROL_INFO('01','SMS_LOG_FLAG');
  LC_FLAG     := GET_TEMPLATE_INFO('01','SHR','FLAG');
  SMS_MSG     := GET_TEMPLATE_INFO('01','SHR','TEXT');
  LC_LOG      := GET_TEMPLATE_INFO('01','SHR','LOG_FLAG');
  SMS_MSG  := REPLACE(SMS_MSG,'#TOT_SHARE#',ARG_TOT_SHARE);
  SMS_MSG  := REPLACE(SMS_MSG,'#REFUND#',ARG_SHARE_RFD);
  SMS_MSG  := REPLACE(SMS_MSG,'#NET_SHARE#',ARG_NET_SHARE);
  SMS_MSG  := REPLACE(SMS_MSG,'#DOCTOR#',LC_MCT_NAME);

  IF PHONE_NO IS NOT NULL AND LC_FLAG = 'Y' THEN
     BEGIN
       DBMS_OUTPUT.ENABLE(1000000);
       URL := 'http://bsms.telecard.com.pk/SMSportal/Customer/apikey.aspx?apikey=58fab9c8953f4553828f724a841496a8'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;
--dbms_output.put_line(URL);
       HTTP_REQ  := UTL_HTTP.BEGIN_REQUEST(URL);

       UTL_HTTP.SET_HEADER(HTTP_REQ, 'User-Agent', 'Mozilla/4.0');
       HTTP_RESP := UTL_HTTP.GET_RESPONSE(HTTP_REQ);

       LOOP
         BEGIN
           URL_TEXT := null;
           UTL_HTTP.READ_LINE(HTTP_RESP, URL_TEXT, TRUE);
           LC_ECODE := URL_TEXT;--SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11,INSTR(SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11),'"')-1);
           IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
              IF LC_ECODE = 'OK' THEN
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_SHR_REC.CPT_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'Y',                     LC_SHR_REC.CPT_NUM,
                        'OPD');
                 COMMIT;
              ELSE
                 INSERT INTO ISR_TO_SMS_LOG
                       (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                        ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                        ISL_OI_TYPE)
                 VALUES(LC_SHR_REC.CPT_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                        URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     LC_SHR_REC.CPT_NUM,
                        'OPD');
                 COMMIT;
              END IF;
           END IF;
         EXCEPTION
           WHEN OTHERS THEN
                EXIT;
         END;
       END LOOP;
       UTL_HTTP.END_RESPONSE(HTTP_RESP);
     EXCEPTION
       WHEN OTHERS THEN
            URL_TEXT := SQLCODE||' - '||SQLERRM;
            IF LC_LOG_FLAG = 'Y' AND LC_LOG = 'Y' THEN
               INSERT INTO ISR_TO_SMS_LOG
                     (ISL_USR_NAME,             ISL_DT_TIME,              ISL_TYPE,                ISL_MSG_TEXT,
                      ISL_REM,                  ISL_PHONE,                ISL_STATUS,              ISL_DOCUMENT_NUMBER,
                      ISL_OI_TYPE)
               VALUES(LC_SHR_REC.CPT_INS_USER,  SYSDATE,                  NULL,                    SMS_MSG,
                      URL_TEXT,                 REPLACE(PHONE_NO,','),    'N',                     LC_SHR_REC.CPT_NUM,
                      'OPD');
               COMMIT;
            END IF;
     END;

  END IF;
  COMMIT;
END;

 --=====================================================================================================================
PROCEDURE RESENT_UNSENT_SMS(ARG_TYPE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_PHONE VARCHAR2) AS
    HTTP_REQ    UTL_HTTP.REQ;
    HTTP_RESP   UTL_HTTP.RESP;
    URL_TEXT    VARCHAR2(32767);
    URL         VARCHAR2(2000);
    SMS_MSG     VARCHAR2(400);
    PHONE_NO    VARCHAR2(15);
    LC_ECODE    VARCHAR2(100);
  CURSOR C1 IS
         SELECT *
         FROM   ISR_TO_SMS_LOG
         WHERE  ISL_TYPE            = ARG_TYPE
         AND    ISL_DOCUMENT_NUMBER = NVL(ARG_DOC_NUM,ISL_DOCUMENT_NUMBER)
         AND    ISL_PHONE           = NVL(ARG_PHONE,ISL_PHONE)
         AND    ISL_STATUS          = 'N';
BEGIN
  FOR A IN C1 LOOP
      PHONE_NO  := A.ISL_PHONE;
      BEGIN
        SMS_MSG  := A.ISL_MSG_TEXT;
        DBMS_OUTPUT.ENABLE(1000000);
        URL := 'http://bsms.telecard.com.pk/SMSPortal/Customer/ProcessSMS.aspx?userid=testalkkhi'||CHR(38)||'pwd=testalkkhi123'||CHR(38)||'msg='||UTL_URL.Escape(SMS_MSG,TRUE)||CHR(38)||'mobileno='||PHONE_NO;

        HTTP_REQ  := UTL_HTTP.BEGIN_REQUEST(URL);

        UTL_HTTP.SET_HEADER(HTTP_REQ, 'User-Agent', 'Mozilla/4.0');
        HTTP_RESP := UTL_HTTP.GET_RESPONSE(HTTP_REQ);

        LOOP
          BEGIN
            URL_TEXT := null;
            UTL_HTTP.READ_LINE(HTTP_RESP, URL_TEXT, TRUE);
            LC_ECODE := SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11,INSTR(SUBSTR(URL_TEXT,INSTR(URL_TEXT,'"errorno":"')+11),'"')-1);
            IF LC_ECODE = 'OK' THEN
               UPDATE ISR_TO_SMS_LOG
               SET    ISL_STATUS          = 'Y',
                      ISL_RESEND_CNT      = NVL(ISL_RESEND_CNT,0) + 1,
                      ISL_DT_TIME         = SYSDATE,
                      ISL_REM             = NULL
               WHERE  ISL_TYPE            = A.ISL_TYPE
               AND    ISL_DOCUMENT_NUMBER = A.ISL_DOCUMENT_NUMBER
               AND    ISL_PHONE           = A.ISL_PHONE
               AND    ISL_STATUS          = A.ISL_STATUS;
               COMMIT;
            ELSE
               UPDATE ISR_TO_SMS_LOG
               SET    ISL_STATUS          = 'N',
                      ISL_RESEND_CNT      = NVL(ISL_RESEND_CNT,0) + 1,
                      ISL_DT_TIME         = SYSDATE,
                      ISL_REM             = URL_TEXT
               WHERE  ISL_TYPE            = A.ISL_TYPE
               AND    ISL_DOCUMENT_NUMBER = A.ISL_DOCUMENT_NUMBER
               AND    ISL_PHONE           = A.ISL_PHONE
               AND    ISL_STATUS          = A.ISL_STATUS;
               COMMIT;
            END IF;
          EXCEPTION
            WHEN OTHERS THEN
                 EXIT;
          END;
        END LOOP;
        UTL_HTTP.END_RESPONSE(HTTP_RESP);
      EXCEPTION
        WHEN OTHERS THEN
             URL_TEXT := SQLERRM;
             UPDATE ISR_TO_SMS_LOG
             SET    ISL_STATUS          = 'N',
                    ISL_RESEND_CNT      = NVL(ISL_RESEND_CNT,0) + 1,
                    ISL_DT_TIME         = SYSDATE,
                    ISL_REM             = URL_TEXT
             WHERE  ISL_TYPE            = A.ISL_TYPE
             AND    ISL_DOCUMENT_NUMBER = A.ISL_DOCUMENT_NUMBER
             AND    ISL_PHONE           = A.ISL_PHONE
             AND    ISL_STATUS          = A.ISL_STATUS;
             COMMIT;
      END;
  END LOOP;
END;
 --=====================================================================================================================
PROCEDURE CANCEL_SMS(ARG_TYPE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_PHONE VARCHAR2) AS
  LC_CNT_REC  ISR_XO_CONTROL%ROWTYPE;
BEGIN
  SELECT *
  INTO   LC_CNT_REC
  FROM   ISR_XO_CONTROL
  WHERE  ISR_CP_CODE = '01';
  IF ARG_TYPE = 'CA' THEN
     UPDATE ISR_TO_SMS_LOG
     SET    ISL_STATUS  = 'C'
     WHERE  ISL_TYPE    = 'CA'
     AND    ISL_STATUS  = 'N'
     AND    ISL_DOCUMENT_NUMBER = NVL(ARG_DOC_NUM,ISL_DOCUMENT_NUMBER)
     AND    ISL_PHONE   = NVL(ARG_PHONE,ISL_PHONE)
     AND    SYSDATE NOT BETWEEN ISL_INS_DATE AND ISL_INS_DATE + LC_CNT_REC.ISR_SMS_ADD_EXP_DAYS;
     COMMIT;
  END IF;
END;
--=====================================================================================================================
PROCEDURE DELETE_SMS(ARG_TYPE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_PHONE VARCHAR2) AS
  LC_CNT_REC  ISR_XO_CONTROL%ROWTYPE;
BEGIN
  SELECT *
  INTO   LC_CNT_REC
  FROM   ISR_XO_CONTROL
  WHERE  ISR_CP_CODE = '01';
  IF ARG_TYPE = 'CA' THEN
     UPDATE ISR_TO_SMS_LOG
     SET    ISL_STATUS  = '-'
     WHERE  ISL_TYPE    = 'CA'
     AND    ISL_STATUS  = 'N'
     AND    ISL_DOCUMENT_NUMBER = NVL(ARG_DOC_NUM,ISL_DOCUMENT_NUMBER)
     AND    ISL_PHONE   = NVL(ARG_PHONE,ISL_PHONE)
     AND    SYSDATE NOT BETWEEN ISL_INS_DATE AND ISL_INS_DATE + LC_CNT_REC.ISR_SMS_ADD_DEL_DAYS;
     COMMIT;
  END IF;
END;
--=====================================================================================================================
PROCEDURE OTP_GENERATE(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_PHONE VARCHAR2,ARG_USR_NAME VARCHAR2,ARG_DATE DATE DEFAULT SYSDATE,ARG_EXP_DATE DATE DEFAULT NULL) AS 
  LC_OTP VARCHAR2(5) := ROUND(DBMS_RANDOM.VALUE(10000, 99999));
BEGIN
  INSERT INTO ISR_TO_OTP
        (OTP_CP_CODE,            OTP_DOC_NUM,             OTP_CODE,             OTP_DATE,             OTP_EXP_DATE, 
         OTP_USR_NAME,           OTP_PHONE,               OTP_FLAG)
  VALUES(ARG_CP_CODE,            ARG_DOC_NUM,             LC_OTP,               NVL(ARG_DATE,SYSDATE), NVL(ARG_EXP_DATE,TO_DATE(TO_CHAR((SYSDATE + (5 / (24 * 60))),'DD-MON-YYYY HH24:MI:SS'),'DD/MM/YYYY HH24:MI:SS')), 
         ARG_USR_NAME,           ARG_PHONE,               'N');
  SENT_SMS_OTP(ARG_CP_CODE,ARG_DOC_NUM,LC_OTP);
  COMMIT;
END;
--=====================================================================================================================
FUNCTION OTP_VALIDATION(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_OTP VARCHAR2) RETURN VARCHAR2 IS
  LC_VAL VARCHAR2(1);
  LC_CNT NUMBER;
BEGIN
  BEGIN
    SELECT 1
    INTO   LC_CNT
    FROM   ISR_TO_OTP
    WHERE  OTP_CP_CODE = ARG_CP_CODE
    AND    OTP_DOC_NUM = ARG_DOC_NUM
    AND    OTP_CODE    = ARG_OTP
    AND    OTP_FLAG    = 'N'
    AND    SYSDATE BETWEEN OTP_DATE AND OTP_EXP_DATE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_CNT := 0;
  END;
  IF LC_CNT > 0 THEN
     LC_VAL := 'Y';
  ELSE
     LC_VAL := 'N';
  END IF;
  RETURN LC_VAL;
END;
--=====================================================================================================================
PROCEDURE OTP_EXPIRE(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_OTP VARCHAR2) AS
  LC_VAL VARCHAR2(1);
  LC_CNT NUMBER;
BEGIN
  BEGIN
    SELECT 1
    INTO   LC_CNT
    FROM   ISR_TO_OTP
    WHERE  OTP_CP_CODE = ARG_CP_CODE
    AND    OTP_DOC_NUM = ARG_DOC_NUM
    AND    OTP_CODE    = ARG_OTP
    AND    OTP_FLAG    = 'N'
    AND    SYSDATE BETWEEN OTP_DATE AND OTP_EXP_DATE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_CNT := 0;
  END;
  IF LC_CNT > 0 THEN
     UPDATE ISR_TO_OTP
     SET    OTP_FLAG    = 'Y'
     WHERE  OTP_CP_CODE = ARG_CP_CODE
     AND    OTP_DOC_NUM = ARG_DOC_NUM
     AND    OTP_CODE    = ARG_OTP
     AND    OTP_FLAG    = 'N'
     AND    SYSDATE BETWEEN OTP_DATE AND OTP_EXP_DATE;
  END IF;
END;
--=====================================================================================================================
PROCEDURE SENT_SMS_OTP(ARG_CP_CODE VARCHAR2,ARG_DOC_NUM VARCHAR2,ARG_OTP_CODE VARCHAR2) AS
  LC_OTP_REC  ISR_TO_OTP%ROWTYPE;
  HTTP_REQ    UTL_HTTP.REQ;
  HTTP_RESP   UTL_HTTP.RESP;
  URL_TEXT    VARCHAR2(32767);
  URL         VARCHAR2(2000);
  SMS_MSG     VARCHAR2(400);
  PHONE_NO    VARCHAR2(15);
  LC_ECODE    VARCHAR2(100);
  LC_FLAG     VARCHAR2(1);
  LC_LOG_FLAG VARCHAR2(100);
  LC_LOG      VARCHAR2(1);
BEGIN
  BEGIN
    SELECT *
    INTO   LC_OTP_REC
    FROM   ISR_TO_OTP
    WHERE  OTP_CP_CODE = ARG_CP_CODE
    AND    OTP_DOC_NUM = ARG_DOC_NUM
    AND    OTP_CODE    = ARG_OTP_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         LC_OTP_REC := NULL;
  END;
  PHONE_NO    := LC_OTP_REC.OTP_PHONE;
  LC_LOG_FLAG := GET_CONTROL_INFO('01','SMS_LOG_FLAG');
