prompt
prompt Creating trigger HOS_TM_OPD_SRV_RCPT_BUD
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.HOS_TM_OPD_SRV_RCPT_BUD
BEFORE UPDATE OR DELETE ON HOS_TM_OPD_SRV_RCPT FOR EACH ROW
DECLARE
  LC_CNT_PQ NUMBER;
  LC_CNT    NUMBER;
BEGIN
  IF UPDATING THEN
     IF :NEW.MSR_PRG_CODE = 'HOSAS26' AND :NEW.MSR_PST_FLAG = 'P' AND :NEW.MSR_PASS IS NOT NULL THEN
        SELECT COUNT(DISTINCT TSR_DSC_CODE)
        INTO   LC_CNT_PQ
        FROM   HOS_TO_OPD_SRV_RCPT_PQ
        WHERE  TSR_CP_CODE = :NEW.MSR_CP_CODE
        AND    TSR_MSR_NUM = :NEW.MSR_NUM;
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   HOS_TD_OPD_SRV_RCPT
        WHERE  DSR_CP_CODE = :NEW.MSR_CP_CODE
        AND    DSR_MSR_NUM = :NEW.MSR_NUM;
        IF LC_CNT > LC_CNT_PQ THEN
           INSERT INTO HOS_TO_OPD_SRV_RCPT_PQ
                 (TSR_CP_CODE,          TSR_MSR_DATE,        TSR_MSR_NUM,         TSR_BR_CODE,         TSR_PAT_ID,
                  TSR_NAME,             TSR_PRG_CODE,        TSR_PRG_DESC,        TSR_DSC_CODE,        TSR_DSC_DESC,
                  TSR_DLV_DATE,         TSR_DLV_TIME,        TSR_ACTION,          TSR_PASS,            TSR_PHONE)
           SELECT :NEW.MSR_CP_CODE,     :NEW.MSR_DATE,       :NEW.MSR_NUM,        :NEW.MSR_BR_CODE,    :NEW.MSR_PAT_ID,
                  :NEW.MSR_NAME,        :NEW.MSR_PRG_CODE,   :NEW.MSR_PRG_DESC,   DSR_DSC_CODE,       (SELECT DSC_DESC FROM HOS_SD_SRV_CHARGES WHERE DSC_CP_CODE = DSR_CP_CODE AND DSC_CODE = DSR_DSC_CODE),
                  DSR_DLV_DATE,         DSR_DLV_TIME,        'U',                 :NEW.MSR_PASS,       :NEW.MSR_PHONE
           FROM   HOS_TD_OPD_SRV_RCPT
           WHERE  DSR_CP_CODE = :NEW.MSR_CP_CODE
           AND    DSR_MSR_NUM = :NEW.MSR_NUM;
        END IF;
     END IF;
  ELSIF DELETING THEN
     IF :OLD.MSR_PRG_CODE = 'HOSAS26' AND NVL(:OLD.MSR_PST_FLAG,'U') = 'P' THEN
        INSERT INTO HOS_TO_OPD_SRV_RCPT_PQ
              (TSR_CP_CODE,          TSR_MSR_DATE,        TSR_MSR_NUM,         TSR_BR_CODE,         TSR_PAT_ID,
               TSR_NAME,             TSR_PRG_CODE,        TSR_PRG_DESC,        TSR_ACTION,          TSR_PASS,
               TSR_PHONE)
        VALUES(:OLD.MSR_CP_CODE,     :OLD.MSR_DATE,       :OLD.MSR_NUM,        :OLD.MSR_BR_CODE,    :OLD.MSR_PAT_ID,
               :OLD.MSR_NAME,        :OLD.MSR_PRG_CODE,   :OLD.MSR_PRG_DESC,   'D',                 :OLD.MSR_PASS,
               :OLD.MSR_PHONE);
     END IF;
  END IF;
END;
/

prompt
prompt Creating trigger LAB_TD_SRV_DIAG_AU
prompt ===================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.LAB_TD_SRV_DIAG_AU
AFTER UPDATE ON LAB_TD_SRV_DIAG FOR EACH ROW
DECLARE
  LC_MDG_REC     LAB_TM_DIAGNOSIS%ROWTYPE;
  LC_FILE_NAME   VARCHAR2(100);
  LC_RPT_PQ_FLAG VARCHAR2(1);
BEGIN
  BEGIN
    SELECT NVL(ISR_LAB_RPT_PQ_FLAG,'Y')
    INTO   LC_RPT_PQ_FLAG
    FROM   ISR_XO_CONTROL;
  EXCEPTION
    WHEN OTHERS THEN
         LC_RPT_PQ_FLAG := 'Y';
  END;
  IF LC_RPT_PQ_FLAG = 'N' AND :NEW.DSD_DSC_CODE = 'VIRO0001' THEN
     SELECT *
     INTO   LC_MDG_REC
     FROM   LAB_TM_DIAGNOSIS
     WHERE  MDG_CP_CODE = :NEW.DSD_CP_CODE
     AND    MDG_RCT_NUM = :NEW.DSD_RCT_NUM
     AND    MDG_RPT_ID  = :NEW.DSD_RPT_ID;
     IF LC_MDG_REC.MDG_TYPE = 'OPD' AND :NEW.DSD_STATUS = 'C' THEN
        LC_FILE_NAME := LC_MDG_REC.MDG_PAT_ID||'_'||LC_MDG_REC.MDG_RPT_ID||'_'||:NEW.DSD_DSC_CODE||'_'||TO_CHAR(:NEW.DSD_FNL_DATE,'DDMMRRRR')||'_'||REPLACE(:NEW.DSD_FNL_TIME,':')||'.pdf';
        OLR_PKG.UPLOAD_OL_LAB_REPORTS(:NEW.DSD_CP_CODE,:NEW.DSD_RPT_ID,:NEW.DSD_DSC_CODE,LC_FILE_NAME);
     END IF;
  END IF;
END;
/

prompt
prompt Creating trigger LAB_TD_SRV_DIAG_BU
prompt ===================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.LAB_TD_SRV_DIAG_BU
BEFORE UPDATE ON LAB_TD_SRV_DIAG FOR EACH ROW
DECLARE
  LC_CNT       NUMBER;
  LC_ID        VARCHAR2(30);
  LC_LAB_URL   VARCHAR2(4000);
  LC_QR_STRING VARCHAR2(4000);
  LC_SPC_DTL   VARCHAR2(4000);
  LC_MDG_REC   LAB_TM_DIAGNOSIS%ROWTYPE;
  LC_MPT_REC   HOS_SM_PATIENT%ROWTYPE;
  LC_SCH_REC   HOS_SD_SRV_CHARGES%ROWTYPE;
  LC_DSR_REC   HOS_TD_OPD_SRV_RCPT%ROWTYPE;
  LC_MSR_REC   HOS_TM_OPD_SRV_RCPT%ROWTYPE;
  LC_PASS      VARCHAR2(100);
  LC_DIS_REC   LAB_TD_IPD_SRVS%ROWTYPE;
  LC_MIS_REC   LAB_TM_IPD_SRVS%ROWTYPE;
  LC_DSC_CODE  VARCHAR2(4000);
 -- LC_MCT_REC   HOS_SM_CONSULTANT%ROWTYPE;
  LC_FILE_NAME VARCHAR2(100);
  LC_MIME_TYPE VARCHAR2(50);
  LC_ERROR     VARCHAR2(1000);
  LC_DIRECTORY VARCHAR2(100);
  LC_RPT_PQ_FLAG VARCHAR2(1);
BEGIN
  BEGIN
    SELECT ISR_LAB_RPT_DIR,NVL(ISR_LAB_RPT_PQ_FLAG,'Y'),ISR_LAB_URL,ISR_OL_DSC_CODE
    INTO   LC_DIRECTORY,LC_RPT_PQ_FLAG,LC_LAB_URL,LC_DSC_CODE
    FROM   ISR_XO_CONTROL
    WHERE  ISR_CP_CODE = :NEW.DSD_CP_CODE;
  EXCEPTION
    WHEN OTHERS THEN
         OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Directory not define. '||SQLERRM);
         LC_DIRECTORY   := NULL;
         LC_RPT_PQ_FLAG := 'Y';
  END;
  BEGIN
    SELECT *
    INTO   LC_MDG_REC
    FROM   LAB_TM_DIAGNOSIS
    WHERE  MDG_CP_CODE = :NEW.DSD_CP_CODE
    AND    MDG_RCT_NUM = :NEW.DSD_RCT_NUM
    AND    MDG_RPT_ID  = :NEW.DSD_RPT_ID;
  EXCEPTION
    WHEN OTHERS THEN
         OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing diagnosis. ('||:NEW.DSD_RPT_ID||' - '||:NEW.DSD_RCT_NUM||') '||SQLERRM);
  END;
 -- RAISE_APPLICATION_ERROR(-20001,'ABCD');
  IF LC_MDG_REC.MDG_TYPE IN ('OPD','IPD') /*AND LC_MDG_REC.MDG_PAT_ID IS NOT NULL */AND :NEW.DSD_STATUS = 'C' AND :NEW.DSD_STATUS <> :OLD.DSD_STATUS AND INSTR(':'||NVL(LC_DSC_CODE,:NEW.DSD_DSC_CODE)||':',':'||:NEW.DSD_DSC_CODE||':') > 0 THEN
--RAISE_APPLICATION_ERROR(-20001,'ABCD');
     :NEW.DSD_FNL_USER := NVL(:NEW.DSD_FNL_USER,:NEW.DSD_UPD_USER);
     :NEW.DSD_FNL_DATE := nvl(:NEW.DSD_FNL_DATE,TO_DATE(SYSDATE));
     :NEW.DSD_FNL_TIME := nvl(:NEW.DSD_FNL_TIME,TO_CHAR(SYSDATE, 'HH24:MI:SS'));
     SELECT COUNT(*)
     INTO   LC_CNT
     FROM   HOS_TD_OPD_SRV_RCPT
     WHERE  DSR_CP_CODE  = LC_MDG_REC.MDG_CP_CODE
     AND    DSR_MSR_NUM  = LC_MDG_REC.MDG_RCT_NUM
     AND    DSR_MSC_TYPE = 'LT'
     AND    DSR_DSC_CODE = :NEW.DSD_DSC_CODE
     AND    LC_MDG_REC.MDG_TYPE = 'OPD';
     SELECT LC_CNT + COUNT(*)
     INTO   LC_CNT
     FROM   LAB_TD_IPD_SRVS
     WHERE  DIS_CP_CODE  = LC_MDG_REC.MDG_CP_CODE
     AND    DIS_SPC_NUM  = LC_MDG_REC.MDG_RCT_NUM
     AND    DIS_DSC_CODE = :NEW.DSD_DSC_CODE
     AND    LC_MDG_REC.MDG_TYPE = 'IPD';
     -- RAISE_APPLICATION_eRror(-20001,LC_CNT);
     IF LC_CNT > 0  THEN
        BEGIN
          SELECT *
          INTO   LC_MPT_REC
          FROM   HOS_SM_PATIENT
          WHERE  MPT_CP_CODE = LC_MDG_REC.MDG_CP_CODE
          AND    MPT_ID      = LC_MDG_REC.MDG_PAT_ID;
        EXCEPTION
          WHEN OTHERS THEN
               LC_MPT_REC := NULL;
        END;
        LC_ID        := TO_CHAR(SYSTIMESTAMP,'RRMMDDHH24MISSFF2')||DBMS_RANDOM.STRING('x',4);
        :NEW.DSD_ID  := LC_ID;
        BEGIN
          SELECT 'Collection Date: '||TO_CHAR(DSC_INS_DATE,'DD-MON-RRRR')||' at '||SUBSTR(DSC_INS_TIME,1,5)
          INTO   LC_SPC_DTL
          FROM   LAB_TD_SMN_COLL
          WHERE  DSC_CP_CODE  = :NEW.DSD_CP_CODE
          AND    DSC_SPC_NUM  = :NEW.DSD_SPC_NUM
          AND    DSC_DOC_NUM  = :NEW.DSD_RCT_NUM
          AND    DSC_DSC_CODE = :NEW.DSD_DSC_CODE
          AND    :NEW.DSD_DSC_CODE = 'VIRO0001';
        EXCEPTION
          WHEN OTHERS THEN
               LC_SPC_DTL := NULL;
        END;
        IF LC_SPC_DTL IS NULL THEN
           LC_QR_STRING :=
           'Patient:'||UPPER(LC_MDG_REC.MDG_PAT_NAME)||CHR(10)||
           'Passport #:'||NVL(LC_MPT_REC.MPT_PASSPORT_NO,' ')||CHR(10)||
           'Date of Test:'||TO_CHAR(LC_MDG_REC.MDG_DOC_DATE,'DD-MON-RRRR')||CHR(10)||
           LC_LAB_URL||LC_ID
           ;
        ELSE
           LC_QR_STRING :=
           'Patient:'||UPPER(LC_MDG_REC.MDG_PAT_NAME)||CHR(10)||
           'Passport #:'||NVL(LC_MPT_REC.MPT_PASSPORT_NO,' ')||CHR(10)||
           LC_SPC_DTL||CHR(10)||
           'Report Date:'||TO_CHAR(LC_MDG_REC.MDG_RPT_DATE,'DD-MON-RRRR')||' at '||SUBSTR(LC_MDG_REC.MDG_INS_TIME,1,5)||CHR(10)||
           LC_LAB_URL||LC_ID
           ;
        END IF;
        :NEW.DSD_QR_BLOB := GENERATE_QR.QR_BIN(LC_QR_STRING);
        -----
        IF LC_MDG_REC.MDG_TYPE = 'OPD' THEN 
           BEGIN
             SELECT *
             INTO   LC_MSR_REC
             FROM   HOS_TM_OPD_SRV_RCPT
             WHERE  MSR_CP_CODE = LC_MDG_REC.MDG_CP_CODE
             AND    MSR_NUM     = LC_MDG_REC.MDG_RCT_NUM;
           EXCEPTION
             WHEN OTHERS THEN
                  OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing services receipt. '||SQLERRM);
           END;
           BEGIN
             SELECT *
             INTO   LC_DSR_REC
             FROM   HOS_TD_OPD_SRV_RCPT
             WHERE  DSR_CP_CODE  = LC_MDG_REC.MDG_CP_CODE
             AND    DSR_MSR_NUM  = LC_MDG_REC.MDG_RCT_NUM
             AND    DSR_DSC_CODE = :NEW.DSD_DSC_CODE;
           EXCEPTION
             WHEN OTHERS THEN
                  OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing services receipt detail. '||SQLERRM);
           END;
        ELSIF LC_MDG_REC.MDG_TYPE = 'IPD' THEN 
          
           BEGIN
             SELECT *
             INTO   LC_MIS_REC
             FROM   LAB_TM_IPD_SRVS
             WHERE  MIS_CP_CODE = LC_MDG_REC.MDG_CP_CODE
             AND    MIS_SPC_NUM = LC_MDG_REC.MDG_RCT_NUM;
           EXCEPTION
             WHEN OTHERS THEN
                  OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing services receipt. '||SQLERRM);
           END;
           BEGIN
             SELECT *
             INTO   LC_DIS_REC
             FROM   LAB_TD_IPD_SRVS
             WHERE  DIS_CP_CODE  = LC_MDG_REC.MDG_CP_CODE
             AND    DIS_SPC_NUM  = LC_MDG_REC.MDG_RCT_NUM
             AND    DIS_DSC_CODE = :NEW.DSD_DSC_CODE;
           EXCEPTION
             WHEN OTHERS THEN
                  OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing services receipt detail. '||SQLERRM);
           END;
           BEGIN
             SELECT MPF_PASS
             INTO   LC_PASS
             FROM   HOS_TM_PATIENT_FILE
             WHERE  MPF_CP_CODE   = LC_MDG_REC.MDG_CP_CODE
             AND    MPF_FILE_NUM  = LC_MDG_REC.MDG_COL_NUM;
           EXCEPTION
             WHEN OTHERS THEN
                  OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in initializing services receipt detail. '||SQLERRM);
           END;
          
        END IF;
        SELECT *
        INTO   LC_SCH_REC
        FROM   HOS_SD_SRV_CHARGES
        WHERE  DSC_CP_CODE = LC_MDG_REC.MDG_CP_CODE
        AND    DSC_CODE    = :NEW.DSD_DSC_CODE;
        --============================================
        -- Diagnosis Reporting
        --============================================
        LC_FILE_NAME := LC_MDG_REC.MDG_PAT_ID||'_'||LC_MDG_REC.MDG_RPT_ID||'_'||:NEW.DSD_DSC_CODE||'_'||TO_CHAR(:NEW.DSD_FNL_DATE,'DDMMRRRR')||'_'||REPLACE(:NEW.DSD_FNL_TIME,':')||'.pdf';
        LC_MIME_TYPE := 'application/pdf';
         
        IF LC_RPT_PQ_FLAG = 'N' THEN
        IF LC_MDG_REC.MDG_TYPE = 'OPD' THEN 
        BEGIN
          INSERT INTO LAB_TO_OL_REPORTING_OLVW--LAB_TO_OL_REPORTING@ISROLSHT
                (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                 TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                 TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                 TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                 TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                 TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                 TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                 TOR_RESULT,                   TOR_BR_CODE,                   TOR_PASS,
                 TOR_ID)
          VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                 LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                 LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                 LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                 :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                 :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                 TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MSR_REC.MSR_PRG_CODE,       LC_MSR_REC.MSR_PRG_DESC,         LC_DSR_REC.DSR_MSC_TYPE,
                 :NEW.DSD_RESULT,              LC_MSR_REC.MSR_BR_CODE,        LC_MSR_REC.MSR_PASS,
                 LC_ID);
        EXCEPTION
          WHEN OTHERS THEN
               LC_ERROR := SQLERRM;
               OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in lab reporting inserting. ('||REPLACE(REPLACE(LC_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
               INSERT INTO LAB_TO_OL_REPORTING_PQ--Pending Queue
                     (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                      TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                      TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                      TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                      TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                      TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                      TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                      TOR_ERROR,                    TOR_RESULT,                    TOR_BR_CODE,                     TOR_PASS,
                      TOR_ID)
               VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                      LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                      LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                      LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                      :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                      :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                      TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MSR_REC.MSR_PRG_CODE,       LC_MSR_REC.MSR_PRG_DESC,         LC_DSR_REC.DSR_MSC_TYPE,
                      LC_ERROR,                     :NEW.DSD_RESULT,               LC_MSR_REC.MSR_BR_CODE,          LC_MSR_REC.MSR_PASS,
                      LC_ID);
         END;
         ELSIF LC_MDG_REC.MDG_TYPE = 'IPD' THEN 
        BEGIN
          INSERT INTO LAB_TO_OL_REPORTING_OLVW--LAB_TO_OL_REPORTING@ISROLSHT
                (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                 TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                 TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                 TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                 TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                 TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                 TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                 TOR_RESULT,                   TOR_BR_CODE,                   TOR_PASS,
                 TOR_ID)
          VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                 LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                 LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                 LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                 :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                 :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                 TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MIS_REC.MIS_PRG_CODE,       LC_MIS_REC.MIS_PRG_DESC,         'LT',
                 :NEW.DSD_RESULT,              LC_MIS_REC.MIS_BR_CODE,        LC_PASS,
                 LC_ID);
        EXCEPTION
          WHEN OTHERS THEN
               LC_ERROR := SQLERRM;
               OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in lab reporting inserting. ('||REPLACE(REPLACE(LC_FILE_NAME,'_','-'),'.pdf')||') '||SQLERRM);
               INSERT INTO LAB_TO_OL_REPORTING_PQ--Pending Queue
                     (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                      TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                      TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                      TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                      TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                      TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                      TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                      TOR_ERROR,                    TOR_RESULT,                    TOR_BR_CODE,                     TOR_PASS,
                      TOR_ID)
               VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                      LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                      LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                      LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                      :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                      :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                      TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MIS_REC.MIS_PRG_CODE,       LC_MIS_REC.MIS_PRG_DESC,         'LT',
                      LC_ERROR,                     :NEW.DSD_RESULT,               LC_MIS_REC.MIS_BR_CODE,          LC_PASS,
                      LC_ID);
         END;
         END IF;
         ELSE
            IF LC_MDG_REC.MDG_TYPE = 'OPD' THEN 
            INSERT INTO LAB_TO_OL_REPORTING_PQ--Pending Queue
                  (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                   TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                   TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                   TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                   TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                   TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                   TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                   TOR_ERROR,                    TOR_RESULT,                    TOR_BR_CODE,                     TOR_PASS,
                   TOR_ID)
            VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                   LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                   LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                   LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                   :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                   :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                   TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MSR_REC.MSR_PRG_CODE,       LC_MSR_REC.MSR_PRG_DESC,         LC_DSR_REC.DSR_MSC_TYPE,
                   LC_ERROR,                     :NEW.DSD_RESULT,               LC_MSR_REC.MSR_BR_CODE,          LC_MSR_REC.MSR_PASS,
                   LC_ID);
            ELSIF LC_MDG_REC.MDG_TYPE = 'IPD' THEN 
              --RAISE_APPLICATION_eRror(-20001,'c');
              --RAISE_APPLICATION_ERROR(-20001,'ABCD');
             INSERT INTO LAB_TO_OL_REPORTING_PQ--Pending Queue
                  (TOR_CP_CODE,                  TOR_RPT_ID,                    TOR_RPT_DATE,                    TOR_RCT_NUM,
                   TOR_PAT_ID,                   TOR_PAT_NAME,                  TOR_PAT_AGE,                     TOR_AGE_TYPE,
                   TOR_PAT_GND,                  TOR_MCT_CODE,                  TOR_MCT_NAME,                    TOR_TYPE,
                   TOR_COL_NUM,                  TOR_SPC_NUM,                   TOR_DSC_CODE,                    TOR_DSC_DESC,
                   TOR_DLV_DATE,                 TOR_DLV_TIME,                  TOR_FNL_USER,                    TOR_FNL_DATE,
                   TOR_FNL_TIME,                 TOR_FILE_NAME,                 TOR_MIME_TYPE,                   TOR_DATE,
                   TOR_TIME,                     TOR_PRG_CODE,                  TOR_PRG_DESC,                    TOR_MSC_TYPE,
                   TOR_ERROR,                    TOR_RESULT,                    TOR_BR_CODE,                     TOR_PASS,
                   TOR_ID)
            VALUES(LC_MDG_REC.MDG_CP_CODE,       LC_MDG_REC.MDG_RPT_ID,         LC_MDG_REC.MDG_RPT_DATE,         LC_MDG_REC.MDG_RCT_NUM,
                   LC_MDG_REC.MDG_PAT_ID,        LC_MDG_REC.MDG_PAT_NAME,       LC_MDG_REC.MDG_PAT_AGE,          LC_MDG_REC.MDG_AGE_TYPE,
                   LC_MDG_REC.MDG_PAT_GND,       LC_MDG_REC.MDG_MCT_CODE,       LC_MDG_REC.MDG_MCT_NAME,         LC_MDG_REC.MDG_TYPE,
                   LC_MDG_REC.MDG_COL_NUM,       :NEW.DSD_SPC_NUM,              :NEW.DSD_DSC_CODE,               LC_SCH_REC.DSC_DESC,
                   :NEW.DSD_DLV_DATE,            :NEW.DSD_DLV_TIME,             :NEW.DSD_FNL_USER,               :NEW.DSD_FNL_DATE,
                   :NEW.DSD_FNL_TIME,            LC_FILE_NAME,                  LC_MIME_TYPE,                    TO_DATE(SYSDATE,'DD-MON-RRRR'),
                   TO_CHAR(SYSDATE,'HH24:MI:SS'),LC_MIS_REC.MIS_PRG_CODE,       LC_MIS_REC.MIS_PRG_DESC,         'LT',
                   LC_ERROR,                     :NEW.DSD_RESULT,               LC_MIS_REC.MIS_BR_CODE,          LC_PASS,
                   LC_ID);
             END IF;
         END IF; --*/--remk16-10-2023
     END IF;
  END IF;
EXCEPTION
  WHEN OTHERS THEN
       OLR_PKG.ERROR_LOG(LC_DIRECTORY,TO_CHAR(SYSDATE,'DD-MON-RRRR HH24:MI:SS')||' Error in before update trigger. '||SQLERRM);
       RAISE_APPLICATION_ERROR(-20001,SQLERRM);
END;
