prompt
prompt Creating trigger LAB_TM_IPD_SRVS_BUD
prompt ====================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.LAB_TM_IPD_SRVS_BUD
BEFORE UPDATE OR DELETE ON LAB_TM_IPD_SRVS FOR EACH ROW
DECLARE
  LC_CNT_PQ NUMBER;
  LC_CNT    NUMBER;
BEGIN
  IF UPDATING THEN
     IF :NEW.MIS_PRG_CODE = 'HOSAS26' AND :NEW.MIS_PST_FLAG = 'P' THEN
        SELECT COUNT(DISTINCT TSR_DSC_CODE)
        INTO   LC_CNT_PQ
        FROM   HOS_TO_OPD_SRV_RCPT_PQ
        WHERE  TSR_CP_CODE = :NEW.MIS_CP_CODE
        AND    TSR_MSR_NUM = :NEW.MIS_SPC_NUM;
        SELECT COUNT(*)
        INTO   LC_CNT
        FROM   LAB_TD_IPD_SRVS
        WHERE  DIS_CP_CODE = :NEW.MIS_CP_CODE
        AND    DIS_SPC_NUM = :NEW.MIS_SPC_NUM;
        IF LC_CNT > LC_CNT_PQ THEN
           INSERT INTO HOS_TO_OPD_SRV_RCPT_PQ
                 (TSR_CP_CODE,          TSR_MSR_DATE,        TSR_MSR_NUM,         TSR_BR_CODE,         TSR_PAT_ID,
                  TSR_NAME,             TSR_PRG_CODE,        TSR_PRG_DESC,        TSR_DSC_CODE,        TSR_DSC_DESC,
                  TSR_DLV_DATE,         TSR_DLV_TIME,        TSR_ACTION,          TSR_PASS,            TSR_DOC_NUM)
           SELECT :NEW.MIS_CP_CODE,     :NEW.MIS_SPC_DATE,   :NEW.MIS_SPC_NUM,   :NEW.MIS_BR_CODE,     :NEW.MIS_PAT_ID,
                  :NEW.MIS_PAT_NAME,    :NEW.MIS_PRG_CODE,   :NEW.MIS_PRG_DESC,   DIS_DSC_CODE,       (SELECT DSC_DESC FROM HOS_SD_SRV_CHARGES WHERE DSC_CP_CODE = DIS_CP_CODE AND DSC_CODE = DIS_DSC_CODE),
                  DIS_DLV_DATE,         DIS_DLV_TIME,        'U',                 MPF_PASS,            MPF_FILE_NUM
           FROM   LAB_TD_IPD_SRVS,HOS_TM_PATIENT_FILE
           WHERE  DIS_CP_CODE = MPF_CP_CODE
           AND    DIS_DOC_NUM = MPF_FILE_NUM
           AND    DIS_CP_CODE = :NEW.MIS_CP_CODE
           AND    DIS_SPC_NUM = :NEW.MIS_SPC_NUM;
        END IF;
     END IF;
  ELSIF DELETING THEN
     IF :OLD.MIS_PRG_CODE = 'HOSAS26' AND NVL(:OLD.MIS_PST_FLAG,'U') = 'P' THEN
        INSERT INTO HOS_TO_OPD_SRV_RCPT_PQ
              (TSR_CP_CODE,          TSR_MSR_DATE,        TSR_MSR_NUM,         TSR_BR_CODE,         TSR_PAT_ID,
               TSR_NAME,             TSR_PRG_CODE,        TSR_PRG_DESC,        TSR_ACTION,          TSR_PASS)
        VALUES(:OLD.MIS_CP_CODE,     :OLD.MIS_SPC_DATE,   :OLD.MIS_SPC_NUM,    :OLD.MIS_BR_CODE,    :OLD.MIS_PAT_ID,
               :OLD.MIS_PAT_NAME,    :OLD.MIS_PRG_CODE,   :OLD.MIS_PRG_DESC,   'D',                 NULL);
     END IF;
  END IF;
END;
/

prompt
prompt Creating trigger LAB_TO_UPLOAD_FILE_BD
prompt ======================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.LAB_TO_UPLOAD_FILE_BD
BEFORE DELETE ON LAB_TO_UPLOAD_FILE FOR EACH ROW
DECLARE
  LC_STRING VARCHAR2(4000);
BEGIN
  BEGIN
    SELECT LAB_RPT_DIR
    INTO   LC_STRING
    FROM   SYSTEM.V$HW_SPEC;
  EXCEPTION
    WHEN OTHERS THEN
         LC_STRING := NULL;
  END;
  IF LC_STRING IS NOT NULL THEN
     LC_STRING := LC_STRING||OLR_PKG.ENCRYPT(REPLACE(:OLD.LUF_FILE_NAME,'.pdf'))||'.tmp';
     LC_STRING := 'DEL '||LC_STRING;
     HOST_COMMAND(LC_STRING);
  END IF;
END;
/

prompt
prompt Creating trigger TRG_HOS_TM_OPD_SRV_RCPT
prompt ========================================
prompt
CREATE OR REPLACE TRIGGER MDHSYS.TRG_HOS_TM_OPD_SRV_RCPT
 BEFORE INSERT OR UPDATE
 ON HOS_TM_OPD_SRV_RCPT REFERENCING NEW AS NEW OLD AS OLD FOR EACH ROW
DECLARE
  LC_CNT NUMBER;
BEGIN
  SELECT COUNT(*)
  INTO   LC_CNT
  FROM   ISR_XO_DOC_ALIAS
  WHERE  DAL_CP_CODE   =   :NEW.MSR_CP_CODE
  AND    DAL_BR_CODE   =   :NEW.MSR_BR_CODE
  AND    DAL_PRG_CODE  =   :NEW.MSR_PRG_CODE
  AND    DECODE(DAL_TRN_TYPE,'%',:NEW.MSR_TYPE, DAL_TRN_TYPE)  = :NEW.MSR_TYPE
  AND    DECODE(DAL_ACT_TYPE,'%',:NEW.MSR_NF_TYPE,DAL_ACT_TYPE)  = :NEW.MSR_NF_TYPE
  AND    DAL_ALS_CODE  = SUBSTR(:NEW.MSR_NUM,1,3);
  IF LC_CNT = 0 THEN
     RAISE_APPLICATION_ERROR(-20001,'Invalid Document No');
  END IF;
END;
/

