 OF MSR_PRG_DESC, MSR_AGE_TYPE, MSR_AGE_YMDW, MSR_AGE_DAYS, MSR_REF_MCT_NAME, MSR_CP_CODE, MSR_NF_TYPE, MSR_DATE, MSR_NUM, MSR_PAT_TYPE, MSR_PAT_ID, MSR_NAME, MSR_ADDRESS, MSR_PHONE, MSR_MCT_CODE, MSR_DEP_CODE, MSR_TYPE, MSR_MPA_CODE, MSR_EMP_ID, MSR_EMP_NAME, MSR_EMP_RELATION, MSR_EMP_VALID, MSR_EMP_LIMIT, MSR_EMP_APPROVAL, MSR_EMP_APP_REF, MSR_EMP_APP_DATE, MSR_COMPLEMENTRY, MSR_AMOUNT, MSR_DISCOUNT, MSR_NET_AMT, MSR_RCVD_AMT, MSR_RETU_AMT, MSR_DUE_AMT, MSR_DUE_RCVD_AMT, MSR_BILL_NUMBER, MSR_RCVD_STATUS, MSR_STATUS, MSR_DAT_FLAG, MSR_INS_DATE, MSR_INS_USER, MSR_UPD_DATE, MSR_UPD_USER, MSR_BILL_INCLUDE, MSR_EMP_APP_REMARKS, MSR_REF_NUM, MSR_REF_TYPE, MSR_PST_FLAG, MSR_INS_TIME, MSR_JV_DATE, MSR_JV_NUM, MSR_COM_FLAG, MSR_MCT_DESC, MSR_OTH_COMP_CODE, MSR_DIS_USR, MSR_DIS_DATE, MSR_DIS_TIME, MSR_DISC_REASON, MSR_REF_MCT_CODE, MSR_MPT_AGE, MSR_MPT_SEX, MSR_PRT_FLAG, MSR_PAT_GENDER, MSR_PAT_AGE, MSR_MPT_AGE2, MSR_MPT_AGE2_TYP, MSR_BR_CODE, MSR_SDD_SDI_CODE, MSR_SDD_EFF_DATE, MSR_PRG_CODE, MSR_TOKEN_NBR, MSR_WARD_CODE
